window.HH_DAA={"v":1,"title":"الداء والدواء","sub":"الجواب الكافي لمن سأل عن الدواء الشافي","author":"ابن قيم الجوزية","ed":"طبعة دار عالم الفوائد، تحقيق محمد أجمل الإصلاحي، تخريج زائد النشيري، 1429هـ","q0":"ما تقول السادة العلماء أئمة الدين رضي الله عنهم أجمعين في رجل ابتلي ببلية، وعلم أنها إن استمرت به أفسدت عليه دنياه وآخرته، وقد اجتهد في دفعها عن نفسه بكل طريق، فما تزداد إلا توقدا وشدة؟ فما الحيلة في دفعها؟ وما الطريق إلى كشفها؟","q0pg":3,"parts":["p1","p2","p3","p4","p5","p6","p7","p8"],"stations":[{"k":"s1","t":"لكل داء دواء","pgs":[3,11],"q":"هل لكل بلاء يصيب القلب والبدن دواء، وما الطريق إلى الشفاء منه؟","essence":"لكل داء دواء، والقرآن أعظم الشفاء","kw":["الشفاء","الفاتحة","قبول المحل"],"daa":"اليأس من الشفاء والجهل بطريق الدواء حين ينزل البلاء بالقلب أو البدن.","dawa":"طلب الدواء بسؤال أهل العلم، والاستشفاء بالقرآن ولا سيما الفاتحة، مع قبول المحل وقوة همة الفاعل وترك موانع الإجابة.","sections":[{"t":"نص الاستفتاء","pg":3,"lv":"adl","key":"فما الحيلة في دفعها؟ وما الطريق إلى كشفها؟","p":["ما تقول السادة العلماء أئمة الدين رضي الله عنهم أجمعين في رجل ابتلي ببلية، وعلم أنها إن استمرت به أفسدت عليه دنياه وآخرته، وقد اجتهد في دفعها عن نفسه بكل طريق، فما تزداد إلا توقدا وشدة؟ فما الحيلة في دفعها؟ وما الطريق إلى كشفها؟","فرحم الله من أعان مبتلى، «والله في عون العبد ما كان العبد في عون أخيه»، أفتونا مأجورين."],"items":[{"h":"ملاحظة","x":"هذا كلام السائل لا كلام ابن القيم، وعليه بنى ابن القيم كتابه كله جوابا.","pg":3}],"hd":"حديث «والله في عون العبد ما كان العبد في عون أخيه» رواه مسلم 2699","weak":1},{"t":"لكل داء دواء","pg":4,"lv":"adl","key":"وهذا يعم أدواء القلب والروح والبدن، وأدويتها.","p":["ثبت في صحيح البخاري من حديث أبي هريرة رضي الله عنه عن النبي ﷺ أنه قال: «ما أنزل الله داء إلا أنزل له شفاء».","وفي صحيح مسلم من حديث جابر بن عبدالله قال: قال رسول الله ﷺ: «لكل داء دواء، فإذا أصيب دواء الداء برأ بإذن الله».","وهذا يعم أدواء القلب والروح والبدن، وأدويتها."],"items":[{"h":"حديث أبي هريرة","x":"«ما أنزل الله داء إلا أنزل له شفاء»","pg":4},{"h":"حديث جابر","x":"«لكل داء دواء، فإذا أصيب دواء الداء برأ بإذن الله»","pg":4},{"h":"حديث أسامة بن شريك","x":"«إن الله لم ينزل داء إلا أنزل له شفاء، علمه من علمه، وجهله من جهله»","pg":4},{"h":"لفظ آخر لحديث أسامة","x":"«إن الله لم يضع داء إلا وضع له شفاء أو دواء إلا داء واحدا» قالوا: يا رسول الله ما هو؟ قال: «الهرم».","pg":5}],"hd":"حديث أبي هريرة رواه البخاري 5678؛ حديث جابر رواه مسلم 2204؛ حديث أسامة بن شريك أخرجه أحمد 18456، وزيادة «علمه من علمه وجهله من جهله» من طريق مصعب بن سلام وفيه ضعف، ورواية الجماعة بدونها؛ ولفظ «إلا داء واحدا: الهرم» أخرجه الترمذي 2038 وأبو داود وابن ماجه، وقال الترمذي: حسن صحيح، وصححه ابن خزيمة وابن حبان والحاكم","weak":1},{"t":"الجهل داء وشفاؤه السؤال","pg":5,"lv":"adl","key":"فأخبر أن الجهل داء، وأن شفاءه السؤال.","p":["وقد جعل النبي ﷺ الجهل داء، وجعل دواءه سؤال العلماء.","فقال: «قتلوه، قتلهم الله! ألا سألوا إذ لم يعلموا! فإنما شفاء العي السؤال، إنما كان يكفيه أن يتيمم ويعصر، أو يعصب، على جرحه خرقة، ثم يمسح عليها، ويغسل سائر جسده».","فأخبر أن الجهل داء، وأن شفاءه السؤال."],"items":[{"h":"القصة","x":"خرج الصحابة في سفر فأصاب رجلا منهم حجر فشجه في رأسه، ثم احتلم، فسأل أصحابه عن رخصة في التيمم، فقالوا: لا نجد لك رخصة وأنت تقدر على الماء، فاغتسل فمات، فأنكر النبي ﷺ عليهم فتواهم بغير علم.","pg":6}],"hd":"حديث جابر في صاحب الشجة أخرجه أبو داود 336، تفرد به الزبير بن خريق، وقال الدارقطني: ليس بالقوي، وصححه ابن السكن؛ فهو مختلف فيه، ولذلك لم يعرض للناشئ والشاب ولم تبن عليه أسئلة","weak":1},{"t":"القرآن كله شفاء","pg":6,"lv":"kid","key":"فلم ينزل الله سبحانه من السماء شفاء قط أعم ولا أنفع ولا أعظم ولا أنجع في إزالة الداء من القرآن.","p":["وقد أخبر سبحانه عن القرآن أنه شفاء، فقال تعالى: ﴿ولو جعلناه قرآنا أعجميا لقالوا لولا فصلت آياته ءأعجمي وعربي قل هو للذين آمنوا هدى وشفاء﴾ [فصلت 44]. وقال: ﴿وننزل من القرآن ما هو شفاء ورحمة للمؤمنين﴾ [الإسراء 82].","و«من» ههنا لبيان الجنس لا للتبعيض، فإن القرآن كله شفاء، كما قال في الآية الأخرى. فهو شفاء للقلوب من داء الجهل والشك والريب، فلم ينزل الله سبحانه من السماء شفاء قط أعم ولا أنفع ولا أعظم ولا أنجع في إزالة الداء من القرآن."],"items":[{"h":"فائدة لغوية","x":"«و«من» ههنا لبيان الجنس لا للتبعيض، فإن القرآن كله شفاء»","pg":6}]},{"t":"التداوي بالفاتحة","pg":7,"lv":"adl","key":"ولو أحسن العبد التداوي بالفاتحة لرأى لها تأثيرا عجيبا في الشفاء.","p":["فقد أثر هذا الدواء في هذا الداء، وأزاله حتى كأن لم يكن. وهو أسهل دواء وأيسره. ولو أحسن العبد التداوي بالفاتحة لرأى لها تأثيرا عجيبا في الشفاء.","ومكثت بمكة مدة تعتريني أدواء، ولا أجد طبيبا ولا دواء، فكنت أعالج نفسي بالفاتحة، فأرى لها تأثيرا عجيبا. فكنت أصف ذلك لمن يشتكي ألما، وكان كثير منهم يبرأ سريعا."],"items":[{"h":"حديث أبي سعيد","x":"نزل نفر من الصحابة على حي من العرب فأبوا أن يضيفوهم، فلدغ سيد الحي، فرقاه أحدهم بالفاتحة على قطيع من الغنم، «فكأنما نشط من عقال، فانطلق يمشي، وما به قلبة»، فلما أخبروا النبي ﷺ قال: «وما يدريك أنها رقية؟» ثم قال: «قد أصبتم، اقسموا واضربوا لي معكم سهما».","pg":7},{"h":"تجربة ابن القيم","x":"«فكنت أعالج نفسي بالفاتحة، فأرى لها تأثيرا عجيبا»","pg":8}],"hd":"رواه البخاري 2276 ومسلم 2201","weak":1},{"t":"أسباب تخلف الشفاء","pg":8,"lv":"yth","key":"ولكن تستدعي قبول المحل، وقوة همة الفاعل وتأثيره.","p":["ولكن ههنا أمر ينبغي التفطن له، وهو أن الأذكار والآيات والأدعية التي يستشفى بها ويرقى بها، هي في نفسها نافعة شافية، ولكن تستدعي قبول المحل، وقوة همة الفاعل وتأثيره. فمتى تخلف الشفاء كان لضعف تأثير الفاعل، أو لعدم قبول المنفعل، أو لمانع قوي فيه يمنع أن ينجع فيه الدواء.","فإن الطبيعة إذا أخذت الدواء بقبول تام كان انتفاع البدن به بحسب ذلك القبول، وكذلك القلب إذا أخذ الرقى والتعاويذ بقبول تام، وكان للراقي نفس فعالة وهمة مؤثرة، أثر في إزالة الداء."],"items":[{"h":"السبب الأول","x":"«لضعف تأثير الفاعل»","pg":8},{"h":"السبب الثاني","x":"«لعدم قبول المنفعل»","pg":8},{"h":"السبب الثالث","x":"«لمانع قوي فيه يمنع أن ينجع فيه الدواء»","pg":8}]},{"t":"أثر الدعاء وأسباب تخلفه","pg":9,"lv":"adl","key":"وكذلك الدعاء، فإنه من أقوى الأسباب في دفع المكروه وحصول المطلوب.","p":["وكذلك الدعاء، فإنه من أقوى الأسباب في دفع المكروه وحصول المطلوب، ولكن قد يتخلف عنه أثره، إما لضعفه في نفسه بأن يكون دعاء لا يحبه الله لما فيه من العدوان، وإما لضعف القلب وعدم إقباله على الله وجمعيته عليه وقت الدعاء، فيكون بمنزلة القوس الرخو جدا، فإن السهم يخرج منه خروجا ضعيفا؛ وإما لحصول المانع من الإجابة من أكل الحرام، والظلم، ورين الذنوب على القلوب، واستيلاء الغفلة والسهو واللهو وغلبتها عليها.","فهذا دواء نافع مزيل للداء، ولكن غفلة القلب عن الله تبطل قوته. وكذلك أكل الحرام يبطل قوته ويضعفها.","قال رسول الله ﷺ: «أيها الناس، إن الله طيب، لا يقبل إلا طيبا». ثم ذكر الرجل يطيل السفر أشعث أغبر يمد يده إلى السماء: يا رب يا رب، ومطعمه حرام، ومشربه حرام، وملبسه حرام، وغذي بالحرام، فأنى يستجاب لذلك!"],"items":[{"h":"ضعف الدعاء في نفسه","x":"«بأن يكون دعاء لا يحبه الله لما فيه من العدوان»","pg":9},{"h":"ضعف القلب","x":"«فيكون بمنزلة القوس الرخو جدا، فإن السهم يخرج منه خروجا ضعيفا»","pg":9},{"h":"حصول المانع","x":"«من أكل الحرام، والظلم، ورين الذنوب على القلوب، واستيلاء الغفلة والسهو واللهو وغلبتها عليها»","pg":9},{"h":"أثر بني إسرائيل","x":"أصاب بني إسرائيل بلاء فخرجوا مخرجا، فأوحى الله إلى نبيهم أنهم يخرجون إلى الصعيد بأبدان نجسة، ويرفعون أكفا سفكوا بها الدماء وملؤوا بها بيوتهم من الحرام، فلن يزدادوا منه إلا بعدا.","pg":11},{"h":"أثر أبي ذر","x":"«يكفي من الدعاء مع البر ما يكفي الطعام من الملح»","pg":11}],"hd":"حديث «إن الله طيب» رواه مسلم 1015؛ وحديث «ادعوا الله وأنتم موقنون بالإجابة» ضعيف (انظر weak)؛ وأثر بني إسرائيل في سنده ضعف؛ وأثر أبي ذر مرسل منقطع","weak":1}],"lv":{"kid":{"show":true,"title":"لكل مرض علاج","intro":"الله رحيم بعباده، فما أنزل مرضا إلا أنزل له علاجا. والقرآن الكريم أعظم علاج للقلب، وسورة الفاتحة التي تقرؤها في كل صلاة لها أثر عجيب في الشفاء إذا قرأتها بقلب حاضر واثق بالله.","points":["لكل مرض دواء، فلا أيأس إذا مرضت أو حزنت.","القرآن كله شفاء لقلبي.","أقرأ الفاتحة على نفسي وعلى أهلي بقلب حاضر.","الدعاء من أقوى الأسباب لدفع ما أكره.","القلب الغافل يضعف أثر الدعاء، فأنتبه حين أدعو."],"quote":{"x":"فإن القرآن كله شفاء","pg":6},"quiz":[{"q":"ماذا أخبرنا النبي ﷺ عن الأمراض؟","o":["أنزل الله لكل داء دواء","المرض يبقى ولا يزول أبدا","الدواء لا ينفع أبدا","الشفاء يأتي بلا أي سبب"],"why":"«ما أنزل الله داء إلا أنزل له شفاء»","pg":4},{"q":"أي سورة رقى بها الصحابي سيد الحي الملدوغ؟","o":["سورة الفاتحة","سورة الإخلاص","سورة الناس","سورة الفلق"],"why":"فانطلق يتفل عليه، ويقرأ ﴿الحمد لله رب العالمين﴾، فكأنما نشط من عقال.","pg":7},{"q":"القرآن شفاء للقلوب من أي شيء؟","o":["الجهل والشك والريب","الجوع والعطش والبرد","التعب والنوم والكسل","الحر والمطر والريح"],"why":"«فهو شفاء للقلوب من داء الجهل والشك والريب»","pg":6},{"q":"بماذا وصف ابن القيم التداوي بالفاتحة؟","o":["أسهل دواء وأيسره","أصعب دواء وأشقه","دواء نادر الأثر","دواء للبدن وحده فقط"],"why":"«وهو أسهل دواء وأيسره»","pg":8}],"scene":{"t":"أخي مريض","x":"مرض أخوك الصغير، وذهب به والدك إلى الطبيب وأعطاه الدواء. جلست بجانبه وأنت تريد أن تساعده. ماذا تفعل؟","opts":["أقرأ عليه الفاتحة وأدعو له مع أخذه الدواء","أقول: الدواء وحده يكفي ولا حاجة للدعاء","أقول: سيشفى وحده فلا داعي لأي شيء"],"why":"«وكذلك الدعاء، فإنه من أقوى الأسباب في دفع المكروه وحصول المطلوب»","pg":9},"act":{"type":"match","t":"صل الدواء بوصفه","x":"صل كل كلمة في العمود الأول بما يناسبها في العمود الثاني كما ذكر ابن القيم.","items":[{"a":"القرآن","b":"كله شفاء"},{"a":"الفاتحة","b":"أسهل دواء وأيسره"},{"a":"الدعاء","b":"من أقوى الأسباب"},{"a":"غفلة القلب","b":"تبطل قوة الدعاء"}]}},"yth":{"show":true,"title":"لكل داء دواء: ابدأ العلاج الصحيح","intro":"كل شاب يمر بهموم أو عادات يريد التخلص منها. ابن القيم يبدأ كتابه بقاعدة مطمئنة: ما من داء إلا وله دواء، وأعظم الأدوية القرآن. لكن الدواء النافع يحتاج قلبا يقبله، وهمة صادقة، وتركا للموانع التي تبطل أثره.","points":["لكل داء دواء، والقرآن كله شفاء لا بعضه.","الفاتحة دواء سهل، يظهر أثره لمن أحسن التداوي بها.","يتخلف الشفاء لضعف الفاعل، أو عدم قبول المحل، أو وجود مانع.","الدعاء من القلب الغافل كالسهم من القوس الرخو.","أكل الحرام والظلم والذنوب تمنع أثر الدعاء."],"quote":{"x":"فهذا دواء نافع مزيل للداء، ولكن غفلة القلب عن الله تبطل قوته","pg":10},"quiz":[{"q":"ما معنى «من» في قوله تعالى ﴿وننزل من القرآن ما هو شفاء﴾ عند ابن القيم؟","o":["لبيان الجنس لا للتبعيض","للتبعيض لا لبيان الجنس","لابتداء الغاية في الزمان","زائدة لتأكيد المعنى"],"why":"«و«من» ههنا لبيان الجنس لا للتبعيض، فإن القرآن كله شفاء»","pg":6},{"q":"لماذا لا يشفى بعض من يرقي نفسه بالآيات؟","o":["لضعف الفاعل أو عدم القبول أو لمانع","لأن الآيات تنفع بعض الناس فقط","لأن الرقية لا أثر لها في المرض","لأن الشفاء لا يكون إلا بالطبيب الحاذق"],"why":"«فمتى تخلف الشفاء كان لضعف تأثير الفاعل، أو لعدم قبول المنفعل، أو لمانع قوي فيه يمنع أن ينجع فيه الدواء»","pg":8},{"q":"بماذا شبه ابن القيم الدعاء من قلب ضعيف غير مقبل على الله؟","o":["القوس الرخو جدا","البذر بلا سقي","الغيم الأسود","الطعام بلا ملح"],"why":"«فيكون بمنزلة القوس الرخو جدا، فإن السهم يخرج منه خروجا ضعيفا»","pg":9},{"q":"أي هذه ذكره ابن القيم من موانع إجابة الدعاء؟","o":["أكل الحرام والظلم ورين الذنوب","رفع اليدين واستقبال القبلة","الإلحاح وتكرار المسألة","الدعاء في الثلث الأخير"],"why":"«وإما لحصول المانع من الإجابة من أكل الحرام، والظلم، ورين الذنوب على القلوب»","pg":9},{"q":"ماذا كان يفعل ابن القيم حين اعترته الأدواء بمكة؟","o":["يعالج نفسه بالفاتحة","يترك العلاج صبرا","يسافر إلى طبيب بعيد","يكتفي بالدواء الحسي"],"why":"«فكنت أعالج نفسي بالفاتحة، فأرى لها تأثيرا عجيبا»","pg":8}],"scene":{"t":"الرقية والجوال","x":"قال لك صديقك: قرأت الفاتحة على نفسي وأنا أتصفح الجوال، ولم أشعر بأي فرق، إذن لا فائدة منها. بماذا ترد عليه؟","opts":["أبين له أن الرقية تحتاج قلبا حاضرا وقبولا تاما","أوافقه وأقول إن الرقية لا تنفع","أقول له: أعدها مرة أخرى وأنت تتصفح"],"why":"«وكذلك القلب إذا أخذ الرقى والتعاويذ بقبول تام، وكان للراقي نفس فعالة وهمة مؤثرة، أثر في إزالة الداء»","pg":8},"act":{"type":"sort","t":"يقوي الدواء أم يضعفه؟","x":"افرز البطاقات إلى صنفين: (أ) سبب يقوي أثر الرقية والدعاء، (ب) سبب يضعف أثرهما أو يمنعه.","items":[{"x":"قبول المحل","ok":"أ"},{"x":"قوة همة الفاعل","ok":"أ"},{"x":"إقبال القلب على الله وقت الدعاء","ok":"أ"},{"x":"نفس فعالة وهمة مؤثرة","ok":"أ"},{"x":"أكل الحرام","ok":"ب"},{"x":"الظلم","ok":"ب"},{"x":"رين الذنوب على القلب","ok":"ب"},{"x":"استيلاء الغفلة والسهو واللهو","ok":"ب"},{"x":"دعاء فيه عدوان","ok":"ب"}]}},"adl":{"show":true,"title":"لكل داء دواء: فقه الاستشفاء بالوحي","intro":"يفتتح ابن القيم جوابه بتأسيس قاعدة كلية: لكل داء دواء، وهي تعم أدواء القلب والروح والبدن. ثم يقرر أن القرآن أعظم الشفاء، وأن الأذكار والرقى نافعة في نفسها، غير أن أثرها مشروط بقبول المحل وقوة همة الفاعل وانتفاء المانع، كما هو الشأن في الأدوية الحسية. وهذا مفتاح الكتاب كله: الذنوب موانع، والطاعة دواء.","points":["القاعدة: «ما أنزل الله داء إلا أنزل له شفاء»، وهي عامة في أدواء القلب والبدن.","«من» في آية الإسراء بيانية، فالقرآن كله شفاء.","أثر الدواء القلبي يتوقف على ثلاثة: الفاعل والمحل وانتفاء المانع.","الدعاء سبب قوي، يضعفه ما فيه من عدوان، وغفلة القلب، وأكل الحرام والظلم والذنوب.","زيادة «علمه من علمه وجهله من جهله» في إسنادها ضعف، وحديث صاحب الشجة مختلف فيه."],"quote":{"x":"فلم ينزل الله سبحانه من السماء شفاء قط أعم ولا أنفع ولا أعظم ولا أنجع في إزالة الداء من القرآن","pg":6},"quiz":[{"q":"قاس ابن القيم تخلف أثر الرقى على تخلف أثر الأدوية الحسية. ما وجه القياس؟","o":["كلاهما يحتاج قبول المحل وانتفاء المانع","كلاهما لا ينفع إلا إذا وصفه طبيب حاذق","كلاهما يؤثر بمجرده دون أي شرط","كلاهما مختص بأمراض البدن وحده"],"why":"«كما يكون ذلك في الأدوية والأدواء الحسية، فإن عدم تأثيرها قد يكون لعدم قبول الطبيعة لذلك الدواء، وقد يكون لمانع قوي يمنع من اقتضائه أثره»","pg":8},{"q":"قال ابن القيم بعد أحاديث الدواء: «وهذا يعم...». ما الذي يعمه هذا الأصل؟","o":["أدواء القلب والروح والبدن","أمراض البدن الظاهرة فقط","الأمراض التي عرف دواؤها","أدواء القلب دون البدن"],"why":"«وهذا يعم أدواء القلب والروح والبدن، وأدويتها»","pg":5},{"q":"ما الذي يجعل غفلة القلب خطرا على الدعاء في نظر ابن القيم؟","o":["تبطل قوة دواء نافع في نفسه","تجعل الدعاء محرما على صاحبه","تمنع رفع اليدين في الدعاء","تقطع الصلة بالأسباب الحسية"],"why":"«فهذا دواء نافع مزيل للداء، ولكن غفلة القلب عن الله تبطل قوته»","pg":10},{"q":"الرجل الأشعث الأغبر يمد يديه إلى السماء ولا يستجاب له. ما السبب في الحديث؟","o":["مطعمه ومشربه وملبسه حرام","لم يرفع يديه إلى السماء","دعا في غير وقت الإجابة","لم يلح في دعائه وسؤاله لربه"],"why":"«ومطعمه حرام، ومشربه حرام، وملبسه حرام، وغذي بالحرام، فأنى يستجاب لذلك!»","pg":10},{"q":"في تقسيم ابن القيم لأسباب تخلف الشفاء، ماذا يمثل الراقي؟","o":["الفاعل الذي تشترط قوة همته","المحل الذي يشترط قبوله","المانع الذي يدفع أثر الدواء","المنفعل الذي يتلقى الدواء"],"why":"«ولكن تستدعي قبول المحل، وقوة همة الفاعل وتأثيره»","pg":8}],"scene":{"t":"طالب قلق قبل الاختبار","x":"جاءك طالب في صفك يقول: أقرأ الأذكار كل صباح ومع ذلك يلازمني القلق قبل الاختبارات، فما فائدتها؟ كيف توجهه؟","opts":["أوجهه إلى حضور القلب والثقة بالدواء وترك الموانع مع أخذ الأسباب","أخبره أن الأذكار لا علاقة لها بالقلق","أطلب منه أن يكثر الأذكار دون التفات إلى حال قلبه"],"why":"«هي في نفسها نافعة شافية، ولكن تستدعي قبول المحل، وقوة همة الفاعل وتأثيره»","pg":8},"act":{"type":"class","t":"عيادة القلب الأولى","x":"نشاط صفي مدته 30 دقيقة لتأسيس قاعدة الكتاب: لكل داء دواء، وشروط نفع الدواء.","items":["5 دقائق: يقرأ المعلم نص الاستفتاء ويسأل: ما البلية التي يمكن أن يقصدها السائل؟","5 دقائق: عرض حديث «ما أنزل الله داء إلا أنزل له شفاء» وقول ابن القيم «وهذا يعم أدواء القلب والروح والبدن».","10 دقائق: يرسم الطلاب مثلثا رؤوسه: الفاعل، المحل، المانع، ويكتبون تحت كل رأس مثالا من النص.","5 دقائق: مقارنة بين القوس الرخو والقوس القوية، وربطها بحضور القلب في الدعاء.","5 دقائق: يكتب كل طالب مانعا واحدا يريد تركه هذا الأسبوع ليقوى أثر دعائه."]}},"alt":{}},"highlights":[{"x":"فإن القرآن كله شفاء","pg":6,"lv":"kid"},{"x":"وهو أسهل دواء وأيسره","pg":8,"lv":"kid"},{"x":"ولو أحسن العبد التداوي بالفاتحة لرأى لها تأثيرا عجيبا في الشفاء","pg":8,"lv":"kid"},{"x":"فهذا دواء نافع مزيل للداء، ولكن غفلة القلب عن الله تبطل قوته","pg":10,"lv":"yth"},{"x":"وكذلك أكل الحرام يبطل قوته ويضعفها","pg":10,"lv":"yth"},{"x":"وهذا يعم أدواء القلب والروح والبدن، وأدويتها","pg":5,"lv":"adl"},{"x":"فلم ينزل الله سبحانه من السماء شفاء قط أعم ولا أنفع ولا أعظم ولا أنجع في إزالة الداء من القرآن","pg":6,"lv":"yth"}],"concepts":[{"term":"شروط نفع الدواء القلبي","def":"ولكن تستدعي قبول المحل، وقوة همة الفاعل وتأثيره","pg":8},{"term":"أسباب تخلف الشفاء","def":"فمتى تخلف الشفاء كان لضعف تأثير الفاعل، أو لعدم قبول المنفعل، أو لمانع قوي فيه يمنع أن ينجع فيه الدواء","pg":8},{"term":"القوس الرخو","def":"فيكون بمنزلة القوس الرخو جدا، فإن السهم يخرج منه خروجا ضعيفا","pg":9},{"term":"«من» البيانية في آية الشفاء","def":"و«من» ههنا لبيان الجنس لا للتبعيض، فإن القرآن كله شفاء","pg":6}],"stories":[{"t":"رقية سيد الحي بالفاتحة","x":"نزل نفر من الصحابة على حي من العرب فلم يضيفوهم، فلدغ سيدهم، فرقاه أحد الصحابة بالفاتحة فقام كأنما نشط من عقال، وأقرهم النبي ﷺ وقال: «وما يدريك أنها رقية؟».","pg":7,"lv":"adl","hd":"رواه البخاري 2276 ومسلم 2201","weak":1},{"t":"ابن القيم يتداوى بالفاتحة في مكة","x":"مكث ابن القيم بمكة تعتريه أدواء ولا يجد طبيبا ولا دواء، فكان يعالج نفسه بالفاتحة فيرى لها أثرا عجيبا، ويصفها لمن يشتكي ألما فيبرأ كثير منهم سريعا.","pg":8,"lv":"kid","hd":""},{"t":"الرجل الأشعث الأغبر","x":"رجل يطيل السفر أشعث أغبر يمد يده إلى السماء: يا رب يا رب، ومطعمه ومشربه وملبسه حرام، فأنى يستجاب له.","pg":10,"lv":"adl","hd":"رواه مسلم 1015","weak":1},{"t":"صاحب الشجة والفتوى بغير علم","x":"شج رجل في سفر ثم احتلم، فأفتاه أصحابه بالغسل فاغتسل فمات، فقال النبي ﷺ: «قتلوه، قتلهم الله! ألا سألوا إذ لم يعلموا!».","pg":6,"lv":"adl","hd":"أخرجه أبو داود 336، تفرد به الزبير بن خريق، قال الدارقطني: ليس بالقوي، وصححه ابن السكن","weak":1},{"t":"دعاء بني إسرائيل المردود","x":"خرج بنو إسرائيل يدعون لبلاء نزل بهم، فأوحى الله إلى نبيهم أنهم يرفعون أكفا سفكوا بها الدماء وملؤوا بها بيوتهم من الحرام، فلن يزدادوا منه إلا بعدا.","pg":11,"lv":"adl","hd":"ذكره عبدالله بن أحمد في الزهد، وأخرجه أبو داود في الزهد 13، وفي سنده ضعف"}],"ready":true},{"k":"s2","t":"الدعاء من أنفع الأدوية","pgs":[11,35],"q":"كيف يكون الدعاء دواء يدفع البلاء، وما الذي يقويه أو يبطله، وهل ينافي القدر؟","essence":"الدعاء سبب مقدور يدفع به البلاء","kw":["الإلحاح","الاضطرار","القدر"],"daa":"الاستعجال وترك الدعاء، والاتكال على القدر بحجة أن المقدور واقع دعا العبد أو لم يدع.","dawa":"الإلحاح في الدعاء مع حضور القلب وتوفر آدابه وانتفاء موانعه، واليقين بأن الدعاء من أقوى الأسباب التي قدر الله بها المقدور.","sections":[{"t":"الدعاء من أنفع الأدوية","pg":11,"lv":"adl","key":"والدعاء من أنفع الأدوية، وهو عدو البلاء، يدافعه ويعالجه، ويمنع نزوله، ويرفعه، أو يخففه إذا نزل.","p":["والدعاء من أنفع الأدوية، وهو عدو البلاء، يدافعه ويعالجه، ويمنع نزوله، ويرفعه، أو يخففه إذا نزل."],"items":[{"h":"حديث علي","x":"«الدعاء سلاح المؤمن، وعماد الدين، ونور السموات والأرض»","pg":11}],"hd":"حديث «الدعاء سلاح المؤمن» أخرجه الحاكم 1812، وفيه محمد بن الحسن الهمداني متروك الحديث، انظر السلسلة الضعيفة 179؛ فهو ضعيف لا يعرض للناشئ والشاب","weak":1},{"t":"مقامات الدعاء مع البلاء","pg":12,"lv":"adl","key":"وله مع البلاء ثلاث مقامات","p":["وله مع البلاء ثلاث مقامات: أحدها: أن يكون أقوى من البلاء، فيدفعه. الثاني: أن يكون أضعف من البلاء، فيقوى عليه البلاء، فيصاب به العبد، ولكن قد يخففه، وإن كان ضعيفا. الثالث: أن يتقاوما، ويمنع كل واحد منهما صاحبه."],"items":[{"h":"المقام الأول","x":"«أن يكون أقوى من البلاء، فيدفعه»","pg":12},{"h":"المقام الثاني","x":"«أن يكون أضعف من البلاء، فيقوى عليه البلاء، فيصاب به العبد، ولكن قد يخففه، وإن كان ضعيفا»","pg":12},{"h":"المقام الثالث","x":"«أن يتقاوما، ويمنع كل واحد منهما صاحبه»","pg":12},{"h":"حديث عائشة","x":"«لا يغني حذر من قدر، والدعاء ينفع مما نزل ومما لم ينزل. وإن البلاء لينزل، فيلقاه الدعاء، فيعتلجان إلى يوم القيامة»","pg":12},{"h":"حديث ابن عمر","x":"«الدعاء ينفع مما نزل ومما لم ينزل، فعليكم عباد الله بالدعاء»","pg":12},{"h":"حديث ثوبان","x":"«لا يرد القدر إلا الدعاء، ولا يزيد في العمر إلا البر، وإن الرجل ليحرم الرزق بالذنب يصيبه»","pg":13}],"hd":"أحاديث عائشة وابن عمر وثوبان كلها ضعيفة الأسانيد عند المحقق (انظر weak)، فتعرض للراشد فقط مع بيان ضعفها، والمقامات الثلاثة من كلام ابن القيم","weak":1},{"t":"الإلحاح في الدعاء","pg":13,"lv":"adl","key":"ومن أنفع الأدوية: الإلحاح في الدعاء","p":["ومن أنفع الأدوية: الإلحاح في الدعاء.","وفي كتاب الزهد للإمام أحمد عن قتادة قال: قال مورق: ما وجدت للمؤمن مثلا إلا رجلا في البحر على خشبة، فهو يدعو: يا رب يا رب، لعل الله عز وجل أن ينجيه."],"items":[{"h":"حديث أبي هريرة","x":"«من لم يسأل الله يغضب عليه»","pg":13},{"h":"حديث أنس","x":"«لا تعجزوا في الدعاء، فإنه لا يهلك مع الدعاء أحد»","pg":14},{"h":"حديث عائشة","x":"«إن الله يحب الملحين في الدعاء»","pg":14},{"h":"مثل مورق","x":"ما وجدت للمؤمن مثلا إلا رجلا في البحر على خشبة، فهو يدعو: يا رب يا رب، لعل الله عز وجل أن ينجيه.","pg":14}],"hd":"الأحاديث الثلاثة في هذا الفصل ضعيفة عند المحقق (انظر weak)، والصحيح أن «إن الله يحب الملحين» من قول الأوزاعي؛ وأثر مورق أخرجه أحمد في الزهد 1765 ورجاله ثقات","weak":1},{"t":"الآفات التي تمنع ترتب أثر الدعاء: الاستعجال","pg":15,"lv":"adl","key":"ومن الآفات التي تمنع ترتب أثر الدعاء عليه: أن يستعجل العبد، ويستبطئ الإجابة، فيستحسر، ويدع الدعاء.","p":["ومن الآفات التي تمنع ترتب أثر الدعاء عليه: أن يستعجل العبد، ويستبطئ الإجابة، فيستحسر، ويدع الدعاء. وهو بمنزلة من بذر بذرا، أو غرس غراسا، فجعل يتعاهده ويسقيه، فلما استبطأ كماله وإدراكه، تركه وأهمله!","وفي صحيح البخاري من حديث أبي هريرة أن رسول الله ﷺ قال: «يستجاب لأحدكم ما لم يعجل، يقول: دعوت، فلم يستجب لي».","وفي صحيح مسلم عنه: «لا يزال يستجاب للعبد ما لم يدع بإثم أو قطيعة رحم، ما لم يستعجل». قيل: يا رسول الله، وما الاستعجال؟ قال: «يقول: قد دعوت وقد دعوت، فلم أر يستجيب لي. فيستحسر عند ذلك ويدع الدعاء»."],"items":[{"h":"حديث أنس في المسند","x":"«لا يزال العبد بخير ما لم يستعجل» قالوا: يا رسول الله، كيف يستعجل؟ قال: «يقول: قد دعوت ربي، فلم يستجب لي».","pg":16}],"hd":"حديث «يستجاب لأحدكم ما لم يعجل» رواه البخاري 6340؛ وحديث «لا يزال يستجاب للعبد» رواه مسلم 2735؛ وحديث أنس في المسند فيه أبو هلال الراسبي ولا يثبت","weak":1},{"t":"إذا جمع الدعاء حضور القلب","pg":16,"lv":"yth","key":"فإن هذا الدعاء لا يكاد يرد أبدا","p":["وإذا جمع الدعاء حضور القلب وجمعيته بكليته على المطلوب، وصادف وقتا من أوقات الإجابة الستة وهي: الثلث الأخير من الليل، وعند الأذان، وبين الأذان والإقامة، وأدبار الصلوات المكتوبات، وعند صعود الإمام يوم الجمعة على المنبر حتى تقضى الصلاة، وآخر ساعة بعد العصر من ذلك اليوم؛ وصادف خشوعا في القلب، وانكسارا بين يدي الرب، وذلا له، وتضرعا ورقة؛","واستقبل الداعي القبلة، وكان على طهارة، ورفع يديه إلى الله تعالى، وبدأ بحمد الله والثناء عليه، ثم ثنى بالصلاة على محمد عبده ورسوله ﷺ، ثم قدم بين يدي حاجته التوبة والاستغفار، ثم دخل على الله، وألح عليه في المسألة، وتملقه، ودعاه رغبة ورهبة، وتوسل إليه بأسمائه وصفاته وتوحيده، وقدم بين يدي دعائه صدقة،","فإن هذا الدعاء لا يكاد يرد أبدا، ولا سيما إن صادف الأدعية التي أخبر النبي ﷺ أنها مظنة الإجابة، أو أنها متضمنة للاسم الأعظم."],"items":[{"h":"حال القلب","x":"حضور القلب وجمعيته بكليته على المطلوب، والخشوع والانكسار والذل والتضرع والرقة.","pg":16},{"h":"الوقت","x":"أوقات الإجابة الستة.","pg":16},{"h":"الهيئة","x":"استقبال القبلة، والطهارة، ورفع اليدين.","pg":16},{"h":"الترتيب","x":"الحمد والثناء، ثم الصلاة على النبي ﷺ، ثم التوبة والاستغفار، ثم المسألة مع الإلحاح.","pg":16},{"h":"الوسيلة","x":"التوسل بالأسماء والصفات والتوحيد، وتقديم صدقة بين يدي الدعاء.","pg":17}]},{"t":"الأدعية التي هي مظنة الإجابة","pg":17,"lv":"yth","key":"ولا سيما إن صادف الأدعية التي أخبر النبي ﷺ أنها مظنة الإجابة، أو أنها متضمنة للاسم الأعظم","p":["فمنها ما في السنن وصحيح ابن حبان من حديث عبدالله بن بريدة عن أبيه أن رسول الله ﷺ سمع رجلا يقول: اللهم إني أسألك بأني أشهد أنك أنت الله، لا إله إلا أنت، الأحد الصمد الذي لم يلد ولم يولد ولم يكن له كفوا أحد. فقال: «لقد سأل الله بالاسم الذي إذا سئل به أعطى، وإذا دعي به أجاب»."],"items":[{"h":"حديث بريدة","x":"«اللهم إني أسألك بأني أشهد أنك أنت الله، لا إله إلا أنت، الأحد الصمد الذي لم يلد ولم يولد ولم يكن له كفوا أحد»","pg":17,"hd":"أخرجه أبو داود 1493 والترمذي 3475 وابن ماجه 3857 وابن حبان 892"},{"h":"حديث أنس","x":"«اللهم إني أسألك بأن لك الحمد، لا إله إلا أنت المنان بديع السموات والأرض، يا ذا الجلال والإكرام، يا حي يا قيوم»","pg":18,"hd":"أخرجه أبو داود 1495 والنسائي 1300 وابن ماجه 3858، وصححه ابن حبان والحاكم والضياء"},{"h":"حديث أسماء بنت يزيد","x":"«اسم الله الأعظم في هاتين الآيتين: ﴿وإلهكم إله واحد لا إله إلا هو الرحمن الرحيم﴾ وفاتحة آل عمران: ﴿الم الله لا إله إلا هو الحي القيوم﴾»","pg":19,"hd":"أخرجه الترمذي 3476 وصححه، وفيه عبيدالله بن أبي زياد وشهر بن حوشب في حفظهما ضعف"},{"h":"ألظوا بيا ذا الجلال والإكرام","x":"«ألظوا بيا ذا الجلال والإكرام» يعني: تعلقوا بها، والزموها، وداوموا عليها.","pg":19,"hd":"صحيح الإسناد من حديث ربيعة بن عامر عند أحمد 17596 والحاكم 1836، ولا يثبت من حديث أبي هريرة وأنس"},{"h":"حديث أبي هريرة","x":"كان النبي ﷺ إذا أهمه الأمر رفع رأسه إلى السماء فقال: «سبحان الله العظيم»، وإذا اجتهد في الدعاء قال: «يا حي يا قيوم».","pg":19,"hd":"أخرجه الترمذي 3436 وقال: غريب، وفيه إبراهيم بن الفضل المخزومي متروك"},{"h":"حديث أنس","x":"كان النبي ﷺ إذا كربه أمر قال: «يا حي يا قيوم، برحمتك أستغيث».","pg":20,"hd":"أخرجه الترمذي 3524 وقال: غريب، تفرد به يزيد الرقاشي وهو ضعيف؛ وله طريق عند الطبراني ظاهر سنده لا بأس به"},{"h":"حديث أبي أمامة","x":"«اسم الله الأعظم في ثلاث سور من القرآن: البقرة وآل عمران وطه». قال القاسم: فالتمستها، فإذا هي آية ﴿الحي القيوم﴾.","pg":20,"hd":"أخرجه الحاكم 1861 وابن ماجه 3856، وفي رواية القاسم عن أبي أمامة كلام"},{"h":"دعوة ذي النون","x":"«دعوة ذي النون إذ دعا، وهو في بطن الحوت: ﴿لا إله إلا أنت سبحانك إني كنت من الظالمين﴾ إنه لم يدع بها مسلم في شيء قط إلا استجاب الله له»","pg":20,"hd":"أخرجه الترمذي 3505 والحاكم وصححه، وقال الهيثمي: رجاله رجال الصحيح"},{"h":"دعاء الكرب","x":"«لا إله إلا الله العظيم الحليم، لا إله إلا الله رب العرش العظيم، لا إله إلا الله رب السموات ورب الأرض رب العرش الكريم»","pg":22,"hd":"رواه البخاري 6346 ومسلم 2730"},{"h":"حديث علي","x":"علمني رسول الله ﷺ إذا نزل بي كرب أن أقول: «لا إله إلا الله الحليم الكريم، سبحان الله، وتبارك الله رب العرش العظيم، والحمد لله رب العالمين».","pg":22,"hd":"أخرجه أحمد 1/91، وصححه ابن حبان والحاكم وابن حجر"},{"h":"دعاء الهم والحزن","x":"«اللهم إني عبدك، ابن عبدك، ابن أمتك، ناصيتي بيدك، ماض في حكمك، عدل في قضاؤك، أسألك اللهم بكل اسم هو لك، سميت به نفسك، أو علمته أحدا من خلقك، أو أنزلته في كتابك، أو استأثرت به في علم الغيب عندك: أن تجعل القرآن العظيم ربيع قلبي، ونور صدري، وجلاء حزني، وذهاب همي»","pg":23,"hd":"أخرجه أحمد 3712 وابن حبان 979، وصححه ابن حبان والحاكم والمؤلف، وحسنه ابن حجر، وفي إسناده كلام"}],"hd":"درجة كل دعاء مذكورة في عنصره؛ يعرض للناشئ والشاب ما ثبت فقط: حديث بريدة، وحديث أنس عند أبي داود والنسائي، وألظوا من حديث ربيعة بن عامر، ودعوة ذي النون، ودعاء الكرب، وحديث علي، ودعاء الهم"},{"t":"السر في الاضطرار لا في لفظ الدعاء","pg":25,"lv":"adl","key":"وهذا موضع يغلط فيه كثير من الناس.","p":["وكثيرا ما تجد أدعية دعا بها قوم، فاستجيب لهم، ويكون قد اقترن بالدعاء ضرورة صاحبه، وإقباله على الله، أو حسنة تقدمت منه جعل الله سبحانه إجابة دعوته شكرا لحسنته، أو صادف وقت إجابة ونحو ذلك، فأجيبت دعوته. فيظن الظان أن السر في لفظ ذلك الدعاء، فيأخذه مجردا عن تلك الأمور التي قارنته من ذلك الداعي.","وهذا موضع يغلط فيه كثير من الناس.","ومن هذا أنه قد يتفق دعاؤه باضطرار عند قبر فيجاب، فيظن الجاهل أن السر للقبر، ولم يعلم أن السر للاضطرار وصدق اللجأ إلى الله. فإذا حصل ذلك في بيت من بيوت الله كان أفضل وأحب إلى الله."],"items":[{"h":"ما يقترن بالدعاء فيجاب","x":"ضرورة صاحبه، وإقباله على الله، أو حسنة تقدمت منه، أو مصادفة وقت إجابة.","pg":25},{"h":"المثل","x":"«وهذا كما إذا استعمل رجل دواء نافعا في الوقت الذي ينبغي على الوجه الذي ينبغي، فانتفع به، فظن غيره أن استعمال هذا الدواء بمجرده كاف في حصول المطلوب، كان غالطا»","pg":25}],"hd":"قصة أبي معلق التي ساقها قبل هذا الفصل (ص 23 إلى 25) لا يثبت سندها عند المحقق، فوضعت في القصص للراشد","weak":1},{"t":"الأدعية والتعوذات بمنزلة السلاح","pg":26,"lv":"kid","key":"والأدعية والتعوذات بمنزلة السلاح، والسلاح بضاربه لا بحده فقط","p":["والأدعية والتعوذات بمنزلة السلاح، والسلاح بضاربه لا بحده فقط، فمتى كان السلاح سلاحا تاما لا آفة به، والساعد ساعد قوي، والمانع مفقود، حصلت به النكاية في العدو. ومتى تخلف واحد من هذه الثلاثة تخلف التأثير.","فإذا كان الدعاء في نفسه غير صالح، أو الداعي لم يجمع بين قلبه ولسانه في الدعاء، أو كان ثم مانع من الإجابة، لم يحصل الأثر."],"items":[{"h":"السلاح التام","x":"الدعاء الصالح في نفسه.","pg":26},{"h":"الساعد القوي","x":"الداعي الذي يجمع بين قلبه ولسانه.","pg":26},{"h":"فقد المانع","x":"انتفاء موانع الإجابة.","pg":26}]},{"t":"الدعاء والقدر","pg":26,"lv":"adl","key":"وحينئذ فالدعاء من أقوى الأسباب.","p":["وههنا سؤال مشهور، وهو أن المدعو به إن كان قد قدر لم يكن بد من وقوعه، دعا به العبد أو لم يدع. وإن لم يكن قد قدر لم يقع، سواء سأله العبد أو لم يسأله.","والصواب أن ههنا قسما ثالثا غير ما ذكره السائل، وهو أن هذا المقدور قدر بأسباب، ومن أسبابه الدعاء. فلم يقدر مجردا عن سببه، ولكن قدر بسببه. فمتى أتى العبد بالسبب وقع المقدور، ومتى لم يأت بالسبب انتفى المقدور.","وحينئذ فالدعاء من أقوى الأسباب. فإذا قدر وقوع المدعو به بالدعاء لم يصح أن يقال: لا فائدة في الدعاء، كما لا يقال: لا فائدة في الأكل والشرب وجميع الحركات والأعمال! وليس شيء من الأسباب أنفع من الدعاء ولا أبلغ في حصول المطلوب."],"items":[{"h":"القول الأول: ترك الدعاء","x":"«فظنت طائفة صحة هذا السؤال، فتركت الدعاء، وقالت: لا فائدة فيه!»، وهؤلاء «متناقضون، فإن طرد مذهبهم يوجب تعطيل جميع الأسباب».","pg":26},{"h":"القول الثاني: تعبد محض","x":"«الاشتغال بالدعاء من باب التعبد المحض، يثيب الله عليه الداعي، من غير أن يكون له تأثير في المطلوب بوجه ما»","pg":27},{"h":"القول الثالث: علامة مجردة","x":"«بل الدعاء علامة مجردة نصبها الله سبحانه أمارة على قضاء الحاجة»، ولا ارتباط عندهم «إلا مجرد الاقتران العادي، لا التأثير السببي».","pg":27},{"h":"الصواب","x":"«أن هذا المقدور قدر بأسباب، ومن أسبابه الدعاء»","pg":28},{"h":"حال الصحابة","x":"«وكان عمر بن الخطاب رضي الله عنه يستنصر به على عدوه، وكان أعظم جنديه»، «وكان يقول: إني لا أحمل هم الإجابة، ولكن هم الدعاء. فإذا ألهمت الدعاء فإن الإجابة معه».","pg":29},{"h":"الثمرة","x":"«فمن ألهم الدعاء فقد أريد به الإجابة»","pg":30}],"hd":"قول عمر «لستم تنصرون بكثرة، وإنما تنصرون من السماء» لم يقف عليه المحقق؛ وحديث «من لم يسأل الله يغضب عليه» المعاد في ص 30 ضعيف","weak":1},{"t":"ترتيب الجزاء على الأعمال في القرآن","pg":30,"lv":"adl","key":"وهذا في القرآن يزيد على ألف موضع.","p":["وقد دل العقل والنقل والفطر وتجارب الأمم، على اختلاف أجناسها ومللها ونحلها، على أن التقرب إلى رب العالمين وطلب مرضاته، والبر والإحسان إلى خلقه، من أعظم الأسباب الجالبة لكل خير. وأضدادها من أكبر الأسباب الجالبة لكل شر. فما استجلبت نعم الله واستدفعت نقمه بمثل طاعته والتقرب إليه، والإحسان إلى خلقه.","وقد رتب الله سبحانه حصول الخيرات في الدنيا والآخرة وحصول الشرور في الدنيا والآخرة في كتابه على الأعمال، ترتب الجزاء على الشرط، والمعلول على العلة، والمسبب على السبب. وهذا في القرآن يزيد على ألف موضع.","وبالجملة، فالقرآن من أوله إلى آخره صريح في ترتب الجزاء بالخير والشر والأحكام الكونية والأمرية على الأسباب، بل ترتب أحكام الدنيا والآخرة ومصالحهما ومفاسدهما على الأسباب والأعمال."],"items":[{"h":"الوصف المناسب","x":"﴿فلما عتوا عن ما نهوا عنه قلنا لهم كونوا قردة خاسئين﴾ [الأعراف 166]","pg":31},{"h":"الشرط والجزاء","x":"﴿إن تتقوا الله يجعل لكم فرقانا ويكفر عنكم سيئاتكم ويغفر لكم﴾ [الأنفال 29]، ﴿وألو استقاموا على الطريقة لأسقيناهم ماء غدقا﴾ [الجن 16]","pg":32},{"h":"لام التعليل","x":"﴿ليدبروا آياته وليتذكر أولو الألباب﴾ [ص 29]","pg":32},{"h":"أداة كي","x":"﴿كي لا يكون دولة بين الأغنياء منكم﴾ [الحشر 7]","pg":32},{"h":"باء السببية","x":"﴿ذلك بما قدمت أيديكم﴾ [آل عمران 182]، ﴿بما كنتم تعملون﴾ [الأعراف 43]","pg":32},{"h":"المفعول لأجله","x":"﴿أن تقولوا يوم القيامة إنا كنا عن هذا غافلين﴾ [الأعراف 172]","pg":33},{"h":"فاء السببية","x":"﴿فعصوا رسول ربهم فأخذهم أخذة رابية﴾ [الحاقة 10]","pg":33},{"h":"لما الدالة على الجزاء","x":"﴿فلما آسفونا انتقمنا منهم﴾ [الزخرف 55]","pg":33},{"h":"إن وما عملت فيه","x":"﴿إنهم كانوا يسارعون في الخيرات﴾ [الأنبياء 90]","pg":33},{"h":"لولا","x":"﴿فلولا أنه كان من المسبحين للبث في بطنه إلى يوم يبعثون﴾ [الصافات 143، 144]","pg":33},{"h":"لو الدالة على الشرط","x":"﴿ولو أنهم فعلوا ما يوعظون به لكان خيرا لهم﴾ [النساء 66]","pg":33}],"hd":"أثر وهب بن منبه «أنا الله، لا إله إلا أنا، إذا رضيت باركت...» في الزهد لأحمد 289، سنده صحيح إلى وهب، وهو من الإسرائيليات"},{"t":"الفقيه يرد القدر بالقدر","pg":34,"lv":"yth","key":"بل الفقيه كل الفقيه الذي يرد القدر بالقدر، ويدفع القدر بالقدر، ويعارض القدر بالقدر","p":["ومن فقه هذه المسألة، وتأملها حق التأمل، انتفع بها غاية النفع، ولم يتكل على القدر جهلا منه وعجزا وتفريطا وإضاعة، فيكون توكله عجزا، وعجزه توكلا.","بل الفقيه كل الفقيه الذي يرد القدر بالقدر، ويدفع القدر بالقدر، ويعارض القدر بالقدر، بل لا يمكن الإنسان يعيش إلا بذلك، فإن الجوع والعطش والبرد وأنواع المخاوف والمحاذير هي من القدر، والخلق كلهم ساعون في دفع هذا القدر بالقدر.","وهكذا من وفقه الله، وألهمه رشده، يدفع قدر العقوبة الأخروية بقدر التوبة والإيمان والأعمال الصالحة؛ فهذا وزان القدر المخوف في الدنيا وما يضاده سواء. فرب الدارين واحد، وحكمته واحدة، لا يناقض بعضها بعضا، ولا يبطل بعضها بعضا."],"items":[{"h":"مكانة المسألة","x":"«فهذه المسألة من أشرف المسائل لمن عرف قدرها، ورعاها حق رعايتها، والله المستعان»","pg":35}]},{"t":"أمران تتم بهما سعادة المرء وفلاحه","pg":35,"lv":"yth","key":"لكن يبقى عليه أمران، بهما تتم سعادته وفلاحه","p":["لكن يبقى عليه أمران، بهما تتم سعادته وفلاحه: أحدهما: أن يعرف تفاصيل أسباب الشر والخير، ويكون له بصيرة في ذلك بما يشاهده في العالم، وما جربه في نفسه وغيره، وما سمعه من أخبار الأمم قديما وحديثا.","ومن أنفع ما في ذلك تدبر القرآن، فإنه كفيل بذلك على أكمل الوجوه، وفيه أسباب الشر والخير جميعا مفصلة مبينة. ثم السنة، فإنها شقيقة القرآن، وهي الوحي الثاني. ومن صرف إليهما عنايته اكتفى بهما عن غيرهما، وهما يريانك الخير والشر وأسبابهما، حتى كأنك تعاين ذلك عيانا."],"items":[{"h":"مصادر البصيرة","x":"ما يشاهده في العالم، وما جربه في نفسه وغيره، وما سمعه من أخبار الأمم قديما وحديثا.","pg":35},{"h":"أنفع المصادر","x":"«ومن أنفع ما في ذلك تدبر القرآن»، «ثم السنة، فإنها شقيقة القرآن، وهي الوحي الثاني».","pg":35},{"h":"الأمر الثاني","x":"يأتي ذكره في الصفحات التالية خارج هذا الجزء.","pg":35}]}],"lv":{"kid":{"show":true,"title":"أدعو الله ولا أمل","intro":"الدعاء دواء عجيب: يمنع البلاء أو يرفعه أو يخففه. والمسلم يدعو ربه بقلب حاضر، ويلح عليه ولا يستعجل، كمن يزرع بذرة ويسقيها كل يوم حتى تكبر. والدعاء مثل السلاح، لا ينفع إلا بيد قوية.","points":["الدعاء عدو البلاء: يدفعه أو يرفعه أو يخففه.","أكرر الدعاء وألح على الله ولا أقول: دعوت فلم يستجب لي.","أدعو وأنا طاهر، مستقبل القبلة، رافع يدي، أبدأ بحمد الله والصلاة على النبي ﷺ.","أتحرى أوقات الإجابة، مثل ما بين الأذان والإقامة.","أحفظ دعاء يونس عليه السلام: لا إله إلا أنت سبحانك إني كنت من الظالمين."],"quote":{"x":"والدعاء من أنفع الأدوية","pg":11},"quiz":[{"q":"كم مقاما للدعاء مع البلاء ذكر ابن القيم؟","o":["ثلاثة مقامات","مقامان اثنان","أربعة مقامات","خمسة مقامات"],"why":"«وله مع البلاء ثلاث مقامات»","pg":12},{"q":"من استعجل الإجابة فترك الدعاء يشبه من:","o":["زرع بذرا ثم تركه","سقى زرعه كل يوم","حمل سلاحا قويا","استقبل القبلة"],"why":"«وهو بمنزلة من بذر بذرا، أو غرس غراسا، فجعل يتعاهده ويسقيه، فلما استبطأ كماله وإدراكه، تركه وأهمله!»","pg":15},{"q":"أكمل دعاء ذي النون: «لا إله إلا أنت سبحانك...»","o":["إني كنت من الظالمين","رب السموات والأرض","يا ذا الجلال والإكرام","الحليم الكريم العظيم"],"why":"﴿لا إله إلا أنت سبحانك إني كنت من الظالمين﴾ [الأنبياء 87]","pg":20},{"q":"أي هذه الأوقات ذكره ابن القيم من أوقات الإجابة؟","o":["بين الأذان والإقامة","وقت الضحى قبل الظهر","بعد طلوع الشمس بقليل","عند منتصف النهار"],"why":"«الثلث الأخير من الليل، وعند الأذان، وبين الأذان والإقامة، وأدبار الصلوات المكتوبات»","pg":16}],"scene":{"t":"حفظ السورة","x":"دعوت الله أن يعينك على حفظ سورة الملك، ومر أسبوع ولم تحفظها كاملة بعد. ماذا تفعل؟","opts":["أستمر في الدعاء والمراجعة ولا أمل","أقول: دعوت فلم يستجب لي، وأترك الدعاء","أترك الحفظ لأن الدعاء لم ينفع"],"why":"«يستجاب لأحدكم ما لم يعجل، يقول: دعوت، فلم يستجب لي»","pg":15},"act":{"type":"order","t":"رتب خطوات دعائي","x":"رتب هذه الخطوات كما ذكرها ابن القيم في الدعاء الذي لا يكاد يرد.","items":["أتوضأ وأستقبل القبلة","أرفع يدي إلى الله","أبدأ بحمد الله والثناء عليه","أصلي على النبي ﷺ","أتوب وأستغفر","أسأل الله حاجتي وألح عليه"]}},"yth":{"show":true,"title":"الدعاء: أقوى سبب بين يديك","intro":"يظن بعض الشباب أن الدعاء لا يغير شيئا ما دام كل شيء مكتوبا. ابن القيم يهدم هذه الشبهة: المقدور قدر بأسبابه، والدعاء من أقوى أسبابه، كما قدر الشبع بالأكل والري بالشرب. والفقيه حقا هو الذي يرد القدر بالقدر، فيدفع قدر البلاء بقدر الدعاء والعمل.","points":["للدعاء مع البلاء ثلاث مقامات: يدفعه، أو يخففه، أو يتقاومان.","الاستعجال آفة: يستحسر العبد فيدع الدعاء.","الدعاء كالسلاح: لا يؤثر إلا إذا صلح، وقوي القلب، وزال المانع.","السر في الاضطرار وصدق اللجأ إلى الله، لا في مكان ولا قبر.","من ترك الأسباب اتكالا على القدر صار توكله عجزا وعجزه توكلا."],"quote":{"x":"بل الفقيه كل الفقيه الذي يرد القدر بالقدر، ويدفع القدر بالقدر، ويعارض القدر بالقدر","pg":34},"quiz":[{"q":"ما المقام الثالث من مقامات الدعاء مع البلاء؟","o":["أن يتقاوما ويمنع كل منهما صاحبه","أن يكون الدعاء أقوى فيدفع البلاء","أن يقوى البلاء فيصاب به العبد","أن يرتفع البلاء ثم يعود أشد"],"why":"«الثالث: أن يتقاوما، ويمنع كل واحد منهما صاحبه»","pg":12},{"q":"إن كان المقدور سيقع فلماذا أدعو؟ ما الجواب الصواب عند ابن القيم؟","o":["المقدور قدر بأسباب، ومن أسبابه الدعاء","الدعاء تعبد محض لا أثر له في المطلوب","الدعاء علامة مجردة على قضاء الحاجة","لا فائدة في الدعاء ما دام المقدور واقعا"],"why":"«والصواب أن ههنا قسما ثالثا غير ما ذكره السائل، وهو أن هذا المقدور قدر بأسباب، ومن أسبابه الدعاء»","pg":28},{"q":"دعا رجل مضطرا عند قبر فأجيب. ما السر في الإجابة عند ابن القيم؟","o":["الاضطرار وصدق اللجأ إلى الله","بركة المكان الذي دعا عنده","ألفاظ الدعاء التي قالها وحدها","قرب القبر من بيت من بيوت الله"],"why":"«فيظن الجاهل أن السر للقبر، ولم يعلم أن السر للاضطرار وصدق اللجأ إلى الله»","pg":25},{"q":"متى يتخلف أثر الدعاء الذي شبهه ابن القيم بالسلاح؟","o":["إذا فسد أو غاب القلب أو وجد مانع","إذا دعا العبد بصوت منخفض خاشع","إذا لم يحفظ الأدعية المأثورة كلها","إذا دعا في البيت لا في المسجد"],"why":"«فإذا كان الدعاء في نفسه غير صالح، أو الداعي لم يجمع بين قلبه ولسانه في الدعاء، أو كان ثم مانع من الإجابة، لم يحصل الأثر»","pg":26},{"q":"على من ينطبق قول ابن القيم: «فيكون توكله عجزا، وعجزه توكلا»؟","o":["من اتكل على القدر وترك الأسباب","من أخذ بالأسباب مع التوكل","من دعا وألح على الله في حاجته","من رد القدر بالقدر في حياته"],"why":"«ولم يتكل على القدر جهلا منه وعجزا وتفريطا وإضاعة، فيكون توكله عجزا، وعجزه توكلا»","pg":34}],"scene":{"t":"النجاح المكتوب","x":"قال زميلك قبل الاختبار: لن أذاكر ولن أدعو، فإن كان النجاح مكتوبا لي فسأنجح. بماذا ترد عليه؟","opts":["أبين له أن النجاح قدر بأسبابه كالمذاكرة والدعاء","أوافقه لأن كل شيء مكتوب","أقول له: ادع فقط ولا حاجة للمذاكرة"],"why":"«فمتى أتى العبد بالسبب وقع المقدور، ومتى لم يأت بالسبب انتفى المقدور»","pg":28},"act":{"type":"plan","t":"خطة الإلحاح سبعة أيام","x":"اختر حاجة واحدة صادقة، ثم اختر من الخطوات التالية ما تلتزم به سبعة أيام، وسجل في دفترك كل يوم ما فعلت دون أن تستعجل الإجابة.","items":["أدعو في الثلث الأخير من الليل","أدعو بين الأذان والإقامة","أدعو في أدبار الصلوات المكتوبة","أتحرى آخر ساعة بعد العصر يوم الجمعة","أبدأ بحمد الله ثم الصلاة على النبي ﷺ","أقدم التوبة والاستغفار بين يدي حاجتي","أقدم صدقة قبل دعائي","أدعو بدعوة ذي النون عند الضيق","أتوسل إلى الله بأسمائه وصفاته","أترك مانعا من موانع الإجابة كالظلم أو المال الحرام"]}},"adl":{"show":true,"title":"الدعاء والقدر: فقه الأسباب","intro":"في هذه المحطة يبني ابن القيم نظرية متكاملة للدعاء: الدعاء دواء له مقامات مع البلاء، ويقويه الإلحاح، وتفسده آفات أولها الاستعجال، ويكمل بشروط من حضور القلب والوقت والهيئة والوسيلة. ثم يحسم مسألة الدعاء والقدر بالقسم الثالث: المقدور قدر بأسبابه، ويرد على تارك الدعاء وعلى من جعله تعبدا محضا أو علامة مجردة. وينبه المربي إلى أن كثيرا من أحاديث هذا الفصل ضعيفة الإسناد عند المحقق، والأصل ثابت بالقرآن والصحيح.","points":["الدعاء عدو البلاء وله معه ثلاث مقامات، وأحاديث «يعتلجان» و«لا يرد القدر إلا الدعاء» ضعيفة الإسناد.","آفة الاستعجال ثابتة في الصحيحين، وهي أن يستحسر العبد فيدع الدعاء.","السر في الاضطرار وصدق اللجأ، وتعليق الإجابة بالقبور غلط عقدي ينبه عليه ابن القيم.","الأقوال في الدعاء والقدر أربعة: تركه، أو جعله تعبدا محضا، أو علامة مجردة، والصواب أنه سبب مقدور.","ترتيب الجزاء على الأعمال في القرآن يزيد على ألف موضع، والفقيه يرد القدر بالقدر."],"quote":{"x":"وليس شيء من الأسباب أنفع من الدعاء ولا أبلغ في حصول المطلوب","pg":29},"quiz":[{"q":"قالت طائفة: الدعاء علامة مجردة على قضاء الحاجة. ما موضع الخطأ عند ابن القيم؟","o":["نفي تأثير الدعاء وجعله اقترانا عاديا","إثبات أن للدعاء أثرا في حصول المطلوب","القول بأن المقدور قدر بأسبابه","عد الدعاء من أعظم أسباب الخير"],"why":"«ليس شيء من ذلك سببا ألبتة، ولا ارتباط بينه وبين ما يترتب عليه إلا مجرد الاقتران العادي، لا التأثير السببي. وخالفوا بذلك الحس، والعقل، والشرع، والفطرة»","pg":28},{"q":"كم موضعا في القرآن ذكر ابن القيم أنه رتب فيه الجزاء على الأعمال؟","o":["يزيد على ألف موضع","نحو مئة موضع فقط","نحو مئتي موضع فقط","قرابة خمسمئة موضع"],"why":"«وهذا في القرآن يزيد على ألف موضع»","pg":31},{"q":"جاء ترتيب الجزاء في قوله تعالى ﴿فلما آسفونا انتقمنا منهم﴾ بأي أداة؟","o":["أداة لما الدالة على الجزاء","لام التعليل الداخلة على الفعل","باء السببية الداخلة على ما","فاء السببية بين الجملتين"],"why":"«وتارة يأتي بأداة (لما) الدالة على الجزاء، كقوله: ﴿فلما آسفونا انتقمنا منهم﴾»","pg":33},{"q":"كان عمر يقول: إني لا أحمل هم الإجابة ولكن هم الدعاء. ما الفقه الذي استنبطه ابن القيم؟","o":["من ألهم الدعاء فقد أريد به الإجابة","الإجابة لا تتعلق بالدعاء أصلا","الدعاء عبادة لا يرجى منها شيء","هم الإجابة أولى من هم الدعاء"],"why":"«فمن ألهم الدعاء فقد أريد به الإجابة، فإن الله سبحانه يقول: ﴿ادعوني أستجب لكم﴾»","pg":30},{"q":"ما الأمر الأول الذي تتم به سعادة العبد وفلاحه بعد فقه مسألة القدر؟","o":["معرفة تفاصيل أسباب الشر والخير","حفظ الأدعية المأثورة كلها","ترك الأسباب توكلا على الله","الاقتصار على تجارب الناس"],"why":"«أحدهما: أن يعرف تفاصيل أسباب الشر والخير، ويكون له بصيرة في ذلك»","pg":35}],"scene":{"t":"ابني يكتفي بالدعاء","x":"ابنك يدعو كل ليلة أن يتفوق في دراسته، لكنه يهمل المذاكرة ويقول: الدعاء يكفي، والله على كل شيء قدير. كيف تعالج هذا الفهم؟","opts":["أعلمه أن الدعاء سبب والمذاكرة سبب، والفقيه يأخذ بالأسباب كلها","أمنعه من الدعاء حتى يذاكر","أقول له: إن كان التفوق مكتوبا فلا حاجة للتعب"],"why":"«وهذا كما قدر الشبع والري بالأكل والشرب»، «فمتى أتى العبد بالسبب وقع المقدور، ومتى لم يأت بالسبب انتفى المقدور»","pg":28},"act":{"type":"class","t":"مناظرة الأقوال الأربعة في الدعاء والقدر","x":"نشاط صفي مدته 40 دقيقة يعرض فيه المعلم الأقوال في مسألة الدعاء والقدر كما ساقها ابن القيم.","items":["5 دقائق: يطرح المعلم السؤال المشهور: إن كان المدعو به مقدرا فما فائدة الدعاء؟","10 دقائق: تقسيم الصف أربع مجموعات: تارك الدعاء، التعبد المحض، العلامة المجردة، القسم الثالث، وتقرأ كل مجموعة نص قولها من ص 26 إلى 28.","10 دقائق: تعرض كل مجموعة قولها، وترد المجموعة الرابعة بأمثلة ابن القيم: الشبع بالأكل، والري بالشرب، والزرع بالبذر.","10 دقائق: يستخرج الطلاب من القرآن ثلاث آيات رتب فيها الجزاء على العمل، ويحددون الأداة (الشرط، لام التعليل، باء السببية، فاء السببية).","5 دقائق: يكتب كل طالب جملة: كيف أرد القدر بالقدر في حياتي هذا الأسبوع؟"]}},"alt":{}},"highlights":[{"x":"والدعاء من أنفع الأدوية، وهو عدو البلاء","pg":11,"lv":"kid"},{"x":"ومن أنفع الأدوية: الإلحاح في الدعاء","pg":13,"lv":"kid"},{"x":"والأدعية والتعوذات بمنزلة السلاح، والسلاح بضاربه لا بحده فقط","pg":26,"lv":"yth"},{"x":"وليس شيء من الأسباب أنفع من الدعاء ولا أبلغ في حصول المطلوب","pg":29,"lv":"yth"},{"x":"فمن ألهم الدعاء فقد أريد به الإجابة","pg":30,"lv":"yth"},{"x":"فيكون توكله عجزا، وعجزه توكلا","pg":34,"lv":"yth"},{"x":"بل الفقيه كل الفقيه الذي يرد القدر بالقدر، ويدفع القدر بالقدر، ويعارض القدر بالقدر","pg":34,"lv":"adl"},{"x":"وهذا موضع يغلط فيه كثير من الناس","pg":25,"lv":"adl"}],"concepts":[{"term":"الاستحسار","def":"أن يستعجل العبد، ويستبطئ الإجابة، فيستحسر، ويدع الدعاء","pg":15},{"term":"مقامات الدعاء مع البلاء","def":"وله مع البلاء ثلاث مقامات","pg":12},{"term":"القسم الثالث في الدعاء والقدر","def":"وهو أن هذا المقدور قدر بأسباب، ومن أسبابه الدعاء. فلم يقدر مجردا عن سببه، ولكن قدر بسببه","pg":28},{"term":"الاقتران العادي","def":"ليس شيء من ذلك سببا ألبتة، ولا ارتباط بينه وبين ما يترتب عليه إلا مجرد الاقتران العادي، لا التأثير السببي","pg":28},{"term":"رد القدر بالقدر","def":"بل الفقيه كل الفقيه الذي يرد القدر بالقدر، ويدفع القدر بالقدر، ويعارض القدر بالقدر","pg":34},{"term":"السنة الوحي الثاني","def":"ثم السنة، فإنها شقيقة القرآن، وهي الوحي الثاني","pg":35}],"stories":[{"t":"الغريق على الخشبة","x":"قال مورق: ما وجدت للمؤمن مثلا إلا رجلا في البحر على خشبة، فهو يدعو: يا رب يا رب، لعل الله عز وجل أن ينجيه.","pg":14,"lv":"kid","hd":"أخرجه أحمد في الزهد 1765، ورجاله ثقات"},{"t":"الزارع المستعجل","x":"مثل ضربه ابن القيم لمن يستعجل الإجابة: رجل بذر بذرا أو غرس غرسا، فجعل يتعاهده ويسقيه، فلما استبطأ كماله تركه وأهمله.","pg":15,"lv":"kid","hd":""},{"t":"عمر يستنصر بالدعاء","x":"كان عمر بن الخطاب رضي الله عنه يستنصر بالدعاء على عدوه، وكان أعظم جنديه، وكان يقول: إني لا أحمل هم الإجابة، ولكن هم الدعاء.","pg":29,"lv":"yth","hd":"قوله «لستم تنصرون بكثرة» لم يقف عليه المحقق، وقوله «لا أحمل هم الإجابة» ذكره المصنف وشيخ الإسلام بلا إسناد"},{"t":"أبو معلق واللص","x":"تاجر من الأنصار ناسك ورع لقيه لص يريد قتله، فصلى أربع ركعات ودعا: «يا ودود، يا ذا العرش المجيد، يا فعال لما يريد...» ثلاث مرات، فجاء فارس فقتل اللص، وأخبره أنه ملك من أهل السماء الرابعة.","pg":23,"lv":"adl","hd":"رواه ابن أبي الدنيا في مجابي الدعوة 23، ولا يثبت سنده","weak":1},{"t":"الدعاء عند القبر","x":"قد يدعو المضطر عند قبر فيجاب، فيظن الجاهل أن السر للقبر، وإنما السر للاضطرار وصدق اللجأ إلى الله، ولو كان ذلك في بيت من بيوت الله كان أفضل وأحب إلى الله.","pg":25,"lv":"yth","hd":""}],"ready":true},{"k":"s3","t":"بين حسن الظن والغرور","pgs":[35,98],"q":"كيف أفرّق بين رجاء صادق يدفعني إلى الله وغرور يخدعني فأستمر في الذنب؟","essence":"الرجاء الصادق يسوق إلى العمل","kw":["حسن الظن","الغرور","الرجاء"],"daa":"مغالطة النفس بالاتكال على عفو الله مع الإصرار على المعصية وترك العمل.","dawa":"أن يعرف العبد أسباب الخير والشر بتدبر القرآن والسنة، وأن يقرن رجاءه بالعمل والخوف والسعي.","sections":[{"t":"لكن يبقى عليه أمران، بهما تتم سعادته وفلاحه","pg":35,"lv":"yth","key":"ومن أنفع ما في ذلك تدبّر القرآن، فإنه كفيل بذلك على أكمل الوجوه، وفيه أسباب الشرّ والخير جميعًا مفصّلةً مبيّنةً.","p":["أحدهما: أن يعرف تفاصيل أسباب الشر والخير، ويكون له بصيرة في ذلك بما يشاهده في العالم، وما جرّبه في نفسه وغيره، وما سمعه من أخبار الأمم قديمًا وحديثًا.","ثم السنّة، فإنها شقيقة القرآن، وهي الوحي الثاني."],"items":[{"h":"الأمر الأول","x":"معرفة تفاصيل أسباب الشر والخير بالمشاهدة والتجربة وأخبار الأمم، وأنفع ذلك تدبر القرآن ثم السنة.","pg":35},{"h":"الأمر الثاني","x":"أن يحذر مغالطة نفسه له على هذه الأسباب.","pg":36}],"hd":""},{"t":"فصل: والأمر الثاني أن يحذر مغالطة نفسه","pg":36,"lv":"adl","key":"فإنّ العبد يعرف أنّ المعصية والغفلة من الأسباب المضرة له في دنياه وآخرته، ولا بدّ؛ ولكن تغالطه نفسه","p":["ولكن تغالطه نفسه بالاتكال على عفو الله ومغفرته تارة، وبالتسويف بالتوبة تارة، وبالاستغفار باللسان تارة، وبفعل المندوبات تارة، وبالعلم تارة، وبالاحتجاج بالقدر تارة، وبالاحتجاج بالأشباه والنظراء والاقتداء بالأكابر تارة.","وكثير من الناس يظن أنه لو فعل ما فعل، ثم قال: «أستغفر الله» زال أثر الذنب، وراح هذا بهذا!"],"items":[{"h":"الاتكال على العفو","x":"بالاتكال على عفو الله ومغفرته تارة","pg":36},{"h":"التسويف","x":"وبالتسويف بالتوبة تارة","pg":36},{"h":"استغفار اللسان","x":"وبالاستغفار باللسان تارة","pg":36},{"h":"المندوبات","x":"وبفعل المندوبات تارة","pg":36},{"h":"العلم","x":"وبالعلم تارة","pg":36},{"h":"القدر","x":"وبالاحتجاج بالقدر تارة","pg":36},{"h":"الأشباه والأكابر","x":"وبالاحتجاج بالأشباه والنظراء والاقتداء بالأكابر تارة","pg":36}],"hd":"حديث «من قال في يوم: سبحان الله وبحمده مائة مرة حُطّت عنه خطاياه»: رواه البخاري 6405 ومسلم 2691. وحديث «أذنب عبد ذنبًا»: رواه البخاري 7507 ومسلم 2758.","weak":1},{"t":"أمثلة المغترين بنصوص الرجاء","pg":38,"lv":"adl","key":"وهذا الضرب من الناس قد تعلّق بنصوص الرجاء، واتّكل عليها، وتعلّق بها بكلتا يديه.","p":["وإذا عوتب على الخطايا والانهماك فيها سرد لك ما يحفظه من سعة رحمة الله ومغفرته ونصوص الرجاء.","وهذا إنما أُتي صاحبه من قلة علمه وفهمه."],"items":[{"h":"المتعلق بالجبر","x":"ومن هؤلاء المغرورين من يتعلق بمسألة الجبر، وأن العبد لا فعل له البتة ولا اختيار، وإنما هو مجبور على فعل المعاصي.","pg":38},{"h":"المغتر بالإرجاء","x":"ومن هؤلاء من يغترّ بمسألة الإرجاء، وأنّ الإيمان هو مجرد التصديق، والأعمال ليست من الإيمان.","pg":39},{"h":"المغتر بمحبة الصالحين","x":"ومن هؤلاء من يغترّ بمحبة الفقراء والمشايخ والصالحين، وكثرة التردد إلى قبورهم، والتضرّع إليهم، والاستشفاع بهم.","pg":39},{"h":"المغتر بآبائه","x":"ومنهم من يغترّ بآبائه وأسلافه، وأنّ لهم عند الله مكانة وصلاحًا؛ فلا يدَعون أن يخلّصوه.","pg":39},{"h":"المغتر بغنى الله","x":"ومنهم من يغترّ بأنّ الله عز وجل غنيّ عن عذابه، وأنّ عذابه لا يزيد في ملكه شيئًا، ورحمته له لا ينقص من ملكه شيئًا.","pg":39},{"h":"الفهم الفاسد لآية الضحى","x":"كاتكال بعضهم على قوله تعالى: ﴿وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَىٰ﴾ قالوا: وهو لا يرضى أن يكون في النار أحد من أمته! وهذا من أقبح الجهل، وأبين الكذب عليه.","pg":40},{"h":"آية الزمر","x":"ولا خلاف أنّ هذه الآية في حق التائبين، فإنّه يغفر كلّ ذنب للتائب، أي ذنب كان.","pg":40},{"h":"آية الانفطار","x":"وأتى سبحانه بلفظ «الكريم»، وهو السيّد العظيم المطاع الذي لا ينبغي الاغترار به ولا إهمال حقه.","pg":41},{"h":"آية الليل","x":"فإنّ الصِّليَّ أخصّ من الدخول، ونفيُ الأخصّ لا يستلزم نفي الأعم.","pg":42},{"h":"صوم عاشوراء وعرفة","x":"ولم يدر هذا المغتر أنّ صوم رمضان والصلوات الخمس أعظم وأجلّ من صيام يوم عرفة ويوم عاشوراء، وهي إنما تكفر ما بينها إذا اجتُنِبَت الكبائر.","pg":42}],"hd":"حديث صوم عرفة وعاشوراء: رواه مسلم 1162. وحديث «الصلوات الخمس والجمعة إلى الجمعة ورمضان إلى رمضان مكفرات ما بينهن إذا اجتنب الكبائر»: رواه مسلم 233.","weak":1},{"t":"حسن الظن إنما يكون مع الإحسان","pg":44,"lv":"adl","key":"ولا ريب أنّ حسن الظن إنما يكون مع الإحسان","p":["فإنّ المحسن حسن الظن بربه أنه يجازيه على إحسانه، ولا يخلف وعده، ويقبل توبته.","ومن تأمل هذا الموضع حقّ التأمل علم أنّ حسنَ الظن بالله هو حسنُ العمل نفسه.","بل حسن الظن ينفع من تاب، وندم، وأقلع، وبدّل السيئة بالحسنة، واستقبل بقية عمره بالخير والطاعة، ثم حسّن الظنّ. فهذا حسن الظن، والأول غرور!"],"items":[{"h":"المسيء مستوحش","x":"ولا يجامع وحشةَ الإساءة إحسانُ الظنّ أبدًا، فإنّ المسيء مستوحش بقدر إساءته. وأحسنُ الناس ظنًّا بربّه أطوعُهم له.","pg":45},{"h":"قول الحسن","x":"إنّ المؤمن أحسن الظن بربّه، فأحسن العمل. وإنّ الفاجر أساء الظنّ بربّه، فأساء العمل.","pg":45},{"h":"ظن أرداهم","x":"﴿وَذَٰلِكُمْ ظَنُّكُمُ الَّذِي ظَنَنتُم بِرَبِّكُمْ أَرْدَاكُمْ فَأَصْبَحْتُم مِّنَ الْخَاسِرِينَ﴾ [فصلت: 23]","pg":46},{"h":"خداع النفس","x":"فإذا ظنّ أنه يُدخله الجنة كان هذا غرورًا وخداعًا من نفسه، وتسويلًا من الشيطان، لا إحسانَ ظنٍّ بربّه.","pg":46},{"h":"كلما حسن الظن حسن العمل","x":"فالذي حمله على العمل حسنُ الظن، وكلّما حسُن ظنُّه حسُن عملُه، وإلا فحسنُ الظن مع اتباع الهوى عجز.","pg":48},{"h":"أسباب النجاة","x":"وبالجملة، فحسن الظن إنّما يكون مع انعقاد أسباب النجاة. وأما مع انعقاد أسباب الهلاك، فلا يتأتّى إحسان الظن.","pg":49},{"h":"أهل الرجاء","x":"فجعل هؤلاء أهل الرجاء، لا البطّالين والفاسقين.","pg":50},{"h":"العالم والجاهل","x":"فالعالم يضع الرجاء مواضعه، والجاهل المغتر يضعه في غير مواضعه.","pg":50}],"hd":"حديث «أنا عند حسن ظن عبدي بي»: رواه أحمد 16016 وابن حبان 633، وصححه ابن حبان والحاكم ووافقه الذهبي. وأثر الحسن البصري: رواه أحمد في الزهد 1652 وأبو نعيم، قال المحقق: فالأثر لا بأس به. وحديث عائشة في الدنانير: رواه أحمد 24733 بسند ضعيف فيه موسى بن جبير، ورواه أحمد 24222 وابن حبان 715 من طريق آخر بلفظ «ما ظنّ محمد بربه»، قال المحقق: والحديث سنده صحيح، وقد صححه ابن حبان. وحديث «الكيّس من دان نفسه»: رواه الترمذي 2459 وحسّنه، وصححه الحاكم، فتعقبه الذهبي بقوله: لا والله، أبو بكر واهٍ.","weak":1},{"t":"فصل: اعتماد الجهال على الرحمة، وأحاديث وآثار في ردع المغترين","pg":51,"lv":"adl","key":"ومن اعتمد على العفو مع الإصرار فهو كالمعاند.","p":["وكثير من الجهال اعتمدوا على رحمة الله وعفوه وكرمه، وضيّعوا أمره ونهيه، ونسوا أنه شديد العقاب، وأنه لا يردّ بأسه عن القوم المجرمين.","والأحاديث في هذا الباب أضعافُ أضعافِ ما ذكرنا، فلا ينبغي لمن نصح نفسه أن يتعامى عنها، ويرسل نفسه في المعاصي، ويتعلّق بحبل الرجاء وحسن الظن."],"items":[{"h":"قول معروف","x":"رجاؤك لرحمة من لا تطيعه من الخِذلان والحمق.","pg":51},{"h":"خوف الحسن","x":"وقيل للحسن: نراك طويل البكاء! فقال: أخاف أن يطرحني في النار، ولا يبالي.","pg":51},{"h":"الآمر بالمعروف ولا يأتيه","x":"فيقول: كنت آمركم بالمعروف ولا آتيه وأنهاكم عن المنكر وآتيه.","pg":52},{"h":"خطباء الدنيا","x":"خطباء من أهل الدنيا، كانوا يأمرون الناس بالبرّ، وينسون أنفسهم، أفلا يعقلون؟","pg":54},{"h":"الغيبة","x":"هؤلاء الذين يأكلون لحوم الناس ويقعون في أعراضهم.","pg":54},{"h":"دعاء الثبات","x":"يا مقلّب القلوب ثبّتْ قلبي على دينك","pg":54},{"h":"أول من تسعر بهم النار","x":"حديث الثلاثة: المقاتل ليقال جريء، والمتعلم والقارئ ليقال عالم وقارئ، والمنفق ليقال جواد.","pg":72},{"h":"شر الناس من تشبه بخيارهم","x":"فخير الناس بعدهم العلماء والشهداء والمتصدقون المخلصون، فشرّ الناس من تشبّه بهم، يوهم أنه منهم، وليس منهم.","pg":73},{"h":"المظالم","x":"من كانت عنده لأخيه مظلمة في مال أو عِرض، فَلْيأتِه، فَلْيستحِلَّها منه قبل أن يؤخذ، وليس عنده دينار ولا درهم.","pg":73},{"h":"قول ابن عقيل","x":"احذرْه ولا تغترّ؛ فإنّه قطع اليد في ثلاثة دراهم، وجلد الحدّ في مثل رأس الإبرة من الخمر، وقد دخلت امرأةٌ النارَ في هرّة.","pg":75},{"h":"الكلمة الواحدة","x":"وهذه الكلمة الواحدة يتكلّم بها العبد يهوي بها في النار أبعد ما بين المشرق والمغرب.","pg":76},{"h":"الاغترار بالنعم","x":"وربما اتكل بعض المغترين على ما يرى من نعم الله عليه في الدنيا، وأنه لا يغيّر به، ويظنّ أنّ ذلك من محبة الله له، وأنه يعطيه في الآخرة أفضل من ذلك. وهذا من الغرور.","pg":77},{"h":"الاستدراج","x":"إذا رأيت الله يتابع نعمه عليك، وأنت مقيم على معاصيه، فاحذره؛ فإنما هو استدراج يستدرجك به.","pg":78},{"h":"النعمة والابتلاء","x":"ليس كلّ من نعّمتُه ووسّعتُ عليه رزقه أكون قد أكرمتُه، ولا كلُّ من ابتليته وضيّقت عليه رزقه أكون قد أهنتُه. بل أبتلي هذا بالنعمة، وأكرم هذا بالابتلاء.","pg":78},{"h":"رب مستدرج","x":"ربّ مستدرَجٍ بنعم الله عليه، وهو لا يعلم؛ وربّ مغرورٍ بستر الله عليه، وهو لا يعلم؛ وربّ مفتونٍ بثناء الناس عليه، وهو لا يعلم.","pg":79}],"hd":"حديث أسامة «يُجاء بالرجل يوم القيامة فيُلقى في النار»: رواه البخاري 3267 ومسلم 2989. حديث «خطباء من أهل الدنيا»: رواه أحمد 12211، وله طريق قال المحقق: وسنده صحيح. حديث «أظفار من نحاس»: رواه أحمد 13340 وأبو داود 4878، رجاله ثقات وصححه الضياء. حديث «يا مقلب القلوب»: رواه الترمذي 2140، صححه الترمذي والحاكم والضياء. حديث صبغ أنعم أهل الدنيا: رواه مسلم 2807. حديث البراء الطويل في القبر: رواه أبو داود 4753 وأحمد 18534، صححه جماعة منهم أبو عوانة وابن خزيمة وابن منده والحاكم والبيهقي. حديث الجنازة «قدّموني»: رواه البخاري 1314. حديث أبي أمامة «تدنو الشمس»: رواه أحمد 22186، والحديث ثابت عن المقداد عند مسلم 2864. حديث «من تعظّم في نفسه»: رواه أحمد 5995 والبخاري في الأدب المفرد 549، قال الحاكم: صحيح على شرط الشيخين. حديث المصورين: رواه البخاري 2105 ومسلم 2108. حديث عرض المقعد: رواه البخاري 1379 ومسلم 2866. حديث ذبح الموت: رواه البخاري 6548 ومسلم 2850. حديث «من شرب الخمر لم يقبل الله له صلاة أربعين صباحًا»: رواه أحمد 6644 وابن ماجه 3377، سنده صحيح وصححه ابن حبان. حديث «كل مسكر حرام»: رواه مسلم 2002. حديث «إياكم ومحقرات الذنوب»: رواه أحمد 3818، وتكلم المحقق في طريقيه وأشار إلى أن رواية ابن عيينة عن إبراهيم الهجري تقتضي صحة حديثه عنه. حديث الصراط: رواه البخاري 6573 ومسلم 182. حديث الثلاثة: رواه مسلم 1905. حديث المظلمة: رواه البخاري 2449. حديث «من أخذ شبرًا من الأرض»: رواه البخاري 2454 و3196، ومسلم 1611 من حديث أبي هريرة بلفظ «طوقه الله». حديث «ناركم هذه»: رواه البخاري 3265 ومسلم 2843. أثر «دخل رجل الجنة في ذباب»: رواه أحمد في الزهد 84، وروي عن سلمان نحوه، قال المحقق: وسنده صحيح. حديث الكلمة: رواه البخاري 6477 ومسلم 2988. حديث «إذا رأيت الله يعطي العبد من الدنيا على معاصيه ما يحب فإنما هو استدراج»: رواه أحمد 17311، وحسّنه العراقي، وقال المحقق: وهذا يدل على ثبوت هذا الحديث. أثر «رب مستدرج»: رواه أحمد في الزهد 1606 عن الحسن بمعناه، وسنده صحيح. وانظر الأحاديث الضعيفة في هذا الفصل في قائمة weak.","weak":1},{"t":"فصل: وأعظم الخلق غرورًا من اغترّ بالدنيا وعاجلها","pg":79,"lv":"adl","key":"وأعظم الخلق غرورًا من اغترّ بالدنيا وعاجلها، فآثرها على الآخرة، ورضي بها من الآخرة","p":["حتى يقول بعض هؤلاء: الدنيا نقد، والآخرة نسيئة، والنقد أنفع من النسيئة! ويقول بعضهم: ذرّة منقودة، ولا درّة موعودة! ويقول آخر منهم: لذاتُ الدنيا متيقّنة، ولذات الآخرة مشكوك فيها، ولا أدع اليقين للشك!","وهذا من أعظم تلبيس الشيطان وتسويله. والبهائم العُجم أعقل من هؤلاء، فإنّ البهيمة إذا خافت مضرةَ شيء لم تُقدِم عليه ولو ضُربت."],"items":[{"h":"جواب النقد والنسيئة","x":"فكيف والدنيا كلّها من أولها إلى آخرها كنفس واحد من أنفاس الآخرة!","pg":80},{"h":"الغبن","x":"فإيثار هذا النقد على هذه النسيئة من أعظم الغبن وأقبح الجهل.","pg":81},{"h":"جواب الشاك","x":"وإن كنتَ على شك، فراجعْ آيات الربّ تعالى الدالّة على وجوده وقدرته ومشيئته ووحدانيته، وصدق رسُله فيما أخبروا به عنه.","pg":81},{"h":"الإنسان دليل نفسه","x":"وأنّ الإنسان دليل لنفسه على وجود خالقه، وتوحيده، وصدق رسله، وإثبات صفات كماله.","pg":83},{"h":"مغرور على التقديرين","x":"فقد بان أنّ المضيّع مغرور على التقديرين: تقدير تصديقه ويقينه، وتقدير تكذيبه وشكّه.","pg":83}],"hd":"حديث «ما الدنيا في الآخرة إلا كما يدخل أحدكم إصبعه في اليم»: رواه مسلم 2858 وأحمد 18008 والترمذي 2322.","weak":1},{"t":"أسباب تخلف العمل مع التصديق بالمعاد","pg":83,"lv":"adl","key":"وجِماعُ هذه الأسباب يرجع إلى ضعف البصيرة والصبر.","p":["فإن قلت: كيف يجتمع التصديق الجازم الذي لا شك فيه بالمعاد والجنة والنار، ويتخلف العمل؟ قيل: هذا لعَمرُ الله سؤال صحيح وارد على أكثر هذا الخلق. واجتماعُ هذين الأمرين من أعجب الأشياء.","أحدها: ضعف العلم ونقصان اليقين. ومن ظنّ أن العلم لا يتفاوت، فقوله من أفسد الأقوال وأبطلها."],"items":[{"h":"ضعف العلم ونقصان اليقين","x":"أحدها: ضعف العلم ونقصان اليقين.","pg":84},{"h":"غيبة العلم عن القلب","x":"عدمُ استحضاره وغيبتُه عن القلب في كثير من أوقاته أو أكثرها، لاشتغاله بما يضادّه","pg":85},{"h":"تقاضي الطبع وغلبات الهوى","x":"تقاضي الطبع، وغلَبات الهوى، واستيلاءُ الشهوة","pg":85},{"h":"تسويل النفس وغرور الشيطان","x":"وتسويلُ النفس، وغرورُ الشيطان، واستبطاءُ الوعد","pg":85},{"h":"طول الأمل والغفلة","x":"وطولُ الأمل، ورقدةُ الغفلة، وحبُّ العاجلة","pg":85},{"h":"رخص التأويل وإلف العوائد","x":"ورُخَصُ التأويل، وإلفُ العوائد","pg":85},{"h":"مدح أهل الصبر واليقين","x":"ولهذا مدح الله سبحانه أهل الصبر واليقين، وجعلهم أئمة الدين، فقال تعالى: ﴿وَجَعَلْنَا مِنْهُمْ أَئِمَّةً يَهْدُونَ بِأَمْرِنَا لَمَّا صَبَرُوا وَكَانُوا بِآيَاتِنَا يُوقِنُونَ﴾ [السجدة: 24].","pg":85}],"hd":"حديث «ليس الخبر كالمعاينة»: رواه أحمد 1842 وابن حبان 6214 والحاكم، وصححه ابن حبان والحاكم ووافقه الذهبي.","weak":1},{"t":"فصل: الفرق بين حسن الظن والغرور","pg":86,"lv":"kid","key":"وحسن الظن هو الرجاء. فمن كان رجاؤه حاديًا له على الطاعة، زاجرًا له عن المعصية، فهو رجاء صحيح.","p":["فقد تبين الفرق بين حسن الظن والغرور، وأنّ حسن الظن إن حمل على العمل، وحثّ عليه، وساق إليه، فهو صحيح. وإن دعا إلى البطالة والانهماك في المعاصي، فهو غرور.","ولو أن رجلًا له أرض يؤمّل أن يعود عليه من مُغَلّها ما ينفعه فأهملها، ولم يبذرها، ولم يحرثها، وأحسن ظنه بأنه يأتي من مغلّها ما يأتي مَن حرث، وبذر، وسقى، وتعاهد الأرض، لعدّه الناس من أسفه السفهاء.","وسرّ المسألة أنّ الرجاء وحسن الظن إنما يكون مع الإتيان بالأسباب التي اقتضتها حكمة الله في شرعه، وقدَره، وثوابه وكرامته."],"items":[{"h":"مثل طالب العلم","x":"أو يصير أعلمَ أهل زمانه من غير طلب للعلم وحرص تامّ عليه، وأمثال ذلك.","pg":86},{"h":"الدرجات العلى","x":"فكذلك من حسّن ظنه وقوي رجاؤه في الفوز بالدرجات العلى والنعيم المقيم، من غير طاعة ولا تقرب إلى الله تعالى بامتثال أوامره واجتناب نواهيه.","pg":87},{"h":"الرجاء إتيان الطاعات","x":"فتأمّلْ كيف جعل رجاءَهم إتيانَهم بهذه الطاعات!","pg":87}],"hd":""},{"t":"فصل: لوازم الرجاء","pg":87,"lv":"adl","key":"فكلُّ راجٍ خائفٌ، والسائر على الطريق إذا خاف أسرعَ السيرَ مخافةَ الفوات.","p":["ومما ينبغي أن يعلم أنّ من رجا شيئًا استلزم رجاؤه أمورًا: أحدها: محبة ما يرجوه. الثاني: خوفه من فواته. الثالث: سعيه في تحصيله بحسب الإمكان.","وأما رجاءٌ لا يقارنه شيء من ذلك، فهو من باب الأماني! والرجاء شيء، والأماني شيء آخر."],"items":[{"h":"المحبة","x":"أحدها: محبة ما يرجوه.","pg":87},{"h":"الخوف","x":"الثاني: خوفه من فواته.","pg":87},{"h":"السعي","x":"الثالث: سعيه في تحصيله بحسب الإمكان.","pg":88},{"h":"الخوف والرجاء النافع","x":"فعُلم أنّ الرجاء والخوف النافع هو ما اقترن به العمل.","pg":89}],"hd":"حديث «من خاف أدلج»: رواه الترمذي 2450 وقال: حسن غريب، وفيه يزيد بن سنان ضعيف الحفظ، وطريق أبي بن كعب قال فيه المحقق: لا يثبت إسناده. فلا يبنى عليه.","weak":1},{"t":"وصف أهل السعادة بالإحسان مع الخوف، وخوف الصحابة من النفاق","pg":91,"lv":"adl","key":"ومن تأمل أحوال الصحابة رضي الله عنهم وجدهم في غاية العمل مع غاية الخوف. ونحن جمعنا بين التقصير، بل التفريط، والأمن!","p":["والله سبحانه وصف أهل السعادة بالإحسان مع الخوف، ووصف الأشقياء بالإساءة مع الأمن.","وقال ابن أبي مليكة: أدركتُ ثلاثين من أصحاب النبي ﷺ كلُّهم يخاف النفاقَ على نفسه، ما منهم أحد يقول إنه على إيمان جبريل وميكائيل."],"items":[{"h":"آية المؤمنون","x":"﴿وَالَّذِينَ يُؤْتُونَ مَا آتَوا وَّقُلُوبُهُمْ وَجِلَةٌ أَنَّهُمْ إِلَىٰ رَبِّهِمْ رَاجِعُونَ﴾ [المؤمنون: 60]","pg":89},{"h":"أبو بكر ولسانه","x":"وذكر عنه أنه كان يمسك بلسانه ويقول: هذا أوردني الموارد!","pg":91},{"h":"ابن عباس","x":"وددتُ أنّي أنجو، لا أجرَ ولا وِزر.","pg":93},{"h":"علي وطول الأمل","x":"فأما طول الأمل فيُنسي الآخرة، وأما اتباع الهوى فيصدّ عن الحق.","pg":94},{"h":"أبو الدرداء","x":"إنّ أشدّ ما أخاف على نفسي يوم القيامة أن يقال لي: يا أبا الدرداء قد علمتَ، فكيف عملتَ فيما علمتَ؟","pg":95},{"h":"تميم الداري","x":"وقرأ تميم الداري ليلةً سورة الجاثية، فلمّا أتى على هذه الآية ﴿أَمْ حَسِبَ الَّذِينَ اجْتَرَحُوا السَّيِّئَاتِ أَن نَّجْعَلَهُمْ كَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ﴾ جعل يردّدها ويبكي حتى أصبح.","pg":96},{"h":"إبراهيم التيمي","x":"ما عرضتُ قولي على عملي إلا خشيتُ أن أكون مكذِّبًا.","pg":96},{"h":"الحسن","x":"ما خافه إلا مؤمن، ولا أمِنه إلا منافق.","pg":97},{"h":"عمر وحذيفة","x":"أنشُدك الله، هل سمّاني لك رسول الله ﷺ؟ يعني في المنافقين، فيقول: لا، ولا أزكّي بعدك أحدًا.","pg":97},{"h":"فهم شيخ الإسلام","x":"ليس مراده أنّي لا أبرّئ غيرك من النفاق، بل المراد: لا أفتح عليّ هذا الباب، فكلّ من سألني: هل سمّاني لك رسول الله ﷺ؟ فأزكّيه.","pg":97},{"h":"سبقك بها عكاشة","x":"ولم يُرِد أنّ عكاشة وحده أحقّ بذلك ممن عداه من الصحابة. ولكن لو دعا له لقام آخر وآخر، وانفتح الباب، وربّما قام من لم يستحق أن يكون منهم. فكان الإمساك أولى.","pg":97}],"hd":"حديث عائشة في تفسير آية المؤمنون: رواه الترمذي 3175، قال المحقق: هذا الإسناد ضعيف للإرسال، ولا يثبت سنده عن عائشة. أثر أبي بكر «هذا أوردني الموارد»: رواه مالك في الموطأ 2825، وسنده صحيح. أثر ابن عباس «لا أجر ولا وزر»: رواه أحمد في الزهد 697، وسنده صحيح. حديث عثمان في القبر: رواه الترمذي 2308 وقال: حسن غريب، وصححه الحاكم. أثر علي: علّقه البخاري بصيغة الجزم في كتاب الرقاق. أثر ابن عباس في الدموع: سنده حسن. أثر تميم الداري: سنده صحيح إلى مسروق. أثر ابن أبي مليكة: رواه البخاري في تاريخه وأحمد في الزهد، وسنده صحيح. أثر الحسن: قال ابن رجب: صحيح عنه. أثر عمر وحذيفة: قال ابن حجر: إسناده صحيح. حديث «سبقك بها عكاشة»: رواه البخاري 6542 ومسلم 216.","weak":1}],"lv":{"kid":{"show":true,"title":"أرجو الله وأعمل","intro":"الله رحيم كريم يحب أن نرجوه ونحسن الظن به. لكن الرجاء الصادق مثل الفلاح الذي يحرث أرضه ويزرعها ثم يرجو المطر والثمر. أما من يترك العمل ويقول الله كريم فهو مخدوع، وليس راجيًا حقًا.","points":["حسن الظن بالله يجعلني أعمل الخير أكثر.","من يرجو شيئًا يحبه ويخاف أن يفوته ويسعى إليه.","الاستغفار الصادق معه ندم وترك للذنب.","الصحابة كانوا يعملون كثيرًا ويخافون الله كثيرًا.","التمني بلا عمل ليس رجاء."],"quote":{"x":"وكلّما حسُن ظنُّه حسُن عملُه","pg":48},"quiz":[{"q":"متى يكون حسن الظن بالله صادقًا؟","o":["إذا عملت الخير ورجوت قبوله","إذا تركت الصلاة ورجوت الجنة","إذا أخّرت التوبة إلى أن أكبر","إذا كسلت وقلت إن الله كريم"],"why":"وكلّما حسُن ظنُّه حسُن عملُه","pg":48},{"q":"فلاح يريد ثمرًا كثيرًا، ماذا يفعل؟","o":["يحرث ويبذر ويسقي ثم يرجو","ينام ويرجو أن ينبت الزرع","يترك أرضه ويتمنى الثمر","يشتكي ولا يزرع شيئًا أبدًا"],"why":"فأهملها، ولم يبذرها، ولم يحرثها، وأحسن ظنه بأنه يأتي من مغلّها ما يأتي مَن حرث، وبذر، وسقى، وتعاهد الأرض، لعدّه الناس من أسفه السفهاء.","pg":86},{"q":"المسافر الذي يخاف أن يفوته الطريق، ماذا يفعل؟","o":["يسرع في السير خوف الفوات","يجلس ليستريح وقتًا طويلًا","يرجع إلى بيته ويترك السفر","يمشي ببطء ولا يبالي بالوقت"],"why":"فكلُّ راجٍ خائفٌ، والسائر على الطريق إذا خاف أسرعَ السيرَ مخافةَ الفوات.","pg":88},{"q":"كيف كان حال الصحابة رضي الله عنهم؟","o":["عمل كثير مع خوف من الله","عمل قليل مع أمن تام","كلام كثير مع عمل قليل","تمنٍّ كثير مع ترك العمل"],"why":"ومن تأمل أحوال الصحابة رضي الله عنهم وجدهم في غاية العمل مع غاية الخوف.","pg":91}],"scene":{"t":"اختبار الغد","x":"سعيد عنده اختبار غدًا، فقال لصديقه: لن أذاكر، فالله كريم وسأنجح. لو كنت صديقه فبماذا تنصحه؟","opts":["أن يذاكر دروسه ثم يدعو الله أن يوفقه","أن يلعب ويتكل على أن الله كريم","أن ينام مبكرًا ولا يفتح كتابه"],"why":"وبالجملة، فحسن الظن إنّما يكون مع انعقاد أسباب النجاة.","pg":49},"act":{"type":"sort","t":"رجاء صادق أم تمنٍّ؟","x":"اقرأ كل بطاقة، وضعها في صندوق «رجاء صادق» إذا كان صاحبها يعمل ويرجو، أو في صندوق «تمنٍّ بلا عمل» إذا كان يرجو ولا يعمل.","a":"رجاء صادق","b":"تمنٍّ بلا عمل","items":[{"x":"أصلي وأرجو أن يتقبل الله صلاتي","ok":"أ"},{"x":"أترك الصلاة وأقول الله يغفر لي","ok":"ب"},{"x":"أعتذر لأخي وأستغفر الله ولا أعود","ok":"أ"},{"x":"أكذب ثم أقول أستغفر الله وأعود للكذب","ok":"ب"},{"x":"أذاكر دروسي ثم أدعو الله بالنجاح","ok":"أ"},{"x":"أؤجل التوبة حتى أكبر","ok":"ب"},{"x":"أحب الجنة فأعمل لها كل يوم","ok":"أ"},{"x":"أتمنى الجنة ولا أعمل شيئًا","ok":"ب"}]}},"yth":{"show":true,"title":"رجاء يدفعك لا غرور يخدعك","intro":"النفس ماكرة؛ تعرف أن الذنب يضرها ثم تبحث لك عن عذر: الله غفور، سأتوب لاحقًا، الكل يفعل هذا. ابن القيم يكشف هذه الحيل واحدة واحدة، ويضع لك ميزانًا واضحًا: الرجاء الذي يدفعك إلى الطاعة ويمنعك من المعصية صحيح، والرجاء الذي يجعلك كسولًا غارقًا في الذنب غرور.","points":["سبع حيل تغالطك بها نفسك، أولها الاتكال على العفو مع الإصرار.","حسن الظن بالله هو حسن العمل نفسه.","النعمة مع المعصية قد تكون استدراجًا لا علامة رضا.","الدنيا كلها كنفس واحد من أنفاس الآخرة، فلا تبع الباقي بالفاني.","كل راج خائف، والرجاء بلا عمل أمانٍ."],"quote":{"x":"فمن كان رجاؤه حاديًا له على الطاعة، زاجرًا له عن المعصية، فهو رجاء صحيح.","pg":86},"quiz":[{"q":"متى يكون الرجاء صحيحًا عند ابن القيم؟","o":["إذا ساقك إلى الطاعة وزجرك عن المعصية","إذا أكثرت الحديث عن سعة رحمة الله","إذا اطمأننت ولم تخف من شيء أبدًا","إذا اكتفيت بالاستغفار باللسان وحده"],"why":"فمن كان رجاؤه حاديًا له على الطاعة، زاجرًا له عن المعصية، فهو رجاء صحيح.","pg":86},{"q":"ما الأمور الثلاثة التي يستلزمها الرجاء؟","o":["محبة المرجو وخوف فواته والسعي له","التمني والانتظار وترك الأسباب كلها","كثرة الحديث عن الرحمة والمغفرة","الأمن التام وترك الخوف من الفوات"],"why":"ومما ينبغي أن يعلم أنّ من رجا شيئًا استلزم رجاؤه أمورًا: أحدها: محبة ما يرجوه. الثاني: خوفه من فواته. الثالث: سعيه في تحصيله بحسب الإمكان.","pg":87},{"q":"شاب يقول عن ذنبه: كل أصحابي يفعلونه. بأي مغالطة تغالطه نفسه؟","o":["الاحتجاج بالأشباه والنظراء","التسويف بالتوبة إلى الغد","الاحتجاج بالقدر على الذنب","الاستغفار باللسان مع الإصرار"],"why":"وبالاحتجاج بالأشباه والنظراء والاقتداء بالأكابر تارة.","pg":36},{"q":"يتابع الله نعمه على إنسان وهو مقيم على معاصيه. ماذا يعني ذلك بحسب ما نقله ابن القيم؟","o":["قد يكون استدراجًا فليحذر","أن الله راضٍ عنه لا محالة","أنه سيعطى في الآخرة أفضل","أن معاصيه لا تضره شيئًا"],"why":"إذا رأيت الله يتابع نعمه عليك، وأنت مقيم على معاصيه، فاحذره؛ فإنما هو استدراج يستدرجك به.","pg":78},{"q":"إلى أي شيء يرجع جماع أسباب تخلف العمل مع التصديق بالآخرة؟","o":["ضعف البصيرة والصبر","ضعف البدن وكثرة المرض","قلة المال وكثرة الشغل","صعوبة الدين وكثرة أحكامه"],"why":"وجِماعُ هذه الأسباب يرجع إلى ضعف البصيرة والصبر.","pg":85}],"scene":{"t":"سأتوب بعدين","x":"صديقك في المدرسة يقول لك: أعرف أن هذا الفعل حرام، لكني سأتوب حين أكبر، والكل يفعل مثلي، والله غفور رحيم. ماذا تفعل؟","opts":["تذكّره برفق أن هذه حيل النفس وتدعوه إلى التوبة الآن","تسكت حتى لا تخسر صداقته","توافقه لأن الله غفور رحيم"],"why":"ولكن تغالطه نفسه بالاتكال على عفو الله ومغفرته تارة، وبالتسويف بالتوبة تارة","pg":36},"act":{"type":"match","t":"اكشف حيلة النفس","x":"صِل كل عبارة يقولها المغتر بالرد المناسب من كلام ابن القيم.","items":[{"a":"سأتوب لاحقًا","b":"التسويف بالتوبة من مغالطة النفس","pg":36},{"a":"ما دامت النعم عليّ فالله راضٍ عني","b":"النعمة مع الإقامة على المعصية قد تكون استدراجًا","pg":78},{"a":"الدنيا نقد والآخرة نسيئة","b":"الدنيا كلها كنفس واحد من أنفاس الآخرة","pg":80},{"a":"أحسن الظن بالله وأفعل ما أشاء","b":"حسن الظن بالله هو حسن العمل نفسه","pg":48},{"a":"سأصوم عرفة فتمحى كل ذنوبي","b":"التكفير بالصوم والصلاة مشروط باجتناب الكبائر","pg":42},{"a":"الكل يفعل مثلي","b":"الاحتجاج بالأشباه والنظراء مغالطة للنفس","pg":36}]}},"adl":{"show":true,"title":"فقه الرجاء بين حسن الظن والغرور","intro":"يعالج ابن القيم في هذا الموضع آفة دقيقة: أن يعرف العبد ضرر الذنب ثم تغالطه نفسه بنصوص الرجاء. فيعدد صور الاغترار، ويرد على الفهم الفاسد للآيات والأحاديث، ويقرر أن حسن الظن لا يكون إلا مع الإحسان، وأن الرجاء يستلزم محبة وخوفًا وسعيًا، ثم يختم بحال الصحابة الذين جمعوا غاية العمل مع غاية الخوف. والمربي أحوج الناس إلى هذا الميزان؛ لأنه يعالج به التسويف عند طلابه وأبنائه دون أن يقنطهم.","points":["مغالطة النفس سبع صور، منها العلم وفعل المندوبات والاحتجاج بالقدر.","نصوص الرجاء تفهم في مواضعها: آية الزمر في التائبين، والتكفير بالطاعات مشروط باجتناب الكبائر.","حسن الظن إنما يكون مع انعقاد أسباب النجاة، ومع أسباب الهلاك غرور.","تخلف العمل مع التصديق أسبابه كثيرة، وجماعها ضعف البصيرة والصبر.","الرجاء والخوف النافع ما اقترن به العمل، والصحابة خافوا النفاق مع كمال عملهم."],"quote":{"x":"فالعالم يضع الرجاء مواضعه، والجاهل المغتر يضعه في غير مواضعه.","pg":50},"quiz":[{"q":"احتج مصرّ على الكبائر بقوله تعالى ﴿إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا﴾. فما وجه الرد عند ابن القيم؟","o":["أن الآية في حق التائبين بلا خلاف","أن الآية خاصة بصغائر الذنوب وحدها","أن الآية نزلت في أهل الكتاب وحدهم","أن الآية منسوخة بنصوص الوعيد"],"why":"ولا خلاف أنّ هذه الآية في حق التائبين، فإنّه يغفر كلّ ذنب للتائب، أي ذنب كان.","pg":40},{"q":"لماذا لا يصح اتكال المصرّ على الكبائر على صوم عرفة وعاشوراء؟","o":["لأن ما هو أعظم منهما لا يكفر إلا باجتناب الكبائر","لأن صيام النوافل لا يكفر شيئًا من الذنوب أصلًا","لأن فضل صيامهما لم يثبت فيه حديث صحيح","لأن التكفير خاص بمن صامهما في الحرم المكي"],"why":"ولم يدر هذا المغتر أنّ صوم رمضان والصلوات الخمس أعظم وأجلّ من صيام يوم عرفة ويوم عاشوراء، وهي إنما تكفر ما بينها إذا اجتُنِبَت الكبائر.","pg":42},{"q":"ما معنى تقرير ابن القيم أن حسن الظن بالله هو حسن العمل نفسه؟","o":["أن حسن الظن الصادق يحمل صاحبه على العمل","أن العمل يغني عن الرجاء وحسن الظن بالكلية","أن حسن الظن يكفي ولو لم يصحبه أي عمل","أن حسن الظن شعور في القلب لا صلة له بالعمل"],"why":"فإنّ العبد إنما يحمله على حسن العمل حسنُ ظنّه بربه أن يجازيه على أعماله، ويثيبه عليها، ويتقبّلها منه.","pg":48},{"q":"قال عمر لحذيفة بعد أن نفى عنه النفاق: «ولا أزكّي بعدك أحدًا». كيف فهمها شيخ الإسلام؟","o":["أراد سد باب السؤال لا اتهام غيره بالنفاق","أراد أن كل من سواه من الصحابة منافق","أراد أن حذيفة وحده يعلم من في الجنة","أراد أن التزكية محرمة في كل الأحوال"],"why":"ليس مراده أنّي لا أبرّئ غيرك من النفاق، بل المراد: لا أفتح عليّ هذا الباب، فكلّ من سألني: هل سمّاني لك رسول الله ﷺ؟ فأزكّيه.","pg":97},{"q":"ما مراد ابن القيم بأن المضيّع مغرور على التقديرين؟","o":["أنه مغرور سواء صدّق بالمعاد أو شك فيه","أنه مغرور في الدنيا وحدها دون الآخرة","أنه مغرور إن كان عالمًا ومعذور إن جهل","أنه مغرور إن ترك الفرض لا إن ترك النفل"],"why":"فقد بان أنّ المضيّع مغرور على التقديرين: تقدير تصديقه ويقينه، وتقدير تكذيبه وشكّه.","pg":83}],"scene":{"t":"الله غفور رحيم يا أبي","x":"ابنك في المرحلة الثانوية يتهاون في صلاة الفجر، فلما نبهته قال: لماذا تشدد علي؟ الله غفور رحيم. كيف تتصرف بوصفك أبًا أو معلمًا؟","opts":["تقر معه بسعة رحمة الله، ثم تبين أن الله جعل الرجاء لأهل العمل، وتعينه عمليًا على الصلاة","تخوفه بالنار وحدها ولا تذكر له رحمة الله","تسكت وتقول له: صدقت، الله غفور رحيم"],"why":"قال تعالى: ﴿إِنَّ الَّذِينَ آمَنُوا وَالَّذِينَ هَاجَرُوا وَجَاهَدُوا فِي سَبِيلِ اللَّهِ أُولَٰئِكَ يَرْجُونَ رَحْمَتَ اللَّهِ﴾ [البقرة: 218]، فجعل هؤلاء أهل الرجاء، لا البطّالين والفاسقين.","pg":50},"act":{"type":"class","t":"محكمة الحجج: الرجاء أم الغرور","x":"نشاط صفي في 40 دقيقة يدرّب الطلاب على تمييز الرجاء الصادق من الغرور بمادة ابن القيم نفسها، دون تقنيط ولا تهوين.","items":[{"step":"تمهيد بمثل الفلاح الذي أهمل أرضه وأحسن الظن بمحصولها، وسؤال الطلاب: ما حكم الناس عليه؟ (5 دقائق)","pg":86},{"step":"توزيع الطلاب على 7 مجموعات، لكل مجموعة صورة من صور مغالطة النفس: العفو، التسويف، استغفار اللسان، المندوبات، العلم، القدر، الأشباه والأكابر. (5 دقائق)","pg":36},{"step":"كل مجموعة تكتب مثالًا واقعيًا من حياة الطلاب لهذه المغالطة، ثم تبحث في نص الفصل عن الرد. (12 دقيقة)","pg":38},{"step":"عرض سريع: المجموعة تقرأ المغالطة، وبقية الصف يحكم: رجاء أم غرور؟ مع ذكر الدليل. (10 دقائق)","pg":86},{"step":"ختام بلوازم الرجاء الثلاثة: محبة وخوف وسعي، وكتابة كل طالب خطوة عملية واحدة لهذا الأسبوع. (8 دقائق)","pg":87}]}},"alt":{}},"highlights":[{"x":"وكلّما حسُن ظنُّه حسُن عملُه","pg":48,"lv":"kid"},{"x":"وأحسنُ الناس ظنًّا بربّه أطوعُهم له.","pg":45,"lv":"kid"},{"x":"فكلُّ راجٍ خائفٌ","pg":88,"lv":"kid"},{"x":"والرجاء شيء، والأماني شيء آخر.","pg":88,"lv":"yth"},{"x":"ومن اعتمد على العفو مع الإصرار فهو كالمعاند.","pg":51,"lv":"yth"},{"x":"رجاؤك لرحمة من لا تطيعه من الخِذلان والحمق.","pg":51,"lv":"yth"},{"x":"فالعالم يضع الرجاء مواضعه، والجاهل المغتر يضعه في غير مواضعه.","pg":50,"lv":"adl"},{"x":"بل أبتلي هذا بالنعمة، وأكرم هذا بالابتلاء.","pg":78,"lv":"adl"}],"concepts":[{"term":"حسن الظن","def":"وحسن الظن هو الرجاء.","pg":86},{"term":"الرجاء الصحيح","def":"فمن كان رجاؤه حاديًا له على الطاعة، زاجرًا له عن المعصية، فهو رجاء صحيح.","pg":86},{"term":"المغرور","def":"ومن كانت بطالته رجاءً، ورجاؤه بطالةً وتفريطًا، فهو المغرور.","pg":86},{"term":"الأماني","def":"وأما رجاءٌ لا يقارنه شيء من ذلك، فهو من باب الأماني!","pg":88},{"term":"الاستدراج","def":"إذا رأيت الله يتابع نعمه عليك، وأنت مقيم على معاصيه، فاحذره؛ فإنما هو استدراج يستدرجك به.","pg":78},{"term":"لوازم الرجاء","def":"أحدها: محبة ما يرجوه. الثاني: خوفه من فواته. الثالث: سعيه في تحصيله بحسب الإمكان.","pg":87}],"stories":[{"t":"الفلاح الذي أهمل أرضه","x":"مثل ضربه ابن القيم: رجل له أرض يرجو محصولها فأهملها فلم يحرثها ولم يبذرها، ثم أحسن ظنه أن يأتيه منها ما يأتي من حرث وبذر وسقى، فهذا يعده الناس من أسفه السفهاء. وكذلك من رجا الجنة بلا طاعة.","pg":86,"lv":"kid","hd":""},{"t":"أبو بكر يمسك لسانه","x":"كان أبو بكر الصديق رضي الله عنه يمسك بلسانه ويقول: هذا أوردني الموارد!","pg":91,"lv":"adl","hd":"رواه مالك في الموطأ 2825، وسنده صحيح.","weak":1},{"t":"دنانير في بيت النبي ﷺ","x":"كانت عند عائشة رضي الله عنها دنانير في مرض النبي ﷺ فأمرها أن تفرقها، فشغلها وجعه، فلما عافاه الله سأل عنها، فدعا بها فوضعها في كفه وقال: «ما ظنّ محمد بربه لو لقي الله، وهذه عنده؟»","pg":47,"lv":"adl","hd":"رواه أحمد 24222 وابن حبان 715 بهذا اللفظ، قال المحقق: والحديث سنده صحيح، وقد صححه ابن حبان. وأما الطريق الأولى عند أحمد 24733 ففيها موسى بن جبير وسندها ضعيف.","weak":1},{"t":"عمر يسأل حذيفة","x":"كان عمر بن الخطاب رضي الله عنه يقول لحذيفة: أنشدك الله، هل سماني لك رسول الله ﷺ في المنافقين؟ فيقول: لا، ولا أزكي بعدك أحدًا. وفسره شيخ الإسلام بأنه أراد ألا يفتح باب السؤال.","pg":97,"lv":"yth","hd":"قال ابن حجر: إسناده صحيح."},{"t":"تميم الداري يردد آية حتى الصباح","x":"قرأ تميم الداري ليلة سورة الجاثية، فلما بلغ ﴿أَمْ حَسِبَ الَّذِينَ اجْتَرَحُوا السَّيِّئَاتِ﴾ جعل يرددها ويبكي حتى أصبح.","pg":96,"lv":"yth","hd":"سنده صحيح إلى مسروق."},{"t":"ثلاثون صحابيًا يخافون النفاق","x":"قال ابن أبي مليكة: أدركت ثلاثين من أصحاب النبي ﷺ كلهم يخاف النفاق على نفسه، ما منهم أحد يقول إنه على إيمان جبريل وميكائيل.","pg":96,"lv":"adl","hd":"رواه البخاري في تاريخه وأحمد في الزهد، وسنده صحيح.","weak":1},{"t":"علي وأبناء الآخرة","x":"كان علي بن أبي طالب رضي الله عنه يشتد خوفه من اثنتين: طول الأمل واتباع الهوى، ويقول: كونوا من أبناء الآخرة، ولا تكونوا من أبناء الدنيا، فإن اليوم عمل ولا حساب، وغدًا حساب ولا عمل.","pg":94,"lv":"yth","hd":"علّقه البخاري بصيغة الجزم في كتاب الرقاق."},{"t":"ابن عباس يتمنى النجاة","x":"قال ابن عباس لعمر: مصّر الله بك الأمصار وفتح بك الفتوح، فقال عمر: وددت أني أنجو، لا أجر ولا وزر.","pg":93,"lv":"adl","hd":"رواه أحمد في الزهد 697، وسنده صحيح.","weak":1},{"t":"أبو الدرداء وسؤال العلم","x":"كان أبو الدرداء يقول: إن أشد ما أخاف على نفسي يوم القيامة أن يقال لي: يا أبا الدرداء قد علمت، فكيف عملت فيما علمت؟","pg":95,"lv":"adl","hd":"رواه أحمد في الزهد 730 وأبو نعيم، ولم يذكر المحقق حكمًا.","weak":1},{"t":"دخل رجل الجنة في ذباب","x":"رجلان مرا على قوم لهم صنم لا يجوزه أحد حتى يقرب له، فقرب أحدهما ذبابًا فدخل النار، وأبى الآخر أن يقرب لغير الله فقتلوه فدخل الجنة.","pg":76,"lv":"adl","hd":"رواه أحمد في الزهد 84 عن طارق بن شهاب، وروي عن سلمان نحوه، قال المحقق: وسنده صحيح.","weak":1}],"ready":true},{"k":"s4","t":"الذنوب أصل كل شر وداء","pgs":[98,139],"q":"لماذا كان كل شر وداء في الدنيا والآخرة سببه الذنوب والمعاصي؟","essence":"الذنب سم القلب وأصل كل بلاء","kw":["سموم القلب","عقوبات الأمم","آثار المعاصي"],"daa":"الاستخفاف بالذنب والاغترار بتأخر أثره وعقوبته.","dawa":"أن يعلم العبد أن الذنوب تضر ولابد، فيتركها ويلزم التقوى التي تجلب نور العلم وسعة الرزق وتيسير الأمور.","sections":[{"t":"فصل: الذنوب تضر ولابد","pg":98,"lv":"kid","key":"فمما ينبغي أن يعلم أن الذنوب تضر ولابد، وأن ضررها في القلوب كضرر السموم في الأبدان، على اختلاف درجاتها في الضرر.","p":["فلنرجع إلى ما كنا فيه من ذكر دواء الداء الذي إن استمر أفسد دنيا العبد وآخرته.","وهل في الدنيا والآخرة شر وداء إلا وسببه الذنوب والمعاصي؟"],"items":[],"hd":""},{"t":"ما الذي أخرج الأبوين من الجنة؟ عقوبات الذنوب في الأمم","pg":98,"lv":"yth","key":"فما الذي أخرج الأبوين من الجنة دار اللذة والنعيم والبهجة والسرور إلى دار الآلام والأحزان والمصائب؟","p":["فهان على الله غاية الهوان، وسقط من عينه غاية السقوط، وحل عليه غضب الرب تعالى فأهواه، ومقته أكبر المقت فأرداه.","وما الذي أغرق فرعون وقومه في البحر، ثم نقلت أرواحهم إلى جهنم. فالأجساد للغرق، والأرواح للحرق؟"],"items":[{"h":"إبليس","x":"وما الذي أخرج إبليس من ملكوت السماء، وطرده ولعنه، ومسخ ظاهره وباطنه، فجعلت صورته أقبح صورة وأشنعها","pg":98},{"h":"قوم نوح","x":"وما الذي غرق أهل الأرض كلهم حتى علا الماء فوق رؤوس الجبال؟","pg":99},{"h":"قوم عاد","x":"وما الذي سلط الريح العقيم على قوم عاد حتى ألقتهم موتى على وجه الأرض، كأنهم أعجاز نخل خاوية","pg":99},{"h":"قوم ثمود","x":"وما الذي أرسل على قوم ثمود الصيحة حتى قطعت قلوبهم في أجوافهم، وماتوا عن آخرهم؟","pg":99},{"h":"قوم لوط","x":"رفع الله قراهم ثم قلبها عليهم وأتبعهم حجارة من السماء، فجمع عليهم من العقوبة ما لم يجمعه على أمة غيرهم.","pg":100},{"h":"قوم شعيب","x":"وما الذي أرسل على قوم شعيب سحاب العذاب كالظلل، فلما صار فوق رؤوسهم أمطر عليهم نارا تلظى؟","pg":100},{"h":"قارون","x":"وما الذي خسف بقارون وداره وماله وأهله؟","pg":100},{"h":"بنو إسرائيل","x":"سلط الله عليهم أولي بأس شديد مرة بعد مرة، وأنواع العقوبات مرة بالقتل والسبي وخراب البلاد، ومرة بجور الملوك، ومرة بالمسخ، وآخر ذلك قسم الرب: ﴿لَيَبْعَثَنَّ عَلَيْهِمْ إِلَىٰ يَوْمِ الْقِيَامَةِ مَن يَسُومُهُمْ سُوءَ الْعَذَابِ﴾ (الأعراف: 167).","pg":101}],"hd":""},{"t":"آثار السلف وأحاديث في هلاك الأمم بالمعاصي","pg":101,"lv":"adl","key":"ويحك يا جبير، ما أهون الخلق على الله عز وجل إذا أضاعوا أمره! بينما هي أمة قاهرة ظاهرة لهم الملك، تركوا أمر الله، فصاروا إلى ما ترى!","p":["لن يهلك الناس حتى يعذروا من أنفسهم","إذا ظهرت المعاصي في أمتي عمهم الله بعذاب من عنده. فقلت: يا رسول الله أما فيهم يومئذ أناس صالحون؟ قال: بلى. قالت: فكيف يصنع بأولئك؟ قال: يصيبهم ما أصاب الناس، ثم يصيرون إلى مغفرة من الله ورضوان"],"items":[{"h":"تداعي الأمم","x":"يوشك أن تتداعى عليكم الأمم من كل أفق، كما تتداعى الأكلة على قصعتها... ولكنكم غثاء كغثاء السيل. تنزع المهابة من قلوب عدوكم، ويجعل في قلوبكم الوهن. قالوا: وما الوهن؟ قال: حب الحياة، وكراهة الموت","pg":104},{"h":"الحسن البصري","x":"إن الفتنة والله ما هي إلا عقوبة من الله عز وجل على الناس.","pg":115},{"h":"دانيال وبختنصر","x":"وقال بختنصر لدانيال: ما الذي سلطني على قومك؟ قال: عظم خطيئتك، وظلم قومي أنفسهم.","pg":115},{"h":"الفضيل بن عياض","x":"أوحى الله إلى بعض الأنبياء: إذا عصاني من يعرفني سلطت عليه من لا يعرفني.","pg":117},{"h":"الزلزلة على عهد عمر","x":"زلزلت المدينة على عهد عمر، فقال: يا أيها الناس ما هذا؟ ما أسرع ما أحدثتم، لئن عادت لا أساكنكم فيها.","pg":112},{"h":"كعب","x":"إنما تزلزل الأرض إذا عمل فيها بالمعاصي، فترعد فرقا من الرب جل جلاله أن يطلع عليها.","pg":112},{"h":"عمر بن عبدالعزيز","x":"أما بعد، فإن هذا الرجف شيء يعاتب الله عز وجل به العباد.","pg":112},{"h":"ترك الجهاد والتبايع بالعينة","x":"إذا ضن الناس بالدينار والدرهم، وتبايعوا بالعينة، واتبعوا أذناب البقر، وتركوا الجهاد في سبيل الله، أنزل الله بهم بلاء، فلا يرفعه حتى يراجعوا دينهم","pg":115},{"h":"بريد الكفر","x":"المعاصي بريد الكفر، كما أن القبلة بريد الجماع، والغناء بريد الزنا، والنظر بريد العشق، والمرض بريد الموت.","pg":125},{"h":"ما يتبع الذنب","x":"ولما يتبع الذنب أعظم من الذنب إذا عملته: قلة حيائك ممن على اليمين وعلى الشمال، وأنت على الذنب، أعظم من الذنب. وضحكك، وأنت لا تدري ما الله صانع بك، أعظم من الذنب. وفرحك بالذنب إذا ظفرت به أعظم من الذنب.","pg":126}],"hd":"أثر أبي الدرداء: سنده صحيح. «لن يهلك الناس حتى يعذروا من أنفسهم»: أبو داود 4347 وأحمد، وسنده صحيح. «إذا ظهرت المعاصي في أمتي»: حديث أم سلمة في المسند، رجح المحقق طريقا منه وقال: فالإسناد صحيح. «يوشك أن تتداعى عليكم الأمم»: المسند، وسنده لا بأس به. «إذا ضن الناس بالدينار والدرهم»: صححه ابن القطان، وجود شيخ الإسلام إسنادي أحمد وأبي داود، وحسنه المؤلف، وصححه الألباني بمجموع طرقه، وأعل ابن حجر طريق الأعمش. أثر الحسن: سنده صحيح. أثر صفية في زلزلة المدينة: سنده صحيح. أثر عمر بن عبدالعزيز: سنده صحيح. أثر ابن عباس «يا صاحب الذنب»: من طريق جويبر وهو ضعيف جدا، والضحاك لم يسمع من ابن عباس.","weak":1},{"t":"ترك الأمر بالمعروف والنهي عن المنكر سبب لعموم العقوبة","pg":120,"lv":"adl","key":"إن الناس إذا رأوا الظالم، فلم يأخذوا على يديه، أوشك أن يعمهم الله بعقاب من عنده","p":["إن من غفلتك عن نفسك وإعراضك عن الله أن ترى ما يسخط الله، فتتجاوزه، ولا تأمر فيه، ولا تنهى عنه، خوفا ممن لا يملك ضرا ولا نفعا.","من ترك الأمر بالمعروف والنهي عن المنكر مخافة من المخلوقين نزعت منه الطاعة، ولو أمر ولده أو بعض مواليه لاستخف بحقه."],"items":[{"h":"أبو بكر الصديق","x":"أيها الناس إنكم تتلون هذه الآية، وإنكم تضعونها على غير مواضعها: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا عَلَيْكُمْ أَنفُسَكُمْ لَا يَضُرُّكُم مَّن ضَلَّ إِذَا اهْتَدَيْتُمْ﴾","pg":121},{"h":"حديث جرير","x":"ما من قوم يعمل فيهم بالمعاصي، هم أعز وأكثر ممن يعمله، لم يغيروه، إلا عمهم الله بعقاب","pg":123},{"h":"الرجل الذي لم يتمعر وجهه","x":"بعث الله عز وجل ملكين إلى قرية أن دمراها بمن فيها، فوجدا فيها رجلا قائما يصلي في مسجد، فقالا: يا رب إن فيها عبدك فلانا يصلي. فقال الله عز وجل: دمراها، ودمراه معها، فإنه ما تمعر وجهه في قط.","pg":109},{"h":"حبر بني إسرائيل","x":"رأى بعض بنيه يغمز النساء فقال: مهلا يا بني. فأوحى الله إلى نبيهم: ما كان غضبك لي إلا أن قلت: مهلا يا بني، مهلا يا بني!","pg":124}],"hd":"حديث أبي بكر: أبو داود 4338 والترمذي وابن ماجه وغيرهم، وسنده صحيح، وصححه الترمذي وابن حبان والنووي. أثر العمري: سنده حسن. حديث جرير: المسند وأبو داود وابن ماجه، فيه عبيدالله بن جرير مقبول، وله شواهد. خبر الملكين: في سنده ضعف إلى أبي هزان، وجاء نحوه عن مسعر بسند حسن إليه، ولا يصح مرفوعا.","weak":1},{"t":"محقرات الذنوب: لا تنظر إلى صغر الخطيئة","pg":124,"lv":"kid","key":"لا تنظر إلى صغر الخطيئة، ولكن انظر من عصيت","p":["بقدر ما يصغر الذنب عندك، يعظم عند الله. وبقدر ما يعظم عندك، يصغر عند الله.","إنكم لتعملون أعمالا هي أدق في أعينكم من الشعر، إن كنا لنعدها على عهد رسول الله ﷺ من الموبقات."],"items":[{"h":"المرأة والهرة","x":"عذبت امرأة في هرة حبستها حتى ماتت، فدخلت النار. لا هي أطعمتها، ولا سقتها، ولا تركتها تأكل من خشاش الأرض","pg":125},{"h":"حذيفة","x":"قيل له: في يوم واحد تركت بنو إسرائيل دينهم؟ قال: لا، ولكنهم كانوا إذا أمروا بشيء تركوه، وإذا نهوا عن شيء ركبوه، حتى انسلخوا من دينهم، كما ينسلخ الرجل من قميصه.","pg":125}],"hd":"قول بلال بن سعد: سنده صحيح. أثر أنس: البخاري 6492. حديث الهرة: في الصحيحين، تقدم تخريجه في ص 57. أثر حذيفة: سنده صحيح. «إياكم ومحقرات الذنوب» المذكور ص 124: تقدم تخريجه في ص 70."},{"t":"النكتة السوداء والران","pg":127,"lv":"adl","key":"إن المؤمن إذا أذنب نكتت في قلبه نكتة سوداء، فإن تاب، ونزع، واستغفر، صقل قلبه. وإن زاد زادت حتى تعلو قلبه، فذلك الران الذي ذكر الله عز وجل: ﴿كَلَّا ۖ بَلْ ۜ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُوا يَكْسِبُونَ﴾","p":["إذا أذنب العبد نكت في قلبه نكتة سوداء حتى يصير قلبه كالشاة الربداء."],"items":[{"h":"وهب بن منبه","x":"إني إذا أطعت رضيت، وإذا رضيت باركت، وليس لبركتي نهاية. وإذا عصيت غضبت، وإذا غضبت لعنت، ولعنتي تبلغ السابع من الولد.","pg":128},{"h":"عائشة إلى معاوية","x":"أما بعد، فإن العبد إذا عمل بمعصية الله عاد حامده من الناس ذاما.","pg":129},{"h":"أبو الدرداء","x":"إن العبد يخلو بمعاصي الله، فيلقي الله بغضه في قلوب المؤمنين، من حيث لا يشعر.","pg":129}],"hd":"حديث النكتة: أحمد والترمذي وابن ماجه وابن حبان والحاكم، وقال الترمذي: هذا حديث صحيح. أثر حذيفة: سنده صحيح. أثر عائشة: موقوف عليها، ورفعه لا يثبت. أثر أبي الدرداء: في سنده انقطاع.","weak":1},{"t":"نكتة دقيقة يغلط فيها الناس في أمر الذنب","pg":130,"lv":"yth","key":"وهاهنا نكتة دقيقة يغلط فيها الناس في أمر الذنب، وهي أنهم لا يرون تأثيره في الحال، وقد يتأخر تأثيره فينسى، ويظن العبد أنه لا يغبر بعد ذلك","p":["وما أكثر المغترين بها من العلماء، فضلا عن الجهال! ولم يعلم المغتر أن الذنب ينقض، ولو بعد حين؛ كما ينقض السم، وكما ينقض الجرح المندمل على الغش والدغل.","هذا، مع أن للذنب نقدا معجلا لا يتأخر عنه."],"items":[{"h":"ابن سيرين","x":"أنه لما ركبه الدين اغتم لذلك، فقال: إني لأعرف هذا الغم بذنب أصبته منذ أربعين سنة!","pg":130},{"h":"البيت","x":"إذا لم يغبر حائط في وقوعه ... فليس له بعد الوقوع غبار","pg":130},{"h":"أبو الدرداء","x":"اعبدوا الله كأنكم ترونه، وعدوا أنفسكم في الموتى، واعلموا أن قليلا يغنيكم خير من كثير يلهيكم. واعلموا أن البر لا يبلى، وأن الإثم لا ينسى.","pg":131},{"h":"سليمان التيمي","x":"إن الرجل ليصيب الذنب في السر، فيصبح وعليه مذلته.","pg":131},{"h":"يحيى بن معاذ","x":"عجبت من ذي عقل يقول في دعائه: اللهم لا تشمت بي الأعداء، ثم هو يشمت بنفسه كل عدو له! قيل: وكيف ذلك؟ قال: يعصي الله فيشمت به في القيامة كل عدو.","pg":131}],"hd":"أثر سليمان التيمي: سنده صحيح. أثر أبي الدرداء: رجاله ثقات وفي سنده انقطاع، وله طرق."},{"t":"فصل: حرمان العلم وحرمان الرزق","pg":132,"lv":"kid","key":"وللمعاصي من الآثار القبيحة المذمومة المضرة بالقلب والبدن في الدنيا والآخرة ما لا يعلمه إلا الله. فمنها: حرمان العلم، فإن العلم نور يقذفه الله في القلب، والمعصية تطفئ ذلك النور.","p":["ولما جلس الشافعي بين يدي مالك وقرأ عليه أعجبه ما رأى من وفور فطنته، وتوقد ذكائه، وكمال فهمه؛ فقال: إني أرى الله قد ألقى على قلبك نورا، فلا تطفئه بظلمة المعصية.","ومنها: حرمان الرزق... وكما أن تقوى الله مجلبة للرزق، فترك التقوى مجلبة للفقر. فما استجلب رزق الله بمثل ترك المعاصي."],"items":[{"h":"بيت الشافعي","x":"شكوت إلى وكيع سوء حفظي ... فأرشدني إلى ترك المعاصي / وقال اعلم بأن العلم فضل ... وفضل الله لا يؤتاه عاص","pg":132},{"h":"الحديث","x":"إن العبد ليحرم الرزق بالذنب يصيبه","pg":133}],"hd":"«إن العبد ليحرم الرزق بالذنب يصيبه»: في المسند من حديث ثوبان، تقدم تخريجه في ص 12 (خارج هذا الجزء)."},{"t":"وحشة العاصي بينه وبين الله، وبينه وبين الناس","pg":133,"lv":"kid","key":"ومنها: وحشة يجدها العاصي في قلبه بينه وبين الله، لا يوازنها ولا يقارنها لذة أصلا. ولو اجتمعت له لذات الدنيا بأسرها لم تف بتلك الوحشة.","p":["فلو لم يترك الذنوب إلا حذرا من وقوع تلك الوحشة، لكان العاقل حريا بتركها.","وليس على القلب أمر من وحشة الذنب على الذنب، فالله المستعان."],"items":[{"h":"البيت","x":"إذا كنت قد أوحشتك الذنوب ... فدعها إذا شئت واستأنس","pg":133},{"h":"الوحشة بينه وبين الناس","x":"ومنها: الوحشة التي تحصل له بينه وبين الناس، ولا سيما أهل الخير منهم؛ فإنه يجد وحشة بينه وبينهم؛ وكلما قويت تلك الوحشة بعد منهم ومن مجالستهم، وحرم بركة الانتفاع بهم، وقرب من حزب الشيطان بقدر ما بعد من حزب الرحمن.","pg":134},{"h":"بعض السلف","x":"إني لأعصي الله، فأرى ذلك في خلق دابتي وامرأتي.","pg":134}],"hd":""},{"t":"تعسير الأمور وظلمة القلب","pg":134,"lv":"adl","key":"ومنها: تعسير أموره عليه. فلا يتوجه لأمر إلا يجده مغلقا دونه، أو متعسرا عليه. وهذا كما أن من اتقى الله جعل له من أمره يسرا، فمن عطل التقوى جعل له من أمره عسرا.","p":["ويالله العجب! كيف يجد العبد أبواب الخير والمصالح مسدودة عنه، وطرقها معسرة عليه، وهو لا يعلم من أين أتي؟!","ومنها: ظلمة يجدها في قلبه حقيقة، يحس بها كما يحس بظلمة الليل البهيم إذا ادلهم، فتصير ظلمة المعصية لقلبه كالظلمة الحسية لبصره. فإن الطاعة نور، والمعصية ظلمة، وكلما قويت الظلمة ازدادت حيرته، حتى يقع في البدع والضلالات والأمور المهلكة، وهو لا يشعر، كأعمى خرج في ظلمة الليل يمشي وحده."],"items":[{"h":"ابن عباس","x":"إن للحسنة ضياء في الوجه، ونورا في القلب، وسعة في الرزق، وقوة في البدن، ومحبة في قلوب الخلق. وإن للسيئة سوادا في الوجه، وظلمة في القلب، ووهنا في البدن، ونقصا في الرزق، وبغضة في قلوب الخلق.","pg":135}],"hd":"قول ابن عباس: لم يقف عليه المحقق، وورد نحوه عن الحسن البصري بسند صحيح، وعن مالك بن دينار وإبراهيم بن أدهم، وروي عن أنس مرفوعا وقال أبو حاتم: حديث منكر.","weak":1},{"t":"المعاصي توهن القلب والبدن، وحرمان الطاعة","pg":136,"lv":"yth","key":"ومنها: أن المعاصي توهن القلب والبدن. أما وهنها للقلب، فأمر ظاهر بل لا تزال توهنه حتى تزيل حياته بالكلية.","p":["وأما وهنها للبدن، فإن المؤمن قوته من قلبه، وكلما قوي قلبه قوي بدنه. وأما الفاجر، فإنه وإن كان قوي البدن، فهو أضعف شيء عند الحاجة، فتخونه قوته أحوج ما يكون إلى نفسه.","ومنها: حرمان الطاعة. فلو لم يكن للذنب عقوبة إلا أنه يصد عن طاعة تكون بدله، ويقطع طريق طاعة أخرى، فينقطع عليه طريق ثالثة، ثم رابعة، وهلم جرا. فينقطع عليه بالذنب طاعات كثيرة، كل واحدة منها خير له من الدنيا وما عليها."],"items":[{"h":"المثال","x":"وهذا كرجل أكل أكلة أوجبت له مرضة طويلة منعته من عدة أكلات أطيب منها، فالله المستعان.","pg":136},{"h":"فارس والروم","x":"وتأمل قوة أبدان فارس والروم، كيف خانتهم أحوج ما كانوا إليها؛ وقهرهم أهل الإيمان بقوة أبدانهم وقلوبهم؟","pg":136}],"hd":""},{"t":"المعاصي تقصر العمر وتمحق بركته","pg":137,"lv":"yth","key":"ومنها: أن المعاصي تقصر العمر، وتمحق بركته، ولابد؛ فإن البر كما يزيد في العمر، فالفجور يقصر العمر.","p":["فالحياة في الحقيقة حياة القلب، وعمر الإنسان مدة حياته، فليس عمره إلا أوقات حياته بالله، فتلك ساعات عمره. فالبر والتقوى والطاعة تزيد في هذه الأوقات التي هي حقيقة عمره، ولا عمر له سواها.","وسر المسألة أن عمر الإنسان مدة حياته، ولا حياة له إلا بإقباله على ربه، والتنعم بحبه وذكره، وإيثار مرضاته."],"items":[{"h":"القول الأول","x":"نقصان عمر العاصي هو ذهاب بركة عمره ومحقها عليه. وهذا حق، وهو بعض تأثير المعاصي.","pg":137},{"h":"القول الثاني","x":"بل تنقصه حقيقة، كما ينقص الرزق. فجعل الله سبحانه للبركة في الرزق أسبابا تكثره وتزيده، وللبركة في العمر أسبابا تكثره وتزيده.","pg":137},{"h":"ضياع الحياة الحقيقية","x":"فالعبد إذا أعرض عن الله، واشتغل بالمعاصي، ضاعت عليه أيام حياته الحقيقية التي يجد غب إضاعتها يوم يقول: ﴿يَا لَيْتَنِي قَدَّمْتُ لِحَيَاتِي﴾","pg":138}],"hd":""}],"lv":{"kid":{"show":true,"title":"ذنبي يؤذي قلبي","intro":"القلب مثل الجسم، يمرض إذا دخله شيء ضار. والذنب يضر القلب كما يضر السم الجسم. لكن الله رحيم، فإذا تاب الإنسان واستغفر نظف قلبه وعاد مضيئا. والطاعة نور يملأ القلب، يفتح أبواب العلم والرزق، ويجعل الأمور سهلة.","points":["الذنب يترك في القلب نقطة سوداء، والتوبة تمسحها.","الطاعة نور، والمعصية ظلمة.","ترك المعاصي يعين على الحفظ والفهم.","التقوى تجلب الرزق وتيسر الأمور.","لا أنظر إلى صغر الخطأ، بل أتذكر أنني أطيع الله أو أعصيه."],"quote":{"x":"فإن الطاعة نور، والمعصية ظلمة","pg":135},"quiz":[{"q":"بماذا شبه ابن القيم ضرر الذنوب في القلوب؟","o":["بضرر السموم في الأبدان","بضرر البرد في أيام الشتاء","بضرر النار في الحطب","بضرر الماء في الطين"],"why":"وأن ضررها في القلوب كضرر السموم في الأبدان","pg":98},{"q":"ماذا يحدث لقلب المؤمن إذا تاب واستغفر؟","o":["يصقل قلبه ويعود نظيفا","تبقى النقطة السوداء فيه","يقسو قلبه ولا يلين","يزيد الذنب في قلبه"],"why":"فإن تاب، ونزع، واستغفر، صقل قلبه","pg":127},{"q":"بماذا نصح وكيع الشافعي حين شكا سوء حفظه؟","o":["بترك المعاصي","بكثرة السهر","بقلة الكلام","بتكرار الدرس"],"why":"شكوت إلى وكيع سوء حفظي ... فأرشدني إلى ترك المعاصي","pg":132},{"q":"ما الذي يجلب رزق الله أكثر من أي شيء؟","o":["ترك المعاصي","كثرة النوم","جمع الأموال","طول اللعب"],"why":"فما استجلب رزق الله بمثل ترك المعاصي","pg":133}],"scene":{"t":"الواجب المنسي","x":"نسي سعد حل واجبه، فلما سأله المعلم قال كذبا: نسيت الدفتر في البيت. ثم شعر بضيق في صدره طوال اليوم. ماذا يفعل سعد؟","opts":["يعتذر للمعلم ويقول الصدق ويستغفر الله","ينسى الأمر ويكمل يومه كأن شيئا لم يكن","يكذب كذبة أخرى حتى لا يكتشف أحد"],"why":"إن المؤمن إذا أذنب نكتت في قلبه نكتة سوداء، فإن تاب، ونزع، واستغفر، صقل قلبه","pg":127},"act":{"type":"sort","t":"نور أم ظلمة؟","x":"اقرأ كل بطاقة وضعها في صندوق «نور في القلب» إذا كانت طاعة، أو في صندوق «ظلمة في القلب» إذا كانت معصية. ثم اختر بطاقة نور واحدة تعمل بها اليوم.","a":"نور في القلب","b":"ظلمة في القلب","items":[{"x":"أصلي في وقتي","ok":"أ"},{"x":"أكذب على أمي","ok":"ب"},{"x":"أقرأ القرآن قبل النوم","ok":"أ"},{"x":"أسخر من زميلي","ok":"ب"},{"x":"أساعد أبي دون أن يطلب","ok":"أ"},{"x":"أغش في الاختبار","ok":"ب"},{"x":"أستغفر الله بعد الخطأ","ok":"أ"},{"x":"آخذ شيئا ليس لي","ok":"ب"}]}},"yth":{"show":true,"title":"لماذا يتأخر أثر الذنب؟","intro":"يظن بعض الشباب أن الذنب لا يضر لأنه لم ير عقوبة سريعة. وابن القيم ينبه إلى أن هذا غلط كبير: فالذنب يعمل في القلب كالسم، وقد يظهر أثره بعد حين. ومن آثاره العاجلة: حرمان العلم والرزق، ووحشة القلب، وتعسير الأمور، وظلمة القلب، وحرمان الطاعة، ومحق بركة العمر.","points":["تأخر الأثر لا يعني السلامة، فالذنب ينقض ولو بعد حين.","كل ذنب يقطع طريق طاعة كانت ستأتي بعده.","لا تنظر إلى صغر الخطيئة، بل إلى عظمة من عصيت.","السكوت عن المنكر سبب لعموم العقوبة.","عمرك الحقيقي هو أوقات حياتك مع الله."],"quote":{"x":"ولم يعلم المغتر أن الذنب ينقض، ولو بعد حين؛ كما ينقض السم","pg":130},"quiz":[{"q":"ما النكتة الدقيقة التي يغلط فيها الناس في أمر الذنب؟","o":["لا يرون أثره في الحال فيظنونه لا يضر","يظنون التوبة لا تقبل من الشباب أبدا","يرون الذنب الكبير أهون من الصغير","يعتقدون أن الطاعة لا تزيد في الرزق شيئا"],"why":"وهي أنهم لا يرون تأثيره في الحال، وقد يتأخر تأثيره فينسى، ويظن العبد أنه لا يغبر بعد ذلك","pg":130},{"q":"ما وصية بلال بن سعد في النظر إلى الخطيئة؟","o":["انظر من عصيت لا إلى صغر الخطيئة","انظر إلى عدد خطاياك لا إلى نوعها","انظر إلى من يراك من الناس حين تخطئ","انظر إلى عقوبة الدنيا قبل الآخرة"],"why":"لا تنظر إلى صغر الخطيئة، ولكن انظر من عصيت","pg":126},{"q":"لما ركب ابن سيرين الدين واغتم، إلى أي شيء رد السبب؟","o":["إلى ذنب أصابه منذ أربعين سنة","إلى كثرة إنفاقه على أهله والناس","إلى بلاء يصيب الصالحين خاصة","إلى سوء تدبيره في تجارته"],"why":"إني لأعرف هذا الغم بذنب أصبته منذ أربعين سنة!","pg":130},{"q":"كيف يحرم الذنب صاحبه من الطاعة؟","o":["يقطع طريق طاعة ثم أخرى وهلم جرا","يضعف البدن فقط ولا يمس الطاعات","ينقص المال ولا علاقة له بالعبادة","يؤخر الصلاة يوما ثم يعود كما كان"],"why":"فلو لم يكن للذنب عقوبة إلا أنه يصد عن طاعة تكون بدله، ويقطع طريق طاعة أخرى، فينقطع عليه طريق ثالثة، ثم رابعة، وهلم جرا.","pg":136},{"q":"ما حقيقة عمر الإنسان عند ابن القيم؟","o":["أوقات حياته بالله","عدد سنواته جميعها","أيام صحته وقوته","ساعات عمله وكسبه"],"why":"فليس عمره إلا أوقات حياته بالله، فتلك ساعات عمره.","pg":138}],"scene":{"t":"لم يحدث لي شيء","x":"يتابع خالد محتوى محرما سرا منذ أشهر، ويقول لنفسه: لم يحدث لي شيء، فلا داعي للقلق. لكنه لاحظ أنه صار ثقيلا عن الصلاة وضعيف التركيز في دروسه. ما التصرف الصحيح؟","opts":["يتوب الآن ويقطع الطريق إلى ذلك المحتوى ولا يغتر بتأخر الأثر","يستمر لأنه لم ير عقوبة واضحة","يقلل منه قليلا دون أن يتوب"],"why":"ولم يعلم المغتر أن الذنب ينقض، ولو بعد حين؛ كما ينقض السم، وكما ينقض الجرح المندمل على الغش والدغل.","pg":130},"act":{"type":"match","t":"صل الأثر بدليله","x":"صل كل أثر من آثار المعاصي بالعبارة التي وصفه بها ابن القيم، ثم اكتب في دفترك أثرا شعرت به وكيف تعالجه.","items":[{"a":"حرمان العلم","b":"العلم نور يقذفه الله في القلب، والمعصية تطفئ ذلك النور"},{"a":"حرمان الرزق","b":"ترك التقوى مجلبة للفقر"},{"a":"الوحشة","b":"لا يوازنها ولا يقارنها لذة أصلا"},{"a":"تعسير الأمور","b":"لا يتوجه لأمر إلا يجده مغلقا دونه"},{"a":"ظلمة القلب","b":"كما يحس بظلمة الليل البهيم إذا ادلهم"},{"a":"حرمان الطاعة","b":"يصد عن طاعة تكون بدله"}]}},"adl":{"show":true,"title":"عقوبات الذنوب في الأفراد والأمم","intro":"يفتح ابن القيم هذا الباب بقاعدة جامعة: لا شر ولا داء في الدنيا والآخرة إلا وسببه الذنوب. ثم يستعرض مصارع الأمم من إبليس إلى بني إسرائيل، ويسوق آثار السلف في أن ترك الأمر بالمعروف يعم بالعقوبة، ثم يكشف غلط الناس في تأخر أثر الذنب، ويبدأ سرد آثار المعاصي في القلب والبدن والرزق والعمر.","points":["القاعدة: الذنوب تضر ولابد، وضررها في القلوب كالسموم في الأبدان.","سنة الله في الأمم: ما أهون الخلق على الله إذا أضاعوا أمره.","السكوت عن المنكر مع القدرة يعرض الجماعة كلها للعقوبة.","تأخر العقوبة استدراج يغتر به حتى بعض العلماء.","للذنب نقد معجل: وحشة وظلمة ووهن وحرمان طاعة ومحق بركة العمر."],"quote":{"x":"وهل في الدنيا والآخرة شر وداء إلا وسببه الذنوب والمعاصي؟","pg":98},"quiz":[{"q":"على أي شيء بنى ابن القيم أن العاصي قد يقع في البدع والضلالات وهو لا يشعر؟","o":["على قوة ظلمة المعصية في قلبه","على ضعف بدنه عند كثرة الذنوب","على وحشته من أهل الخير وبعده عنهم","على حرمانه بركة العمر والرزق"],"why":"وكلما قويت الظلمة ازدادت حيرته، حتى يقع في البدع والضلالات والأمور المهلكة، وهو لا يشعر","pg":135},{"q":"ما سر المسألة في تقصير المعاصي للعمر كما ختم به ابن القيم؟","o":["لا حياة للعبد إلا بإقباله على ربه","أن الأجل يزيد بالصدقة وحدها دون غيرها","أن العاصي يمرض فيموت قبل أجله المكتوب","أن البركة لا صلة لها بالعمر مطلقا"],"why":"وسر المسألة أن عمر الإنسان مدة حياته، ولا حياة له إلا بإقباله على ربه، والتنعم بحبه وذكره، وإيثار مرضاته.","pg":138},{"q":"لماذا تخون الفاجر قوته أحوج ما يكون إليها؟","o":["لأن قوة المؤمن من قلبه لا من بدنه","لأن الفاجر قليل الطعام كثير السهر","لأن بدن الفاجر أضعف خلقة من غيره","لأن الفاجر لا يتدرب على القتال"],"why":"فإن المؤمن قوته من قلبه، وكلما قوي قلبه قوي بدنه. وأما الفاجر، فإنه وإن كان قوي البدن، فهو أضعف شيء عند الحاجة","pg":136},{"q":"ما الذي أنكره أبو بكر الصديق على الناس في آية: عليكم أنفسكم؟","o":["أنهم يضعونها على غير مواضعها","أنهم لا يحفظونها حفظا متقنا","أنهم يقرؤونها في غير الصلاة","أنهم يخصونها بأهل الكتاب"],"why":"أيها الناس إنكم تتلون هذه الآية، وإنكم تضعونها على غير مواضعها","pg":121},{"q":"بماذا أجاب دانيال بختنصر حين سأله عن سبب تسلطه على قومه؟","o":["عظم خطيئتك وظلم قومي أنفسهم","قوة جيشك وكثرة سلاحك وعتادك","ضعف ملوكهم وقلة عددهم وعدتهم","بعد ديارهم عن ديار الأنبياء"],"why":"عظم خطيئتك، وظلم قومي أنفسهم.","pg":115}],"scene":{"t":"غش جماعي صغير","x":"معلم يلاحظ أن طلاب صفه يتبادلون الإجابات في الواجبات المنزلية، ويقول بعضهم: الأمر بسيط والجميع يفعله. وبعض زملائه يرون السكوت أريح. ما التصرف الأحكم؟","opts":["يبين لهم بلطف خطر محقرات الذنوب ويغير المنكر بحكمة","يسكت لأن الأمر صغير والجميع يفعله","يعاقبهم جميعا دون بيان ولا نصح"],"why":"إنكم لتعملون أعمالا هي أدق في أعينكم من الشعر، إن كنا لنعدها على عهد رسول الله ﷺ من الموبقات.","pg":124},"act":{"type":"class","t":"خريطة آثار الذنوب","x":"نشاط صفي أو أسري مدته 40 دقيقة، يبني فيه المشاركون خريطة لآثار المعاصي العاجلة من نص ابن القيم.","items":["5 دقائق: يقرأ المربي القاعدة «الذنوب تضر ولابد» ويسأل: هل في الدنيا شر إلا وسببه الذنوب؟","10 دقائق: توزع المجموعات على آثار الفصل: حرمان العلم، حرمان الرزق، الوحشة، تعسير الأمور، ظلمة القلب، وهن القلب والبدن، حرمان الطاعة، قصر العمر.","10 دقائق: تستخرج كل مجموعة العبارة الحرفية وتكتب مثالا واقعيا من حياة الطلاب أو الأسرة.","10 دقائق: تعرض المجموعات، ويربط المربي كل أثر بدوائه من الكتاب: التقوى، ترك المعاصي، التوبة.","5 دقائق: يكتب كل مشارك في دفتره الخاص أثرا يخشاه وطاعة يعزم عليها."]}},"alt":{}},"highlights":[{"x":"أن الذنوب تضر ولابد","pg":98,"lv":"kid"},{"x":"فإن الطاعة نور، والمعصية ظلمة","pg":135,"lv":"kid"},{"x":"فما استجلب رزق الله بمثل ترك المعاصي","pg":133,"lv":"kid"},{"x":"لا تنظر إلى صغر الخطيئة، ولكن انظر من عصيت","pg":126,"lv":"kid"},{"x":"أن البر لا يبلى، وأن الإثم لا ينسى","pg":131,"lv":"yth"},{"x":"ما أهون الخلق على الله عز وجل إذا أضاعوا أمره!","pg":101,"lv":"yth"},{"x":"إن الرجل ليصيب الذنب في السر، فيصبح وعليه مذلته","pg":131,"lv":"yth"},{"x":"ولا حياة له إلا بإقباله على ربه","pg":138,"lv":"adl"}],"concepts":[{"term":"الران","def":"وإن زاد زادت حتى تعلو قلبه، فذلك الران الذي ذكر الله عز وجل","pg":127},{"term":"حقيقة العمر","def":"فليس عمره إلا أوقات حياته بالله، فتلك ساعات عمره.","pg":138},{"term":"حقيقة الحياة","def":"فالحياة في الحقيقة حياة القلب","pg":138},{"term":"وحشة المعصية","def":"وحشة يجدها العاصي في قلبه بينه وبين الله، لا يوازنها ولا يقارنها لذة أصلا","pg":133},{"term":"نقد الذنب المعجل","def":"هذا، مع أن للذنب نقدا معجلا لا يتأخر عنه.","pg":131}],"stories":[{"t":"مالك والشافعي","x":"لما جلس الشافعي بين يدي مالك وقرأ عليه أعجبه ذكاؤه وفهمه، فقال له: إني أرى الله قد ألقى على قلبك نورا، فلا تطفئه بظلمة المعصية.","pg":132,"lv":"kid","hd":""},{"t":"وكيع والشافعي","x":"شكا الشافعي إلى شيخه وكيع سوء حفظه، فأرشده إلى ترك المعاصي، وأخبره أن العلم فضل من الله لا يؤتاه عاص.","pg":132,"lv":"kid","hd":""},{"t":"بكاء أبي الدرداء يوم فتح قبرس","x":"لما فتحت قبرس فرق بين أهلها فبكى بعضهم إلى بعض، ورأى جبير بن نفير أبا الدرداء جالسا وحده يبكي، فسأله: ما يبكيك في يوم أعز الله فيه الإسلام وأهله؟ فقال: ما أهون الخلق على الله إذا أضاعوا أمره! بينما هي أمة قاهرة ظاهرة لهم الملك، تركوا أمر الله، فصاروا إلى ما ترى.","pg":101,"lv":"yth","hd":"سنده صحيح (المحقق)"},{"t":"زلزلة المدينة على عهد عمر","x":"زلزلت المدينة على عهد عمر رضي الله عنه، فقال: يا أيها الناس ما هذا؟ ما أسرع ما أحدثتم، لئن عادت لا أساكنكم فيها.","pg":112,"lv":"yth","hd":"أثر صفية: سنده صحيح"},{"t":"ابن سيرين وغم الدين","x":"لما ركب محمد بن سيرين الدين اغتم، فقال: إني لأعرف هذا الغم بذنب أصبته منذ أربعين سنة.","pg":130,"lv":"yth","hd":"ثابت عنه (المحقق)"},{"t":"حبر بني إسرائيل","x":"كان حبر يعظ الناس، فرأى بعض بنيه يغمز النساء فاكتفى بقوله: مهلا يا بني. فأصيب في بدنه وأهله، وأوحى الله إلى نبيهم أن غضبه لله لم يتجاوز قوله: مهلا يا بني.","pg":124,"lv":"adl","hd":"أثر عن مالك بن دينار، أخرجه أحمد في الزهد"},{"t":"الرجل الذي لم يتمعر وجهه لله","x":"أمر الله ملكين بتدمير قرية، فوجدا فيها رجلا يصلي، فأمرهما أن يبدآ به لأنه لم يتمعر وجهه لله قط.","pg":109,"lv":"adl","hd":"في سنده ضعف، وجاء نحوه عن مسعر بسند حسن إليه، ولا يصح مرفوعا","weak":1}],"ready":true},{"k":"s5","t":"آثار المعاصي في القلب والنفس","pgs":[139,199],"q":"كيف تغير المعاصي القلب والنفس حتى تسلب العبد حياءه وعزه ونعمه وصلته بربه؟","essence":"المعصية تجر أختها وتطفئ حياة القلب","kw":["الحياء والغيرة","أسر الشيطان","زوال النعم"],"daa":"تراكم المعاصي حتى تصير صفة راسخة تضعف الإرادة وتطفئ الحياء والغيرة وتعمي القلب.","dawa":"الطاعة التي تولد الطاعة، وتغيير المعصية بالطاعة، ولزوم التقوى والقرب من الله الذي يورث الأنس والعز والأمان.","sections":[{"t":"فصل: المعاصي تزرع أمثالها","pg":139,"lv":"kid","key":"ومنها: أن المعاصي تزرع أمثالها، ويولد بعضها بعضا حتى يعز على العبد مفارقتها والخروج منها، كما قال بعض السلف: إن من عقوبة السيئة السيئة بعدها، وإن من ثواب الحسنة الحسنة بعدها.","p":["فالعبد إذا عمل حسنة قالت أخرى إلى جانبها: اعملني أيضا، فإذا عملها قالت الثانية كذلك، وهلم جرا، فتضاعف الربح، وتزايدت الحسنات. وكذلك جانب السيئات أيضا، حتى تصير الطاعات والمعاصي هيئات راسخة وصفات لازمة وملكات ثابتة.","فلو عطل المحسن الطاعة لضاقت عليه نفسه، وضاقت عليه الأرض بما رحبت، وأحس من نفسه بأنه كالحوت إذا فارق الماء، حتى يعاودها، فتسكن نفسه، وتقر عينه."],"items":[{"h":"الملائكة والشياطين","x":"ولا يزال العبد يعاني الطاعة، ويألفها، ويحبها، ويؤثرها حتى يرسل الله سبحانه برحمته عليه الملائكة تؤزه إليها أزا، وتحرضه عليها، وتزعجه عن فراشه ومجلسه إليها. ولا يزال يألف المعاصي، ويحبها، ويؤثرها، حتى يرسل الله عليه الشياطين فتؤزه إليها أزا.","pg":140},{"h":"الجند والمدد","x":"فالأول قوى جند الطاعة بالمدد، فصاروا من أكبر أعوانه. وهذا قوى جند المعصية بالمدد، فكانوا أعوانا عليه.","pg":140}],"hd":""},{"t":"فصل: تضعف القلب عن إرادته","pg":141,"lv":"yth","key":"أنها تضعف القلب عن إرادته، فتقوى إرادة المعصية، وتضعف إرادة التوبة شيئا فشيئا إلى أن تنسلخ من قلبه إرادة التوبة بالكلية","p":["فيأتي من الاستغفار وتوبة الكذابين باللسان بشيء كثير، وقلبه معقود بالمعصية، مصر عليها، عازم على مواقعتها متى أمكنته.","وهذا من أعظم الأمراض وأقربها إلى الهلاك."],"items":[],"hd":""},{"t":"فصل: ينسلخ من القلب استقباحها","pg":141,"lv":"yth","key":"ومنها: أنه ينسلخ من القلب استقباحها، فتصير له عادة، فلا يستقبح من نفسه رؤية الناس له، ولا كلامهم فيه.","p":["وهذا عند أرباب الفسوق هو غاية التهتك وتمام اللذة، حتى يفتخر أحدهم بالمعصية، ويحدث بها من لم يعلم أنه عملها","وهذا الضرب من الناس لا يعافون، وتسد عليهم طريق التوبة، وتغلق عنهم أبوابها في الغالب"],"items":[{"h":"المجاهرون","x":"كل أمتي معافى إلا المجاهرين. وإن من الإجهار أن يستر الله على العبد، ثم يصبح يفضح نفسه، ويقول: يا فلان عملت يوم كذا كذا وكذا، فيهتك نفسه، وقد بات يستره ربه","pg":142}],"hd":"حديث المجاهرين: البخاري 6069 ومسلم 2990."},{"t":"كل معصية ميراث عن أمة أهلكها الله","pg":142,"lv":"adl","key":"ومنها: أن كل معصية من المعاصي فهي ميراث عن أمة من الأمم التي أهلكها الله عز وجل.","p":["فالعاصي لابس ثياب بعض هذه الأمم، وهم أعداء الله."],"items":[{"h":"قوم لوط","x":"فاللوطية: ميراث عن قوم لوط.","pg":142},{"h":"قوم شعيب","x":"وأخذ الحق بالزائد، ودفعه بالناقص: ميراث عن قوم شعيب.","pg":142},{"h":"فرعون","x":"والعلو في الأرض والفساد: ميراث عن فرعون وقومه.","pg":142},{"h":"قوم هود","x":"والتكبر والتجبر: ميراث عن قوم هود.","pg":142},{"h":"مالك بن دينار","x":"أوحى الله إلى نبي من أنبياء بني إسرائيل أن قل لقومك: لا تدخلوا مداخل أعدائي، ولا تلبسوا ملابس أعدائي، ولا تركبوا مراكب أعدائي، ولا تطعموا مطاعم أعدائي؛ فتكونوا أعدائي، كما هم أعدائي.","pg":142},{"h":"الحديث","x":"بعثت بالسيف بين يدي الساعة حتى يعبد الله وحده لا شريك له، وجعل رزقي تحت ظل رمحي، وجعل الذلة والصغار على من خالف أمري. ومن تشبه بقوم فهو منهم","pg":143}],"hd":"«بعثت بالسيف»: المسند وأبو داود (طرفه الأخير)، تفرد به عبدالرحمن بن ثابت وفي حفظه ضعف، وصححه جماعة منهم شيخ الإسلام ابن تيمية والذهبي والعراقي وابن حجر. أثر مالك بن دينار: لم يقف عليه المحقق في الزهد، وهو من قوله عند ابن أبي الدنيا وأبي نعيم."},{"t":"فصل: المعصية سبب لهوان العبد على ربه","pg":144,"lv":"yth","key":"ومنها: أن المعصية سبب لهوان العبد على ربه، وسقوطه من عينه.","p":["قال الحسن البصري: هانوا عليه فعصوه، ولو عزوا عليه لعصمهم.","وإذا هان العبد على الله لم يكرمه أحد، كما قال تعالى: ﴿وَمَن يُهِنِ اللَّهُ فَمَا لَهُ مِن مُّكْرِمٍ﴾ (الحج: 18). وإن عظمهم الناس في الظاهر لحاجتهم إليهم أو خوفا من شرهم، فهم في قلوبهم أحقر شيء وأهونه."],"items":[],"hd":""},{"t":"الذنب يهون على العبد ويصغر في قلبه","pg":144,"lv":"kid","key":"ومنها: أن العبد لا يزال يرتكب الذنب، حتى يهون عليه، ويصغر في قلبه. وذلك علامة الهلاك، فإن الذنب كلما صغر في عين العبد عظم عند الله.","p":["إن المؤمن يرى ذنوبه كأنه في أصل جبل يخاف أن يقع عليه. وإن الفاجر يرى ذنوبه كذباب وقع على أنفه، فقال به هكذا، فطار."],"items":[],"hd":"أثر ابن مسعود: البخاري 6308."},{"t":"فصل: شؤم الذنوب يعود على الناس والدواب","pg":145,"lv":"yth","key":"ومنها: أن غيره من الناس والدواب يعود عليه شؤم ذنوبه، فيحترق هو وغيره بشؤم الذنوب والظلم.","p":["فلا يكفيه عقاب ذنبه، حتى يبوء بلعنة من لا ذنب له."],"items":[{"h":"أبو هريرة","x":"إن الحبارى لتموت في وكرها من ظلم الظالم.","pg":145},{"h":"مجاهد","x":"إن البهائم تلعن عصاة بني آدم إذا اشتدت السنة، وأمسك المطر؛ وتقول: هذا بشؤم معصية ابن آدم.","pg":145},{"h":"عكرمة","x":"دواب الأرض وهوامها حتى الخنافس والعقارب يقولون: منعنا القطر بذنوب بني آدم.","pg":146}],"hd":"أثر أبي هريرة: محتمل للتحسين من بعض طرقه. أثر مجاهد: صحيح عنه. أثر عكرمة: بسند لا بأس به."},{"t":"فصل: المعصية تورث الذل","pg":146,"lv":"kid","key":"ومنها: أن المعصية تورث الذل، ولابد؛ فإن العز كل العز في طاعة الله تعالى.","p":["قال تعالى: ﴿مَن كَانَ يُرِيدُ الْعِزَّةَ فَلِلَّهِ الْعِزَّةُ جَمِيعًا﴾ (فاطر: 10)، أي: فليطلبها بطاعة الله، فإنه لا يجدها إلا في طاعته.","قال الحسن البصري: إنهم، وإن طقطقت بهم البغال، وهملجت بهم البراذين، إن ذل المعصية لا يفارق قلوبهم. أبى الله إلا أن يذل من عصاه."],"items":[{"h":"دعاء بعض السلف","x":"اللهم أعزني بطاعتك، ولا تذلني بمعصيتك.","pg":146},{"h":"ابن المبارك","x":"رأيت الذنوب تميت القلوب ... وقد يورث الذل إدمانها / وترك الذنوب حياة القلوب ... وخير لنفسك عصيانها","pg":147}],"hd":""},{"t":"فصل: المعاصي تفسد العقل","pg":147,"lv":"yth","key":"ومنها: أن المعاصي تفسد العقل. فإن للعقل نورا، والمعصية تطفئ نور العقل، ولابد؛ وإذا طفئ نوره ضعف ونقص.","p":["وقال بعض السلف: ما عصى الله أحد حتى يغيب عقله.","وهذا ظاهر، فإنه لو حضره عقله لحجزه عن المعصية، وهو في قبضة الرب تعالى وتحت قهره، وهو مطلع عليه، وفي داره وعلى بساطه، وملائكته شهود عليه ناظرون إليه، وواعظ القرآن ينهاه، وواعظ الإيمان ينهاه، وواعظ الموت ينهاه، وواعظ النار ينهاه"],"items":[{"h":"الخلاصة","x":"والذي يفوته بالمعصية من خير الدنيا والآخرة أضعاف أضعاف ما يحصل له من السرور واللذة بها، فهل يقدم على الاستهانة بذلك كله والاستخفاف به ذو عقل سليم؟","pg":148}],"hd":""},{"t":"فصل: الذنوب إذا تكاثرت طبع على القلب","pg":148,"lv":"yth","key":"ومنها: أن الذنوب إذا تكاثرت طبع على قلب صاحبها، فكان من الغافلين","p":["كما قال بعض السلف في قوله تعالى: ﴿كَلَّا ۖ بَلْ ۜ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُوا يَكْسِبُونَ﴾ (المطففين: 14) قال: هو الذنب بعد الذنب. وقال الحسن: هو الذنب على الذنب حتى يعمى القلب.","وأصل هذا أن القلب يصدأ من المعصية، فإن زادت غلب الصدأ حتى يصير رانا، ثم يغلب حتى يصير طبعا وقفلا وختما، فيصير القلب في غشاوة وغلاف. فإن حصل له ذلك بعد الهدى والبصيرة انتكس فصار أعلاه أسفله، فحينئذ يتولاه عدوه، ويسوقه حيث أراد."],"items":[],"hd":""},{"t":"فصل: الذنوب تدخل العبد تحت لعنة رسول الله ﷺ","pg":149,"lv":"adl","key":"ومنها: أن الذنوب تدخل العبد تحت لعنة رسول الله ﷺ. فإنه لعن على معاص، وغيرها أكبر منها، فهي أولى بدخول فاعلها تحت اللعنة.","p":["فلو لم يكن في فعل ذلك إلا رضا فاعله بأن يكون ممن يلعنه الله ورسوله وملائكته، لكان في ذلك ما يدعو إلى تركه."],"items":[{"h":"الربا","x":"ولعن آكل الربا، وموكله، وكاتبه، وشاهديه.","pg":149},{"h":"الخمر","x":"ولعن شارب الخمر، وساقيها، وعاصرها، ومعتصرها، وبائعها، ومشتريها، وآكل ثمنها، وحاملها، والمحمولة إليه.","pg":149},{"h":"حدود الأرض","x":"ولعن من غير منار الأرض، وهي أعلامها وحدودها.","pg":150},{"h":"الوالدان","x":"ولعن من لعن والديه.","pg":150},{"h":"الرفق بالحيوان","x":"ولعن من اتخذ شيئا فيه الروح غرضا يرميه بالسهام. ولعن من وسم دابة في وجهها.","pg":150},{"h":"الإيذاء والمكر","x":"ولعن من ضار بمسلم أو مكر به.","pg":150},{"h":"الإحداث في الدين","x":"ولعن من أحدث حدثا أو آوى محدثا.","pg":150},{"h":"الرشوة","x":"ولعن الراشي، والمرتشي، والرائش، وهو الواسطة في الرشوة.","pg":152},{"h":"سب الصحابة","x":"ولعن من سب أصحابه.","pg":151}],"hd":"لم يخرج المحقق هذه الأحاديث تفصيلا، وأحال إلى كتاب «مرويات اللعن في السنة المطهرة» لباسم بن فيصل الجوابرة. حذفت من البنود ما يتصل بالفواحش والمعاشرة، ويبقى في نص الكتاب للراشد."},{"t":"فصل: حرمان دعوة رسول الله ﷺ ودعوة الملائكة","pg":152,"lv":"yth","key":"ومنها: حرمان دعوة رسول الله ﷺ ودعوة الملائكة. فإن الله سبحانه أمر نبيه أن يستغفر للمؤمنين والمؤمنات","p":["فهذا دعاء الملائكة للمؤمنين التائبين، المتبعين لكتابه وسنة رسوله، الذين لا سبيل لهم غيرهما. فلا يطمع غير هؤلاء بإجابة هذه الدعوة إذ لم يتصف بصفات المدعو له بها. والله المستعان."],"items":[{"h":"آية غافر","x":"﴿الَّذِينَ يَحْمِلُونَ الْعَرْشَ وَمَنْ حَوْلَهُ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَيُؤْمِنُونَ بِهِ وَيَسْتَغْفِرُونَ لِلَّذِينَ آمَنُوا رَبَّنَا وَسِعْتَ كُلَّ شَيْءٍ رَّحْمَةً وَعِلْمًا فَاغْفِرْ لِلَّذِينَ تَابُوا وَاتَّبَعُوا سَبِيلَكَ وَقِهِمْ عَذَابَ الْجَحِيمِ﴾ (غافر: 7)","pg":152}],"hd":""},{"t":"فصل: من عقوبات المعاصي في حديث سمرة بن جندب","pg":153,"lv":"yth","key":"ومن عقوبات المعاصي: ما رواه البخاري في صحيحه من حديث سمرة بن جندب","p":["أما الرجل الأول الذي أتيت عليه يثلغ رأسه بالحجر، فإنه الرجل يأخذ القرآن، فيرفضه، وينام عن الصلاة المكتوبة.","وأما الرجل الذي أتيت عليه يشرشر شدقه إلى قفاه، ومنخره إلى قفاه، وعينه إلى قفاه؛ فإنه الرجل يغدو من بيته، فيكذب الكذبة تبلغ الآفاق."],"items":[{"h":"آكل الربا","x":"وأما الرجل الذي أتيت عليه يسبح في النهر، ويلقم الحجارة، فإنه آكل الربا.","pg":157},{"h":"أهل التنور","x":"وأما الرجال والنساء العراة الذين هم في مثل بناء التنور، فإنهم الزناة والزواني.","pg":156},{"h":"إبراهيم والولدان","x":"وأما الرجل الطويل الذي في الروضة، فإنه إبراهيم. وأما الولدان الذين حوله، فكل مولود مات على الفطرة","pg":157},{"h":"من خلطوا","x":"وأما القوم الذين كانوا شطر منهم حسن، وشطر منهم قبيح، فإنهم قوم خلطوا عملا صالحا وآخر سيئا، تجاوز الله عنهم","pg":157}],"hd":"حديث سمرة: البخاري 7047."},{"t":"فصل: المعاصي تحدث في الأرض أنواعا من الفساد","pg":157,"lv":"yth","key":"ومن آثار الذنوب والمعاصي: أنها تحدث في الأرض أنواعا من الفساد في المياه، والهواء، والزروع، والثمار، والمساكن.","p":["فالمراد بالفساد النقص والشر والآلام التي يحدثها الله في الأرض عند معاصي العباد، فكلما أحدثوا ذنبا أحدث لهم عقوبة، كما قال بعض السلف: كلما أحدثتم ذنبا أحدث الله لكم من سلطانه عقوبة.","وهذا لأن الأرض لما طهرت من المعاصي ظهرت فيها آثار البركة من الله تعالى التي محقتها الذنوب والكفر."],"items":[{"h":"آية الروم","x":"﴿ظَهَرَ الْفَسَادُ فِي الْبَرِّ وَالْبَحْرِ بِمَا كَسَبَتْ أَيْدِي النَّاسِ لِيُذِيقَهُم بَعْضَ الَّذِي عَمِلُوا لَعَلَّهُمْ يَرْجِعُونَ﴾ (الروم: 41)","pg":157},{"h":"مجاهد","x":"إذا ولي الظالم سعى بالظلم والفساد، فيحبس الله بذلك القطر، فيهلك الحرث والنسل، والله لا يحب الفساد.","pg":158},{"h":"اليسير من أعمالنا","x":"فهذا حالنا، وإنما أذاقنا الشيء اليسير من أعمالنا، فلو أذاقنا كل أعمالنا لما ترك على ظهرها من دابة.","pg":159},{"h":"ديار ثمود","x":"وقد مر رسول الله ﷺ على ديار ثمود، فمنعهم من دخول ديارهم، ومن شرب مياههم، ومن الاستقاء من آبارهم، حتى أمر أن يعلف العجين الذي عجن بمائهم للنواضح، لتأثير شؤم المعصية في الماء.","pg":160},{"h":"حنطة زمن العدل","x":"وجدت في خزائن بني أمية حنطة، الحبة بقدر نواة التمر. وهي في صرة مكتوب عليها: هذا كان ينبت في زمن العدل.","pg":160},{"h":"نقص الخلق","x":"خلق الله آدم، وطوله في السماء ستون ذراعا، فلم يزل الخلق ينقص حتى الآن","pg":161},{"h":"مقارنة الشيطان","x":"وتأمل مقارنة الشيطان ومحله وداره، فإنه لما قارن العبد واستولى عليه، نزعت البركة من عمره، وعمله، وقوله، ورزقه.","pg":163}],"hd":"أثر مجاهد: سنده صحيح. نهيه ﷺ في ديار ثمود: البخاري 3379 ومسلم 2981. خبر الحنطة: في المسند، وسنده صحيح إلى أبي قحذم. حديث خلق آدم: في الصحيحين (البخاري 3326 ومسلم 2841)، وعزاه المؤلف هنا للترمذي."},{"t":"فصل: تطفئ من القلب نار الغيرة","pg":163,"lv":"yth","key":"ومن عقوبات الذنوب: أنها تطفئ من القلب نار الغيرة التي هي لحياته وصلاحه كالحرارة الغريزية لحياة جميع البدن.","p":["فالغيرة حرارته وناره التي تخرج ما فيه من الخبث والصفات المذمومة، كما يخرج الكير خبث الذهب والفضة والحديد. وأشرف الناس وأعلاهم همة أشدهم غيرة على نفسه، وخاصته، وعموم الناس.","وهذا يدلك على أن أصل الدين الغيرة، ومن لا غيرة له لا دين له. فالغيرة تحمي القلب، فتحمى له الجوارح، فتدفع السوء والفواحش."],"items":[{"h":"غيرة النبي ﷺ","x":"أتعجبون من غيرة سعد؟ لأنا أغير منه، والله أغير مني","pg":163},{"h":"الغيرة الممدوحة","x":"وإنما الممدوح اقتران الغيرة بالعذر، فيغار في محل الغيرة، ويعذر في موضع العذر. ومن كان هكذا فهو الممدوح حقا.","pg":165},{"h":"تدرج المعصية","x":"فإن الخطرة تنقلب وسوسة، والوسوسة تصير إرادة، والإرادة تقوى فتصير عزيمة، ثم تصير فعلا، ثم تصير صفة لازمة وهيئة ثابتة راسخة، وحينئذ يتعذر الخروج منها كما يتعذر الخروج من صفاته القائمة به.","pg":167},{"h":"باب الهلاك","x":"وقد تضعف في القلب جدا حتى لا يستقبح بعد ذلك القبيح، لا من نفسه ولا من غيره. وإذا وصل إلى هذا الحد فقد دخل في باب الهلاك.","pg":167},{"h":"المثل","x":"ومثل الغيرة في القلب مثل القوة التي تدفع المرض وتقاومه، فإذا ذهبت القوة وجد الداء المحل قابلا، ولم يجد دافعا، فتمكن، فكان الهلاك.","pg":168}],"hd":"«أتعجبون من غيرة سعد»: البخاري 6846 ومسلم 1499. «إن من الغيرة ما يحبها الله» (ص 165): صححه ابن حبان والحاكم وابن حجر وغيرهم، وقال المحقق: وفيه نظر، لجهالة ابن جابر بن عتيك. حديث الديوث المشار إليه (ص 167): أحمد 6180، وصححه ابن حبان والحاكم والذهبي."},{"t":"فصل: ذهاب الحياء","pg":168,"lv":"kid","key":"ومن عقوباتها: ذهاب الحياء الذي هو مادة الحياة للقلب، وهو أصل كل خير، وذهابه ذهاب الخير أجمعه.","p":["والمقصود أن الذنوب تضعف الحياء من العبد حتى ربما انسلخ منه بالكلية، حتى إنه ربما لا يتأثر بعلم الناس بسوء حاله ولا باطلاعهم عليه","ومن استحيا من الله عند معصيته استحيا الله من عقوبته يوم يلقاه، ومن لم يستحي من معصيته لم يستحي من عقوبته."],"items":[{"h":"الحياء خير كله","x":"وفي الصحيح عنه ﷺ أنه قال: الحياء خير كله.","pg":168},{"h":"كلام النبوة الأولى","x":"إن مما أدرك الناس من كلام النبوة الأولى: إذا لم تستحي فاصنع ما شئت!","pg":168},{"h":"التفسيران","x":"أحدهما: أنه على التهديد والوعيد، والمعنى: من لم يستح فإنه يصنع ما شاء من القبائح... والثاني: أن الفعل إذا لم تستح منه من الله فافعله، وإنما الذي ينبغي تركه ما يستحى منه من الله.","pg":169},{"h":"الحياء والحياة","x":"والحياء مشتق من الحياة... فمن لا حياء فيه ميت في الدنيا شقي في الآخرة.","pg":170},{"h":"التلازم","x":"وبين الذنوب وبين قلة الحياء وعدم الغيرة تلازم من الطرفين، وكل منهما يستدعي الآخر، ويطلبه حثيثا.","pg":170}],"hd":"«الحياء خير كله»: مسلم 37. «إذا لم تستحي فاصنع ما شئت»: البخاري 3483."},{"t":"فصل: تضعف في القلب تعظيم الرب","pg":170,"lv":"yth","key":"ومن عقوبات الذنوب: أنها تضعف في القلب تعظيم الرب جل جلاله، وتضعف وقاره في قلب العبد، ولابد، شاء أم أبى. ولو تمكن وقار الله وعظمته في قلب العبد لما تجرأ على معاصيه.","p":["وربما اغتر المغتر وقال: إنما يحملني على المعاصي حسن الرجاء وطمعي في عفوه، لا ضعف عظمته في قلبي. وهذا من مغالطة النفس","فعلى قدر محبة العبد لله يحبه الناس. وعلى قدر خوفه من الله يخافه الناس، وعلى قدر تعظيمه لله وحرماته يعظم الناس حرماته."],"items":[{"h":"سنة المعاملة","x":"وكيف ينتهك عبد حرمات الله، ويطمع أن لا ينتهك الناس حرماته؟ أم كيف يهون عليه حق الله، ولا يهونه الله على الناس؟","pg":171},{"h":"من أهانه الله","x":"ومن ذا يكرم من أهانه الله، أو يهين من أكرمه الله؟","pg":172}],"hd":""},{"t":"فصل: تستدعي نسيان الله لعبده","pg":172,"lv":"yth","key":"ومن عقوباتها: أنها تستدعي نسيان الله لعبده، وتركه، وتخليته بينه وبين نفسه وشيطانه. وهنالك الهلاك الذي لا يرجى معه نجاة.","p":["وأعظم العقوبات نسيان العبد لنفسه، وإهماله لها، وإضاعته حظها ونصيبها من الله، وبيعها ذلك بالغبن والهوان وأبخس الثمن.","فما ظلم العبد ربه، ولكن ظلم نفسه. وما ظلمه ربه، ولكن هو الذي ظلم نفسه!"],"items":[{"h":"آية الحشر","x":"﴿يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَلْتَنظُرْ نَفْسٌ مَّا قَدَّمَتْ لِغَدٍ ۖ وَاتَّقُوا اللَّهَ ۚ إِنَّ اللَّهَ خَبِيرٌ بِمَا تَعْمَلُونَ ۝ وَلَا تَكُونُوا كَالَّذِينَ نَسُوا اللَّهَ فَأَنسَاهُمْ أَنفُسَهُمْ ۚ أُولَٰئِكَ هُمُ الْفَاسِقُونَ﴾ (الحشر: 18 و19)","pg":172},{"h":"البيت","x":"من كل شيء إذا ضيعته عوض ... وما من الله إن ضيعته عوض","pg":173},{"h":"لا غنى عنه","x":"فالله سبحانه يعوض عن كل ما سواه، ولا يعوض منه شيء. ويغني عن كل شيء، ولا يغني عنه شيء... فكيف يستغني العبد عن طاعة من هذا شأنه طرفة عين؟","pg":174}],"hd":""},{"t":"فصل: تخرج العبد من دائرة الإحسان","pg":174,"lv":"yth","key":"ومن عقوباتها: أنها تخرج العبد من دائرة الإحسان، وتمنعه ثواب المحسنين.","p":["فإن الإحسان إذا باشر القلب منعه من المعاصي، فإن من عبد الله كأنه يراه لم يكن ذلك إلا لاستيلاء ذكره ومحبته وخوفه ورجائه على قلبه، بحيث يصير كأنه يشاهده، وذلك يحول بينه وبين إرادة المعصية، فضلا عن مواقعتها.","والمقصود أن الإيمان سبب جالب لكل خير، وكل خير في الدنيا والآخرة فسببه الإيمان، وكل شر في الدنيا والآخرة فسببه عدم الإيمان."],"items":[{"h":"الحديث","x":"لا يزني الزاني حين يزني وهو مؤمن، ولا يشرب الخمر حين يشربها وهو مؤمن، ولا يسرق حين يسرق وهو مؤمن، ولا ينتهب نهبة ذات شرف يرفع إليه فيها الناس أبصارهم حين ينتهبها وهو مؤمن. فإياكم إياكم، والتوبة معروضة بعد","pg":175},{"h":"خصال الإيمان","x":"وفاته كل خير رتبه الله في كتابه على الإيمان، وهو نحو مائة خصلة، كل خصلة منها خير من الدنيا وما فيها: منها الأجر العظيم، والدفع عنهم، واستغفار حملة العرش لهم، وموالاة الله لهم، وأمره ملائكته بتثبيتهم، والدرجات، والعزة، ومعية الله، والرفعة، والكفلان من رحمته والنور، والود، والأمان من الخوف، والقرآن هدى وشفاء.","pg":175},{"h":"خوف السلف","x":"ومن هنا اشتد خوف السلف، كما قال بعضهم: أنتم تخافون الذنوب، وأنا أخاف الكفر!","pg":177}],"hd":"حديث «لا يزني الزاني»: البخاري 2475 ومسلم 57."},{"t":"فصل: تضعف سير القلب إلى الله والدار الآخرة","pg":178,"lv":"yth","key":"ومن عقوباتها: أنها تضعف سير القلب إلى الله والدار الآخرة، أو تعوقه، أو توقفه وتقطعه عن السير، فلا تدعه يخطو إلى الله خطوة.","p":["فالذنب يحجب الواصل، ويقطع السائر، وينكس الطالب. والقلب إنما يسير إلى الله بقوته، فإذا مرض بالذنوب ضعفت تلك القوة التي تسيره.","فالذنب إما أن يميت القلب، أو يمرضه مرضا مخوفا، أو يضعف قوته، ولا بد، حتى ينتهي ضعفه إلى الأشياء الثمانية التي استعاذ منها النبي ﷺ."],"items":[{"h":"الهم والحزن","x":"فإن المكروه الوارد على القلب إن كان من أمر مستقبل يتوقعه أحدث الهم، وإن كان من أمر ماض قد وقع أحدث الحزن.","pg":178},{"h":"العجز والكسل","x":"فإن تخلف العبد عن أسباب الخير والفلاح إن كان لعدم قدرته فهو العجز، وإن كان لعدم إرادته فهو الكسل.","pg":179},{"h":"الجبن والبخل","x":"فإن عدم النفع منه إن كان ببدنه فهو الجبن، وإن كان بماله فهو البخل.","pg":179},{"h":"ضلع الدين وقهر الرجال","x":"فإن استعلاء الغير عليه إن كان بحق فهو من ضلع الدين، وإن كان بباطل فهو قهر الرجال.","pg":179},{"h":"الخلاصة","x":"والمقصود أن الذنوب من أقوى الأسباب الجالبة لهذه الثمانية، كما أنها من أقوى الأسباب الجالبة لجهد البلاء، ودرك الشقاء، وسوء القضاء، وشماتة الأعداء","pg":179}],"hd":"الاستعاذة من الثمانية: البخاري 6369 من حديث أنس. التعوذ من جهد البلاء: البخاري 6347 ومسلم 2707. التعوذ من زوال النعمة: مسلم 2739."},{"t":"فصل: الذنوب تزيل النعم وتحل النقم","pg":179,"lv":"adl","key":"ومن عقوبات الذنوب أنها تزيل النعم وتحل النقم. فما زالت عن العبد نعمة إلا بذنب، ولا حلت به نقمة إلا بذنب","p":["كما قال علي بن أبي طالب رضي الله عنه: ما نزل بلاء إلا بذنب، ولا رفع بلاء إلا بتوبة.","فإذا غير غير عليه جزاء وفاقا، وما ربك بظلام للعبيد. فإن غير المعصية بالطاعة غير الله عليه العقوبة بالعافية، والذل بالعز."],"items":[{"h":"آية الرعد","x":"﴿إِنَّ اللَّهَ لَا يُغَيِّرُ مَا بِقَوْمٍ حَتَّىٰ يُغَيِّرُوا مَا بِأَنفُسِهِمْ﴾ (الرعد: 11)","pg":180},{"h":"آية الشورى","x":"﴿وَمَا أَصَابَكُم مِّن مُّصِيبَةٍ فَبِمَا كَسَبَتْ أَيْدِيكُمْ وَيَعْفُو عَن كَثِيرٍ﴾ (الشورى: 30)","pg":180},{"h":"الأثر الإلهي","x":"وعزتي وجلالي، لا يكون عبد من عبيدي على ما أحب، ثم ينتقل عنه إلى ما أكره، إلا انتقلت له مما يحب إلى ما يكره.","pg":180},{"h":"الأبيات","x":"إذا كنت في نعمة فارعها ... فإن المعاصي تزيل النعم / وحطها بطاعة رب العباد ... فرب العباد سريع النقم","pg":181}],"hd":"قول علي: نقله المؤلف عنه، ونسبه شيخ الإسلام إلى عمر بن عبدالعزيز، وورد نحوه من دعاء العباس بن عبدالمطلب في الاستسقاء بسند ضعيف جدا. الأثر الإلهي: لم يقف عليه المحقق.","weak":1},{"t":"فصل: الرعب والخوف في قلب العاصي","pg":182,"lv":"yth","key":"ومن عقوباتها: ما يلقيه الله سبحانه من الرعب والخوف في قلب العاصي، فلا تراه إلا خائفا مرعوبا.","p":["فإن الطاعة حصن الله الأعظم الذي من دخله كان من الآمنين من عقوبة الدنيا والآخرة، ومن خرج عنه أحاطت به المخاوف من كل جانب. فمن أطاع الله انقلبت المخاوف في حقه أمانا، ومن عصاه انقلبت مآمنه مخاوف.","فمن خاف الله آمنه من كل شيء، ومن لم يخف الله أخافه من كل شيء."],"items":[{"h":"البيت","x":"بذا قضى الله بين الناس مذ خلقوا ... أن المخاوف والإجرام في قرن","pg":182}],"hd":""},{"t":"فصل: توقع الوحشة العظيمة في القلب","pg":182,"lv":"yth","key":"ومن عقوباتها: أنها توقع الوحشة العظيمة في القلب، فيجد المذنب نفسه مستوحشا، قد وقعت الوحشة بينه وبين ربه، وبينه وبين الخلق، وبينه وبين نفسه. وكلما كثرت الذنوب اشتدت الوحشة.","p":["وسر المسألة أن الطاعة توجب القرب من الرب، وكلما اشتد القرب قوي الأنس؛ والمعصية توجب البعد من الرب، وكلما ازداد البعد قويت الوحشة.","والوحشة سببها الحجاب، وكلما غلظ الحجاب زادت الوحشة. فالغفلة توجب الوحشة، وأشد منها وحشة المعصية، وأشد منها وحشة الشرك والكفر."],"items":[{"h":"أمر العيش وأطيبه","x":"وأمر العيش عيش المستوحشين الخائفين، وأطيب العيش عيش المستأنسين.","pg":182}],"hd":""},{"t":"فصل: تصرف القلب عن صحته إلى مرضه","pg":184,"lv":"yth","key":"ومن عقوباتها: أنها تصرف القلب عن صحته واستقامته إلى مرضه وانحرافه، فلا يزال مريضا معلولا، لا ينتفع بالأغذية التي بها حياته وصلاحه.","p":["فإن تأثير الذنوب في القلوب كتأثير الأمراض في الأبدان، بل الذنوب أمراض القلوب وأدواؤها، ولا دواء لها إلا تركها.","فهؤلاء في نعيم، وهؤلاء في جحيم. وهل النعيم إلا نعيم القلب؟ وهل العذاب إلا عذاب القلب؟"],"items":[{"h":"إجماع السائرين","x":"وقد أجمع السائرون إلى الله أن القلوب لا تعطى مناها حتى تصل إلى مولاها، ولا تصل إلى مولاها حتى تكون صحيحة سليمة، ولا تكون صحيحة سليمة حتى ينقلب داؤها فيصير نفس دوائها. ولا يصح لها ذلك إلا بمخالفة هواها، فهواها مرضها، وشفاؤها مخالفته","pg":184},{"h":"عذاب التعلق بغير الله","x":"وكل شيء تعلق به وأحبه من دون الله فإنه يسومه سوء العذاب. فكل من أحب شيئا غير الله عذب به ثلاث مرات في هذه الدار: فهو يعذب به قبل حصوله حتى يحصل. فإذا حصل عذب به حال حصوله بالخوف من سلبه وفواته... فإذا سلبه اشتد عذابه عليه.","pg":185},{"h":"أقوال العارفين","x":"إن كان أهل الجنة في مثل هذه الحال، إنهم لفي عيش طيب! ... مساكين أهل الدنيا، خرجوا منها وما ذاقوا لذيذ العيش فيها، وما ذاقوا أطيب ما فيها! ... لو علم الملوك وأبناء الملوك ما نحن فيه لجالدونا عليه بالسيوف.","pg":186},{"h":"شيخ الإسلام","x":"إن في الدنيا جنة، من لم يدخلها لم يدخل جنة الآخرة.","pg":187},{"h":"البضاعة","x":"فيا عجبا من بضاعة معك، الله مشتريها، وثمنها جنة المأوى، والسفير الذي جرى على يده عقد التبايع وضمن الثمن عن المشتري هو الرسول، وقد بعتها بغاية الهوان!","pg":187}],"hd":""},{"t":"فصل: تعمي بصيرة القلب","pg":187,"lv":"yth","key":"ومن عقوباتها: أنها تعمي بصيرة القلب، وتطمس نوره، وتسد طرق العلم، وتحجب مواد الهداية.","p":["ولا يزال هذا النور يضعف ويضمحل، وظلام المعصية يقوى، حتى يصير القلب في مثل الليل البهيم. فكم من مهلك يسقط فيه، وهو لا يبصره، كأعمى خرج بالليل في طريق ذات مهالك ومعاطب. فيا عزة السلامة، ويا سرعة العطب!"],"items":[{"h":"وصية مالك للشافعي","x":"إني أرى الله قد ألقى على قلبك نورا، فلا تطفئه بظلمة المعصية.","pg":188},{"h":"ظلمة القبر","x":"إن هذه القبور ممتلئة على أهلها ظلمة، وإن الله منورها بصلاتي عليهم","pg":188}],"hd":"«إن هذه القبور ممتلئة على أهلها ظلمة»: مسلم 956."},{"t":"فصل: تصغر النفس وتقمعها وتدسيها","pg":189,"lv":"yth","key":"ومن عقوباتها: أنها تصغر النفس، وتقمعها، وتدسيها، وتحقرها، حتى تصير أصغر شيء وأحقره، كما أن الطاعة تنميها وتزكيها وتكبرها.","p":["قال تعالى: ﴿قَدْ أَفْلَحَ مَن زَكَّاهَا ۝ وَقَدْ خَابَ مَن دَسَّاهَا﴾ (الشمس: 9 و10). والمعنى قد أفلح من كبرها وأعلاها بطاعة الله وأظهرها. وقد خسر من أخفاها وحقرها وصغرها بمعصية الله.","فما صغر النفوس مثل معصية الله، وما كبرها وشرفها ورفعها مثل طاعة الله."],"items":[],"hd":""},{"t":"فصل: العاصي دائما في أسر شيطانه","pg":190,"lv":"adl","key":"ومن عقوباتها: أن العاصي دائما في أسر شيطانه، وسجن شهواته، وقيود هواه؛ فهو أسير مسجون مقيد.","p":["ومثل القلب مثل الطائر، كلما علا بعد عن الآفات، وكلما نزل احتوشته الآفات.","وأصل هذا كله أن القلب كلما كان أبعد من الله كانت الآفات إليه أسرع، وكلما قرب من الله بعدت عنه الآفات."],"items":[{"h":"الشاة والذئب","x":"وكما أن الشاة التي لا حافظ لها وهي بين الذئاب سريعة العطب، فكذا العبد إذا لم يكن عليه حافظ من الله، فذئبه مفترسه، ولابد. وإنما يكون عليه حافظ من الله بالتقوى، فهي وقاية وجنة حصينة بينه وبين ذئبه","pg":191},{"h":"مراتب البعد","x":"والبعد من الله مراتب بعضها أشد من بعض. فالغفلة تبعد العبد عن الله، وبعد المعصية أعظم من بعد الغفلة، وبعد البدعة أعظم من بعد المعصية، وبعد النفاق والشرك أعظم من ذلك كله.","pg":191}],"hd":"«الشيطان ذئب الإنسان»: منقطع ولا يصح، ولأصل معناه شواهد، منها حديث أبي الدرداء «فإنما يأكل الذئب القاصية» وسنده لا بأس به، وصححه ابن خزيمة وابن حبان والحاكم.","weak":1},{"t":"فصل: سقوط الجاه والمنزلة والكرامة","pg":192,"lv":"yth","key":"ومن عقوباتها: سقوط الجاه والمنزلة والكرامة عند الله وعند خلقه.","p":["فإن أكرم الخلق عند الله أتقاهم، وأقربهم منه منزلة أطوعهم له، وعلى قدر طاعة العبد له تكون منزلته عنده. فإذا عصاه وخالف أمره سقط من عينه، فأسقطه من قلوب عباده.","فأتباع الرسل لهم نصيب من ذلك بحسب ميراثهم من طاعتهم ومتابعتهم. وكل من خالفهم فاته من ذلك بحسب مخالفتهم ومعصيتهم."],"items":[{"h":"لسان الصدق","x":"ومن أعظم نعم الله على العبد أن يرفع له بين العالمين ذكره ويعلي قدره.","pg":192}],"hd":""},{"t":"فصل: تسلب أسماء المدح وتكسو أسماء الذم","pg":193,"lv":"yth","key":"ومن عقوباتها: أنها تسلب صاحبها أسماء المدح والشرف، وتكسوه أسماء الذم والصغار.","p":["فتسلبه اسم المؤمن، والبر، والمحسن، والمتقي، والمطيع، والمنيب، والولي، والورع، والمصلح، والعابد، والخائف، والأواب، والطيب، والمرضي، ونحوها.","وتلك أسماء توجب رضى الرحمن، ودخول الجنان، وتوجب شرف المسمى بها على سائر نوع الإنسان."],"items":[{"h":"أسماء الذم","x":"وتكسوه اسم الفاجر، والعاصي، والمخالف، والمسيء، والمفسد، والخبيث، والمسخوط، والكاذب، والخائن، والغادر، وقاطع الرحم، وأمثالها.","pg":194},{"h":"ناهي العقل","x":"فلو لم يكن في عقوبة المعصية إلا استحقاق تلك الأسماء وموجباتها لكان في العقل ناه عنها.","pg":194}],"hd":""},{"t":"فصل: تؤثر بالخاصية في نقصان العقل","pg":194,"lv":"yth","key":"ومن عقوباتها: أنها تؤثر بالخاصية في نقصان العقل. فلا تجد عاقلين أحدهما مطيع لله، والآخر عاص، إلا وعقل المطيع منهما أوفر وأكمل، وفكره أصح، ورأيه أسد، والصواب قرينه.","p":["فأي عقل لمن آثر لذة ساعة أو يوم أو دهر، ثم تنقضي كأنها حلم لم يكن، على هذا النعيم المقيم والفوز العظيم؟","فلا إله إلا الله، ما أنقص عقل من باع الدر بالبعر، والمسك بالرجيع"],"items":[{"h":"خطاب القرآن","x":"ولهذا تجد خطاب القرآن إنما هو مع أولي العقول والألباب","pg":194},{"h":"الجائحة العامة","x":"فلولا الاشتراك في هذا النقصان لظهر لمطيعنا نقصان عقل عاصينا، ولكن الجائحة عامة، والجنون فنون!","pg":195}],"hd":""},{"t":"فصل: توجب القطيعة بين العبد وربه","pg":196,"lv":"yth","key":"ومن أعظم عقوباتها: أنها توجب القطيعة بين العبد وبين ربه تبارك وتعالى، وإذا وقعت القطيعة انقطعت عنه أسباب الخير، واتصلت به أسباب الشر.","p":["قال بعض السلف: رأيت العبد ملقى بين الله سبحانه وبين الشيطان، فإن أعرض الله عنه تولاه الشيطان، وإن تولاه الله لم يقدر عليه الشيطان.","ويشبه أن يكون تحت هذا الخطاب نوع من العتاب لطيف عجيب، وهو أني عاديت إبليس إذ لم يسجد لأبيكم آدم مع ملائكتي، فكانت معاداته لأجلكم، ثم كان عاقبة هذه المعاداة أن عقدتم بينكم وبينه عقد المصالحة!"],"items":[{"h":"آية الكهف","x":"﴿أَفَتَتَّخِذُونَهُ وَذُرِّيَّتَهُ أَوْلِيَاءَ مِن دُونِي وَهُمْ لَكُمْ عَدُوٌّ ۚ بِئْسَ لِلظَّالِمِينَ بَدَلًا﴾ (الكهف: 50)","pg":197},{"h":"موالاة العدو","x":"وأما أن توالي أعداء الملك ثم تدعي أنك موال له، فهذا محال.","pg":198}],"hd":"قول مطرف بن عبدالله بن الشخير: أخرجه أحمد في الزهد وسنده حسن، وابن المبارك وابن عساكر وسنده صحيح."},{"t":"فصل: تمحق بركة الدين والدنيا","pg":199,"lv":"kid","key":"ومن عقوباتها: أنها تمحق بركة العمر، وبركة الرزق، وبركة العلم، وبركة العمل، وبركة الطاعة. وبالجملة، تمحق بركة الدين والدنيا.","p":["فلا تجد أقل بركة في عمره ودينه ودنياه ممن عصى الله. وما محقت البركة من الأرض إلا بمعاصي الخلق."],"items":[{"h":"آية الأعراف","x":"﴿وَلَوْ أَنَّ أَهْلَ الْقُرَىٰ آمَنُوا وَاتَّقَوْا لَفَتَحْنَا عَلَيْهِم بَرَكَاتٍ مِّنَ السَّمَاءِ وَالْأَرْضِ﴾ (الأعراف: 96)","pg":199},{"h":"الحديث","x":"إن روح القدس نفث في روعي أنه لن تموت نفس حتى تستكمل رزقها، فاتقوا الله وأجملوا في الطلب، فإنه لا ينال ما عند الله إلا بطاعته","pg":199}],"hd":"«إن روح القدس نفث في روعي»: أبو عبيد في غريب الحديث والبغوي والقضاعي، من طريق زبيد اليامي عمن أخبره عن ابن مسعود، وفيه اختلاف (يتم كلام المحقق في ص 200 خارج هذا الجزء). «إن العبد ليحرم الرزق بالذنب يصيبه»: سبق تخريجه في ص 103."}],"lv":{"kid":{"show":true,"title":"الحسنة تنادي أختها","intro":"إذا عملت عملا طيبا نادتك حسنة أخرى: اعملني أيضا، فيكثر الخير في حياتك. والطاعة تجعلك عزيزا، والحياء يحفظك، والقلب الذي يقترب من الله يكون مثل الطائر الذي يطير عاليا بعيدا عن الخطر. أما المعصية فتنادي أختها، وتذهب ببركة الوقت والرزق والنعم.","points":["الحسنة تجر حسنة بعدها، والسيئة تجر سيئة بعدها.","العز كله في طاعة الله.","الحياء خير كله، ومن استحيا من الله أحبه الله.","النعم تبقى بالطاعة والشكر، وتزول بالمعصية.","كلما اقترب قلبي من الله ابتعد عنه الشر."],"quote":{"x":"إن من ثواب الحسنة الحسنة بعدها","pg":139},"quiz":[{"q":"ماذا تقول الحسنة إذا عملها العبد كما في الكتاب؟","o":["اعملني أيضا","اتركني الآن","انسني غدا","أخرني قليلا"],"why":"فالعبد إذا عمل حسنة قالت أخرى إلى جانبها: اعملني أيضا","pg":139},{"q":"كيف وصف النبي ﷺ الحياء؟","o":["الحياء خير كله","الحياء ضعف وخجل","الحياء للصغار فقط","الحياء يمنع التعلم"],"why":"وفي الصحيح عنه ﷺ أنه قال: الحياء خير كله.","pg":168},{"q":"أين يجد الإنسان العز كما في الكتاب؟","o":["في طاعة الله","في كثرة المال","في شهرة اسمه","في قوة جسمه"],"why":"فإن العز كل العز في طاعة الله تعالى.","pg":146},{"q":"بماذا شبه ابن القيم القلب الذي يعلو فيبتعد عن الآفات؟","o":["بالطائر","بالحجر","بالسمكة","بالشجرة"],"why":"ومثل القلب مثل الطائر، كلما علا بعد عن الآفات، وكلما نزل احتوشته الآفات.","pg":190}],"scene":{"t":"الهاتف المفتوح","x":"ترك صديق عمر هاتفه مفتوحا على الطاولة وخرج من الصف، ولا أحد ينظر. تذكر عمر أن الله يراه. ماذا يفعل؟","opts":["لا يلمسه ويحفظ سر صديقه حتى يعود","يفتح رسائل صديقه خفية","يأخذ الهاتف ليلعب به قليلا"],"why":"ومن استحيا من الله عند معصيته استحيا الله من عقوبته يوم يلقاه","pg":170},"act":{"type":"match","t":"الطاعة وثمرتها","x":"صل كل عمل بثمرته كما في كتاب ابن القيم، ثم لون الثمرة التي تحب أن تراها في حياتك هذا الأسبوع.","items":[{"a":"الحسنة","b":"تجر حسنة بعدها"},{"a":"طاعة الله","b":"العز"},{"a":"الحياء","b":"خير كله"},{"a":"القرب من الله","b":"تبتعد الآفات"},{"a":"التقوى","b":"تفتح البركات"}]}},"yth":{"show":true,"title":"حين تصير المعصية عادة","intro":"يشرح ابن القيم كيف تتدرج المعصية: خطرة ثم وسوسة ثم إرادة ثم عزيمة ثم فعل ثم صفة راسخة. ومع الإصرار تضعف إرادة التوبة، ويذهب استقباح الذنب حتى يجاهر به صاحبه، ويطبع على القلب، وتنطفئ الغيرة والحياء، ويصير العبد أسيرا لشيطانه وشهوته. والطريق المعاكس متاح: الطاعة تجر الطاعة حتى تصير عادة يحبها القلب.","points":["أخطر الآثار ضعف إرادة التوبة حتى تصير توبة باللسان فقط.","المجاهرة بالذنب تغلق أبواب العافية في الغالب.","الغيرة والحياء حراس القلب، والذنوب تطفئهما.","الطاعة حصن، فمن خاف الله آمنه من كل شيء.","المعصية تصغر النفس، والطاعة تكبرها وتشرفها."],"quote":{"x":"فالذنب يحجب الواصل، ويقطع السائر، وينكس الطالب.","pg":178},"quiz":[{"q":"ما الأثر الذي وصفه ابن القيم بأنه من أخوف آثار المعاصي على العبد؟","o":["أنها تضعف القلب عن إرادة التوبة","أنها تنقص المال وتذهب بالتجارة","أنها تمرض البدن وتضعف السمع","أنها تكثر الأعداء من الناس حوله"],"why":"أنها تضعف القلب عن إرادته، فتقوى إرادة المعصية، وتضعف إرادة التوبة شيئا فشيئا","pg":141},{"q":"لماذا يخشى على المجاهر بالمعصية أكثر من غيره؟","o":["لأنه تسد عليه طريق التوبة غالبا","لأن ذنبه لا يكتب عليه أصلا","لأن الناس يعذرونه فلا يلومونه أبدا","لأنه يستر نفسه فلا يعرفه أحد"],"why":"وهذا الضرب من الناس لا يعافون، وتسد عليهم طريق التوبة، وتغلق عنهم أبوابها في الغالب","pg":142},{"q":"ما ترتيب تحول الخاطرة إلى صفة راسخة كما في الكتاب؟","o":["خطرة ثم وسوسة ثم إرادة ثم عزيمة ثم فعل","فعل ثم خطرة ثم إرادة ثم وسوسة ثم عزيمة","إرادة ثم فعل ثم خطرة ثم عزيمة ثم وسوسة","وسوسة ثم فعل ثم عزيمة ثم خطرة ثم إرادة"],"why":"فإن الخطرة تنقلب وسوسة، والوسوسة تصير إرادة، والإرادة تقوى فتصير عزيمة، ثم تصير فعلا، ثم تصير صفة لازمة وهيئة ثابتة راسخة","pg":167},{"q":"من الذي يؤمنه الله من كل شيء؟","o":["من خاف الله","من كثر أصحابه","من قوي جسمه","من كثر ماله"],"why":"فمن خاف الله آمنه من كل شيء، ومن لم يخف الله أخافه من كل شيء.","pg":182},{"q":"ما الذي يصغر النفس ويحقرها أكثر من أي شيء؟","o":["معصية الله","شدة الفقر","قلة الأصحاب","ضعف الأجسام"],"why":"فما صغر النفوس مثل معصية الله، وما كبرها وشرفها ورفعها مثل طاعة الله.","pg":189}],"scene":{"t":"المقطع المنشور","x":"صور يوسف نفسه يفعل مخالفة ونشر المقطع لأصدقائه وهو يضحك ويفتخر، فأعجب به بعضهم. ما التصرف الصحيح؟","opts":["يحذف المقطع ويستر نفسه ويتوب إلى الله","يتركه لأنه مجرد مزاح بين الأصدقاء","يعتذر لأصدقائه ويبقي المقطع منشورا"],"why":"كل أمتي معافى إلا المجاهرين. وإن من الإجهار أن يستر الله على العبد، ثم يصبح يفضح نفسه","pg":142},"act":{"type":"guard","t":"لكل أثر حارس","x":"اقرأ كل أثر من آثار المعاصي، واكتب أمامه الحارس الذي ذكره ابن القيم، ثم اختر أثرا واحدا تحرس نفسك منه هذا الأسبوع بخطوة عملية تكتبها في دفترك.","items":[{"a":"الذل","b":"العز كل العز في طاعة الله"},{"a":"الوحشة","b":"الطاعة توجب القرب من الرب فيقوى الأنس"},{"a":"الرعب والخوف","b":"من خاف الله آمنه من كل شيء"},{"a":"أسر الشيطان","b":"التقوى وقاية وجنة حصينة"},{"a":"زوال النعم","b":"تغيير المعصية بالطاعة"},{"a":"مرض القلب","b":"مخالفة الهوى"}]}},"adl":{"show":true,"title":"خريطة آثار المعاصي في القلب والنفس","intro":"في هذه الفصول يتابع ابن القيم سرد آثار المعاصي، فيبين أنها تتوالد وتضعف الإرادة وتذهب الاستقباح، وتورث الهوان والذل، وتفسد العقل، وتطبع على القلب، وتدخل تحت اللعنة وتحرم دعوة الملائكة، وتفسد الأرض، وتطفئ الغيرة والحياء وتعظيم الرب، وتستدعي نسيان الله لعبده، وتخرجه من دائرة الإحسان، وتضعف سيره إلى الله، وتزيل النعم، وتورث الرعب والوحشة ومرض القلب وعماه، وتصغر النفس، وتأسره للشيطان، وتسقط جاهه، وتسلبه أسماء المدح، وتنقص عقله، وتقطعه عن ربه، وتمحق البركة.","points":["القاعدة الجامعة: الذنوب أمراض القلوب، ولا دواء لها إلا تركها.","التلازم بين الذنوب وقلة الحياء وعدم الغيرة يجعل الانحدار متسارعا.","الجزاء من جنس العمل: على قدر تعظيم العبد لله يعظم الناس حرماته.","البعد عن الله مراتب: الغفلة ثم المعصية ثم البدعة ثم النفاق والشرك.","تغيير المعصية بالطاعة يغير العقوبة بالعافية والذل بالعز."],"quote":{"x":"بل الذنوب أمراض القلوب وأدواؤها، ولا دواء لها إلا تركها.","pg":184},"quiz":[{"q":"ما الغيرة الممدوحة كما قررها ابن القيم؟","o":["اقتران الغيرة بالعذر كل في موضعه","شدة الغيرة في كل حال ولو بلا ريبة","قبول كل عذر حتى في مواضع الريبة","ترك الغيرة كلها لئلا يظلم بها أحد"],"why":"وإنما الممدوح اقتران الغيرة بالعذر، فيغار في محل الغيرة، ويعذر في موضع العذر.","pg":165},{"q":"بماذا وصف ابن القيم قول العاصي: يحملني على المعاصي حسن الرجاء؟","o":["مغالطة للنفس","كمال للمعرفة","مقام للصالحين","حسن ظن صحيح"],"why":"وربما اغتر المغتر وقال: إنما يحملني على المعاصي حسن الرجاء وطمعي في عفوه، لا ضعف عظمته في قلبي. وهذا من مغالطة النفس","pg":171},{"q":"ما العلاقة بين الذنوب وقلة الحياء وعدم الغيرة؟","o":["تلازم من الطرفين يستدعي كل منهما الآخر","الذنوب تزيد الحياء وتضعف الغيرة وحدها","الحياء يقوى كلما كثرت الذنوب في القلب","لا علاقة بينها لأن الحياء طبع لا يتغير"],"why":"وبين الذنوب وبين قلة الحياء وعدم الغيرة تلازم من الطرفين، وكل منهما يستدعي الآخر، ويطلبه حثيثا.","pg":170},{"q":"ما ترتيب مراتب البعد عن الله من الأخف إلى الأشد؟","o":["الغفلة ثم المعصية ثم البدعة ثم النفاق والشرك","المعصية ثم الغفلة ثم النفاق والشرك ثم البدعة","البدعة ثم الغفلة ثم المعصية ثم النفاق والشرك","الغفلة ثم البدعة ثم المعصية ثم النفاق والشرك"],"why":"فالغفلة تبعد العبد عن الله، وبعد المعصية أعظم من بعد الغفلة، وبعد البدعة أعظم من بعد المعصية، وبعد النفاق والشرك أعظم من ذلك كله.","pg":191},{"q":"ما أعظم العقوبات في فصل نسيان الله لعبده؟","o":["نسيان العبد لنفسه وإضاعة حظها من الله","فقد المال والولد في الدنيا مع الصبر","تسلط الأعداء على البلاد والأموال","ذهاب الصحة وقوة البدن مع كبر السن"],"why":"وأعظم العقوبات نسيان العبد لنفسه، وإهماله لها، وإضاعته حظها ونصيبها من الله","pg":173}],"scene":{"t":"الطالب المتباهي","x":"معلم يرى طالبا يحكي لزملائه مخالفاته في نهاية الأسبوع متباهيا، وهم يضحكون ويشجعونه. ما التصرف الأحكم؟","opts":["ينفرد به وينصحه بستر نفسه ويبين له خطر المجاهرة","يفضحه أمام الصف ليرتدع غيره","يتجاهل الأمر ما دام خارج وقت الدرس"],"why":"وهذا عند أرباب الفسوق هو غاية التهتك وتمام اللذة، حتى يفتخر أحدهم بالمعصية، ويحدث بها من لم يعلم أنه عملها","pg":141},"act":{"type":"class","t":"مجلس خريطة الآثار","x":"نشاط للمربي مع طلابه أو أبنائه مدته 45 دقيقة، يحول فيه فصول آثار المعاصي إلى خريطة مرئية تربط كل داء بدوائه.","items":["5 دقائق: يقرأ المربي قوله «بل الذنوب أمراض القلوب وأدواؤها، ولا دواء لها إلا تركها» ويطرح السؤال: كيف يمرض القلب؟","10 دقائق: توزع البطاقات على 5 مجموعات: آثار في الإرادة، آثار في الحياء والغيرة، آثار في الصلة بالله، آثار في النعم والبركة، آثار في المنزلة والعقل.","10 دقائق: تستخرج كل مجموعة الجملة الحرفية لكل أثر وصفحتها، وتكتب علامة يعرف بها الطالب الأثر في نفسه.","10 دقائق: تعرض المجموعات، ويضيف المربي الدواء من الكتاب: الطاعة تولد الطاعة، تغيير المعصية بالطاعة، الخوف من الله، مخالفة الهوى، التقوى.","10 دقائق: يكتب كل مشارك في دفتره الخاص أثرا يخشاه، وطاعة صغيرة يبدأ بها لتجر أختها."]}},"alt":{}},"highlights":[{"x":"إن من ثواب الحسنة الحسنة بعدها","pg":139,"lv":"kid"},{"x":"فإن العز كل العز في طاعة الله تعالى","pg":146,"lv":"kid"},{"x":"الحياء خير كله","pg":168,"lv":"kid"},{"x":"فالذنب يحجب الواصل، ويقطع السائر، وينكس الطالب","pg":178,"lv":"yth"},{"x":"فمن خاف الله آمنه من كل شيء، ومن لم يخف الله أخافه من كل شيء","pg":182,"lv":"yth"},{"x":"وهل النعيم إلا نعيم القلب؟ وهل العذاب إلا عذاب القلب؟","pg":185,"lv":"yth"},{"x":"فما صغر النفوس مثل معصية الله، وما كبرها وشرفها ورفعها مثل طاعة الله","pg":189,"lv":"yth"},{"x":"إن في الدنيا جنة، من لم يدخلها لم يدخل جنة الآخرة","pg":187,"lv":"adl"}],"concepts":[{"term":"الران","def":"هو الذنب بعد الذنب","pg":148},{"term":"الطبع والختم","def":"وأصل هذا أن القلب يصدأ من المعصية، فإن زادت غلب الصدأ حتى يصير رانا، ثم يغلب حتى يصير طبعا وقفلا وختما","pg":148},{"term":"الحياء","def":"الحياء الذي هو مادة الحياة للقلب، وهو أصل كل خير","pg":168},{"term":"الغيرة","def":"فالغيرة حرارته وناره التي تخرج ما فيه من الخبث والصفات المذمومة، كما يخرج الكير خبث الذهب والفضة والحديد","pg":163},{"term":"الهم والحزن","def":"فإن المكروه الوارد على القلب إن كان من أمر مستقبل يتوقعه أحدث الهم، وإن كان من أمر ماض قد وقع أحدث الحزن.","pg":178},{"term":"العجز والكسل","def":"فإن تخلف العبد عن أسباب الخير والفلاح إن كان لعدم قدرته فهو العجز، وإن كان لعدم إرادته فهو الكسل.","pg":179},{"term":"الجبن والبخل","def":"فإن عدم النفع منه إن كان ببدنه فهو الجبن، وإن كان بماله فهو البخل.","pg":179},{"term":"ضلع الدين وقهر الرجال","def":"فإن استعلاء الغير عليه إن كان بحق فهو من ضلع الدين، وإن كان بباطل فهو قهر الرجال.","pg":179},{"term":"التدسية","def":"وأصل التدسية الإخفاء... فالعاصي يدس نفسه في المعصية، ويخفي مكانها، ويتوارى من الخلق من سوء ما يأتي به","pg":189},{"term":"الوحشة","def":"والوحشة سببها الحجاب، وكلما غلظ الحجاب زادت الوحشة.","pg":183}],"stories":[{"t":"رؤيا النبي ﷺ في حديث سمرة","x":"رأى النبي ﷺ في منامه رجلين انطلقا به فأراه من عقوبات أهل المعاصي: رجلا يشدخ رأسه بالحجر لأنه رفض القرآن ونام عن الصلاة المكتوبة، ورجلا يشق شدقه لأنه كذب كذبة تبلغ الآفاق، وآكل الربا يسبح في نهر من دم ويلقم الحجارة، ثم أراه إبراهيم عليه السلام في روضة حوله أولاد الناس الذين ماتوا على الفطرة، ومدينة من ذهب وفضة هي جنة عدن.","pg":153,"lv":"yth","hd":"البخاري 7047"},{"t":"ديار ثمود","x":"مر النبي ﷺ على ديار ثمود فمنع أصحابه من دخولها والشرب من مياهها، وأمر أن يعلف العجين الذي عجن بمائها للإبل، لتأثير شؤم المعصية في الماء.","pg":160,"lv":"yth","hd":"البخاري 3379 ومسلم 2981"},{"t":"حنطة زمن العدل","x":"وجدت في خزائن بني أمية صرة فيها حبات حنطة كل حبة بقدر نواة التمر، مكتوب عليها: هذا كان ينبت في زمن العدل.","pg":160,"lv":"adl","hd":"المسند، وسنده صحيح إلى أبي قحذم"},{"t":"غيرة سعد","x":"قال النبي ﷺ لما ذكرت غيرة سعد بن عبادة: أتعجبون من غيرة سعد؟ لأنا أغير منه، والله أغير مني.","pg":163,"lv":"adl","hd":"البخاري 6846 ومسلم 1499"},{"t":"لو علم الملوك","x":"قال أحد العارفين واصفا لذة الأنس بالله: لو علم الملوك وأبناء الملوك ما نحن فيه لجالدونا عليه بالسيوف.","pg":186,"lv":"yth","hd":"ينسب إلى إبراهيم بن أدهم، الحلية"},{"t":"العتاب اللطيف","x":"يذكر الله عباده أنه أكرم أباهم آدم وأمر الملائكة بالسجود له، فأبى إبليس، فعاداه الله لأجلهم، ثم صالحوه هم واتخذوه وذريته أولياء من دون الله.","pg":198,"lv":"yth","hd":""}],"ready":true},{"k":"s6","t":"المعاصي في حياة العبد، وثغور الشيطان","pgs":[199,258],"q":"كيف تفسد المعاصي حياة العبد، ومن أين يدخل الشيطان إلى قلبه؟","essence":"كل معصية مدد لعدوك وثغر مفتوح","kw":["البركة","الثغور","المرابطة"],"daa":"معاص تمحق البركة وتعمي القلب وتفتح ثغور العين والأذن واللسان للعدو.","dawa":"لزوم الطاعة حصنا، ومرابطة الثغور بالصبر والتقوى، وذكر الله ومخالفة الهوى، والتوبة النصوح.","sections":[{"t":"فصل: ومن عقوباتها أنها تمحق البركة","pg":199,"lv":"adl","key":"ومن عقوباتها: أنها تمحق بركة العمر، وبركة الرزق، وبركة العلم، وبركة العمل، وبركة الطاعة. وبالجملة، تمحق بركة الدين والدنيا.","p":["فلا تجد أقل بركة في عمره ودينه ودنياه ممن عصى الله. وما محقت البركة من الأرض إلا بمعاصي الخلق.","وليست سعة الرزق والعمل بكثرته، ولا طول العمر بكثرة الشهور والأعوام، ولكن سعة الرزق والعمر بالبركة فيه.","فمن كل شيء يفوت العبد عوض، وإذا فاته الله لم يعوض عنه شيء البتة."],"items":[{"h":"شاهد القرآن","x":"﴿ولو أن أهل القرى آمنوا واتقوا لفتحنا عليهم بركات من السماء والأرض﴾ [الأعراف 96]","pg":199},{"h":"حياة القلب","x":"فإن حياة الإنسان بحياة قلبه وروحه، ولا حياة لقلبه إلا بمعرفة فاطره، ومحبته، وعبادته وحده، والإنابة إليه، والطمأنينة بذكره، والأنس بقربه.","pg":201},{"h":"سبب المحق","x":"وإنما كانت معصية الله سببا لمحق بركة الرزق والأجل، لأن الشيطان موكل بها وبأصحابها، فسلطانه عليهم، وحوالته على هذا الديوان وأهله أصحابه","pg":202},{"h":"علاج يجلب البركة","x":"ولهذا شرع ذكر اسم الله تعالى عند الأكل والشرب واللبس والركوب والجماع، لما في مقارنة اسم الله من البركة. وذكر اسمه يطرد الشيطان، فتحصل البركة، ولا معارض لها.","pg":202},{"h":"ضد البركة","x":"وكل شيء لا يكون لله، فبركته منزوعة، فإن الرب هو الذي تبارك وحده، والبركة كلها منه","pg":202},{"h":"ما يبقى لك","x":"فكل وقت عصيت الله فيه، أو مال عصي الله به، أو بدن، أو جاه، أو علم، أو عمل، فهو على صاحبه، ليس له. فليس له من عمره وماله وقوته وجاهه وعلمه وعمله إلا ما أطاع الله به.","pg":203}],"hd":"حديث «إن روح القدس نفث في روعي...»: قال المحقق: ضعيف الإسناد للإبهام في قوله (عمن أخبره)، وورد معناه من حديث جابر عند ابن ماجه 2144 وابن حبان والحاكم. وحديث «إن الله جعل الروح والفرح في الرضا واليقين...»: موقوف على ابن مسعود فيه انقطاع، والمرفوع لا يصح. وحديث «الدنيا ملعونة...»: رواه الترمذي 2322 وقال حسن غريب، وذكر المحقق اضطراب ابن ثوبان فيه وعدّه العقيلي من منكراته، وأثر «إلا ما كان لله» الصواب أنه مرسل. وعبارة «وإن العبد ليحرم الرزق بالذنب يصيبه» أحال المحقق على تخريجها في ص 103.","weak":1},{"t":"فصل: ومن عقوباتها أنها تجعل صاحبها من السفلة","pg":205,"lv":"adl","key":"ومن عقوباتها: أنها تجعل صاحبها من السفلة بعد أن كان مهيأ لأن يكون من العلية.","p":["وجعل أهل طاعته الأعلين في الدنيا والآخرة، وأهل معصيته الأسفلين في الدنيا والآخرة؛ كما جعل أهل طاعته أكرم خلقه عليه، وأهل معصيته أهون خلقه عليه، وجعل العزة لهؤلاء، والذلة والصغار لهؤلاء.","فكلما عمل العبد معصية نزل إلى أسفل درجة، ولا يزال في نزول حتى يكون من الأسفلين. وكلما عمل طاعة ارتفع بها درجة، ولا يزال في ارتفاع حتى يكون من الأعلين."],"items":[{"h":"غلط عظيم","x":"وهو أن العبد قد ينزل نزولا بعيدا أبعد مما بين المشرق والمغرب ومما بين السماء والأرض، فلا يفي صعوده ألف درجة بهذا النزول الواحد","pg":206},{"h":"النزول إلى غفلة","x":"ولكن من الناس من يكون نزوله إلى غفلة، فهذا متى استيقظ من غفلته عاد إلى درجته، أو إلى أرفع منها بحسب يقظته.","pg":206},{"h":"النزول إلى مباح","x":"ومنهم من يكون نزوله إلى مباح لا ينوي به الاستعانة على الطاعة. فهذا متى رجع إلى الطاعة فقد يعود إلى درجته، وقد لا يصل إليها، وقد يرتفع عنها","pg":206},{"h":"النزول إلى معصية","x":"ومنهم من يكون نزوله إلى معصية: إما صغيرة أو كبيرة، فهذا يحتاج في عوده إلى درجته إلى توبة نصوح وإنابة صادقة.","pg":207},{"h":"حكم شيخ الإسلام","x":"التحقيق أن من التائبين من يعود إلى أرفع من درجته، ومنهم من يعود إلى مثل درجته، ومنهم من لا يصل إلى درجته.","pg":208},{"h":"قوة التوبة","x":"قلت: وهذا بحسب قوة التوبة وكمالها، وما أحدثته المعصية للعبد من الذل والخضوع والإنابة، والحذر والخوف من الله، والبكاء من خشيته","pg":208},{"h":"الخطيئة قد تكون رحمة","x":"فهذا قد تكون الخطيئة في حقه رحمة، فإنها نفت عنه داء العجب، وخلصته من ثقته بنفسه وأعماله","pg":208},{"h":"حلم الله","x":"ولولا حلمه ومغفرته لزالت السموات والأرض من معاصي العباد.","pg":210},{"h":"النزول إلى الشك","x":"فإن كان نزوله إلى أمر يقدح في أصل إيمانه مثل الشكوك والريب والنفاق، فذاك نزول لا يرجى لصاحبه صعود إلا بتجديد إسلامه من رأس.","pg":212}],"hd":"حديث «إن العبد ليتكلم بالكلمة الواحدة لا يلقي لها بالا يهوي بها في النار أبعد مما بين المشرق والمغرب»: رواه البخاري 6477 ومسلم 2988. وحديث «جعل الذلة والصغار على من خالف أمري»: أحال المحقق على تخريجه في ص 143.","weak":1},{"t":"فصل: ومن عقوباتها أنها تجرئ على العبد من لم يكن يجترئ عليه","pg":212,"lv":"kid","key":"ومن عقوباتها: أنها تجرئ على العبد من لم يكن يجترئ عليه من أصناف المخلوقات.","p":["فيجترئ عليه الشياطين بالأذى، والإغواء، والوسوسة، والتخويف، والتحزين، وإنسائه ما مصلحته في ذكره، ومضرته في نسيانه؛ فتجترئ عليه الشياطين حتى تؤزه إلى معصية الله أزا.","وذلك لأن الطاعة حصن الرب تبارك وتعالى الذي من دخله كان من الآمنين، فإذا فارق الحصن اجترأ عليه قطاع الطريق وغيرهم"],"items":[{"h":"شياطين الإنس والأهل","x":"ويجترئ عليه شياطين الإنس بما تقدر عليه من أذاه في غيبته وحضوره. ويجترئ عليه أهله وخدمه وأولاده وجيرانه، حتى الحيوان البهيم!","pg":212},{"h":"تجترئ عليه نفسه","x":"وكذلك تجترئ عليه نفسه، فتتأسد عليه، وتستصعب عليه، فلو أرادها لخير لم تطاوعه، ولم تنقد له. وتسوقه إلى ما فيه هلاكه، شاء أم أبى.","pg":212},{"h":"الوقاية","x":"فإن ذكر الله، وطاعته، والصدقة، وإرشاد الجاهل، والأمر بالمعروف والنهي عن المنكر وقاية ترد عن العبد، بمنزلة القوة التي ترد المرض وتقاومه","pg":213},{"h":"قانون التدافع","x":"وكلما قوي جانب الحسنات كان الرد أقوى، فإن الله يدافع عن الذين آمنوا، والإيمان قول وعمل، فبحسب قوة الإيمان يكون الدفع.","pg":213}],"hd":""},{"t":"فصل: ومن عقوباتها أنها تخون العبد أحوج ما يكون إلى نفسه","pg":213,"lv":"yth","key":"ومن عقوباتها: أنها تخون العبد أحوج ما يكون إلى نفسه.","p":["وأعلم الناس أعرفهم بذلك على التفصيل، وأقواهم وأكيسهم من قوي على نفسه وإرادته، فاستعملها فيما ينفعه، وكفها عما يضره.","كذلك القلب يصدأ بالذنوب ويجرب، ويصير مثخنا بالمرض، فإذا احتاج إلى محاربة العدو به لم يجد معه شيئا. والعبد إنما يحارب ويصاول ويقدم بقلبه، والجوارح تبع للقلب"],"items":[{"h":"مثل السيف","x":"وكان بمنزلة رجل معه سيف قد غشيه الجرب، ولزم قرابه بحيث لا ينجذب مع صاحبه إذا جذبه، فعرض له عدو يريد قتله، فوضع يده على قائم سيفه، واجتهد ليخرجه، فلم يخرج معه، فدهمه العدو، وظفر به.","pg":214},{"h":"عند الشدة","x":"والمقصود أن العبد إذا وقع في شدة أو كربة أو بلية خانه قلبه ولسانه وجوارحه عما هو أنفع شيء له، فلا ينجذب قلبه للتوكل على الله، والإنابة إليه، والجمعية عليه، والتضرع والتذلل والانكسار بين يديه.","pg":215},{"h":"مثل الجند","x":"وهذا كله أثر الذنوب والمعاصي، كمن له جند يدفعون عنه الأعداء، فأهمل جنده، وضيعهم، وأضعفهم، وقطع أخبارهم، ثم أراد منهم عند هجوم العدو عليه أن يستفرغوا وسعهم في الدفع عنه بغير قوة!","pg":216},{"h":"الأخوف","x":"وثم أمر أخوف من ذلك وأدهى منه وأمر، وهو أن يخونه قلبه ولسانه عند الاحتضار والانتقال إلى الله تعالى، فربما تعذر عليه النطق بالشهادة","pg":216},{"h":"آخر العمل","x":"فإن ذلك آخر العمل، فأقوى ما يكون عليه شيطانه ذلك الوقت، وأضعف ما يكون هو في تلك الحال؟ فمن ترى يسلم على ذلك؟","pg":218},{"h":"خوف الخاتمة","x":"ولقد قطع خوف الخاتمة ظهور المتقين، وكأن المسيئين الظالمين قد أخذوا توقيعا بالأمان!","pg":219}],"hd":""},{"t":"فصل: ومن عقوباتها أنها تعمي القلب","pg":220,"lv":"kid","key":"ومن عقوباتها: أنها تعمي القلب، فإن لم تعمه أضعفت بصيرته، ولابد.","p":["فإذا عمي القلب وضعف فاته من معرفة الهدى، وقوته على تنفيذه في نفسه وفي غيره، بحسب ضعف بصيرته وقوته.","بل قد تتوارد على القلب حتى ينعكس إدراكه، كما ينعكس سيره، فيدرك الباطل حقا، والحق باطلا، والمعروف منكرا، والمنكر معروفا.","وهذا كما أن الطاعة تنور القلب، وتجلوه، وتصقله، وتقويه وتثبته، حتى يصير كالمرآة المجلوة في جلائها وصفائها ويمتلئ نورا"],"items":[{"h":"لو لم يكن إلا هذه","x":"ولو لم يكن في عقوبة الذنوب إلا هذه العقوبة وحدها لكانت كافية داعية إلى تركها والبعد منها","pg":222},{"h":"القلب المنور","x":"فالشيطان يفرق من هذا القلب أشد من فرق الذئب من الأسد","pg":222},{"h":"القرين","x":"قيض الله منه شيطانا عقوبة له بإعراضه عن كتابه. فهو قرينه الذي لا يفارقه في الإقامة ولا في المسير","pg":223}],"hd":""},{"t":"مدار الكمال الإنساني وانقسام الناس أربعة أقسام","pg":220,"lv":"yth","key":"فإن الكمال الإنساني مداره على أصلين: معرفة الحق من الباطل، وإيثاره عليه.","p":["وما تفاوتت منازل الخلق عند الله في الدنيا والآخرة إلا بقدر تفاوت منازلهم في هذين الأمرين.","فالأيدي: القوى في تنفيذ الحق، والأبصار: البصائر في الدين. فوصفهم بكمال إدراك الحق، وكمال تنفيذه."],"items":[{"h":"القسم الأول","x":"فهؤلاء أشرف أقسام الخلق وأكرمهم على الله.","pg":220},{"h":"القسم الثاني","x":"عكس هؤلاء، لا بصيرة في الدين، ولا قوة على تنفيذ الحق.","pg":220},{"h":"القسم الثالث","x":"من له بصيرة بالحق ومعرفة به، لكنه ضعيف لا قوة له على تنفيذه ولا الدعوة إليه. وهذا حال المؤمن الضعيف، والمؤمن القوي خير وأحب إلى الله منه.","pg":221},{"h":"القسم الرابع","x":"من له قوة وهمة وعزيمة، لكنه ضعيف البصيرة في الدين، لا يكاد يميز بين أولياء الرحمن وأولياء الشيطان، بل يحسب كل سوداء تمرة، وكل بيضاء شحمة","pg":221},{"h":"الإمامة في الدين","x":"فأخبر سبحانه أن بالصبر واليقين نالوا الإمامة في الدين.","pg":221}],"hd":"«والمؤمن القوي خير وأحب إلى الله منه»: أحال المحقق على تخريجه في ص 166، وهو في صحيح مسلم."},{"t":"فصل: ومن عقوباتها أنها مدد من الإنسان يمد به عدوه عليه","pg":225,"lv":"kid","key":"ومن عقوباتها: أنها مدد من الإنسان يمد به عدوه عليه، وجيش يقويه به على حربه.","p":["وذلك أن الله سبحانه ابتلى هذا الإنسان بعدو لا يفارقه طرفة عين، ينام، ولا ينام عنه. ويغفل، ولا يغفل عنه. يراه هو وقبيله من حيث لا يراه.","وقد أعلمنا سبحانه بذلك كله من عدونا، وأمرنا أن نأخذ له أهبته، ونعد له عدته."],"items":[{"h":"قائد الحرب","x":"فعقد سبحانه لواء هذا الحرب لخلاصة مخلوقاته، وهو القلب الذي هو محل معرفته، ومحبته، وعبوديته، والإخلاص له، والتوكل عليه، والإنابة إليه.","pg":227},{"h":"جند الملائكة","x":"ويقولون: إنما هو صبر ساعة، وقد استرحت راحة الأبد.","pg":227},{"h":"أعوان القلب","x":"وأمده مع ذلك بالعقل وزيرا له ومدبرا، وبالمعرفة مشيرة عليه ناصحة له، وبالإيمان مثبتا له ومؤيدا وناصرا، وباليقين كاشفا له عن حقيقة الأمر.","pg":227},{"h":"القوى الظاهرة","x":"فجعل العين طليعته، والأذن صاحب خبره، واللسان ترجمانه، واليدين والرجلين أعوانه","pg":228},{"h":"الكلمات الأربع","x":"﴿يا أيها الذين آمنوا اصبروا وصابروا ورابطوا واتقوا الله لعلكم تفلحون﴾ [آل عمران 200]","pg":228},{"h":"المرابطة","x":"وهي لزوم ثغر القلب وحراسته لئلا يدخل منه العدو، ولزوم ثغر العين والأذن واللسان والبطن واليد والرجل.","pg":229},{"h":"درس أحد","x":"وقد أخلوا المكان الذي أمروا بلزومه يوم أحد، فدخل منه العدو، فكان ما كان.","pg":229},{"h":"عمود الأمر","x":"وجماع هذه الثلاثة وعمودها الذي تقوم به هو تقوى الله، فلا ينفع الصبر ولا المصابرة ولا المرابطة إلا بالتقوى، ولا تقوم التقوى إلا على ساق الصبر.","pg":229}],"hd":""},{"t":"طريقة الشيطان في غزو القلب","pg":229,"lv":"yth","key":"أقبل ملك الكفر بجنوده وعساكره، فوجد القلب في حصنه جالسا على كرسي مملكته، أمره نافذ في أعوانه، وجنده قد حفوا به، يقاتلون عنه، ويدافعون عن حوزته","p":["فلم يمكنه الهجوم عليه إلا بمخامرة بعض أمرائه وجنده عليه. فسأل عن أخص الجند به وأقربهم منه منزلة، فقيل له: هي النفس","فإذا خامرت على القلب، وصارت معكم عليه، ملكتم ثغر العين والأذن واللسان والفم واليد والرجل، فرابطوا على هذه الثغور كل المرابطة."],"items":[{"h":"مدخل النفس","x":"ادخلوا عليها من مرادها وانظروا مواقع محبتها وما هو محبوبها، فعدوها به، ومنوها إياه","pg":230},{"h":"إضعاف السرية","x":"وإن غلبتم فاجتهدوا في إضعاف السرية ووهنها حتى لا تصل إلى القلب، وإن وصلت إليه وصلت ضعيفة لا تغني عنه شيئا.","pg":230},{"h":"اليدان والرجلان","x":"ثم الزموا ثغر اليدين والرجلين فامنعوها أن تبطش بما يضركم أو تمشي فيه.","pg":238},{"h":"مصالحة النفس الأمارة","x":"واعلموا أن أكبر عونكم على لزوم هذه الثغور مصالحة النفس الأمارة. فأعينوها واستعينوا بها، وأمدوها واستمدوا منها. وكونوا معها على حرب النفس المطمئنة","pg":238}],"hd":""},{"t":"ثغر العين","pg":230,"lv":"yth","key":"فإذا استوليتم على هذه الثغور فامنعوا ثغر العين أن يكون نظره اعتبارا، بل اجعلوا نظره تفرجا واستحسانا وتلهيا.","p":["ودونكم ثغر العين، فإن منه تنالون بغيتكم، فإني ما أفسدت بني آدم بشيء مثل النظر، فإني أبذر به في القلب بذر الشهوة، ثم أسقيه بماء الأمنية، ثم لا أزال أعده وأمنيه حتى أقوي عزيمته، وأقوده بزمام الشهوة إلى الانخلاع من العصمة."],"items":[{"h":"إفساد نظرة العبرة","x":"فإن استرق نظرة عبرة فأفسدوها عليه بنظر الغفلة والاستحسان والشهوة، فإنه أقرب إليه، وأعلق بنفسه، وأخف عليه.","pg":230},{"h":"التهوين","x":"فلا تهملوا أمر هذا الثغر، وأفسدوه بحسب استطاعتكم، وهونوا عليه أمره","pg":231},{"h":"شبهة العلم","x":"وإن ظفرتم به قليل العلم فاسد العقل، فقولوا: هذه الصورة مظهر من مظاهر الحق ومجلى من مجاليه، فادعوه إلى القول بالاتحاد","pg":231}],"hd":""},{"t":"ثغر الأذن","pg":231,"lv":"yth","key":"ثم امنعوا ثغر الأذن أن يدخل منه ما يفسد عليكم الأمر، فاجتهدوا أن لا تدخلوا منه إلا الباطل، فإنه خفيف على النفس تستحليه وتستملحه","p":["وإياكم أن يدخل من هذا الثغر شيء من كلام الله أو كلام رسوله أو كلام النصحاء! فإن غلبتم على ذلك، ودخل من ذلك شيء، فحولوا بينه وبين فهمه وتدبره، والتفكر فيه، والعظة به","فيدخلون الباطل عليه في كل قالب يقبله ويخف عليه، ويخرجون له الحق في كل قالب يكرهه ويثقل عليه."],"items":[{"h":"تزيين الباطل","x":"وتخيروا له أعذب الألفاظ وأسحرها للألباب، وامزجوه بما تهوى النفوس مزجا. وألقوا الكلمة، فإن رأيتم منه إصغاء إليها فزجوه بأخواتها.","pg":232},{"h":"ثلاث حيل لصد الحق","x":"إما بإدخال ضده عليه، وإما بتهويل ذلك وتعظيمه، وأن هذا أمر قد حيل بين النفوس وبينه... وإما بإرخاصه على النفوس","pg":232},{"h":"قوالب شياطين الإنس","x":"كيف يخرجون الأمر بالمعروف والنهي عن المنكر في قالب كثرة الفضول، وتتبع عثرات الناس، والتعرض من البلاء لما لا يطيق، وإلقاء الفتن بين الناس","pg":233},{"h":"اللفظ لا الحقيقة","x":"وأكثر الناس ضعفاء العقول يقبلون الشيء بلفظ، ويردونه بعينه بلفظ آخر!","pg":234},{"h":"الزخرف","x":"فسماه زخرفا وهو باطل، لأن صاحبه يزخرفه ويزينه ما استطاع، ويلقيه إلى سمع المغرور، فيغتر به.","pg":234},{"h":"خلاصة","x":"والمقصود أن الشيطان قد لزم ثغر الأذن، يدخل فيها ما يضر العبد ولا ينفعه، ويمنع أن يدخل إليها ما ينفعه، وإن دخل بغير اختياره أفسده عليه.","pg":234}],"hd":""},{"t":"ثغر اللسان","pg":234,"lv":"kid","key":"ثم يقول: قوموا على ثغر اللسان، فإنه الثغر الأعظم، وهو قبالة الملك","p":["فأجروا عليه من الكلام ما يضره ولا ينفعه، وامنعوه أن يجري عليه شيء مما ينفعه من ذكر الله تعالى، واستغفاره، وتلاوة كتابه، ونصيحة عباده، أو التكلم بالعلم النافع.","فالرباط الرباط على هذا الثغر أن يتكلم بحق، أو يمسك عن باطل."],"items":[{"h":"الأمر الأول","x":"التكلم بالباطل، فإن المتكلم بالباطل أخ من إخوانكم، ومن أكبر جندكم وأعوانكم.","pg":235},{"h":"الأمر الثاني","x":"السكوت عن الحق، فإن الساكت عن الحق أخ لكم أخرس، كما أن الأول أخ لكم ناطق، وربما كان الأخ الثاني أنفع إخوانكم لكم.","pg":235},{"h":"قول الناصح","x":"المتكلم بالباطل شيطان ناطق، والساكت عن الحق شيطان أخرس.","pg":235},{"h":"أكثر الهلكى","x":"واعلموا يا بني أن ثغر اللسان هو الذي أهلك منه بني آدم، وأكبهم منه على مناخرهم في النار","pg":235},{"h":"وصية الشيطان","x":"لينطق أحدكم على لسان أخيه من الإنس بالكلمة، ويكون الآخر على لسان السامع، فينطق باستحسانها وتعظيمها والتعجب منها، ويطلب من أخيه إعادتها.","pg":235}],"hd":""},{"t":"الشيطان قاعد لابن آدم بكل طريق","pg":236,"lv":"yth","key":"أوما تروني قد قعدت لابن آدم بطرقه كلها، فلا يفوتني من طريق إلا قعدت له بطريق غيره حتى أصيب منه حاجتي أو بعضها.","p":["إن الشيطان قد قعد لابن آدم بطرقه كلها، فقعد له بطريق الإسلام، فقال: أتسلم وتذر دينك ودين آبائك؟ فخالفه، وأسلم. فقعد له بطريق الهجرة، فقال: أتهاجر وتذر أرضك وسماءك؟ فخالفه، وهاجر. فقعد له بطريق الجهاد، فقال: تجاهد، فتقتل، فيقسم المال، وتنكح الزوجة!"],"items":[{"h":"طريق الصدقة","x":"فإذا أراد أحدهم أن يتصدق فاقعدوا له على طريق الصدقة، وقولوا له في نفسه: أتخرج المال، فتبقى مثل هذا السائل، وتصير بمنزلته أنت وهو سواء؟","pg":237},{"h":"طريق الحج","x":"واقعدوا له بطريق الحج، فقولوا: طريقه مخوفة مشقة، يتعرض سالكها لتلف النفس والمال.","pg":237},{"h":"سائر طرق الخير","x":"وهكذا فاقعدوا له على سائر طرق الخير بالتنفير منها وذكر صعوبتها وآفاتها.","pg":237},{"h":"طرق المعاصي","x":"ثم اقعدوا على طرق المعاصي، فحسنوها في أعين بني آدم، وزينوها في قلوبهم","pg":237}],"hd":"حديث «إن الشيطان قد قعد لابن آدم بأطرقه»: أخرجه النسائي 3134 وأحمد وابن حبان 4593، والحديث صححه ابن حبان، وصحح إسناده العراقي، وحسن إسناده ابن حجر."},{"t":"الشهوة والغفلة والغضب: أسلحة العدو","pg":239,"lv":"adl","key":"واستعينوا يا بني بجندين عظيمين لن تغلبوا معهما: أحدهما: جند الغفلة... والثاني: جند الشهوات فزينوها في قلوبهم، وحسنوها في أعينهم.","p":["فأغفلوا قلوب بني آدم عن الله والدار الآخرة بكل طريق، فليس لكم شيء أبلغ في تحصيل غرضكم من ذلك، فإن القلب إذا غفل عن الله تمكنتم منه ومن أعوانه.","وأبلغ أسلحتكم فيهم وأنكاها: الغفلة، واتباع الهوى. وأعظم أسلحتهم فيكم وأمنع حصونهم: ذكر الله، ومخالفة الهوى. فإذا رأيتم الرجل مخالفا لهواه، فاهربوا من ظله، ولا تدنوا منه."],"items":[{"h":"قرن الغافلين","x":"واستعينوا على الغفلة بالشهوات، وعلى الشهوات بالغفلة. واقرنوا بين الغافلين، ثم استعينوا بهما على الذاكر","pg":239},{"h":"موطنا الصيد","x":"وانتهزوا فرصكم فيهم عند الشهوة والغضب، فلا تصطادون بني آدم في أعظم من هذين الموطنين!","pg":240},{"h":"من باب إرادته","x":"وادخلوا على كل واحد من بني آدم من باب إرادته وشهوته، فساعدوه عليها","pg":240},{"h":"الشهوة والغضب","x":"وإنما أخرجت أبويهم من الجنة بالشهوة، وإنما ألقيت العداوة بين أولادهم بالغضب. فبه قطعت أرحامهم، وسفكت دماءهم، وبه قتل أحد ابني آدم أخاه.","pg":240},{"h":"إطفاء النار","x":"واعلموا أن الغضب جمرة في قلب ابن آدم، والشهوة نار تثور من قلبه، وإنما تطفأ النار بالماء والصلاة والذكر والتكبير","pg":241},{"h":"الصبر والصلاة","x":"وقد أوصاهم الله أن يستعينوا عليكم بالصبر والصلاة، فحولوا بينهم وبين ذلك، وأنسوهم إياه","pg":242},{"h":"الخلاصة","x":"والمقصود أن الذنوب والمعاصي سلاح ومدد يمد بها العبد أعداءه، ويعينهم بها على نفسه، فيقاتلونه بسلاحه، ويكون معهم على نفسه. وهذا غاية الجهل","pg":242},{"h":"قول بعض السلف","x":"ألا رب مهين لنفسه وهو يزعم أنه لها مكرم، ومذل لنفسه وهو يزعم أنه لها معز، ومصغر لنفسه وهو يزعم أنه لها مكبر، ومضيع لنفسه وهو يزعم أنه مراع لحقها.","pg":243}],"hd":"حديث «إن الغضب جمرة في قلب ابن آدم... فمن أحس بذلك فليتوضأ»: أخرجه الترمذي 2191 وغيره من طريق علي بن زيد بن جدعان، قال المحقق: ابن جدعان إلى الضعف أقرب، وخاصة إذا تفرد بهذا السياق الطويل. وحديث «إنما تطفأ النار بالماء»: قال المحقق: هذا الإسناد ضعيف، محمد بن عطية مجهول، وعده ابن حبان من منكرات أبي وائل القاص. وأحاديث إطفاء الحريق بالتكبير: كلها واهية ولا يثبت منها شيء. وأثر «ألا رب مهين لنفسه»: لم يقف عليه المحقق، وورد أوله من قول أبي الدرداء وفي سنده ضعف.","weak":1},{"t":"فصل: ومن عقوباتها أنها تنسي العبد نفسه","pg":243,"lv":"yth","key":"ومن عقوباتها: أنها تنسي العبد نفسه، فإذا نسي نفسه أهملها وأفسدها وأهلكها.","p":["فلما نسوا ربهم سبحانه نسيهم وأنساهم أنفسهم... فعاقب سبحانه من نسيه عقوبتين: إحداهما: أنه سبحانه نسيه. والثانية: أنه أنساه نفسه.","ونسيانه سبحانه للعبد: إهماله، وتركه، وتخليه عنه، وإضاعته؛ فالهلاك أدنى إليه من اليد للفم!"],"items":[{"h":"ينسيه حظوظها","x":"وأما إنساؤه نفسه فهو: إنساؤه لحظوظها العالية وأسباب سعادتها وفلاحها وصلاحها وما تكمل به","pg":244},{"h":"ينسيه عيوبها","x":"وأيضا فينسيه عيوب نفسه ونقصها وآفاتها، فلا يخطر بباله إزالتها وإصلاحها.","pg":244},{"h":"ينسيه أمراضها","x":"فهو مريض مثخن بالمرض، ومرضه مترام به إلى التلف، ولا يشعر بمرضه، ولا يخطر بباله مداواته.","pg":244},{"h":"بيع الغبن","x":"ومن تأمل هذا الموضع تبين له أن أكثر هذا الخلق قد نسوا أنفسهم حقيقة، وضيعوها، وأضاعوا حظها من الله، وباعوها رخيصة بثمن بخس بيع الغبن.","pg":245},{"h":"الرابحون","x":"وأما الرابحون، فإنهم باعوا فانيا بباق، وخسيسا بنفيس، وحقيرا بعظيم","pg":246},{"h":"الخلاصة","x":"والمقصود أن الذنوب تنسي العبد حظه من هذه التجارة الرابحة، وتشغله بالتجارة الخاسرة، وكفى بذلك عقوبة.","pg":248}],"hd":"حديث «كل الناس يغدو، فبائع نفسه، فمعتقها أو موبقها»: أخرجه مسلم في الطهارة 223."},{"t":"فصل: ومن عقوباتها أنها تزيل النعم الحاضرة وتقطع النعم الواصلة","pg":248,"lv":"kid","key":"ومن عقوباتها: أنها تزيل النعم الحاضرة، وتقطع النعم الواصلة، فتزيل الحاصل، وتمنع الواصل.","p":["فإن نعم الله ما حفظ موجودها بمثل طاعته، ولا استجلب مفقودها بمثل طاعته، فإن ما عنده لا ينال إلا بطاعته.","وقد جعل الله سبحانه لكل شيء سببا وآفة: سببا يجلبه، وآفة تبطله. فجعل أسباب نعمه الجالبة لها طاعته، وآفاتها المانعة منها معصيته."],"items":[{"h":"الحفظ والزوال","x":"فإذا أراد حفظ نعمته على عبده ألهمه رعايتها بطاعته فيها، وإذا أراد زوالها عنه خذله حتى عصاه بها.","pg":249},{"h":"العجب","x":"ومن العجب علم العبد بذلك مشاهدة في نفسه وغيره... وهو مقيم على معصية الله، كأنه مستثنى من هذه الجملة","pg":249},{"h":"أي جهل","x":"فأي جهل أبلغ من هذا؟ وأي ظلم للنفس فوق هذا؟","pg":249}],"hd":""},{"t":"فصل: ومن عقوباتها أنها تباعد عن العبد وليه وتدني منه عدوه","pg":249,"lv":"adl","key":"ومن عقوباتها: أنها تباعد عن العبد وليه، وأنفع الخلق له، وأنصحهم له، ومن سعادته في قربه منه، وهو الملك الموكل به. وتدني منه عدوه، وأغش الخلق له وأعظمهم ضررا له، وهو الشيطان.","p":["فإن العبد إذا عصى الله تباعد منه الملك بقدر تلك المعصية، حتى إنه يتباعد عنه بالكذبة الواحدة مسافة بعيدة.","فليس أحد أنفع للعبد من صحبة الملك له، وهو وليه في يقظته ومنامه، وحياته، وعند موته، وفي قبره؛ ومؤنسه في وحشته، وصاحبه في خلوته، ومحدثه في سره."],"items":[{"h":"لمتان","x":"إن للملك بقلب ابن آدم لمة، وللشيطان لمة. فلمة الملك إيعاد بالخير وتصديق بالوعد، ولمة الشيطان إيعاد بالشر وتكذيب بالحق","pg":251},{"h":"على اللسان","x":"وإذا اشتد قرب الملك من العبد تكلم على لسانه، وألقى على لسانه القول السديد. وإذا بعد منه، وقرب منه الشيطان، تكلم على لسانه، وألقى عليه قول الزور والفحش","pg":252},{"h":"الحق والباطل","x":"فالملك يلقي في القلب الحق، ويلقيه على اللسان. والشيطان يلقي الباطل في القلب، ويجريه على اللسان.","pg":253},{"h":"تأمين الملك","x":"وإذا دعا العبد المسلم لأخيه بظهر الغيب أمن الملك على دعائه، وقال: لك بمثله. وإذا فرغ من قراءة الفاتحة أمنت الملائكة على دعائه.","pg":254},{"h":"الضيف والجار","x":"فلا يليق به أن يسيء جواره، ويبالغ في أذاه وطرده عنه وإبعاده، فإنه ضيفه وجاره.","pg":255},{"h":"الحياء من الحافظين","x":"أي: استحيوا من هؤلاء الحافظين الكرام، وأكرموهم، وأجلوهم أن يروا منكم ما تستحيون أن يراكم عليه من هو مثلكم.","pg":256},{"h":"أذى الملائكة","x":"والملائكة تتأذى مما يتأذى منه بنو آدم. فإذا كان ابن آدم يتأذى ممن يفجر ويعصي بين يديه، وإن كان قد يعمل مثل عمله، فما الظن بأذى الملائكة الكرام الكاتبين؟","pg":256}],"hd":"أثر «إذا كذب العبد تباعد منه الملك ميلا من نتن ريحه»: قال المحقق: الحديث منكر لا يثبت. وأثر اللمتين: رواه الترمذي 2988 مرفوعا، وخولف في رفعه، والموقوف على ابن مسعود سنده صحيح، ورجح أبو حاتم وأبو زرعة الموقوف. و«إن السكينة تنطق على لسان عمر»: قال المحقق: والأثر ثابت عن علي رضي الله عنه. وحديث «كان الملك ينافح عنك»: رواه أبو داود 4896 مرسلا و4897 موصولا، قال البخاري: والأول أصح يعني المرسل، وفيه بشير بن المحرر فيه جهالة. وحديث دعاء الأخ بظهر الغيب: مسلم 2732. وتأمين الملائكة: البخاري 780 ومسلم 410. و«إذا نام على وضوء بات في شعاره ملك»: فيه اضطراب وضعفه العقيلي، وجوّد المنذري وابن حجر إسناد حديث ابن عباس. و«إن معكم من لا يفارقكم»: لم يقف عليه المحقق موقوفا، والمرفوع عند الترمذي 2800 ضعيف. و«الملائكة تتأذى مما يتأذى منه بنو آدم»: من حديث جابر عند مسلم 564.","weak":1},{"t":"فصل: ومن عقوباتها أنها تستجلب مواد هلاك العبد في دنياه وآخرته","pg":257,"lv":"kid","key":"فإن الذنوب هي أمراض متى استحكمت قتلت، ولابد.","p":["فكذلك القلب لا تتم حياته إلا بغذاء من الإيمان والأعمال الصالحة يحفظ قوته، واستفراغ بالتوبة النصوح يستفرغ المواد الفاسدة والأخلاط الرديئة منه، وحمية توجب له حفظ الصحة وتجنب ما يضادها","والتقوى اسم متناول لهذه الأمور الثلاثة، فما فات منها فات من التقوى بقدره.","فمن حفظ القوة بامتثال الأوامر، واستعمل الحمية باجتناب النواهي، واستفرغ التخليط بالتوبة النصوح لم يدع للخير مطلبا، ولا من الشر مهربا."],"items":[{"h":"الذنوب ضد الثلاثة","x":"فالذنوب مضادة لهذه الأمور الثلاثة، فإنها تستجلب المواد المؤذية، وتوجب التخليط المضاد للحمية، وتمنع الاستفراغ بالتوبة النصوح.","pg":257},{"h":"مثل البدن العليل","x":"فانظر إلى بدن عليل قد تراكمت عليه الأخلاط الرديئة ومواد المرض، وهو لا يستفرغها ولا يحتمي لها، كيف تكون صحته وبقاؤه؟","pg":257},{"h":"شعر","x":"جسمك بالحمية حصنته مخافة من ألم طاري، وكان أولى بك أن تحتمي من المعاصي خشية النار","pg":258}],"hd":""}],"lv":{"kid":{"show":true,"title":"قلبي حصن وأنا حارسه","intro":"المعصية تسرق من الإنسان أشياء جميلة: تذهب ببركة وقته ورزقه، وتضعف نور قلبه، وتبعد عنه الملك الذي يحبه، وتقرب منه الشيطان. والطاعة حصن قوي، من دخله كان آمنا. ولقلبك أبواب يحرسها: عينك وأذنك ولسانك.","points":["المعصية تذهب ببركة الوقت والرزق والعلم، والطاعة تجلب البركة.","أقول بسم الله عند الأكل والشرب واللبس والركوب، فذكر الله يطرد الشيطان ويجلب البركة.","الطاعة تجعل القلب منيرا كالمرآة الصافية، فيخاف منه الشيطان.","أحرس أبواب قلبي: أنظر إلى ما ينفعني، وأسمع الخير، وأقول الحق أو أسكت.","إذا أخطأت أتوب إلى الله سريعا، فالتوبة تعيدني إلى مكاني."],"quote":{"x":"الطاعة حصن الرب تبارك وتعالى الذي من دخله كان من الآمنين","pg":213},"quiz":[{"q":"ماذا تفعل المعصية بالبركة في الوقت والرزق؟","o":["تذهب بالبركة منهما","تزيد البركة فيهما كثيرا","لا تؤثر فيهما أبدا","تجعلهما أطول دائما"],"why":"ومن عقوباتها: أنها تمحق بركة العمر، وبركة الرزق، وبركة العلم، وبركة العمل، وبركة الطاعة","pg":199},{"q":"ما الذي سماه ابن القيم حصن الرب، من دخله كان آمنا؟","o":["طاعة الله","كثرة المال","قوة الجسم","كثرة الأصحاب"],"why":"وذلك لأن الطاعة حصن الرب تبارك وتعالى الذي من دخله كان من الآمنين","pg":213},{"q":"أي هذه جعله الله طليعة القلب، أي الذي يتقدمه ويكشف له الطريق؟","o":["العين","الأذن","اليدان","الرجل"],"why":"فجعل العين طليعته، والأذن صاحب خبره، واللسان ترجمانه، واليدين والرجلين أعوانه","pg":228},{"q":"ماذا يقول الشيطان في نفس من يريد أن يتصدق؟","o":["ستفتقر مثل السائل","ستصير غنيا بعد العطاء","سيفرح بك أهلك كثيرا","سيمدحك جميع أصحابك"],"why":"فإذا أراد أحدهم أن يتصدق فاقعدوا له على طريق الصدقة، وقولوا له في نفسه: أتخرج المال، فتبقى مثل هذا السائل","pg":237}],"scene":{"t":"مقطع في الجهاز","x":"كنت تلعب على الجهاز، فظهر لك مقطع فيه كلام سيئ وصور لا تليق، وقال لك صديقك: شاهده، لن يعرف أحد.","opts":["أغلق المقطع، وأقول بسم الله، وأختار شيئا نافعا","أشاهده قليلا ثم أغلقه","أشاهده لأن أحدا لن يعرف"],"why":"﴿وإن عليكم لحافظين كراما كاتبين﴾ [الانفطار 10 و11]","pg":256},"act":{"type":"guard","t":"حارس الأبواب الثلاثة","x":"ارسم قلعة لها ثلاثة أبواب: باب العين، وباب الأذن، وباب اللسان. اكتب على كل باب حارسه، وهو عمل صغير تفعله كل يوم، ثم لون الباب كلما حرسته جيدا خلال الأسبوع.","items":[{"k":"باب العين","x":"أنظر إلى خلق الله وأتفكر فيه، وأغض بصري عما لا يليق."},{"k":"باب الأذن","x":"أستمع إلى القرآن والكلام النافع، وأبتعد عن الكلام السيئ."},{"k":"باب اللسان","x":"أذكر الله وأقول الحق، أو أسكت عن الكلام القبيح."},{"k":"مفتاح الحصن","x":"أقول بسم الله عند الأكل والشرب واللبس والركوب."}]}},"yth":{"show":true,"title":"ثغوري الثلاثة: معركة القلب","intro":"يصف ابن القيم حربا حقيقية تدور في داخلك: قائدها القلب، وجنوده العقل والمعرفة والإيمان واليقين، وعدوه لا ينام عنه. والعدو يحاول أن يكسب النفس إلى صفه، ثم يدخل من ثغر العين والأذن واللسان. وكل معصية مدد تعطيه لعدوك ليقاتلك بسلاحك.","points":["الذنب يمحق البركة، فليس لك من وقتك وجهدك إلا ما أطعت الله به.","النظرة بذرة يزرعها الشيطان ثم يسقيها بالأماني حتى تصير عزيمة على المعصية.","الشيطان يقدم لك الباطل في أجمل غلاف، ويقدم لك الحق في غلاف ثقيل مكروه.","على اللسان قاعدة واحدة: أن تتكلم بحق أو تمسك عن باطل.","سلاحاه الأكبران الغفلة والشهوة، وحصنك الأمنع ذكر الله ومخالفة الهوى."],"quote":{"x":"فالرباط الرباط على هذا الثغر أن يتكلم بحق، أو يمسك عن باطل.","pg":235},"quiz":[{"q":"بم شبه ابن القيم القلب الذي أفسدته الذنوب حين يحتاجه صاحبه في الشدة؟","o":["سيف صدئ لا يخرج من غمده","سفينة لا شراع لها في البحر","حصن عال لا أبواب فيه","بيت كبير لا نوافذ فيه"],"why":"وكان بمنزلة رجل معه سيف قد غشيه الجرب، ولزم قرابه بحيث لا ينجذب مع صاحبه إذا جذبه","pg":214},{"q":"قال الشيطان لجنده: ما أفسدت بني آدم بشيء مثل...","o":["النظر","الكسل","الفقر","الجدال"],"why":"فإني ما أفسدت بني آدم بشيء مثل النظر، فإني أبذر به في القلب بذر الشهوة","pg":230},{"q":"ما الجندان اللذان أوصى الشيطان أعوانه بالاستعانة بهما؟","o":["الغفلة والشهوات","الفقر والأمراض","الجهالة والكسل","الحزن والانطوائية"],"why":"واستعينوا يا بني بجندين عظيمين لن تغلبوا معهما: أحدهما: جند الغفلة... والثاني: جند الشهوات","pg":239},{"q":"ما أعظم أسلحة المؤمن وأمنع حصونه أمام الشيطان كما في الكتاب؟","o":["ذكر الله ومخالفة الهوى","العزلة التامة عن الناس","كثرة النوم وطول الراحة","قوة الجسم وكثرة الرياضة"],"why":"وأعظم أسلحتهم فيكم وأمنع حصونهم: ذكر الله، ومخالفة الهوى","pg":242},{"q":"يرضى الشيطان من ثغر اللسان بأحد أمرين، فما هما؟","o":["الكلام بالباطل والسكوت عن الحق","كثرة المزاح وارتفاع الصوت دائما","الكلام بالحق والسكوت عن الباطل","كثرة الشكوى وقلة الشكر لله"],"why":"ويكون لكم في هذا الثغر أمران عظيمان لا تبالون بأيهما ظفرتم: أحدهما: التكلم بالباطل... والثاني: السكوت عن الحق","pg":235}],"scene":{"t":"الساعة الواحدة ليلا","x":"الساعة الواحدة ليلا، وأنت تقلب المقاطع في هاتفك، فظهر لك مقطع فيه ما لا يحل النظر إليه، وتقول لك نفسك: نظرة واحدة لن تضر.","opts":["أغلقه فورا، وأستعيذ بالله، وأضع الهاتف بعيدا وأنام على ذكر","أشاهده لحظة ثم أستغفر","أكمل لأني وحدي ولن يراني أحد"],"why":"ودونكم ثغر العين، فإن منه تنالون بغيتكم، فإني ما أفسدت بني آدم بشيء مثل النظر","pg":230},"act":{"type":"sort","t":"لمة الملك أم لمة الشيطان؟","x":"اقرأ كل خاطرة، ثم ضعها في صنفها: (أ) لمة الملك، وهي إيعاد بالخير وتصديق بالحق، أو (ب) لمة الشيطان، وهي إيعاد بالشر وتكذيب بالحق، كما في ص 251.","items":[{"x":"تصدق، والله يخلف عليك ويبارك لك.","ok":"أ"},{"x":"لا تتصدق، ستفتقر وتصير مثل هذا السائل.","ok":"ب"},{"x":"نظرة واحدة لن تضر أحدا.","ok":"ب"},{"x":"استح من الملائكة الكرام الكاتبين.","ok":"أ"},{"x":"اسكت عن الحق حتى لا يعاديك الناس.","ok":"ب"},{"x":"قل الحق بأدب، أو أمسك عن الباطل.","ok":"أ"},{"x":"الطريق إلى الخير شاق ومخيف فاتركه.","ok":"ب"},{"x":"قم فصل، فإنما هو صبر ساعة.","ok":"أ"}]}},"adl":{"show":true,"title":"المعاصي في حياة العبد، وثغور الشيطان","intro":"يكمل ابن القيم خريطة آثار الذنوب بعشرة فصول: محق البركة، والنزول إلى السفلة، واجتراء المخلوقات، وخيانة القلب عند الحاجة وعند الخاتمة، وعمى البصيرة، وإمداد العدو، ونسيان النفس، وزوال النعم، وبعد الملك، واستجلاب مواد الهلاك. وفي قلب ذلك يصور الحرب بين القلب والشيطان، وخطة العدو في الاستيلاء على النفس ثم ثغور العين والأذن واللسان، وقعوده لابن آدم بكل طريق، واستعانته بالغفلة والشهوة والغضب.","points":["ميزان العمر والمال البركة لا الكثرة: «فليس له من عمره وماله وقوته وجاهه وعلمه وعمله إلا ما أطاع الله به» (ص 203).","التائب قد يعود أرفع من درجته أو مثلها أو دونها، بحسب قوة التوبة وما أحدثته من الذل والانكسار.","مدار الكمال الإنساني معرفة الحق وإيثاره، وعليهما ينقسم الناس أربعة أقسام، ولا يصلح للإمامة إلا الأول.","خطة العدو: يكسب النفس أولا من باب محبوبها، ثم يرابط على الثغور، ويلبس الحق قوالب مكروهة والباطل قوالب محببة.","صحة القلب كصحة البدن: غذاء الإيمان، واستفراغ التوبة النصوح، وحمية التقوى."],"quote":{"x":"فليس له من عمره وماله وقوته وجاهه وعلمه وعمله إلا ما أطاع الله به.","pg":203},"quiz":[{"q":"على أي أصلين جعل ابن القيم مدار الكمال الإنساني؟","o":["معرفة الحق وإيثاره على الباطل","كثرة العبادة وطول قيام الليل","سعة العلم وقوة الحجة والجدل","حسن الخلق وسعة الصحبة لجميع الناس"],"why":"فإن الكمال الإنساني مداره على أصلين: معرفة الحق من الباطل، وإيثاره عليه.","pg":220},{"q":"من الذي يحسب كل سوداء تمرة في تقسيم ابن القيم للناس؟","o":["صاحب القوة الضعيف البصيرة","صاحب البصيرة الضعيف القوة","من لا بصيرة له ولا قوة","من جمع بين البصيرة والقوة معا"],"why":"القسم الرابع: من له قوة وهمة وعزيمة، لكنه ضعيف البصيرة في الدين... بل يحسب كل سوداء تمرة","pg":221},{"q":"بم حكم شيخ الإسلام في عودة التائب إلى درجته؟","o":["منهم من يعلو ومن يساوي ومن يقصر","يعود التائب دائما إلى أرفع من درجته","لا يعود التائب أبدا إلى درجته","يعود التائب إلى درجته بلا زيادة"],"why":"التحقيق أن من التائبين من يعود إلى أرفع من درجته، ومنهم من يعود إلى مثل درجته، ومنهم من لا يصل إلى درجته.","pg":208},{"q":"ما العمود الذي تقوم به أمور الصبر والمصابرة والمرابطة؟","o":["تقوى الله","قوة العقل","سعة العلم","حسن الصحبة"],"why":"وجماع هذه الثلاثة وعمودها الذي تقوم به هو تقوى الله، فلا ينفع الصبر ولا المصابرة ولا المرابطة إلا بالتقوى","pg":229},{"q":"يحتاج القلب كالبدن إلى ثلاثة أمور، فما الذي يقابل الاستفراغ منها؟","o":["التوبة النصوح","الإيمان والعمل","اجتناب النواهي","الصبر على البلاء"],"why":"واستفراغ بالتوبة النصوح يستفرغ المواد الفاسدة والأخلاط الرديئة منه","pg":257}],"scene":{"t":"الحق في قالب مكروه","x":"معلم لاحظ أن طلابه يتداولون مقاطع تسخر من الناصحين، ويصفون الأمر بالمعروف بأنه تدخل في شؤون الآخرين وفضول.","opts":["يبين لهم كيف يلبس العدو الحق قالبا مكروها، ثم يعرض الحق عليهم في قالب محبب","يسكت عنهم حتى لا ينفروا منه","يوبخهم أمام الصف بشدة"],"why":"كيف يخرجون الأمر بالمعروف والنهي عن المنكر في قالب كثرة الفضول، وتتبع عثرات الناس، والتعرض من البلاء لما لا يطيق، وإلقاء الفتن بين الناس","pg":233},"act":{"type":"class","t":"خريطة الثغور: درس من 40 دقيقة","x":"نشاط صفي يقرأ فيه المعلم مع طلابه خطة العدو في غزو القلب (ص 229 إلى 240)، ثم يبنون معا خطة حراسة عملية لكل ثغر.","items":[{"step":"افتتاح: يقرأ المعلم وصف الحرب: القلب قائد، والعين طليعة، والأذن صاحب خبر، واللسان ترجمان (ص 228).","min":5},{"step":"قراءة خطة العدو: كسب النفس من باب محبوبها، ثم الاستيلاء على الثغور (ص 230). يسأل الطلاب: لماذا بدأ العدو بالنفس لا بالقلب؟","min":8},{"step":"ثلاث مجموعات: مجموعة لثغر العين، وأخرى للأذن، وثالثة للسان. تستخرج كل مجموعة من النص حيلة العدو في ثغرها وما يحرسه.","min":12},{"step":"عرض المجموعات على لوح من ثلاثة أعمدة: الثغر، حيلة العدو، الحراسة.","min":8},{"step":"خاتمة: قراءة قوله «وأعظم أسلحتهم فيكم وأمنع حصونهم: ذكر الله، ومخالفة الهوى» (ص 242)، ويكتب كل طالب حراسة واحدة يلتزمها أسبوعا.","min":7}]}},"alt":{}},"highlights":[{"x":"فمن كل شيء يفوت العبد عوض، وإذا فاته الله لم يعوض عنه شيء البتة.","pg":201,"lv":"kid"},{"x":"ولكن سعة الرزق والعمر بالبركة فيه.","pg":201,"lv":"kid"},{"x":"الطاعة حصن الرب تبارك وتعالى الذي من دخله كان من الآمنين","pg":213,"lv":"kid"},{"x":"فالشيطان يفرق من هذا القلب أشد من فرق الذئب من الأسد","pg":222,"lv":"kid"},{"x":"إنما هو صبر ساعة، وقد استرحت راحة الأبد.","pg":227,"lv":"yth"},{"x":"المتكلم بالباطل شيطان ناطق، والساكت عن الحق شيطان أخرس.","pg":235,"lv":"yth"},{"x":"فإذا رأيتم الرجل مخالفا لهواه، فاهربوا من ظله، ولا تدنوا منه.","pg":242,"lv":"yth"},{"x":"ولقد قطع خوف الخاتمة ظهور المتقين، وكأن المسيئين الظالمين قد أخذوا توقيعا بالأمان!","pg":219,"lv":"adl"}],"concepts":[{"term":"البركة","def":"وليست سعة الرزق والعمل بكثرته، ولا طول العمر بكثرة الشهور والأعوام، ولكن سعة الرزق والعمر بالبركة فيه.","pg":201},{"term":"ضد البركة","def":"وضد البركة اللعنة.","pg":203},{"term":"الكمال الإنساني","def":"فإن الكمال الإنساني مداره على أصلين: معرفة الحق من الباطل، وإيثاره عليه.","pg":220},{"term":"الأيدي والأبصار","def":"فالأيدي: القوى في تنفيذ الحق، والأبصار: البصائر في الدين.","pg":220},{"term":"المرابطة","def":"وهي لزوم ثغر القلب وحراسته لئلا يدخل منه العدو، ولزوم ثغر العين والأذن واللسان والبطن واليد والرجل.","pg":229},{"term":"المصابرة","def":"فلا يتم له الصبر إلا بمصابرة العدو، وهي مواقفته ومنازلته","pg":228},{"term":"نسيان الله للعبد","def":"ونسيانه سبحانه للعبد: إهماله، وتركه، وتخليه عنه، وإضاعته","pg":244},{"term":"اللمتان","def":"فلمة الملك إيعاد بالخير وتصديق بالوعد، ولمة الشيطان إيعاد بالشر وتكذيب بالحق","pg":251},{"term":"التقوى","def":"والتقوى اسم متناول لهذه الأمور الثلاثة، فما فات منها فات من التقوى بقدره.","pg":257}],"stories":[{"t":"أبوانا وذنب واحد","x":"أخرج الله سبحانه الأبوين من الجنة بذنب واحد ارتكباه وخالفا فيه نهيه، ولعن إبليس وطرده بذنب واحد ارتكبه وخالف فيه أمره.","pg":210,"lv":"kid","hd":""},{"t":"درس يوم أحد","x":"أصحاب رسول الله خير الخلق بعد النبيين والمرسلين، أخلوا المكان الذي أمروا بلزومه يوم أحد، فدخل منه العدو، فكان ما كان. فالثغر لا يخلى.","pg":229,"lv":"kid","hd":""},{"t":"القلب المنور يصرع الشيطان","x":"يذكر ابن القيم أن القلب الممتلئ نورا بالطاعة يصيب الشيطان منه ما يصيب مسترقي السمع من الشهب، حتى إن صاحبه ليصرع الشيطان، فتقول الشياطين: أصابه إنسي، وبه نظرة من الإنس!","pg":222,"lv":"kid","hd":""},{"t":"أثر المعصية في البيت","x":"قال بعض السلف، وهو الفضيل بن عياض: إني لأعصي الله، فأعرف ذلك في خلق امرأتي ودابتي.","pg":212,"lv":"yth","hd":""},{"t":"مجلس ملك الكفر","x":"يصور ابن القيم ملك الكفر وقد أقبل بجنوده فوجد القلب في حصنه، فلم يقدر عليه إلا بأن يكسب النفس إلى صفه من باب محبوبها، ثم يوصي جنده بثغر العين ثم الأذن ثم اللسان ثم اليدين والرجلين.","pg":229,"lv":"yth","hd":""},{"t":"الشيطان على طرق الإسلام والهجرة والجهاد","x":"قعد الشيطان لابن آدم بطريق الإسلام فخالفه وأسلم، ثم بطريق الهجرة فخالفه وهاجر، ثم بطريق الجهاد فخالفه وجاهد.","pg":236,"lv":"yth","hd":"أخرجه النسائي 3134 وأحمد وابن حبان 4593، صححه ابن حبان، وصحح إسناده العراقي، وحسن إسناده ابن حجر."},{"t":"التاجر عند الموت","x":"حضر بعض التجار الموت، فجعلوا يلقنونه: لا إله إلا الله، وهو يقول: هذه القطعة رخيصة، هذا مشتري جيد، هذه كذا، حتى قضى.","pg":218,"lv":"yth","hd":""},{"t":"أخبار المحتضرين","x":"يسوق ابن القيم أخبار من تعذر عليهم النطق بالشهادة عند الموت: من قال آه آه لا أستطيع أن أقولها، ومن ذكر الشطرنج، ومن جعل يهذي بالغناء، ومن قال: وما ينفعني ما تقول ولم أدع معصية إلا ركبتها.","pg":216,"lv":"adl","hd":""},{"t":"الملك ينافح عن الساكت","x":"اختصم رجلان بين يدي النبي، فجعل أحدهما يسب الآخر وهو ساكت، فلما رد قام النبي، وقال: كان الملك ينافح عنك، فلما رددت عليه جاء الشيطان.","pg":253,"lv":"adl","hd":"رواه أبو داود 4896 مرسلا و4897 موصولا، قال البخاري: والأول أصح يعني المرسل، وفيه بشير بن المحرر فيه جهالة. لا يعرض للناشئ والشاب.","weak":1}],"ready":true},{"k":"s7","t":"العقوبات وأقسام الذنوب","pgs":[258,295],"q":"كيف تتنوع عقوبات الذنوب، وكيف تتفاوت الذنوب نفسها في درجاتها؟","essence":"لكل ذنب عقوبة، وسلامة القلب نجاة","kw":["العقوبات","القلب السليم","الكبائر"],"daa":"الغفلة عن عقوبات الذنوب والاستهانة بها لأن صاحبها لا يشعر بأثرها كالسكران والنائم.","dawa":"استحضار العقوبات الشرعية والقدرية والتوبة النصوح، وطلب سلامة القلب ولزوم الصراط المستقيم.","sections":[{"t":"فصل: العقوبات الشرعية التي شرعها الله على الجرائم","pg":258,"lv":"adl","key":"«فعقوبات الشارع جاءت على أتم الوجوه، وأوفقها للعقل، وأقومها بالمصلحة»","p":["«فإن لم ترعك هذه العقوبات، ولم تجد لها تأثيرا في قلبك، فأحضره العقوبات الشرعية التي شرعها الله ورسوله على الجرائم»","«وجعلها بحكمته على حسب الدواعي إلى تلك الجرائم، وحسب الوازع عنها»","«فما كان الوازع عنه طبيعيا وليس في الطباع داع إليه اكتفى فيه بالتحريم مع التعزير ولم يرتب عليه حدا، كأكل الرجيع، وشرب الدم، وأكل الميتة. وما كان في الطباع داع إليه رتب عليه من العقوبة بقدر مفسدته وبقدر داعي الطبع إليه»"],"items":[{"h":"القتل","x":"«وجعل القتل بإزاء الكفر وما يليه ويقرب منه، وهو الزنا واللواط، فإن هذا يفسد الأديان، وهذا يفسد الأنساب ونوع الإنسان»","pg":261},{"h":"القطع","x":"«وجعل سبحانه القطع بإزاء إفساد الأموال الذي لا يمكن الاحتراز منه»","pg":264},{"h":"الجلد","x":"«وجعل الجلد بإزاء إفساد العقول وتمزيق الأعراض بالقذف»","pg":265},{"h":"حكمة اختيار العضو","x":"«وتأمل حكمته في إفساد العضو الذي باشر به الجناية، كما أفسد على قاطع الطريق يده ورجله اللتين هما آلة قطعه»","pg":259}],"hd":""},{"t":"فصل: وعقوبات الذنوب نوعان: شرعية وقدرية","pg":260,"lv":"yth","key":"«والمقصود أن الذنوب إما أن تترتب عليها العقوبات الشرعية أو القدرية، أو يجمعها الله للعبد، وقد يرفعهما عمن تاب وأحسن»","p":["«وعقوبات الذنوب نوعان: شرعية وقدرية. فإذا أقيمت الشرعية رفعت العقوبات القدرية أو خففتها»","«وأما العقوبة القدرية فإنها تقع عامة وخاصة، فإن المعصية إذا خفيت لم تضر إلا صاحبها، وإذا أعلنت ضرت الخاصة والعامة. وإذا رأى الناس المنكر فاشتركوا في ترك إنكاره أوشك أن يعمهم الله بعقابه»"],"items":[{"h":"لا يجمع الله العقوبتين غالبا","x":"«ولا يكاد الرب تعالى يجمع على عبده بين العقوبتين، إلا إذا لم تف إحداهما برفع موجب الذنب ولم تكف في زوال دائه»","pg":261},{"h":"الشرعية تخص والقدرية تعم","x":"«وإذا عطلت العقوبات الشرعية استحالت قدرية، وربما كانت أشد من الشرعية، وربما كانت دونها، ولكنها تعم، والشرعية تخص»","pg":261}],"hd":""},{"t":"أعظم الذنب وتضاعف الإثم بحسب المفسدة","pg":261,"lv":"adl","key":"«وعلى هذا فاعتبر مفاسد الذنوب، وتضاعف درجاتها في الإثم والعقوبة»","p":["«والنبي ﷺ ذكر من كل نوع أعلاه، ليطابق جوابه سؤال السائل، فإنه سأله عن أعظم الذنب، فأجابه بما تضمن ذكر أعظم أنواعها، وما هو أعظم كل نوع»","«فأعظم أنواع الشرك: أن يجعل العبد لله ندا. وأعظم أنواع القتل: أن يقتل ولده خشية أن يشاركه في طعامه وشرابه»","«فإن اقترن بذلك أن يكون في شهر حرام، أو بلد حرام، أو وقت معظم عند الله كأوقات الصلاة وأوقات الإجابة = تضاعف الإثم»"],"items":[{"h":"حديث ابن مسعود","x":"«يا رسول الله أي الذنب أعظم؟ قال: أن تجعل لله ندا وهو خلقك»","pg":261},{"h":"حق الجار","x":"«لا يدخل الجنة من لا يأمن جاره بوائقه»","pg":263}],"hd":"حديث ابن مسعود: أخرجه البخاري 4477 ومسلم 86. حديث البوائق: أخرجه مسلم 46. حديث حرمة نساء المجاهدين: أخرجه مسلم 1897. حديث الثلاثة الذين لا يكلمهم الله: أخرجه مسلم 107."},{"t":"فصل: الكفارات وأنواعها وأقسام الذنوب من جهة الحد والكفارة","pg":265,"lv":"adl","key":"«فدارت عقوباته سبحانه الشرعية على هذه الأنواع الثلاثة، كما دارت الكفارات على ثلاثة أنواع: العتق وهو أعلاها، والإطعام، والصيام»","p":["«ثم إنه سبحانه جعل الذنوب ثلاثة أقسام: قسما فيه الحد، فهذا لم يشرع فيه كفارة، اكتفاء بالحد. وقسما لم يرتب عليه حدا، فشرع فيه الكفارة. وقسما لم يرتب عليه حدا ولا كفارة»","«ولا يجتمع الحد والتعزير في معصية، بل إن كان فيها حد اكتفي به، وإلا اكتفى بالتعزير. ولا يجتمع الحد والكفارة في معصية»"],"items":[{"h":"النوع الأول","x":"«ما كان مباح الأصل ثم عرض تحريمه، فباشره في الحال التي عرض فيها التحريم، كالوطء في الإحرام والصيام»","pg":265},{"h":"النوع الثاني: التحلة","x":"«ما عقده لله من نذر، أو بالله من يمين، أو حرمه الله ثم أراد حله؛ فشرع الله سبحانه حله بالكفارة، وسماها تحلة»","pg":266},{"h":"النوع الثالث: الجوابر","x":"«ما تكون فيه جابرة لما فات، ككفارة قتل الخطأ وإن لم يكن هناك إثم»","pg":266},{"h":"الخلاصة","x":"«فإن ذلك من باب الجوابر. والنوع الأول من باب الزواجر، والنوع الوسط من باب التحلة لما منعه العقد»","pg":266}],"hd":""},{"t":"فصل: وأما العقوبات القدرية فهي نوعان","pg":267,"lv":"yth","key":"«وعقوبة القلوب أشد العقوبتين، وهي أصل عقوبة الأبدان»","p":["«والتي على القلوب نوعان: أحدهما: آلام وجودية يضرب بها القلب. والثاني: قطع المواد التي بها حياته وصلاحه عنه»","«فليس في الدنيا والآخرة شر أصلا إلا الذنوب وعقوباتها»","«فالذنب لا يخلو من عقوبة البتة، ولكن لجهل العبد لا يشعر بما هو فيه من العقوبة، لأنه بمنزلة السكران والمخدر والنائم الذي لا يشعر بالألم»"],"items":[{"h":"أصل الشر","x":"«وأصله من شر النفس وسيئات الأعمال، وهما الأصلان اللذان كان النبي ﷺ يستعيذ منهما في خطبته بقوله: ونعوذ بالله من شرور أنفسنا ومن سيئات أعمالنا»","pg":268},{"h":"وقاية السيئات","x":"«وقاية السيئات نوعان: أحدهما: وقاية فعلها بالتوفيق فلا تصدر منه. والثاني: وقاية جزائها بالمغفرة فلا يعاقب عليها»","pg":270},{"h":"سعة الرحمة","x":"«وسعة رحمته تتضمن أنه لا يهلك عليه أحد من المؤمنين به أهل توحيده ومحبته، فإنه واسع الرحمة، لا يخرج عن دائرة رحمته إلا الأشقياء، ولا أشقى ممن لم تسعه رحمته التي وسعت كل شيء»","pg":270},{"h":"تنوع العقوبات","x":"«والمقصود: أن عقوبات السيئات تتنوع إلى: عقوبات شرعية. وعقوبات قدرية. وهي إما في القلب، وإما في البدن، وإما فيهما. وعقوبات في دار البرزخ بعد الموت. وعقوبات يوم حشر الأجساد»","pg":271},{"h":"التدريج","x":"«ويذنب الذنب فلا يرى أثره عقيبه، ولا يدري أنه يعمل عمله على التدريج شيئا فشيئا، كما تعمل السموم والأشياء الضارة حذو القذة بالقذة»","pg":272}],"hd":"خطبة الحاجة: أخرجه الترمذي 1105 وقال: وكلا الحديثين صحيح، وأحمد وأبو داود والنسائي وابن ماجه."},{"t":"فصل: فاستحضر بعض العقوبات التي رتبها الله سبحانه على الذنوب","pg":273,"lv":"yth","key":"«فاستحضر بعض العقوبات التي رتبها الله سبحانه على الذنوب، وجوز وصول بعضها إليك، واجعل ذلك داعيا للنفس إلى هجرانها»","p":["«فسبحان الله، كم من قلب منكوس وصاحبه لا يشعر! وقلب ممسوخ، وقلب مخسوف به! وكم من مفتون بثناء الناس عليه، ومغرور بستر الله عليه، ومستدرج بنعم الله عليه!»","«وكل هذه عقوبات وإهانة، ويظن الجاهل أنها كرامة»"],"items":[{"h":"الختم والطبع","x":"«فمنها: الختم على القلوب والأسماع، والغشاوة على الأبصار، والإقفال على القلوب، وجعل الأكنة عليها، والرين عليها والطبع»","pg":273},{"h":"التثبيط","x":"«ومنها: التثبيط عن الطاعة والإقعاد عنها»","pg":274},{"h":"صمم القلب وعماه","x":"«ومنها: جعل القلب أصم لا يسمع الحق، أبكم لا ينطق به، أعمى لا يراه»","pg":274},{"h":"الخسف بالقلب","x":"«ومنها: الخسف بالقلب، كما يخسف بالمكان وما فيه، فيخسف به إلى أسفل سافلين، وصاحبه لا يشعر»","pg":275},{"h":"مسخ القلب","x":"«ومنها: مسخ القلب، فيمسخ كما تمسخ الصورة، فيصير القلب على قلب الحيوان الذي شابهه في أخلاقه وأعماله وطبيعته»","pg":275},{"h":"المكر والإزاغة","x":"«ومنها: مكر الله بالماكر، ومخادعته للمخادع، واستهزاؤه بالمستهزئ، وإزاغته لقلب الزائغ عن الحق»","pg":277},{"h":"نكس القلب","x":"«ومنها: نكس القلب حتى يرى الباطل حقا والحق باطلا، والمعروف منكرا والمنكر معروفا»","pg":277},{"h":"حجاب القلب","x":"«ومنها: حجاب القلب عن الرب في الدنيا، والحجاب الأكبر يوم القيامة»","pg":278},{"h":"المعيشة الضنك","x":"«ومنها: المعيشة الضنك في الدنيا وفي البرزخ، والعذاب في الآخرة»","pg":278},{"h":"الخروج عن الصراط","x":"«فمن أعظم عقوبات الذنوب: الخروج عن الصراط المستقيم في الدنيا والآخرة»","pg":286}],"hd":"ليس الشديد بالصرعة: البخاري 6114 ومسلم 2609. ليس المسكين بالطواف: البخاري 1479 ومسلم 1039. ليكونن من أمتي أقوام: البخاري 5590. تفسير المعيشة الضنك بعذاب القبر روي مرفوعا من حديث أبي هريرة وأبي سعيد، والموقوف أصح عند المحقق. أثر حذيفة في القلوب الأربعة موقوف في سنده انقطاع (انظر weak)."},{"t":"الحياة الطيبة وعيش القلب السليم","pg":279,"lv":"adl","key":"«وهل العيش في الحقيقة إلا عيش القلب السليم؟»","p":["«ولا تقر العين، ولا يهدأ القلب، ولا تطمئن النفس إلا بإلهها ومعبودها الذي هو حق، وكل معبود سواه باطل. فمن قرت عينه بالله قرت به كل عين، ومن لم تقر عينه بالله تقطعت نفسه على الدنيا حسرات»","«والقلب السليم هو الذي سلم من الشرك، والغل، والحقد، والحسد، والشح، والكبر، وحب الدنيا والرياسة»","«فهذا القلب السليم في جنة معجلة في الدنيا، وفي جنة في البرزخ، وفي الجنة يوم المعاد»"],"items":[{"h":"من شرك","x":"«من شرك يناقض التوحيد»","pg":283},{"h":"من بدعة","x":"«وبدعة تخالف السنة»","pg":283},{"h":"من شهوة","x":"«وشهوة تخالف الأمر»","pg":283},{"h":"من غفلة","x":"«وغفلة تناقض الذكر»","pg":283},{"h":"من هوى","x":"«وهوى يناقض التجريد والإخلاص. وهذه الخمسة حجب عن الله»","pg":283},{"h":"أطيب اللذات","x":"«وأي لذة ونعيم في الدنيا أطيب من بر القلب، وسلامة الصدر، ومعرفة الرب تعالى ومحبته، والعمل على موافقته؟»","pg":282}],"hd":"حديث رياض الجنة ضعيف عند المحقق (انظر weak). حديث ما بين بيتي ومنبري روضة من رياض الجنة: البخاري 1195 ومسلم 1390.","weak":1},{"t":"حاجة العبد إلى الصراط المستقيم","pg":283,"lv":"kid","key":"«فليس العبد أحوج منه إلى هذه الدعوة، وليس شيء أنفع له منها»","p":["«ولذلك اشتدت حاجة العبد بل ضرورته إلى أن يسأل الله أن يهديه الصراط المستقيم»","«فإن الصراط المستقيم يتضمن علوما وإرادات وأعمالا وتروكا ظاهرة وباطنة تجري عليه كل وقت»","«وجعل قوة سيرهم وسرعتهم عليه على قدر قوة سيرهم وسرعتهم إليه في الدنيا»"],"items":[{"h":"الصراط يوم اللقاء","x":"«فإذا كان يوم لقائه نصب لخلقه صراطا مستقيما يوصلهم إلى جنته، ثم صرف عنه من صرف عنه في الدنيا، وأقام عليه من أقامه عليه في الدنيا»","pg":285},{"h":"النور على الصراط","x":"«وجعل نور المؤمنين به وبرسوله وما جاء به الذي كان في قلوبهم في الدنيا نورا ظاهرا يسعى بين أيديهم وبأيمانهم في ظلمة الجسر»","pg":285},{"h":"الإركاس","x":"«بل متى وكل إلى طباعه حيل بينه وبين ذلك كله. وهذا هو الإركاس الذي أركس الله به المنافقين بذنوبهم»","pg":284},{"h":"الدنيا مزرعة","x":"«تعلم حينئذ علما يقينا لا شك فيه أن الدنيا مزرعة الآخرة وعنوانها وأنموذجها»","pg":286}],"hd":""},{"t":"فصل: تفاوت الذنوب وأقسامها الأربعة","pg":286,"lv":"yth","key":"«ثم هذه الذنوب تنقسم إلى أربعة أقسام: ملكية، وشيطانية، وسبعية، وبهيمية؛ ولا تخرج عن ذلك»","p":["«ولما كانت الذنوب متفاوتة في درجاتها ومفاسدها تفاوتت عقوباتها في الدنيا والآخرة بحسب تفاوتها»","«أصلها نوعان: ترك مأمور، وفعل محظور. وهما الذنبان اللذان ابتلى الله سبحانه بهما أبوي الجن والإنس»","«ومن تأمل هذا حق التأمل تبين له أن الذنوب دهليز الشرك، والكفر، ومنازعة الله ربوبيته»"],"items":[{"h":"باعتبار المحل","x":"«وكلاهما ينقسم باعتبار محله إلى ظاهر على الجوارح، وباطن في القلب»","pg":287},{"h":"باعتبار المتعلق","x":"«وباعتبار متعلقه إلى حق الله، وحق لخلقه»","pg":287},{"h":"طريق التدرج","x":"«ومنه يدخلون إلى سائر الأقسام، فهو يجرهم إليها بالزمام، فيدخلون منه إلى الذنوب السبعية، ثم إلى الشيطانية، ثم إلى منازعة الربوبية والشرك في الوحدانية»","pg":289}],"hd":""},{"t":"فصل: من الذنوب كبائر وصغائر","pg":289,"lv":"yth","key":"«وقد دل القرآن والسنة وإجماع الصحابة والتابعين بعدهم والأئمة على أن من الذنوب كبائر وصغائر»","p":["«وهذه الأعمال المكفرة لها ثلاث درجات: إحداها: أن تقصر عن تكفير الصغائر، لضعفها وضعف الإخلاص فيها والقيام بحقوقها؛ بمنزلة الدواء الضعيف الذي ينقص عن مقاومة الداء كمية وكيفية. الثانية: أن تقاوم الصغائر، ولا ترتقي إلى تكفير شيء من الكبائر. الثالثة: أن تقوى على تكفير الصغائر، وتبقى فيها قوة تكفر بها بعض الكبائر»","«فتأمل هذا، فإنه يزيل عنك إشكالات كثيرة»"],"items":[{"h":"قول في الحد","x":"«ما اقترن بالنهي عنه وعيد من لعن أو غضب أو عقوبة فهو كبيرة، وما لم يقترن به شيء من ذلك فهو صغيرة»","pg":292},{"h":"قول ثان","x":"«كل ما رتب عليه حد في الدنيا أو وعيد في الآخرة فهو كبيرة. وما لم يرتب عليه لا هذا ولا هذا فهو صغيرة»","pg":293},{"h":"قول ثالث","x":"«كل ما اتفقت الشرائع على تحريمه فهو من الكبائر، وما كان تحريمه في شريعة دون شريعة فهو صغيرة»","pg":293},{"h":"قول رابع","x":"«كل ما لعن الله أو رسوله فاعله فهو كبيرة»","pg":293},{"h":"جمع أبي طالب المكي","x":"«جمعتها من أقوال الصحابة، فوجدتها: أربعة في القلب، وهي: الشرك، والإصرار على المعصية، والقنوط من رحمة الله، والأمن من مكر الله»","pg":292},{"h":"قول من لم يقسمها","x":"«فلا ينظر العبد إلى كبر الذنب وصغره في نفسه، ولكن ينظر إلى قدر من عصاه وعظمته، وانتهاك حرمته بالمعصية»","pg":294}],"hd":"الصلوات الخمس والجمعة إلى الجمعة: مسلم 233. ألا أنبئكم بأكبر الكبائر: البخاري 2653 ومسلم 87. اجتنبوا السبع الموبقات: البخاري 2766 ومسلم 89. قول ابن مسعود هي أربع: الطبري وسنده صحيح."}],"lv":{"kid":{"show":true,"title":"قلبي السليم وطريقي المستقيم","intro":"الذنب يضر القلب كما يضر السم الجسم، لكن الله رحيم يقبل التوبة. وأجمل عيش هو عيش القلب السليم الذي يحب الله ويذكره، ويسير على الصراط المستقيم.","points":["الذنب يترك أثرا في القلب حتى لو لم أشعر به، فأبادر بالتوبة.","القلب السليم نظيف من الحسد والحقد والكبر.","راحة القلب وسعادته في محبة الله وذكره.","أدعو الله في كل ركعة أن يهديني الصراط المستقيم.","من سار إلى الله في الدنيا بسرعة مر على الصراط يوم القيامة بسرعة."],"quote":{"x":"«وهل العيش في الحقيقة إلا عيش القلب السليم؟»","pg":282},"quiz":[{"q":"من أي شيء يسلم القلب السليم؟","o":["من الحسد والكبر","من التعب والمرض","من الحزن والبكاء","من الجوع والعطش"],"why":"«والقلب السليم هو الذي سلم من الشرك، والغل، والحقد، والحسد، والشح، والكبر، وحب الدنيا والرياسة»","pg":282},{"q":"ما الدعاء الذي يحتاجه العبد أشد الحاجة؟","o":["أن يهديه الله الصراط المستقيم","أن يرزقه الله مالا كثيرا جدا","أن يعطيه الله بيتا كبيرا واسعا","أن يجعله الله مشهورا بين الناس"],"why":"«ولذلك اشتدت حاجة العبد بل ضرورته إلى أن يسأل الله أن يهديه الصراط المستقيم»","pg":283},{"q":"متى يطمئن القلب حقا؟","o":["إذا عرف الله وأحبه","إذا ملك ألعابا كثيرة","إذا مدحه الناس كثيرا","إذا نام وقتا طويلا"],"why":"«ولا تقر العين، ولا يهدأ القلب، ولا تطمئن النفس إلا بإلهها ومعبودها الذي هو حق»","pg":280},{"q":"كيف تكون سرعة الناس على الصراط يوم القيامة؟","o":["على قدر سيرهم إلى الله في الدنيا","على قدر قوة أجسامهم في الدنيا","على قدر كثرة أموالهم في الدنيا","على قدر طول أعمارهم في الدنيا"],"why":"«وجعل قوة سيرهم وسرعتهم عليه على قدر قوة سيرهم وسرعتهم إليه في الدنيا»","pg":285}],"scene":{"t":"ضيق بعد الكذب","x":"كذب أحمد على أخيه الصغير ليأخذ لعبته، ثم شعر بضيق في صدره ولم يستطع أن يفرح باللعبة. ماذا يفعل؟","opts":["يعتذر لأخيه ويعيد اللعبة ويستغفر الله ولا يعود","يسكت وينتظر حتى ينسى أخوه الأمر","يكذب كذبة أخرى حتى لا يكتشف أحد"],"why":"«فمن حفظ القوة بامتثال الأوامر، واستعمل الحمية باجتناب النواهي، واستفرغ التخليط بالتوبة النصوح = لم يدع للخير مطلبا، ولا من الشر مهربا»","pg":258},"act":{"type":"sort","t":"قلب سليم أم قلب مريض؟","x":"اقرأ كل بطاقة، وضعها في سلة القلب السليم إن كانت من صفاته، أو في سلة ما يجب أن يسلم منه القلب.","labels":{"أ":"من صفات القلب السليم","ب":"يسلم منه القلب السليم"},"items":[{"x":"محبة الله","ok":"أ"},{"x":"ذكر الله","ok":"أ"},{"x":"سلامة الصدر للناس","ok":"أ"},{"x":"الحسد","ok":"ب"},{"x":"الكبر","ok":"ب"},{"x":"الحقد","ok":"ب"},{"x":"الغفلة عن ذكر الله","ok":"ب"},{"x":"البخل والشح","ok":"ب"}]}},"yth":{"show":true,"title":"عقوبات تصيب القلب قبل الجسد","intro":"يظن بعض الناس أن الذنب يمر بلا أثر، وابن القيم يبين أن الذنب لا يخلو من عقوبة أبدا، وأن أشد العقوبات ما يصيب القلب فيقسو ويعمى وينتكس. ثم يقسم الذنوب أربعة أقسام، ويبين أن منها كبائر وصغائر.","points":["العقوبات نوعان: شرعية يقيمها الحاكم، وقدرية يقدرها الله في القلب والبدن والمال.","عقوبة القلب أشد من عقوبة البدن، ومنها نكس القلب حتى يرى الباطل حقا.","قد يكون ستر الله ونعمه على العاصي استدراجا يظنه كرامة.","الذنوب أربعة أقسام، وأكثرها البهيمية، ومنها يتدرج العبد إلى ما هو أخطر.","الأعمال الصالحة تكفر الصغائر بحسب قوة إخلاصها، والكبائر تحتاج إلى توبة."],"quote":{"x":"«فسبحان الله، كم من قلب منكوس وصاحبه لا يشعر!»","pg":277},"quiz":[{"q":"أي العقوبتين أشد في كلام ابن القيم؟","o":["عقوبة القلوب","عقوبة الأبدان","عقوبة الأموال","عقوبة الأعراض"],"why":"«وعقوبة القلوب أشد العقوبتين، وهي أصل عقوبة الأبدان»","pg":267},{"q":"ما القسم الذي هو أكثر ذنوب الخلق؟","o":["الذنوب البهيمية","الذنوب السبعية","الذنوب الشيطانية","الذنوب الملكية"],"why":"«وهذا القسم أكثر ذنوب الخلق لعجزهم عن الذنوب السبعية والملكية»","pg":288},{"q":"الحسد والغش والمكر من أي أقسام الذنوب؟","o":["الشيطانية","البهيمية","السبعية","الملكية"],"why":"«وأما الشيطانية، فالتشبه بالشيطان في الحسد، والبغي، والغش والغل، والخداع، والمكر»","pg":288},{"q":"ما علامة الخسف بالقلب؟","o":["أن يجول حول الرذائل والقاذورات","أن يكثر صاحبه من النوم والراحة","أن يقل كلام صاحبه مع الناس","أن يحزن صاحبه على ما فاته"],"why":"«وعلامة الخسف به أن لا يزال جوالا حول السفليات والقاذورات والرذائل»","pg":275},{"q":"بم وصف ابن القيم الذنوب في صلتها بالشرك؟","o":["أنها دهليز الشرك والكفر","أنها لا صلة لها بالشرك","أنها كلها من الشرك الأكبر","أنها تبطل التوحيد كله"],"why":"«ومن تأمل هذا حق التأمل تبين له أن الذنوب دهليز الشرك، والكفر، ومنازعة الله ربوبيته»","pg":289}],"scene":{"t":"إنها صغيرة","x":"قال لك صديقك وهو يهم بمعصية: هذه معصية صغيرة، لا تكبر الأمر. كيف تتصرف؟","opts":["تذكره بعظمة من يعصيه وتقترح عليه أن يتركها","تسكت لأنها صغيرة فعلا ولا تضر","تقول له افعلها الآن وتب منها في الكبر"],"why":"«فلا ينظر العبد إلى كبر الذنب وصغره في نفسه، ولكن ينظر إلى قدر من عصاه وعظمته، وانتهاك حرمته بالمعصية»","pg":294},"act":{"type":"match","t":"أقسام الذنوب الأربعة","x":"صل كل قسم من أقسام الذنوب بأمثلته كما ذكرها ابن القيم، ثم اكتب في دفترك: أي باب أحتاج أن أغلقه أولا؟","items":[{"a":"الملكية","b":"العظمة والكبرياء والعلو واستعباد الخلق"},{"a":"الشيطانية","b":"الحسد والبغي والغش والمكر والابتداع"},{"a":"السبعية","b":"العدوان والغضب والتوثب على الضعفاء"},{"a":"البهيمية","b":"الشره والحرص والبخل والجبن والجزع"}]}},"adl":{"show":true,"title":"فقه العقوبات وأقسام الذنوب","intro":"يعرض ابن القيم في هذه المحطة حكمة الشارع في ترتيب الحدود على قدر الدواعي والمفاسد، وأنواع الكفارات، ثم العقوبات القدرية على القلوب والأبدان، وطرفا منها للاستحضار، ثم سلامة القلب والصراط المستقيم، وتقسيم الذنوب أربعة أقسام، والكلام في الكبائر والصغائر ودرجات المكفرات.","points":["الحدود ثلاثة أنواع: القتل والقطع والجلد، وكل منها بإزاء نوع من الفساد.","الكفارات ثلاثة أنواع: زواجر وتحلة وجوابر، ولا يجتمع الحد والكفارة في معصية.","إقامة العقوبة الشرعية ترفع القدرية أو تخففها، وتعطيلها يجعلها قدرية تعم.","سلامة القلب لا تتم إلا بالسلامة من خمسة: الشرك والبدعة والشهوة والغفلة والهوى.","المكفرات ثلاث درجات بحسب قوتها وإخلاص صاحبها كالدواء مع الداء."],"quote":{"x":"«فعقوبات الشارع جاءت على أتم الوجوه، وأوفقها للعقل، وأقومها بالمصلحة»","pg":260},"quiz":[{"q":"على أي أساس جعل الشارع العقوبات على الجرائم؟","o":["على حسب الدواعي إليها والوازع عنها","على حسب عدد مرات وقوع الجريمة","على حسب منزلة الجاني بين الناس","على حسب ما يراه كل حاكم في زمانه وبلده"],"why":"«وجعلها بحكمته على حسب الدواعي إلى تلك الجرائم، وحسب الوازع عنها»","pg":259},{"q":"متى اكتفى الشارع بالتحريم والتعزير دون الحد؟","o":["إذا كان الوازع عنه طبيعيا","إذا تكرر من فاعله مرارا","إذا كانت مفسدته عامة ظاهرة","إذا وقع في الشهر الحرام"],"why":"«فما كان الوازع عنه طبيعيا وليس في الطباع داع إليه اكتفى فيه بالتحريم مع التعزير ولم يرتب عليه حدا»","pg":259},{"q":"ما أثر إقامة العقوبة الشرعية على العقوبة القدرية؟","o":["ترفعها أو تخففها","توجبها معها دائما","لا أثر لها فيها","تؤخرها إلى البرزخ"],"why":"«فإذا أقيمت الشرعية رفعت العقوبات القدرية أو خففتها»","pg":260},{"q":"كفارة اليمين والنذر من أي أنواع الكفارة عند ابن القيم؟","o":["التحلة لما منعه العقد","الزواجر عن المعصية","الجوابر لما فات كالخطأ","الماحية لهتك حرمة الاسم"],"why":"«فشرع الله سبحانه حله بالكفارة، وسماها تحلة. وليست هذه الكفارة ماحية لهتك حرمة الاسم بالحنث كما ظنه بعض الفقهاء»","pg":266},{"q":"متى تكفر الأعمال الصالحة بعض الكبائر؟","o":["إذا قويت على الصغائر وبقيت فيها قوة","إذا كثر عددها ولو ضعف إخلاصها","إذا عملها العبد في آخر أيام عمره فقط","إذا خلت من الخشوع وحضور القلب"],"why":"«الثالثة: أن تقوى على تكفير الصغائر، وتبقى فيها قوة تكفر بها بعض الكبائر»","pg":290}],"scene":{"t":"كل واحد حر","x":"أب يرى ابنه في مجموعة أصدقاء يستهينون بمنكر ظاهر، ويقول له الابن: كل واحد حر، ولا شأن لنا. كيف يتصرف الأب؟","opts":["يبين له بالحكمة أن السكوت الجماعي عن المنكر سبب لعموم العقوبة ويعلمه الإنكار بلطف","يسكت حتى لا يحرج ابنه أمام أصدقائه","يمنعه من أصدقائه فورا دون أن يبين له السبب"],"why":"«وإذا رأى الناس المنكر فاشتركوا في ترك إنكاره أوشك أن يعمهم الله بعقابه»","pg":261},"act":{"type":"class","t":"خريطة عقوبات القلب","x":"نشاط صفي يبني فيه الطلاب خريطة لعقوبات الذنوب على القلب من نص ابن القيم، ثم يربطون كل عقوبة بعلاجها.","items":["5 دقائق: يقرأ المعلم قوله «فاستحضر بعض العقوبات التي رتبها الله سبحانه على الذنوب» ويسأل: لماذا قال: وجوز وصول بعضها إليك؟","10 دقائق: توزع على المجموعات بطاقات العقوبات: الختم، التثبيط، صمم القلب، الخسف، المسخ، النكس، الحجاب، المعيشة الضنك.","10 دقائق: تكتب كل مجموعة مظهرا واقعيا للعقوبة في حياة الشاب اليوم دون تعيين أشخاص.","10 دقائق: تربط كل مجموعة العقوبة بشيء من الخمسة التي يسلم منها القلب السليم: الشرك والبدعة والشهوة والغفلة والهوى.","5 دقائق: يختم المعلم بقوله «فمن أعظم عقوبات الذنوب: الخروج عن الصراط المستقيم في الدنيا والآخرة» ودعاء الهداية."]}},"alt":{}},"highlights":[{"x":"«وهل العيش في الحقيقة إلا عيش القلب السليم؟»","pg":282,"lv":"kid"},{"x":"«فمن قرت عينه بالله قرت به كل عين»","pg":280,"lv":"kid"},{"x":"«أن الدنيا مزرعة الآخرة وعنوانها وأنموذجها»","pg":286,"lv":"kid"},{"x":"«فالذنب لا يخلو من عقوبة البتة»","pg":272,"lv":"yth"},{"x":"«وكل هذه عقوبات وإهانة، ويظن الجاهل أنها كرامة»","pg":277,"lv":"yth"},{"x":"«فمن أعظم عقوبات الذنوب: الخروج عن الصراط المستقيم في الدنيا والآخرة»","pg":286,"lv":"yth"},{"x":"«وعقوبة القلوب أشد العقوبتين، وهي أصل عقوبة الأبدان»","pg":267,"lv":"yth"},{"x":"«فعقوبات الشارع جاءت على أتم الوجوه، وأوفقها للعقل، وأقومها بالمصلحة»","pg":260,"lv":"adl"}],"concepts":[{"term":"العقوبات القدرية","def":"«وأما العقوبات القدرية فهي نوعان: نوع على القلوب والنفوس، ونوع على الأبدان والأموال»","pg":267},{"term":"التحلة","def":"«ما عقده لله من نذر، أو بالله من يمين، أو حرمه الله ثم أراد حله؛ فشرع الله سبحانه حله بالكفارة، وسماها تحلة»","pg":266},{"term":"القلب السليم","def":"«والقلب السليم هو الذي سلم من الشرك، والغل، والحقد، والحسد، والشح، والكبر، وحب الدنيا والرياسة»","pg":282},{"term":"الصراط المستقيم","def":"«فإن الصراط المستقيم يتضمن علوما وإرادات وأعمالا وتروكا ظاهرة وباطنة تجري عليه كل وقت»","pg":283},{"term":"مسخ القلب","def":"«فيمسخ كما تمسخ الصورة، فيصير القلب على قلب الحيوان الذي شابهه في أخلاقه وأعماله وطبيعته»","pg":275},{"term":"الإركاس","def":"«وهذا هو الإركاس الذي أركس الله به المنافقين بذنوبهم، فأعادهم إلى طباعهم، وما خلقت عليه نفوسهم من الجهل والظلم»","pg":284},{"term":"أصل الذنوب","def":"«أصلها نوعان: ترك مأمور، وفعل محظور»","pg":287}],"stories":[{"t":"القلوب جوالة","x":"نقل ابن القيم عن بعض السلف: «إن هذه القلوب جوالة، فمنها ما يجول حول العرش، ومنها ما يجول حول الحش». والحش موضع قضاء الحاجة كما في حاشية المحقق، والقول من كلام أحمد بن خضرويه البلخي.","pg":275,"lv":"yth","hd":""},{"t":"تأويل سفيان بن عيينة لآية الأمم","x":"في قوله تعالى ﴿وَمَا مِنْ دَابَّةٍ فِي الْأَرْضِ وَلَا طَائِرٍ يَطِيرُ بِجَنَاحَيْهِ إِلَّا أُمَمٌ أَمْثَالُكُمْ﴾ قال: «منهم من يكون على أخلاق السباع العادية، ومنهم من يكون على أخلاق الكلاب وأخلاق الخنزير وأخلاق الحمار، ومنهم من يتطوس في ثيابه كما يتطوس الطاووس في ريشه»، ثم ذكر الديك والجمل والغنم والذئاب والثعالب.","pg":276,"lv":"yth","hd":""},{"t":"لذة القلب السليم","x":"نقل عن بعض من ذاق هذه اللذة: «لو علم الملوك وأبناء الملوك ما نحن فيه لجالدونا عليه بالسيوف»، وقال آخر: «إنه ليمر بالقلب أوقات أقول فيها: إن كان أهل الجنة في مثل هذا إنهم لفي عيش طيب». والأول من كلام إبراهيم بن أدهم، والثاني من كلام أبي سليمان المغربي كما في الحاشية.","pg":281,"lv":"yth","hd":""},{"t":"القلوب أربعة","x":"أثر يروى عن حذيفة بن اليمان: «القلوب أربعة: فقلب أجرد فيه سراج يزهر، فذلك قلب المؤمن. وقلب أغلف، فذلك قلب الكافر. وقلب منكوس، فذلك قلب المنافق. وقلب تمده مادتان: مادة إيمان ومادة نفاق، وهو لما غلب عليه منهما».","pg":273,"lv":"adl","hd":"موقوف على حذيفة، قال المحقق: لم أقف عليه عند أحمد، والأثر مع وقفه في سنده انقطاع، فأبو البختري لم يدرك حذيفة، ورفعه ليث بن أبي سليم وهو مخلط."},{"t":"الزاني بامرأة الغازي","x":"ذكر ابن القيم أن الذنب يتضاعف بحسب حرمة المحل، حتى إن الزاني بامرأة الغازي في سبيل الله يوقف له يوم القيامة ويقال: خذ من حسناته ما شئت، ثم قال النبي ﷺ: «فما ظنكم؟».","pg":263,"lv":"adl","hd":"من حديث بريدة، أخرجه مسلم 1897."}],"ready":true},{"k":"s8","t":"أكبر الكبائر","pgs":[295,348],"q":"لماذا كان الشرك أكبر الكبائر لا يغفر إلا بالتوبة، وما الذنوب التي تليه في المفسدة؟","essence":"التوحيد أعدل العدل والشرك أظلم الظلم","kw":["الشرك","سوء الظن","الظلم"],"daa":"الشرك بأنواعه في الذات والصفات والعبادة واللفظ والإرادة، وما يتبعه من سوء الظن بالله والقول عليه بلا علم والبدع والظلم.","dawa":"تحقيق التوحيد والإخلاص في الأقوال والأفعال والإرادات، وحسن الظن بالله بما هو أهله، والعدل في الخلق.","sections":[{"t":"فصل: وكشف الغطاء عن هذه المسألة","pg":295,"lv":"yth","key":"«فالشرك أظلم الظلم، والتوحيد أعدل العدل»","p":["«فأخبر سبحانه أن القصد بالخلق والأمر أن يعرف بأسمائه وصفاته، ويعبد وحده لا يشرك به، وأن يقوم الناس بالقسط، وهو العدل الذي قامت به السموات والأرض»","«فما كان أشد منافاة لهذا المقصود فهو أكبر الكبائر، وتفاوتها في درجاتها بحسب منافاتها له. وما كان أشد موافقة لهذا المقصود فهو أوجب الواجبات، وأفرض الطاعات»","«ولما كان الشرك بالله منافيا بالذات لهذا المقصود كان أكبر الكبائر على الإطلاق، وحرم الله الجنة على كل مشرك»"],"items":[{"h":"غاية الجهل","x":"«فإن المشرك أجهل الجاهلين بالله، حيث جعل له من خلقه ندا، وذلك غاية الجهل به، كما أنه غاية الظلم منه»","pg":297},{"h":"ظلم النفس","x":"«وإن كان المشرك لم يظلم ربه؛ وإنما ظلم نفسه»","pg":297}],"hd":""},{"t":"مسألة: سر كون الشرك لا يغفر","pg":297,"lv":"adl","key":"«فهذه إشارة إلى لطيفة السر الذي لأجله كان الشرك أكبر الكبائر عند الله، وأنه لا يغفر بغير التوبة منه، وأنه يوجب الخلود في العذاب، وأنه ليس تحريمه وقبحه بمجرد النهي عنه، بل يستحيل على الله سبحانه أن يشرع عبادة إله غيره»","p":["«ووقعت مسألة، وهي أن المشرك إنما قصده تعظيم جناب الرب تبارك وتعالى، وأنه لعظمته لا ينبغي الدخول عليه إلا بالوسائط والشفعاء كحال الملوك»","«فتأمل هذا السؤال، واجمع قلبك وذهنك على جوابه، ولا تستهونه، فإنه به يحصل الفرق بين الموحدين والمشركين، والعالمين بالله والجاهلين به، وأهل الجنة وأهل النار»"],"items":[{"h":"الشيطان هو المعبود في الحقيقة","x":"«فما عبد أحد من بني آدم غير الله كائنا من كان إلا وقعت عبادته للشيطان، فيستمتع العابد بالمعبود في حصول غرضه، ويستمتع المعبود بالعابد في تعظيمه له وإشراكه مع الله الذي هو غاية رضى الشيطان»","pg":328}],"hd":""},{"t":"الشرك شركان، والشرك الأول نوعان","pg":298,"lv":"adl","key":"«الشرك شركان: شرك يتعلق بذات المعبود وأسمائه وصفاته وأفعاله. وشرك في عبادته ومعاملته، وإن كان صاحبه يعتقد أنه سبحانه لا شريك له في ذاته ولا في صفاته ولا في أفعاله»","p":["«أحدهما: شرك التعطيل. وهو أقبح أنواع الشرك، كشرك فرعون»","«والشرك والتعطيل متلازمان. فكل مشرك معطل، وكل معطل مشرك؛ لكن الشرك لا يستلزم أصل التعطيل، بل قد يكون المشرك مقرا بالخالق سبحانه وصفاته، ولكنه عطل حق التوحيد»"],"items":[{"h":"أقسام التعطيل","x":"«وهو ثلاثة أقسام: تعطيل المصنوع عن صانعه وخالقه. وتعطيل الصانع سبحانه عن كماله المقدس، بتعطيل أسمائه وأوصافه وأفعاله. وتعطيل معاملته عما يجب على العبد من حقيقة التوحيد»","pg":299},{"h":"النوع الثاني","x":"«النوع الثاني: شرك من جعل معه إلها آخر، ولم يعطل أسماءه وصفاته وربوبيته، كشرك النصارى الذين جعلوه ثالث ثلاثة، فجعلوا المسيح إلها وأمه إلها»","pg":300},{"h":"شرك المجوس والقدرية","x":"«ومن هذا: شرك المجوس القائلين بإسناد حوادث الخير إلى النور وحوادث الشر إلى الظلمة. ومن هذا: شرك القدرية القائلين بأن الحيوان هو الذي يخلق أفعال نفسه»","pg":300},{"h":"شرك الكواكب والشمس والنار","x":"«ومن هذا: شرك كثير ممن يشرك بالكواكب العلويات، ويجعلها أربابا مدبرة لأمر هذا العالم، كما هو مذهب مشركي الصابئة وغيرهم. ومن هذا: شرك عباد الشمس وعباد النار وغيرهم»","pg":301}],"hd":""},{"t":"فصل: وأما الشرك في العبادة","pg":301,"lv":"kid","key":"«فالعمل الصالح هو الخالي من الرياء، المقيد بالسنة»","p":["«ولكن لا يخلص لله في معاملته وعبوديته، بل يعمل لحظ نفسه تارة، ولطلب الدنيا تارة، ولطلب الرفعة والمنزلة والجاه عند الخلق تارة. فلله من عمله وسعيه نصيب، ولنفسه وحظه وهواه نصيب، وللشيطان نصيب، وللخلق نصيب. وهذا حال أكثر الناس»","«فالرياء كله شرك»","«وهذا الشرك في العبادة يبطل ثواب العمل، وقد يعاقب عليه إذا كان العمل واجبا، فإنه ينزله منزلة من لم يعمله، فيعاقب على ترك الأمر»"],"items":[{"h":"حديث أنا أغنى الشركاء","x":"«أنا أغنى الشركاء عن الشرك، فمن عمل عملا أشرك معي فيه غيري، فهو للذي أشرك به، وأنا منه بريء»","pg":303},{"h":"أقسام هذا الشرك","x":"«وهذا الشرك ينقسم إلى مغفور وغير مغفور، وأكبر وأصغر»","pg":304}],"hd":"أنا أغنى الشركاء: أخرجه مسلم 2985. حديث الشرك أخفى من دبيب النمل لم يثبت عند المحقق من أكثر طرقه (انظر weak). دعاء عمر: من طريق الحسن ولم يسمع من عمر."},{"t":"الشرك في المحبة والتعظيم","pg":304,"lv":"adl","key":"«فمنه الشرك بالله في المحبة والتعظيم أن يحب مخلوقا كما يحب الله، فهذا من الشرك الذي لا يغفره الله»","p":["«ومعلوم أنهم ما سووهم به سبحانه في الخلق والرزق والإماتة والإحياء والملك والقدرة، وإنما سووهم به في الحب والتأله والخضوع لهم والتذلل. وهذا غاية الظلم والجهل»","«فيا لك من عدل تضمن أكبر الظلم وأقبحه!»"],"items":[{"h":"قول أهل النار","x":"﴿تَاللَّهِ إِنْ كُنَّا لَفِي ضَلَالٍ مُبِينٍ إِذْ نُسَوِّيكُمْ بِرَبِّ الْعَالَمِينَ﴾","pg":304}],"hd":""},{"t":"فصل: الشرك في الأفعال","pg":305,"lv":"adl","key":"«وقد لعن النبي ﷺ من اتخذ قبور الأنبياء والصالحين مساجد يصلى لله فيها، فكيف بمن اتخذ القبور أوثانا يعبدها من دون الله!»","p":["«فالشرك في الأفعال كالسجود لغيره، والطواف بغير بيته، وحلق الرأس عبودية وخضوعا لغيره، وتقبيل الأحجار غير الحجر الأسود الذي هو يمينه في الأرض، وتقبيل القبور واستلامها والسجود لها»","«وقد حمى النبي ﷺ جانب التوحيد أعظم حماية، حتى نهى عن صلاة التطوع لله سبحانه عند طلوع الشمس وعند غروبها، لئلا يكون ذريعة إلى التشبه بعباد الشمس الذين يسجدون لها في هاتين الحالتين»"],"items":[{"h":"لعن اتخاذ القبور مساجد","x":"«لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد»","pg":306},{"h":"النهي الصريح","x":"«ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك»","pg":306},{"h":"السجود لغير الله","x":"«وأما السجود لغير الله فقال: لا ينبغي لأحد أن يسجد لأحد إلا لله»","pg":309}],"hd":"لعن الله اليهود والنصارى: البخاري 435 ومسلم 531. ألا فلا تتخذوا القبور مساجد: مسلم 532. إن من كان قبلكم كانوا إذا مات فيهم الرجل الصالح: البخاري 434 ومسلم 528. النهي عن الصلاة عند طلوع الشمس وغروبها: البخاري 582 ومسلم 828. لا ينبغي لأحد أن يسجد لأحد: ابن حبان 4162 وسنده حسن. اللهم لا تجعل قبري وثنا يعبد: أحمد 7358، تفرد به حمزة بن المغيرة عن سهيل وعده الدارقطني وأبو نعيم من غرائبه. لعن زوارات القبور والسرج، واشتد غضب الله: ضعيفان (انظر weak).","weak":1},{"t":"فصل: الشرك به في اللفظ","pg":310,"lv":"adl","key":"«ومن الشرك به سبحانه: الشرك به في اللفظ، كالحلف بغيره»","p":["«ومن ذلك قول القائل للمخلوق: ما شاء الله وشئت، كما ثبت عن النبي ﷺ أنه قال له رجل: ما شاء الله وشئت، فقال: أجعلتني لله ندا؟ قل: ما شاء الله وحده»","«فالسجود، والعبادة، والتوكل، والإنابة، والتقوى، والخشية، والتحسب، والتوبة، والنذر، والحلف، والتسبيح، والتكبير، والتهليل، والتحميد، والاستغفار، وحلق الرأس خضوعا وتعبدا، والطواف بالبيت، والدعاء = كل ذلك محض حق الله الذي لا يصلح ولا ينبغي لسواه من ملك مقرب ولا نبي مرسل»"],"items":[{"h":"ألفاظ أفحش","x":"«أنا متوكل على الله وعليك، وأنا في حسب الله وحسبك، ومالي إلا الله وأنت، وهذا من الله ومنك، وهذا من بركات الله وبركاتك، والله لي في السماء وأنت لي في الأرض»","pg":311},{"h":"الموازنة","x":"«فوازن بين هذه الألفاظ وبين قول القائل: ما شاء الله وشئت، ثم انظر: أيهما أفحش، يتبين لك أن قائلها أولى بجواب النبي ﷺ لقائل تلك الكلمة»","pg":311}],"hd":"من حلف بغير الله فقد أشرك: أحمد وأبو داود والترمذي، صححه الحاكم وابن حبان، وانظر السلسلة الصحيحة 2042. أجعلتني لله ندا: أحمد والبخاري في الأدب المفرد وغيرهما، مداره على الأجلح وهو مختلف فيه، وله شواهد. حديث عرف الحق لأهله ضعيف (انظر weak).","weak":1},{"t":"فصل: وأما الشرك في الإرادات والنيات","pg":312,"lv":"yth","key":"«وأما الشرك في الإرادات والنيات، فذلك البحر الذي لا ساحل له، وقل من ينجو منه»","p":["«فمن أراد بعمله غير وجه الله، أو نوى شيئا غير التقرب إليه وطلب الجزاء منه، فقد أشرك في نيته وإرادته»","«والإخلاص أن يخلص لله في أقواله وأفعاله وإراداته ونيته. وهذه هي الحنيفية ملة إبراهيم التي أمر الله بها عباده كلهم، ولا يقبل من أحد غيرها. وهي حقيقة الإسلام»"],"items":[],"hd":""},{"t":"فصل: حقيقة الشرك","pg":313,"lv":"yth","key":"«حقيقة الشرك هو التشبه بالخالق والتشبيه للمخلوق به»","p":["«هذا هو التشبيه في الحقيقة، لا إثبات صفات الكمال التي وصف الله بها نفسه، ووصفه بها رسوله»","«فالمشرك مشبه للمخلوق بالخالق في خصائص الإلهية»","«ومن خصائص الإلهية: العبودية التي قامت على ساقين لا قوام لها بدونهما: غاية الحب مع غاية الذل. هذا تمام العبودية»"],"items":[{"h":"التفرد بالضر والنفع","x":"«فإن من خصائص الإلهية التفرد بملك الضر والنفع والعطاء والمنع، وذلك يوجب تعلق الدعاء والخوف والرجاء والتوكل به وحده»","pg":313},{"h":"الكمال المطلق","x":"«ومن خصائص الإلهية: الكمال المطلق من جميع الوجوه، الذي لا نقص فيه بوجه من الوجوه. وذلك يوجب أن تكون العبادة كلها له وحده»","pg":314},{"h":"من مظاهر التشبيه","x":"«فمن خصائص الإلهية: السجود، فمن سجد لغيره فقد شبه المخلوق به. ومنها: التوكل، فمن توكل على غيره فقد شبهه به. ومنها: التوبة، فمن تاب لغيره فقد شبهه به. ومنها: الحلف باسمه تعظيما وإجلالا له، فمن حلف بغيره فقد شبهه به»","pg":315},{"h":"جانب التشبه","x":"«فمن تعاظم وتكبر، ودعا الناس إلى إطرائه في المدح، والتعظيم، والخضوع، والرجاء، وتعليق القلب به خوفا ورجاء والتجاء واستعانة به، فقد تشبه بالله، ونازعه ربوبيته وإلهيته»","pg":316},{"h":"ملك الملوك","x":"«فهذا مقت الله وغضبه على من تشبه به في الاسم الذي لا ينبغي إلا له. فهو سبحانه ملك الملوك وحده، وهو حاكم الحكام وحده»","pg":318}],"hd":"العظمة إزاري: مسلم 2620. أشد الناس عذابا يوم القيامة المصورون: البخاري 5950 ومسلم 2109. ومن أظلم ممن ذهب يخلق كخلقي: البخاري 7559 ومسلم 2111. أخنع الأسماء: البخاري 6205 ومسلم 2143."},{"t":"فصل: أصل عظيم يكشف سر المسألة: إساءة الظن بالله","pg":318,"lv":"yth","key":"«وهو أن أعظم الذنوب عند الله إساءة الظن به»","p":["«فإن المسيء به الظن قد ظن به خلاف كماله المقدس، وظن به ما يناقض أسماءه وصفاته»","«فلو ظننتم به ما هو أهله من أنه بكل شيء عليم، وعلى كل شيء قدير، وأنه غني عن كل ما سواه، وكل ما سواه فقير إليه؛ وأنه قائم بالقسط على خلقه، وأنه المتفرد بتدبير خلقه، لا يشركه فيه غيره»","«فإدخال الوسائط بينه وبين خلقه تنقص بحق ربوبيته، وإلهيته، وتوحيده؛ وظن به ظن السوء»"],"items":[{"h":"من عبد معه غيره","x":"«فما قدر الله حق قدره من عبد معه من لا يقدر على خلق أضعف حيوان وأصغره»","pg":321},{"h":"من أنكر الرسالة","x":"«وكذلك ما قدره حق قدره من قال: إنه لم يرسل إلى خلقه رسولا ولا أنزل كتابا»","pg":321},{"h":"من نفى الصفات","x":"«ولا قدره حق قدره من نفى حقائق أسمائه الحسنى وصفاته العلى»","pg":322},{"h":"من جعل له صاحبة وولدا","x":"«وكذلك لم يقدره حق قدره من جعل له صاحبة وولدا، أو جعله يحل في مخلوقاته، أو جعله عين هذا الوجود»","pg":324},{"h":"من أنكر البعث","x":"«وكذلك لم يقدره حق قدره من زعم أنه لا يحيي الموتى، ولا يبعث من في القبور، ولا يجمع خلقه ليوم يجازي المحسن فيه بإحسانه والمسيء بإساءته»","pg":325},{"h":"من هان عليه أمره","x":"«وكذلك لم يقدره حق قدره من هان عليه أمره فعصاه، ونهيه فارتكبه، وحقه فضيعه، وذكره فأهمله وغفل قلبه عنه، وكان هواه آثر عنده من طلب رضاه، وطاعة المخلوق أهم عنده من طاعته»","pg":326},{"h":"الحياء من الناس","x":"«ويستحيي من الناس، ولا يستحيي من الله. ويخشى الناس، ولا يخشى الله»","pg":326}],"hd":""},{"t":"فصل: الكبر وتوابعه","pg":329,"lv":"kid","key":"«ولذلك حرم الله الجنة على أهل الشرك والكبر، فلا يدخلها من كان في قلبه مثقال ذرة من كبر»","p":["«فلما كان الشرك أكبر شيء منافاة للأمر الذي خلق الله له الخلق وأمر لأجله بالأمر كان أكبر الكبائر عند الله»","«وكذلك الكبر وتوابعه كما تقدم، فإن الله سبحانه خلق الخلق وأنزل الكتب لتكون الطاعة له وحده، والشرك والكبر ينافيان ذلك»"],"items":[],"hd":"لا يدخل الجنة من كان في قلبه مثقال ذرة من كبر: مسلم 91."},{"t":"فصل: القول على الله بلا علم","pg":329,"lv":"yth","key":"«ويلي ذلك في كبر المفسدة: القول على الله بلا علم في أسمائه وصفاته وأفعاله، ووصفه بضد ما وصف به نفسه ووصفه به رسوله»","p":["«فإن صدر ذلك عن علم فهو عناد أقبح من الشرك، وأعظم إثما عند الله»","«فداء التعطيل هو الداء العضال الذي لا دواء له»","«والقول على الله بلا علم والشرك متلازمان»"],"items":[{"h":"المشرك المقر خير من المعطل","x":"«فإن المشرك المقر بصفات الرب خير من المعطل الجاحد لصفات كماله»","pg":330}],"hd":""},{"t":"البدع المضلة","pg":331,"lv":"adl","key":"«ولما كانت البدع المضلة جهلا بصفات الله وتكذيبا بما أخبر به عن نفسه وأخبر به عنه رسوله عنادا وجهلا كانت من أكبر الكبائر، إن قصرت عن الكفر، وكانت أحب إلى إبليس من كبار الذنوب»","p":["«البدعة أحب إلى إبليس من المعصية، لأن المعصية يتاب منها، والبدعة لا يتاب منها»","«ومعلوم أن المذنب إنما ضرره على نفسه، وأما المبتدع فضرره على النوع. وفتنة المبتدع في أصل الدين، وفتنة المذنب في الشهوة»","«والمبتدع يقطع على الناس طريق الآخرة، والعاصي بطيء السير بسبب ذنوبه»"],"items":[],"hd":"قول البدعة أحب إلى إبليس: من كلام سفيان الثوري، أخرجه ابن الجعد واللالكائي وأبو نعيم، وسنده حسن. أثر إبليس أهلكت بني آدم بالذنوب: سنده واه (انظر weak).","weak":1},{"t":"فصل: الظلم والعدوان والقتل","pg":332,"lv":"adl","key":"«ثم لما كان الظلم والعدوان منافيا للعدل الذي قامت به السموات والأرض، وأرسل سبحانه رسله وأنزل كتبه ليقوم الناس به = كان من أكبر الكبائر عند الله، وكانت درجته في العظم بحسب مفسدته في نفسه»","p":["«وتتفاوت درجات القتل بحسب قبحه، واستحقاق من قتله السعي في إبقائه ونصيحته»","«وقد جعل الله سبحانه جزاء قتل النفس المؤمنة عمدا الخلود في النار، وغضب الجبار، ولعنته، وإعداد العذاب العظيم له. هذا موجب قتل المؤمن عمدا، ما لم يمنع منه مانع»","«ولا خلاف أن الإسلام الواقع بعد القتل طوعا واختيارا مانع من نفوذ ذلك الجزاء»"],"items":[],"hd":""},{"t":"وهل تمنع توبة المسلم منه بعد وقوعه؟","pg":333,"lv":"adl","key":"«والتحقيق في هذه المسألة أن القتل يتعلق به ثلاث حقوق: حق لله، وحق للمقتول، وحق للولي»","p":["«فإذا سلم القاتل نفسه طوعا واختيارا إلى الولي ندما على ما فعل، وخوفا من الله، وتوبة نصوحا = سقط حق الله بالتوبة، وحق الولي بالاستيفاء أو الصلح أو العفو، وبقي حق المقتول يعوضه الله عنه يوم القيامة عن عبده التائب المحسن، ويصلح بينه وبينه؛ فلا يذهب حق هذا، ولا تبطل توبة هذا»"],"items":[{"h":"القول الأول","x":"«والذين قالوا: لا تمنع التوبة من نفوذه، رأوا أنه حق لآدمي لم يستوفه في دار الدنيا، وخرج منها بظلامته، فلابد أن يستوفى له في دار العدل»","pg":333},{"h":"القول الثاني","x":"«قالوا: وإذا كانت التوبة تمحو أثر الكفر والسحر وما هو أعظم إثما من القتل فكيف تقصر عن محو أثر القتل؟»","pg":334}],"hd":""},{"t":"وأما مسألة المال","pg":335,"lv":"adl","key":"«وفصل شيخنا بين الطائفتين، فقال: إن تمكن الموروث من أخذ ماله والمطالبة به فلم يأخذه حتى مات صارت المطالبة للوارث في الآخرة، كما هي كذلك في الدنيا. وإن لم يتمكن من طلبه وأخذه بل حال بينه وبينه ظلما وعدوانا فالطلب له في الآخرة»","p":["«وهذا التفصيل من أحسن ما يقال»","«فإذا كان المال عقارا أو أرضا أو أعيانا قائمة باقية بعد الموت، فهي ملك للوارث، يجب على الغاصب دفعها إليه كل وقت»"],"items":[],"hd":""},{"t":"فصل: فكأنما قتل الناس جميعا","pg":337,"lv":"adl","key":"«فمن آذى مؤمنا واحدا، فكأنما آذى جميع المؤمنين»","p":["«وقد أشكل فهم هذا على كثير من الناس، وقالوا: معلوم أن إثم قاتل مائة أعظم عند الله من إثم قاتل نفس واحدة. وإنما أتوا من ظنهم أن التشبيه في مقدار الإثم والعقوبة»","«وما أوتي عبد بعد الإيمان أفضل من الفهم عن الله ورسوله، وذلك فضل الله يؤتيه من يشاء»"],"items":[{"h":"الوجه الأول","x":"«أن كلا منهما عاص لله ورسوله، مخالف لأمره، متعرض لعقوبته»","pg":339},{"h":"الوجه الثاني","x":"«أنهما سواء في استحقاق إزهاق النفس»","pg":339},{"h":"الوجه الثالث","x":"«أنهما سواء في الجرأة على سفك الدم الحرام»","pg":339},{"h":"وجه التسمية","x":"«أنه يسمى قاتلا أو فاسقا أو ظالما أو عاصيا بقتله واحدا، كما يسمى كذلك بقتله الناس جميعا»","pg":339},{"h":"الجسد الواحد","x":"«أن الله سبحانه جعل المؤمنين في توادهم وتراحمهم وتواصلهم كالجسد الواحد»","pg":339},{"h":"من سن","x":"«وكذلك حكم من سن سنة سيئة فاتبع عليها»","pg":341}],"hd":"مثل المؤمنين في توادهم: البخاري 6011 ومسلم 2586. لا تقتل نفس ظلما إلا كان على ابن آدم الأول كفل من دمها: البخاري 3335 ومسلم 1677. عمرو بن لحي: البخاري 3521 ومسلم 2856. يجيء المقتول بالقاتل: الترمذي 3029 وقال: حديث حسن، وصححه ابن حجر. أول ما ينتن من الإنسان بطنه: البخاري 7152 من كلام جندب. لا يزال المؤمن في فسحة من دينه: البخاري 6862. سباب المسلم فسوق: المحفوظ في الصحيحين من حديث ابن مسعود، البخاري 48 ومسلم 64. لا ترجعوا بعدي كفارا: البخاري 7077 ومسلم 65. من قتل معاهدا: البخاري 3166. من صلى العشاء في جماعة: مسلم 656. من صام رمضان وأتبعه ستا: مسلم 1164. حديث لزوال الدنيا مرفوعا ضعيف (انظر weak).","weak":1},{"t":"فصل: مفسدة الزنى وتعليق الفلاح على حفظ الفرج","pg":345,"lv":"adl","key":"«وعلق سبحانه فلاح العبد على حفظ فرجه منه، فلا سبيل له إلى الفلاح بدونه»","p":["«وأمر تعالى نبيه ﷺ أن يأمر المؤمنين بغض أبصارهم وحفظ فروجهم، وأن يعلمهم أنه مشاهد لأعمالهم، مطلع عليها»","«فمقاساة ألم الشهوة ومعاناتها أيسر من بعض ذلك»","«ولما كان مبدأ ذلك من قبل البصر جعل الأمر بغضه مقدما على حفظ الفرج، فإن الحوادث مبداها من النظر»"],"items":[{"h":"الأبواب الأربعة","x":"«ولهذا قيل: من حفظ هذه الأربعة أحرز دينه: اللحظات، والخطرات، واللفظات، والخطوات»","pg":347},{"h":"اللحظات","x":"«فأما اللحظات فهي رائد الشهوة ورسولها، وحفظها أصل حفظ الفرج. فمن أطلق بصره أورده موارد الهلكات»","pg":348}],"hd":"قصة القردة في الجاهلية: البخاري 3849 من كلام عمرو بن ميمون. حديث لا تتبع النظرة النظرة: ضعيف الإسناد عند المحقق (انظر weak)، فلا يعرض للشاب. وتفصيل الأبواب الأربعة يأتي في الجزء التالي.","weak":1}],"lv":{"kid":{"show":true,"title":"أوحد ربي وأحسن الظن به","intro":"أعظم ذنب في الدنيا أن يجعل الإنسان لله شريكا. والمؤمن يعبد الله وحده، ويعمل العمل له وحده، ولا يحلف إلا به، ويظن بربه كل خير لأنه العليم القدير الرحيم.","points":["أعظم الذنوب أن يجعل الإنسان لله شريكا، فأقول دائما: لا إله إلا الله.","أعمل الخير لله وحده، لا لكي يمدحني الناس.","لا أحلف إلا بالله، ولا أقول: ما شاء الله وشئت، بل: ما شاء الله وحده.","أحسن الظن بربي، فهو يعلم كل شيء ويقدر على كل شيء.","لا أتكبر على أحد، فالكبر يمنع صاحبه من دخول الجنة."],"quote":{"x":"«فالعمل الصالح هو الخالي من الرياء، المقيد بالسنة»","pg":303},"quiz":[{"q":"ما أكبر الكبائر عند الله؟","o":["أن تجعل لله شريكا","أن تكذب في المزاح","أن تنام بعد الفجر","أن تأكل وأنت واقف"],"why":"«فلما كان الشرك أكبر شيء منافاة للأمر الذي خلق الله له الخلق وأمر لأجله بالأمر كان أكبر الكبائر عند الله»","pg":329},{"q":"ما العمل الصالح؟","o":["الخالي من الرياء الموافق للسنة","الكثير الذي يراه كل الناس","الذي يمدحه عليه أصدقاؤه كثيرا","الذي يعمله ليكسب جائزة ثمينة"],"why":"«فالعمل الصالح هو الخالي من الرياء، المقيد بالسنة»","pg":303},{"q":"بمن يحلف المسلم إذا احتاج إلى الحلف؟","o":["بالله تعالى وحده","بالكعبة المشرفة","بحياة والدي الحبيب","بشرف مدرستي الجميلة"],"why":"«ومن الشرك به سبحانه: الشرك به في اللفظ، كالحلف بغيره»","pg":310},{"q":"كيف يظن المؤمن بربه؟","o":["أنه عليم قدير غني عن كل شيء","أنه لا يرى ما يعمله الناس","أنه يحتاج إلى من يعينه على خلقه","أنه بعيد لا يسمع الدعاء أبدا"],"why":"«فلو ظننتم به ما هو أهله من أنه بكل شيء عليم، وعلى كل شيء قدير، وأنه غني عن كل ما سواه»","pg":319}],"scene":{"t":"صلاة أمام الضيوف","x":"جاء ضيوف إلى بيت سعد، فقام يصلي أمامهم، وتمنى في نفسه أن يمدحوه ويقولوا: ما أحسن صلاته! ماذا يفعل سعد؟","opts":["يجدد نيته في قلبه ويصلي لله وحده","يطيل الصلاة كثيرا حتى يمدحه الضيوف","يترك الصلاة حتى يذهب الضيوف"],"why":"«فمن أراد بعمله غير وجه الله، أو نوى شيئا غير التقرب إليه وطلب الجزاء منه، فقد أشرك في نيته وإرادته»","pg":312},"act":{"type":"sort","t":"كلمات أقولها وكلمات أتركها","x":"اقرأ كل عبارة، وضعها في سلة: أقولها، أو في سلة: أتركها لأن فيها تسوية بين الله والمخلوق.","labels":{"أ":"أقولها","ب":"أتركها"},"items":[{"x":"والله","ok":"أ"},{"x":"ما شاء الله وحده","ok":"أ"},{"x":"توكلت على الله","ok":"أ"},{"x":"هذا من فضل الله","ok":"أ"},{"x":"ما شاء الله وشئت","ok":"ب"},{"x":"مالي إلا الله وأنت","ok":"ب"},{"x":"أنا متوكل على الله وعليك","ok":"ب"},{"x":"والكعبة","ok":"ب"}]}},"yth":{"show":true,"title":"التوحيد أعدل العدل","intro":"خلق الله الخلق ليعرف ويعبد وحده، فكان الشرك أشد شيء منافاة لهذا المقصود، ولذلك كان أكبر الكبائر. ويفصل ابن القيم أنواع الشرك حتى يصل إلى الشرك الخفي في النيات، ثم يبين أن أعظم الذنوب إساءة الظن بالله، ثم يذكر القول على الله بلا علم، والبدع، والظلم والقتل.","points":["الشرك شركان: في ذات الله وأسمائه وصفاته وأفعاله، وفي عبادته ومعاملته.","الشرك في النيات بحر لا ساحل له، وعلاجه الإخلاص في القول والفعل والإرادة.","حقيقة الشرك تشبيه المخلوق بالخالق، لا إثبات صفات الكمال لله.","أعظم الذنوب إساءة الظن بالله، ومنها من يستحيي من الناس ولا يستحيي من الله.","المبتدع ضرره على الناس، والقاتل لنفس واحدة كأنما آذى جميع المؤمنين."],"quote":{"x":"«وأما الشرك في الإرادات والنيات، فذلك البحر الذي لا ساحل له، وقل من ينجو منه»","pg":312},"quiz":[{"q":"ما حقيقة الشرك عند ابن القيم؟","o":["التشبه بالخالق والتشبيه للمخلوق به","إثبات صفات الكمال التي وصف الله بها نفسه","ترك بعض النوافل والسنن المؤكدة","الوقوع في شيء من الذنوب الصغيرة"],"why":"«حقيقة الشرك هو التشبه بالخالق والتشبيه للمخلوق به. هذا هو التشبيه في الحقيقة، لا إثبات صفات الكمال التي وصف الله بها نفسه»","pg":313},{"q":"ما الذنب الذي قال إنه أعظم الذنوب عند الله في هذا الأصل؟","o":["إساءة الظن بالله","الغفلة عن ذكر الله","الإسراف في المباح","التقصير في النوافل"],"why":"«وهو أن أعظم الذنوب عند الله إساءة الظن به»","pg":318},{"q":"لماذا كانت البدعة أحب إلى إبليس من المعصية؟","o":["لأن المعصية يتاب منها والبدعة لا يتاب منها","لأن المعصية أثقل على النفس من البدعة","لأن البدعة لا يراها الناس ولا يعرفونها","لأن المعصية لا يعاقب عليها صاحبها"],"why":"«البدعة أحب إلى إبليس من المعصية، لأن المعصية يتاب منها، والبدعة لا يتاب منها»","pg":331},{"q":"ما الفرق بين ضرر المذنب وضرر المبتدع؟","o":["المذنب يضر نفسه والمبتدع يضر النوع","المبتدع يضر نفسه والمذنب يضر النوع","ضررهما واحد فلا فرق بينهما أبدا","المذنب لا يضر أحدا ولا حتى نفسه"],"why":"«ومعلوم أن المذنب إنما ضرره على نفسه، وأما المبتدع فضرره على النوع»","pg":331},{"q":"من الذي لم يقدر الله حق قدره بحسب كلام ابن القيم؟","o":["من يستحيي من الناس ولا يستحيي من الله","من يستحيي من الله أكثر من حيائه من الناس","من يخشى الله في السر والعلانية","من يقدم طاعة الله على هوى نفسه"],"why":"«ويستحيي من الناس، ولا يستحيي من الله. ويخشى الناس، ولا يخشى الله»","pg":326}],"scene":{"t":"عداد الإعجابات","x":"ينشر يوسف مقاطع لتلاوته على الإنترنت، وصار يراقب عدد الإعجابات بقلق، ويحزن إذا قل. ماذا يفعل؟","opts":["يراجع نيته ويجعل همه رضا الله ويخفي بعض عمله","يكثر من المقاطع ليزيد المتابعون مهما كانت نيته","يحزن ويترك التلاوة كلها حتى في بيته"],"why":"«والإخلاص أن يخلص لله في أقواله وأفعاله وإراداته ونيته. وهذه هي الحنيفية ملة إبراهيم التي أمر الله بها عباده كلهم»","pg":313},"act":{"type":"match","t":"خريطة أنواع الشرك","x":"صل كل نوع من أنواع الشرك بمثاله من كلام ابن القيم.","items":[{"a":"شرك التعطيل","b":"قول فرعون: وما رب العالمين"},{"a":"جعل إله آخر معه","b":"قول النصارى في المسيح وأمه"},{"a":"الشرك في العبادة","b":"العمل لطلب المنزلة عند الخلق"},{"a":"الشرك في الأفعال","b":"السجود لغير الله"},{"a":"الشرك في اللفظ","b":"الحلف بغير الله"},{"a":"الشرك في الإرادات","b":"أن يريد بعمله غير وجه الله"}]}},"adl":{"show":true,"title":"أكبر الكبائر وسر عدم مغفرة الشرك","intro":"يجيب ابن القيم عن سؤال دقيق: إذا كان المشرك يزعم أنه يعظم الله باتخاذ الوسائط فلم لا يغفر شركه؟ فيبين أن القصد بالخلق والأمر أن يعرف الله ويعبد وحده، وأن حقيقة الشرك تشبيه المخلوق بالخالق في خصائص الإلهية، وأن ذلك ظن سوء بالله يستحيل أن يشرعه. ثم يرتب الكبائر بعده: القول على الله بلا علم، والبدع، ثم الظلم والقتل وتوبة القاتل والغاصب، ثم الزنى.","points":["قبح الشرك ليس بمجرد النهي عنه، بل هو مستقر في الفطر والعقول.","شرك التعطيل أقبح أنواع الشرك، والشرك في العبادة أخف منه وهو يبطل ثواب العمل.","إدخال الوسائط بين الله وخلقه تنقص لربوبيته وإلهيته وظن سوء به.","القاتل يتعلق به حق لله وحق للمقتول وحق للولي، والتوبة مع التسليم تسقط الأول والثالث ويعوض الله المقتول.","التشبيه بين قاتل النفس وقاتل الناس جميعا ليس في مقدار الإثم بل في وجوه أخرى."],"quote":{"x":"«فالشرك أظلم الظلم، والتوحيد أعدل العدل»","pg":296},"quiz":[{"q":"لماذا كان الشرك أكبر الكبائر على الإطلاق؟","o":["لأنه مناف بالذات للمقصود من الخلق والأمر","لأن قبحه ثبت بمجرد النهي الشرعي عنه","لأنه أكثر الذنوب وقوعا بين الناس قديما","لأن عقوبته في الدنيا أشد من عقوبة سائر الذنوب"],"why":"«ولما كان الشرك بالله منافيا بالذات لهذا المقصود كان أكبر الكبائر على الإطلاق»","pg":296},{"q":"ما أقبح أنواع الشرك عند ابن القيم؟","o":["شرك التعطيل كشرك فرعون","الشرك في اللفظ كالحلف بغيره","الشرك في العبادة كالرياء","شرك من قال: ما شاء الله وشئت"],"why":"«أحدهما: شرك التعطيل. وهو أقبح أنواع الشرك، كشرك فرعون»","pg":299},{"q":"على التحقيق، ما مصير حق المقتول إذا تاب القاتل وسلم نفسه؟","o":["يعوضه الله عنه يوم القيامة","يسقط بالتوبة فلا يبقى منه شيء","يسقط باستيفاء الوارث القصاص","يبقى ولا تقبل توبة القاتل"],"why":"«وبقي حق المقتول يعوضه الله عنه يوم القيامة عن عبده التائب المحسن، ويصلح بينه وبينه؛ فلا يذهب حق هذا، ولا تبطل توبة هذا»","pg":335},{"q":"ما تفصيل شيخ الإسلام في المال المغصوب إذا مات صاحبه؟","o":["إن تمكن من أخذه فلم يأخذه فالطلب للوارث","الطلب للوارث في كل حال بلا تفصيل","الطلب لجميع الورثة المتعاقبين دائما","يسقط الطلب كله بموت صاحب المال"],"why":"«إن تمكن الموروث من أخذ ماله والمطالبة به فلم يأخذه حتى مات صارت المطالبة للوارث في الآخرة، كما هي كذلك في الدنيا»","pg":335},{"q":"مما يجمع قاتل النفس الواحدة وقاتل الناس جميعا:","o":["الجرأة على سفك الدم الحرام","تساوي مقدار الإثم والعقوبة","تساوي دركات العذاب في جهنم","أن كليهما لا تقبل له توبة"],"why":"«الثالث: أنهما سواء في الجرأة على سفك الدم الحرام»","pg":339}],"scene":{"t":"سؤال عن الصفات","x":"سأل طالب معلمه في درس التوحيد: أليس إثبات أن الله سميع بصير تشبيها له بالمخلوق؟ كيف يجيب المعلم؟","opts":["يبين أن التشبيه الحقيقي تشبيه المخلوق بالخالق في خصائص الإلهية لا إثبات صفات الكمال","يطلب منه ترك السؤال عن الصفات لأنها لا تفهم","يقول له إن هذه الصفات ألفاظ لا معاني لها"],"why":"«هذا هو التشبيه في الحقيقة، لا إثبات صفات الكمال التي وصف الله بها نفسه، ووصفه بها رسوله»","pg":313},"act":{"type":"class","t":"ما قدروا الله حق قدره","x":"نشاط صفي أو أسري يتأمل فيه المشاركون صور عدم تقدير الله حق قدره عند ابن القيم، ويستخرجون من كل صورة ظن السوء الذي فيها والصواب المقابل له.","items":["5 دقائق: قراءة قوله «وهو أن أعظم الذنوب عند الله إساءة الظن به» وقوله «فلو ظننتم به ما هو أهله».","10 دقائق: توزيع 6 بطاقات: من عبد معه غيره، من أنكر الرسالة، من نفى الصفات، من أنكر البعث، من هان عليه أمره، من استحيا من الناس ولم يستح من الله.","10 دقائق: تكتب كل مجموعة: ما الظن السيئ بالله الذي تتضمنه الصورة؟ وما الاسم أو الصفة التي تصحح هذا الظن؟","10 دقائق: تركيز على الصورتين الأخيرتين لأنهما تقعان من المسلمين، ونقاش: كيف تظهر في يومنا؟","5 دقائق: يكتب كل مشارك عبارة حسن ظن بالله يرددها هذا الأسبوع."]}},"alt":{}},"highlights":[{"x":"«فالشرك أظلم الظلم، والتوحيد أعدل العدل»","pg":296,"lv":"yth"},{"x":"«فالعمل الصالح هو الخالي من الرياء، المقيد بالسنة»","pg":303,"lv":"kid"},{"x":"«فالرياء كله شرك»","pg":303,"lv":"yth"},{"x":"«وأما الشرك في الإرادات والنيات، فذلك البحر الذي لا ساحل له، وقل من ينجو منه»","pg":312,"lv":"yth"},{"x":"«حقيقة الشرك هو التشبه بالخالق والتشبيه للمخلوق به»","pg":313,"lv":"adl"},{"x":"«ويستحيي من الناس، ولا يستحيي من الله. ويخشى الناس، ولا يخشى الله»","pg":326,"lv":"yth"},{"x":"«وما أوتي عبد بعد الإيمان أفضل من الفهم عن الله ورسوله»","pg":338,"lv":"yth"},{"x":"«فداء التعطيل هو الداء العضال الذي لا دواء له»","pg":330,"lv":"adl"}],"concepts":[{"term":"القسط","def":"«وأن يقوم الناس بالقسط، وهو العدل الذي قامت به السموات والأرض»","pg":296},{"term":"التعطيل","def":"«وهو ثلاثة أقسام: تعطيل المصنوع عن صانعه وخالقه. وتعطيل الصانع سبحانه عن كماله المقدس، بتعطيل أسمائه وأوصافه وأفعاله. وتعطيل معاملته عما يجب على العبد من حقيقة التوحيد»","pg":299},{"term":"الشرك في العبادة","def":"«فإنه يصدر ممن يعتقد أنه لا إله إلا الله، وأنه لا يضر وينفع ويعطي ويمنع إلا الله، وأنه لا إله غيره ولا رب سواه؛ ولكن لا يخلص لله في معاملته وعبوديته»","pg":301},{"term":"الإخلاص","def":"«والإخلاص أن يخلص لله في أقواله وأفعاله وإراداته ونيته»","pg":313},{"term":"العبودية","def":"«العبودية التي قامت على ساقين لا قوام لها بدونهما: غاية الحب مع غاية الذل. هذا تمام العبودية»","pg":315},{"term":"حقيقة الشرك","def":"«حقيقة الشرك هو التشبه بالخالق والتشبيه للمخلوق به»","pg":313}],"stories":[{"t":"فرعون إمام المعطلة","x":"ذكر ابن القيم شرك التعطيل «كشرك فرعون إذ قال: وما رب العالمين؟ وقال لهامان: ابن لي صرحا، لعلي أطلع إلى إله موسى، وإني لأظنه من الكاذبين»، وأنه أنكر على موسى ما أخبر به من أن ربه فوق السموات.","pg":299,"lv":"yth","hd":""},{"t":"الذي حاج إبراهيم في ربه","x":"قال: «فهذا جعل نفسه ندا لله، يحيي ويميت بزعمه كما يحيي الله ويميت. فألزمه إبراهيم أن طرد قولك أن تقدر على الإتيان بالشمس من غير الجهة التي يأتي الله بها منها»، وبين أن هذا ليس انتقالا كما زعم بعض أهل الجدل بل إلزام على طرد الدليل.","pg":301,"lv":"yth","hd":""},{"t":"عمرو بن لحي أول من غير دين إبراهيم","x":"«ولهذا رأى النبي ﷺ عمرو بن لحي يعذب أعظم العذاب في النار، لأنه أول من غير دين إبراهيم»، فمن سن سنة سيئة فاتبع عليها كان عليه إثم من اقتدى به.","pg":340,"lv":"adl","hd":"البخاري 3521 ومسلم 2856."},{"t":"ابن عباس وتوبة القاتل","x":"روى الترمذي عن ابن عباس حديث «يجيء المقتول بالقاتل يوم القيامة ناصيته ورأسه بيده، وأوداجه تشخب دما، يقول: يا رب سل هذا: فيم قتلني؟» فذكروا لابن عباس التوبة فتلا آية النساء ثم قال: «ما نسخت هذه الآية ولا بدلت، وأنى له التوبة!» وابن القيم يرجح بعد ذلك التحقيق الذي يجمع بين قبول التوبة وبقاء حق المقتول يعوضه الله.","pg":341,"lv":"adl","hd":"الترمذي 3029 وقال: حديث حسن، وقال ابن حجر: صحيح."},{"t":"ابن عمر ينظر إلى الكعبة","x":"عن نافع قال: نظر عبدالله بن عمر يوما إلى الكعبة فقال: «ما أعظمك وأعظم حرمتك! والمؤمن أعظم عند الله حرمة منك».","pg":342,"lv":"adl","hd":"الترمذي 2032 وقال: حسن غريب، وقال المحقق: تفرد به أوفى بن دلهم عن نافع، وروي مرفوعا ولا يصح.","weak":1},{"t":"المرأة والهرة","x":"«وإذا كانت امرأة قد دخلت النار في هرة حبستها حتى ماتت جوعا وعطشا، فرآها النبي ﷺ في النار، والهرة تخدشها في وجهها وصدرها؛ فكيف عقوبة من حبس مؤمنا حتى مات بغير جرم؟»","pg":344,"lv":"yth","hd":"سبق تخريجه عند المحقق في ص 75."}],"ready":true},{"k":"s9","t":"مداخل المعاصي الأربعة: اللحظات والخطرات واللفظات والخطوات","pgs":[348,376],"q":"من أين تدخل المعاصي على العبد، وكيف يحرس هذه الأبواب؟","essence":"احرس أربعة أبواب يسلم لك قلبك","kw":["اللحظات","الخطرات","اللفظات"],"daa":"إطلاق النظر، واسترسال الخواطر والأماني، وفضول الكلام، والمشي فيما لا ثواب فيه، وهي أكثر ما تدخل منه المعاصي على العبد.","dawa":"حراسة الأبواب الأربعة: غض البصر من أول النظرة، ودفع الخاطر قبل أن يستدعيه ويحادثه وملء القلب بالفكر النافع، وألا يتكلم إلا فيما يرجو فيه الربح، وألا ينقل قدمه إلا فيما يرجو ثوابه.","sections":[{"t":"فصل: وأكثر ما تدخل المعاصي على العبد من هذه الأبواب الأربعة","pg":348,"lv":"kid","key":"وأكثر ما تدخل المعاصي على العبد من هذه الأبواب الأربعة، فنذكر في كل واحد منها فصلا يليق به","p":[],"items":[]},{"t":"فأما اللحظات","pg":348,"lv":"adl","key":"فأما اللحظات فهي رائد الشهوة ورسولها، وحفظها أصل حفظ الفرج. فمن أطلق بصره أورده موارد الهلكات.","p":["والنظر أصل عامة الحوادث التي تصيب الإنسان، فإن النظرة تولد خطرة، ثم تولد الخطرة فكرة، ثم تولد الفكرة شهوة، ثم تولد الشهوة إرادة، ثم تقوى فتصير عزيمة جازمة، فيقع الفعل، ولا بد، ما لم يمنع منه مانع.","وفي هذا قيل: الصبر على غض البصر أيسر من الصبر على ألم ما بعده."],"items":[{"h":"حق الطريق","x":"وقال: «إياكم والجلوس على الطرقات». قالوا: يا رسول الله، مجالسنا ما لنا منها بد. قال: «فإن كنتم لابد فاعلين، فأعطوا الطريق حقه». قالوا: وما حقه؟ قال: «غض البصر، وكف الأذى، ورد السلام».","pg":350,"hd":"رواه البخاري 2465 ومسلم 2121"},{"h":"سلسلة النظرة","x":"فإن النظرة تولد خطرة، ثم تولد الخطرة فكرة، ثم تولد الفكرة شهوة، ثم تولد الشهوة إرادة، ثم تقوى فتصير عزيمة جازمة، فيقع الفعل","pg":350},{"h":"النظر يورث الحسرات","x":"ومن آفات النظر: أنه يورث الحسرات والزفرات والحرقات، فيرى العبد ما ليس قادرا عليه ولا صابرا عنه. وهذا من أعظم العذاب أن ترى ما لا صبر لك عن بعضه، ولا قدرة لك على بعضه.","pg":351},{"h":"السهم يرجع إلى الرامي","x":"ومن العجب أن لحظة الناظر سهم لا يصل إلى المنظور إليه حتى يتبوأ مكانا من قلب الناظر.","pg":352},{"h":"جرح على جرح","x":"وأعجب من ذلك أن النظرة تجرح القلب، فيتبعها جرحا على جرح، ثم لا يمنعه ألم الجراحة من استدعاء تكرارها.","pg":353},{"h":"حبس اللحظات","x":"وقد قيل: حبس اللحظات أيسر من دوام الحسرات.","pg":353}],"hd":"حديث «إياكم والجلوس على الطرقات» رواه البخاري 2465 ومسلم 2121. أما «لا تتبع النظرة النظرة» و«النظرة سهم مسموم» و«غضوا أبصاركم واحفظوا فروجكم» فضعفها المحقق، انظر weak.","weak":1},{"t":"وأما الخطرات","pg":353,"lv":"yth","key":"وأما الخطرات فشأنها أصعب، فإنها مبدأ الخير والشر، ومنها تتولد الإرادات والهمم والعزائم. فمن راعى خطراته ملك زمام نفسه، وقهر هواه. ومن غلبته خطراته فهواه ونفسه له أغلب، ومن استهان بالخطرات قادته قسرا إلى الهلكات.","p":["واعلم أن ورود الخاطر لا يضر، وإنما يضر استدعاؤه ومحادثته. فالخاطر كالمار على الطريق، فإن لم تستدعه وتركته مر وانصرف عنك، وإن استدعيته سحرك بحديثه وخدعه وغروره.","فالقلب لوح فارغ، والخواطر نقوش تنقش فيه، فكيف يليق بالعاقل أن تكون نقوش لوحه ما بين كذب، وغرور، وخدع، وأماني باطلة، وسراب لا حقيقة له؟"],"items":[{"h":"الخطرات تصير أماني","x":"ولا تزال الخطرات تتردد على القلب حتى تصير منى باطلة","pg":353},{"h":"الأماني الكاذبة","x":"وأخس الناس همة وأوضعهم نفسا من رضي من الحقائق بالأماني الكاذبة، واستجلبها لنفسه، وتحلى بها، وهي لعمر الله رؤوس أموال المفلسين، ومتاجر البطالين.","pg":354},{"h":"ثمرة الأماني","x":"وهي أضر شيء على الإنسان، وتتولد من العجز والكسل، وتولد التفريط والحسرة والندم.","pg":354},{"h":"أصول الخطرات الأربعة","x":"ثم الخطرات بعد أقسام تدور على أربعة أصول: خطرات يستجلب بها منافع دنياه. وخطرات يستدفع بها مضار دنياه. وخطرات يستجلب بها مصالح آخرته. وخطرات يستدفع بها مضار آخرته. فليحصر خطراته وأفكاره وهمومه في هذه الأقسام الأربعة.","pg":355},{"h":"عند التزاحم","x":"وإذا تزاحمت عليه الخطرات لتزاحم متعلقاتها قدم الأهم الذي يخشى فوته وأخر الذي ليس بأهم ولا يخاف فوته.","pg":355},{"h":"القاعدة الكبرى","x":"والتحكيم في هذا الباب للقاعدة الكبرى التي عليها مدار الشرع والقدر، وإليها مرجع الخلق والأمر، وهي إيثار أكبر المصلحتين وأعلاهما، وإن فاتت المصلحة التي هي دونها؛ والدخول في أدنى المفسدتين لدفع ما هو أكبر منها","pg":356},{"h":"أعلى الفكر","x":"وأعلى الفكر وأجلها وأنفعها ما كان لله والدار الآخرة.","pg":356},{"h":"الفكرة في آيات الله المنزلة","x":"أحدها: الفكرة في آياته المنزلة، وتعقلها، وفهم مراده منها. ولذلك أنزلها الله تعالى، لا لمجرد تلاوتها، بل التلاوة وسيلة.","pg":357},{"h":"الفكرة في آياته المشهودة","x":"الثاني: الفكرة في آياته المشهودة، والاعتبار بها، والاستدلال بها على أسمائه وصفاته، وحكمته وإحسانه، وبره وجوده.","pg":357},{"h":"الفكرة في آلائه","x":"الثالث: الفكرة في آلائه، وإحسانه، وإنعامه على خلقه بأصناف النعم، وسعة رحمته ومغفرته وحلمه.","pg":357},{"h":"الفكرة في عيوب النفس","x":"الرابع: الفكرة في عيوب النفس وآفاتها وفي عيوب العمل. وهذه الفكرة عظيمة النفع، وهي باب لكل خير، وتأثيرها في كسر النفس الأمارة.","pg":357},{"h":"الفكرة في واجب الوقت","x":"الخامس: الفكرة في واجب الوقت ووظيفته، وجمع الهم كله عليه. فالعارف ابن وقته، فإن أضاعه ضاعت عليه مصالحه كلها.","pg":358},{"h":"الوقت هو العمر","x":"فوقت الإنسان هو عمره في الحقيقة، وهو مادة حياته الأبدية في النعيم المقيم، ومادة معيشته الضنك في العذاب الأليم، وهو يمر أسرع من مر السحاب.","pg":358},{"h":"النفسان المتعاديتان","x":"وقد ركب الله سبحانه في الإنسان نفسا أمارة ونفسا مطمئنة، وهما متعاديتان، فكل ما خف على هذه ثقل على هذه، وكل ما التذت به هذه تألمت به الأخرى ... والحروب دول وسجال، والنصر مع الصبر.","pg":360},{"h":"خطأ من أخلى قلبه","x":"فإنهم أخلوا القلوب من أن يطرقها خاطر، فبقيت فارغة لا شيء فيها، فصادفها الشيطان خالية، فبذر فيها الباطل في قوالب أوهمهم أنها أعلى الأشياء وأشرفها","pg":362},{"h":"الكمال في امتلاء القلب","x":"إنما الكمال في امتلاء القلب والسر من الخواطر والإرادات والفكر في تحصيل مراضي الرب تعالى من العبد ومن الناس، والفكر في طرق ذلك والتوصل إليه.","pg":362},{"h":"تداخل العبادات","x":"وهذا عمر بن الخطاب كانت تتزاحم عليه الخواطر في مراضي الرب تعالى، فربما استعملها في صلاته، فكان يجهز جيشه وهو في صلاته، فيكون قد جمع بين الجهاد والصلاة.","pg":363,"hd":"أثر علقه البخاري في كتاب العمل في الصلاة، ووصله ابن أبي شيبة، وصحح إسناده ابن حجر"}]},{"t":"وأما اللفظات","pg":363,"lv":"adl","key":"وأما اللفظات، فحفظها بأن لا يخرج لفظة ضائعة، بل لا يتكلم إلا فيما يرجو فيه الربح والزيادة في دينه. فإذا أراد أن يتكلم بالكلمة نظر: هل فيها ربح وفائدة أم لا؟ فإن لم يكن فيها ربح أمسك عنها، وإن كان فيها ربح نظر: هل يفوته بها كلمة هي أربح منها، فلا يضيعها بهذه.","p":["وإذا أردت أن تستدل على ما في القلب، فاستدل عليه بحركة اللسان، فإنه يطلعك على ما في القلب، شاء صاحبه أم أبى.","والكلام أسيرك، فإذا خرج من فيك صرت أسيره. والله عند لسان كل قائل: ﴿مَا يَلْفِظُ مِن قَوْلٍ إِلَّا لَدَيْهِ رَقِيبٌ عَتِيدٌ﴾ [ق: 18]."],"items":[{"h":"القلوب كالقدور","x":"قال يحيى بن معاذ: القلوب كالقدور تغلي بما فيها، وألسنتها مغارفها. فانظر الرجل حين يتكلم، فإن لسانه يغترف لك مما في قلبه: حلو وحامض، وعذب وأجاج، وغير ذلك.","pg":364},{"h":"أكثر ما يدخل الناس النار","x":"وسئل ﷺ عن أكثر ما يدخل الناس النار، فقال: «الفم والفرج».","pg":365,"hd":"رواه الترمذي 2004 وقال: صحيح غريب، وصححه ابن حبان والحاكم"},{"h":"عجيبة اللسان","x":"ومن العجب أن الإنسان يهون عليه التحفظ والاحتراز من أكل الحرام والظلم والزنا والسرقة وشرب الخمر ومن النظر المحرم وغير ذلك، ويصعب عليه التحفظ من حركة لسانه","pg":366},{"h":"المتورع الذي يفري لسانه","x":"وكم ترى من رجل متورع عن الفواحش والظلم، ولسانه يفري في أعراض الأحياء والأموات، ولا يبالي ما يقول!","pg":366},{"h":"كلمة أحبطت العمل","x":"«قال رجل: والله لا يغفر الله لفلان. فقال الله عز وجل: من ذا الذي يتألى علي أني لا أغفر لفلان؟ قد غفرت له، وأحبطت عملك». فهذا العابد الذي قد عبد الله ما شاء أن يعبده، أحبطت هذه الكلمة الواحدة عمله كله!","pg":367,"hd":"رواه مسلم 2621"},{"h":"كلمة لا يلقي لها بالا","x":"«إن العبد ليتكلم بالكلمة من رضوان الله، لا يلقي لها بالا، يرفعه الله بها درجات. وإن العبد ليتكلم بالكلمة من سخط الله، لا يلقي لها بالا، يهوي بها في جهنم».","pg":368,"hd":"رواه البخاري 6478، ومسلم 2988 بنحوه"},{"h":"حديث بلال بن الحارث","x":"«إن أحدكم ليتكلم بالكلمة من رضوان الله، ما يظن أن تبلغ ما بلغت، فيكتب الله له بها رضوانه إلى يوم يلقاه. وإن أحدكم ليتكلم بالكلمة من سخط الله، ما يظن أن تبلغ ما بلغت، فيكتب الله له بها سخطه إلى يوم يلقاه».","pg":369,"hd":"رواه الترمذي 2319 وقال: حسن صحيح، وصححه ابن حبان والحاكم"},{"h":"فليقل خيرا أو ليصمت","x":"«من كان يؤمن بالله واليوم الآخر فليقل خيرا أو ليصمت».","pg":370,"hd":"رواه البخاري 6475 ومسلم 47"},{"h":"ما أخوف ما تخاف علي","x":"قلت: يا رسول الله، قل لي في الإسلام قولا لا أسأل عنه أحدا بعدك. قال: «قل: آمنت بالله، ثم استقم». قلت: يا رسول الله ما أخوف ما تخاف علي؟ فأخذ بلسان نفسه، ثم قال: «هذا».","pg":371,"hd":"رواه مسلم 38 إلى قوله «ثم استقم»، وقال المؤلف: والحديث صحيح"},{"h":"محاسبة السلف","x":"وقد كان السلف يحاسب أحدهم نفسه في قوله: يوم حار، ويوم بارد.","pg":373},{"h":"أيسر الحركات وأضرها","x":"وأيسر حركات الجوارح حركة اللسان، وهي أضرها على العبد.","pg":374},{"h":"هذا أوردني الموارد","x":"وكان الصديق رضي الله عنه يمسك بلسانه ويقول: هذا أوردني الموارد.","pg":374},{"h":"آفتا اللسان","x":"وفي اللسان آفتان عظيمتان، إن خلص من إحداهما لم يخلص من الأخرى: آفة الكلام، وآفة السكوت. وقد يكون كل منهما أعظم إثما من الأخرى في وقتها. فالساكت عن الحق شيطان أخرس عاص لله مراء مداهن إذا لم يخف على نفسه، والمتكلم بالباطل شيطان ناطق عاص لله.","pg":375},{"h":"أهل الوسط","x":"وأهل الوسط، وهم أهل الصراط المستقيم، كفوا ألسنتهم عن الباطل، وأطلقوها فيما يعود عليهم نفعه في الآخرة.","pg":375},{"h":"حسنات أمثال الجبال","x":"وإن العبد ليأتي يوم القيامة بحسنات أمثال الجبال، فيجد لسانه قد هدمها عليه كلها؛ ويأتي بسيئات أمثال الجبال، فيجد لسانه قد هدمها من كثرة ذكر الله وما اتصل به.","pg":375}],"hd":"«الفم والفرج»: الترمذي 2004 صحيح غريب. «إن العبد ليتكلم بالكلمة»: البخاري 6478. «فليقل خيرا أو ليصمت»: البخاري 6475 ومسلم 47. حديث معاذ «وهل يكب الناس» تعقب ابن رجب تصحيحه بالانقطاع، وأحاديث «لا يستقيم إيمان عبد» و«كلام ابن آدم عليه لا له» و«فلعله تكلم فيما لا يعنيه» ضعيفة، و«من حسن إسلام المرء» الراجح إرساله، انظر weak.","weak":1},{"t":"وأما الخطوات","pg":375,"lv":"kid","key":"وأما الخطوات، فحفظها بأن لا ينقل قدمه إلا فيما يرجو ثوابه، فإن لم يكن في خطاه مزيد ثواب، فالقعود عنها خير له. ويمكنه أن يستخرج من كل مباح يخطو إليه قربة ينويها لله، فتقع خطاه قربة.","p":["ولما كانت العثرة عثرتين: عثرة الرجل، وعثرة اللسان جاءت إحداهما قرينة الأخرى في قوله تعالى: ﴿وَعِبَادُ الرَّحْمَٰنِ الَّذِينَ يَمْشُونَ عَلَى الْأَرْضِ هَوْنًا وَإِذَا خَاطَبَهُمُ الْجَاهِلُونَ قَالُوا سَلَامًا﴾ [الفرقان: 63]، فوصفهم بالاستقامة في لفظاتهم وخطواتهم، كما جمع بين اللحظات والخطرات في قوله: ﴿يَعْلَمُ خَائِنَةَ الْأَعْيُنِ وَمَا تُخْفِي الصُّدُورُ﴾ [غافر: 19]."],"items":[]}],"lv":{"kid":{"show":true,"title":"أحرس أبواب قلبي الأربعة","intro":"قلبك مثل بيت جميل له أربعة أبواب: عينك، وفكرك، ولسانك، وقدمك. أكثر ما يدخل منه الخطأ إلى القلب هو هذه الأبواب، فإذا حرستها بقي قلبك نظيفا مضيئا، وإذا تركتها مفتوحة دخل منها ما يتعبك ويحزنك.","points":["عيني باب: أصرفها عما لا يرضي الله، والصبر في أول النظرة أسهل من التعب بعدها","فكري باب: إذا مرت بي فكرة سيئة تركتها تمر ولا أجلس أحادثها","لساني باب: قبل أن أتكلم أسأل نفسي: هل في كلامي خير وفائدة؟","قدمي باب: لا أمشي إلا إلى ما يحبه الله، وأنوي الخير حتى في مشيي إلى المدرسة واللعب","إذا جلست في الطريق أعطيته حقه: أغض بصري، ولا أوذي أحدا، وأرد السلام"],"quote":{"x":"فالخاطر كالمار على الطريق، فإن لم تستدعه وتركته مر وانصرف عنك","pg":360},"quiz":[{"q":"كم بابا ذكر ابن القيم أن المعاصي تدخل منها على العبد؟","o":["أربعة أبواب","ثلاثة أبواب","خمسة أبواب","سبعة أبواب"],"why":"وأكثر ما تدخل المعاصي على العبد من هذه الأبواب الأربعة","pg":348},{"q":"ماذا أفعل بالفكرة السيئة إذا مرت بقلبي؟","o":["أتركها تمر ولا أحادثها","أجلس معها وأفكر فيها","أحكيها لكل أصدقائي فورا","أكتبها كي لا أنساها"],"why":"واعلم أن ورود الخاطر لا يضر، وإنما يضر استدعاؤه ومحادثته. فالخاطر كالمار على الطريق، فإن لم تستدعه وتركته مر وانصرف عنك","pg":360},{"q":"قبل أن أتكلم بكلمة، ماذا أسأل نفسي؟","o":["هل فيها ربح وفائدة؟","هل سيضحك منها الناس؟","هل هي كلمة طويلة؟","هل قالها أحد قبلي؟"],"why":"فإذا أراد أن يتكلم بالكلمة نظر: هل فيها ربح وفائدة أم لا؟ فإن لم يكن فيها ربح أمسك عنها","pg":363},{"q":"ما حق الطريق الذي ذكره النبي صلى الله عليه وسلم؟","o":["غض البصر وكف الأذى ورد السلام","الجلوس فيه طويلا مع الأصحاب","الإسراع في المشي ورفع الصوت","النظر طويلا إلى كل من يمر أمامنا"],"why":"قالوا: وما حقه؟ قال: «غض البصر، وكف الأذى، ورد السلام».","pg":350}],"scene":{"t":"في ساحة المدرسة","x":"كان عمر يلعب مع زملائه، فجاء طالب جديد، فبدأ أحدهم يسخر من شكله بكلمات جارحة، ونادى الجميع ليضحكوا معه.","opts":["يمسك لسانه عن السخرية ويقول للطالب الجديد كلمة طيبة","يضحك معهم حتى لا يغضب منه صاحبه","يسكت ثم يحكي ما حدث لأهله وهو يضحك"],"why":"«من كان يؤمن بالله واليوم الآخر فليقل خيرا أو ليصمت».","pg":370,"hd":"رواه البخاري 6475 ومسلم 47"},"act":{"type":"guard","t":"حارس الأبواب الأربعة","x":"يرسم الطالب قلعة لها أربعة أبواب، ويكتب على كل باب اسمه، ويكتب بجانبه الحارس الذي يحميه. وفي آخر كل يوم من أيام الأسبوع يلون الباب الذي نجح في حراسته، ويضع نجمة على الباب الذي يحتاج أن يقويه غدا.","items":[{"h":"باب العين","x":"أصرف نظري عما لا يحل في الشارع والشاشة"},{"h":"باب الفكر","x":"أترك الفكرة السيئة تمر، وأشغل نفسي بشيء نافع"},{"h":"باب اللسان","x":"أقول خيرا أو أسكت، وأزن الكلمة قبل أن أقولها"},{"h":"باب القدم","x":"أنوي بمشيي إلى المدرسة والمسجد طاعة الله"}]}},"yth":{"show":true,"title":"أبواب القلب الأربعة: من هنا تبدأ المعركة","intro":"كل ذنب كبير بدأ صغيرا من أحد أربعة أبواب: نظرة، أو خاطرة، أو كلمة، أو خطوة. ابن القيم يكشف لك كيف تتحول النظرة إلى فعل خطوة بعد خطوة، ويعطيك مفاتيح الحراسة لكل باب حتى تملك زمام نفسك بدل أن تملكك.","points":["النظرة تولد خطرة، ثم فكرة، ثم شهوة، ثم إرادة، ثم عزيمة، فاقطع السلسلة من أولها","الخاطر لا يضرك مروره، إنما يضرك أن تستدعيه وتجلس تحادثه","الأماني الكاذبة رؤوس أموال المفلسين، فاستبدلها بعمل حقيقي في وقتك","لسانك يكشف ما في قلبك، والكلمة الواحدة قد ترفعك درجات أو تهوي بك","خطوتك في المباح تصير عبادة إذا نويت بها وجه الله"],"quote":{"x":"حبس اللحظات أيسر من دوام الحسرات","pg":353},"quiz":[{"q":"ما ترتيب ما تولده النظرة كما ذكره ابن القيم؟","o":["خطرة ثم فكرة ثم شهوة ثم إرادة","فكرة ثم خطرة ثم إرادة ثم شهوة","شهوة ثم خطرة ثم فكرة ثم إرادة","إرادة ثم شهوة ثم فكرة ثم خطرة"],"why":"فإن النظرة تولد خطرة، ثم تولد الخطرة فكرة، ثم تولد الفكرة شهوة، ثم تولد الشهوة إرادة، ثم تقوى فتصير عزيمة جازمة","pg":350},{"q":"ما الذي يضر من الخواطر؟","o":["استدعاؤه ومحادثته","وروده على القلب","مروره ثم انصرافه","نسيانه بعد مروره"],"why":"واعلم أن ورود الخاطر لا يضر، وإنما يضر استدعاؤه ومحادثته.","pg":360},{"q":"بماذا وصف ابن القيم الأماني الكاذبة؟","o":["رؤوس أموال المفلسين","زاد المجتهدين الصادقين","أول طريق الناجحين","راحة النفس المطمئنة"],"why":"وهي لعمر الله رؤوس أموال المفلسين، ومتاجر البطالين.","pg":354},{"q":"ما الآفتان العظيمتان في اللسان عند ابن القيم؟","o":["آفة الكلام وآفة السكوت","آفة الجهر وآفة الإسرار","آفة الضحك وآفة البكاء","آفة الإطالة وآفة الإيجاز"],"why":"وفي اللسان آفتان عظيمتان، إن خلص من إحداهما لم يخلص من الأخرى: آفة الكلام، وآفة السكوت.","pg":375},{"q":"كيف تصير خطواتك في المباح قربة؟","o":["بأن تنويها لله","بأن تسرع فيها","بأن تكثر منها","بأن تمشيها وحدك"],"why":"ويمكنه أن يستخرج من كل مباح يخطو إليه قربة ينويها لله، فتقع خطاه قربة.","pg":375}],"scene":{"t":"منتصف الليل والهاتف في يده","x":"يتصفح سعد هاتفه قبل النوم، فتظهر له صورة لا تحل، ثم يقترح عليه التطبيق صورا مثلها. يقول في نفسه: نظرة واحدة لن تضر.","opts":["يصرف بصره فورا ويغلق التطبيق ويشغل نفسه بنافع حتى ينام","ينظر قليلا ثم يتوقف وهو واثق من قدرته على الترك","يحفظ الصورة ليقرر لاحقا ماذا يفعل بها"],"why":"وفي هذا قيل: الصبر على غض البصر أيسر من الصبر على ألم ما بعده.","pg":350},"act":{"type":"plan","t":"خطة حراسة الأبواب لأسبوع","x":"يختار الشاب خطوة واحدة على الأقل لكل باب، ويكتبها في دفتره الخاص، ويراجع نفسه كل ليلة: أي باب حرسته اليوم؟ وأي باب دخل منه ما لا أحب؟","items":["باب العين: أصرف بصري من أول نظرة ولا أتبعها بأخرى","باب العين: ألغي متابعة الحسابات التي تعرض ما لا يحل","باب الفكر: إذا جاء خاطر سيئ لا أحادثه، وأنتقل فورا إلى عمل نافع","باب الفكر: أحصر همومي في أربعة: نفع دنياي، ودفع ضرها، ونفع آخرتي، ودفع ضرها","باب الفكر: أحدد كل صباح واجب وقتي وأجمع همي عليه","باب اللسان: قبل أي كلمة أسأل: هل فيها ربح؟ وهل توجد كلمة أربح منها؟","باب اللسان: لا أشارك في غيبة ولا سخرية، وأقول الحق بأدب","باب القدم: أنوي بخروجي للدراسة والرياضة طاعة الله وقوة لدينه"]}},"adl":{"show":true,"title":"مداخل المعاصي الأربعة وفقه حراستها","intro":"يجعل ابن القيم هذه الفصول مقدمة بين يدي تحريم الفواحش، فيبين أن أكثر ما تدخل المعاصي على العبد من أربعة أبواب، ويرسم سلسلة تولد الفعل من النظرة، ويؤسس لتدبير الخواطر بقاعدة الموازنة بين المصالح والمفاسد، ويحذر من آفتي الكلام والسكوت، ثم يجعل الخطوات المباحة قربات بالنية. وهي مادة تربوية متكاملة للمعلم والأب.","points":["اللحظات رائد الشهوة، وحفظها أصل حفظ الفرج، والنظر أصل عامة الحوادث","الخطرات أصعب الأبواب لأنها مبدأ الخير والشر، والعلاج ألا يستدعيها ولا يحادثها، وأن يملأ القلب بالفكر النافع لا أن يخليه","يحكم في تزاحم الخواطر بالقاعدة الكبرى: إيثار أعلى المصلحتين، ودفع أكبر المفسدتين","اللسان أيسر الجوارح حركة وأضرها، وأهل الوسط يكفونه عن الباطل ويطلقونه فيما ينفع","الخطوات تحفظ بألا ينقل قدمه إلا فيما يرجو ثوابه، ويقلب المباح قربة بالنية"],"quote":{"x":"إنما الكمال في امتلاء القلب والسر من الخواطر والإرادات والفكر في تحصيل مراضي الرب تعالى من العبد ومن الناس","pg":362},"quiz":[{"q":"لماذا كان شأن الخطرات أصعب من بقية الأبواب؟","o":["لأنها مبدأ الخير والشر ومنها تتولد الإرادات","لأنها لا تدخل إلا على القلب الفارغ من العلم والذكر","لأن صاحبها لا يقدر على دفعها بحال من الأحوال","لأنها أكثر الأبواب وقوعا في يوم المسلم وليلته"],"why":"وأما الخطرات فشأنها أصعب، فإنها مبدأ الخير والشر، ومنها تتولد الإرادات والهمم والعزائم.","pg":353},{"q":"بم يحكم العاقل إذا تزاحمت عليه الخطرات ولم يمكن الجمع؟","o":["بإيثار أعلى المصلحتين ودفع أكبر المفسدتين","بتقديم ما خطر أولا على ما خطر بعده","بتقديم أخف الأمرين على النفس دائما","بترك الأمرين معا حتى يتبين له وجه الصواب"],"why":"وهي إيثار أكبر المصلحتين وأعلاهما، وإن فاتت المصلحة التي هي دونها؛ والدخول في أدنى المفسدتين لدفع ما هو أكبر منها","pg":356},{"q":"ما خطأ من أخلى قلبه من كل خاطر طلبا للكشف؟","o":["صادفه الشيطان خاليا فبذر فيه الباطل","أنه ترك محاسبة نفسه على الكلام","أنه شغل قلبه بمصالح الدنيا عن الآخرة","أنه جمع بين عبادتين في وقت واحد"],"why":"فبقيت فارغة لا شيء فيها، فصادفها الشيطان خالية، فبذر فيها الباطل في قوالب أوهمهم أنها أعلى الأشياء وأشرفها","pg":362},{"q":"كيف وصف ابن القيم الساكت عن الحق إذا لم يخف على نفسه؟","o":["شيطان أخرس عاص لله مراء مداهن","حكيم آثر السلامة لنفسه فلا يلام","معذور لأن السكوت أسلم في كل حال","أفضل من المتكلم بالحق في كل وقت"],"why":"فالساكت عن الحق شيطان أخرس عاص لله مراء مداهن إذا لم يخف على نفسه، والمتكلم بالباطل شيطان ناطق عاص لله.","pg":375},{"q":"ما الذي استنبطه ابن القيم من آية عباد الرحمن ﴿يمشون على الأرض هونا﴾؟","o":["وصفهم بالاستقامة في لفظاتهم وخطواتهم","وصفهم بحفظ اللحظات والخطرات معا","تفضيل المشي على الكلام في كل حال","تفضيل الصمت التام على كل كلام ولو نافعا"],"why":"ولما كانت العثرة عثرتين: عثرة الرجل، وعثرة اللسان جاءت إحداهما قرينة الأخرى في قوله تعالى ... فوصفهم بالاستقامة في لفظاتهم وخطواتهم","pg":376}],"scene":{"t":"طالب يخاف من أفكاره","x":"بعد الحصة جاء طالب إلى معلمه خائفا، يشكو أن أفكارا سيئة تهجم عليه فجأة، ويظن أنه آثم بمجرد مرورها، حتى صار يكره نفسه.","opts":["يطمئنه أن ورود الخاطر لا يضر، ويعلمه ألا يستدعيه، وأن يملأ قلبه بالفكر النافع","يخبره أن هذه الأفكار دليل فساد قلبه ويخوفه من العقوبة","ينصحه أن يفرغ ذهنه من كل فكرة حتى لا يبقى فيه شيء"],"why":"واعلم أن ورود الخاطر لا يضر، وإنما يضر استدعاؤه ومحادثته.","pg":360},"act":{"type":"class","t":"حصة صفية: حارس الأبواب الأربعة","x":"نشاط صفي مدته 40 دقيقة يحول الفصل إلى خريطة عملية للأبواب الأربعة، مع مراعاة أن الفئة المستهدفة تحدد عمق الأمثلة.","items":[{"h":"التهيئة 5 دقائق","x":"يكتب المعلم على السبورة: من أين يدخل اللص إلى البيت؟ ثم يربطها بقول ابن القيم: أكثر ما تدخل المعاصي على العبد من هذه الأبواب الأربعة."},{"h":"السلسلة 10 دقائق","x":"يعرض بطاقات: نظرة، خطرة، فكرة، شهوة، إرادة، عزيمة، فعل، ويطلب من الطلاب ترتيبها، ثم يسألهم: أين أسهل موضع لقطع السلسلة؟"},{"h":"المجموعات 15 دقيقة","x":"يقسم الصف أربع مجموعات، لكل مجموعة باب، تستخرج من نص الكتاب الخطر وطرق الحفظ، وتكتب موقفا واقعيا وعلاجه."},{"h":"العرض 7 دقائق","x":"تعرض كل مجموعة بابها في دقيقتين، ويعلق المعلم بالقاعدة الكبرى في الموازنة بين المصالح والمفاسد."},{"h":"الختام 3 دقائق","x":"يكتب كل طالب في دفتره الخاص: الباب الذي أحتاج أن أحرسه أكثر هذا الأسبوع هو ... وطريقتي في حراسته هي ..."}]}},"alt":{}},"highlights":[{"x":"فالخاطر كالمار على الطريق، فإن لم تستدعه وتركته مر وانصرف عنك","pg":360,"lv":"kid"},{"x":"والكلام أسيرك، فإذا خرج من فيك صرت أسيره","pg":374,"lv":"kid"},{"x":"وأيسر حركات الجوارح حركة اللسان، وهي أضرها على العبد","pg":374,"lv":"kid"},{"x":"حبس اللحظات أيسر من دوام الحسرات","pg":353,"lv":"yth"},{"x":"فمن راعى خطراته ملك زمام نفسه، وقهر هواه","pg":353,"lv":"yth"},{"x":"وهي لعمر الله رؤوس أموال المفلسين، ومتاجر البطالين","pg":354,"lv":"yth"},{"x":"فوقت الإنسان هو عمره في الحقيقة","pg":358,"lv":"yth"},{"x":"والحروب دول وسجال، والنصر مع الصبر","pg":360,"lv":"adl"}],"concepts":[{"term":"اللحظات","def":"فهي رائد الشهوة ورسولها، وحفظها أصل حفظ الفرج","pg":348},{"term":"الخطرات","def":"فإنها مبدأ الخير والشر، ومنها تتولد الإرادات والهمم والعزائم","pg":353},{"term":"الأماني","def":"وهي قوت النفس الفارغة التي قد قنعت من الوصل بزورة الخيال، ومن الحقائق بكواذب الآمال","pg":354},{"term":"القاعدة الكبرى","def":"وهي إيثار أكبر المصلحتين وأعلاهما، وإن فاتت المصلحة التي هي دونها؛ والدخول في أدنى المفسدتين لدفع ما هو أكبر منها","pg":356},{"term":"القلب والخواطر","def":"فالقلب لوح فارغ، والخواطر نقوش تنقش فيه","pg":361},{"term":"تداخل العبادات","def":"وهذا من باب تداخل العبادات في العبادة الواحدة. وهو باب عزيز شريف لا يعرفه إلا صادق الطلب، متضلع من العلم، عالي الهمة","pg":363},{"term":"أهل الوسط","def":"كفوا ألسنتهم عن الباطل، وأطلقوها فيما يعود عليهم نفعه في الآخرة","pg":375}],"stories":[{"t":"عمر يجهز جيشه وهو في الصلاة","x":"كانت تتزاحم على عمر بن الخطاب الخواطر في مراضي الرب، فربما استعملها في صلاته، فكان يجهز جيشه وهو يصلي، فيجمع بين الجهاد والصلاة.","pg":363,"lv":"yth","hd":"أثر علقه البخاري، ووصله ابن أبي شيبة، وصحح إسناده ابن حجر"},{"t":"العابد الذي أحبطت عمله كلمة","x":"قال رجل: والله لا يغفر الله لفلان، فقال الله: من ذا الذي يتألى علي أني لا أغفر لفلان؟ قد غفرت له وأحبطت عملك. قال ابن القيم: هذا العابد أحبطت الكلمة الواحدة عمله كله.","pg":367,"lv":"adl","hd":"رواه مسلم 2621","weak":1},{"t":"الصديق يمسك بلسانه","x":"كان أبو بكر الصديق رضي الله عنه يمسك بلسانه ويقول: هذا أوردني الموارد.","pg":374,"lv":"kid","hd":"أثر تقدم تخريجه عند المحقق ص 91"},{"t":"يوم حار ويوم بارد","x":"كان السلف يحاسب أحدهم نفسه حتى في قوله: يوم حار، ويوم بارد.","pg":373,"lv":"kid"},{"t":"موقوف على كلمة","x":"رئي بعض الأكابر من أهل العلم في النوم، فسئل عن حاله، فقال: أنا موقوف على كلمة قلتها: قلت: ما أحوج الناس إلى غيث! فقيل لي: وما يدريك؟ أنا أعلم بمصلحة عبادي.","pg":373,"lv":"yth","hd":"منام ذكره المؤلف، وعين المحقق أنه الجنيد"},{"t":"كلمة بغير خطام","x":"قال بعض الصحابة لخادمه يوما: هات السفرة نعبث بها، ثم قال: أستغفر الله، ما أتكلم بكلمة إلا وأنا أخطمها وأزمها، إلا هذه الكلمة خرجت مني بغير خطام ولا زمام.","pg":373,"lv":"adl","hd":"أثر عن شداد بن أوس، رواه أحمد وابن المبارك، ورواية الجماعة أرجح لكن فيها انقطاع","weak":1}],"ready":true},{"k":"s10","t":"حفظ الفرج وعلاج العشق: الطريق الأول المانع من حصوله","pgs":[376,540],"q":"لماذا عظمت مفسدة الفواحش، وكيف يمنع العبد داء العشق قبل أن يحصل في قلبه؟","essence":"أغلق باب العين واملأ القلب بالأعلى","kw":["العفة","غض البصر","حسن الخاتمة","الإخلاص","يوسف"],"daa":"الفواحش وداء العشق الذي يفسد القلب والعقل، ويجلب الهم والذل، وقد يحول بين العبد وحسن الخاتمة.","dawa":"حسم مادة الداء قبل حصولها بأمرين: غض البصر بفوائده العشر، واشتغال القلب بما يصده عنه من خوف مقلق أو حب مزعج، مع بصيرة صحيحة وقوة عزم وصبر.","sections":[{"t":"فصل: وهذا كله ذكرناه مقدمة بين يدي تحريم الفواحش ووجوب حفظ الفرج","pg":376,"lv":"adl","key":"وهذا كله ذكرناه مقدمة بين يدي تحريم الفواحش ووجوب حفظ الفرج.","p":["وقد قال النبي ﷺ: «أكثر ما يدخل الناس النار: الفم والفرج»."],"items":[],"hd":"رواه الترمذي 2004 وقال: صحيح غريب، وصححه ابن حبان والحاكم","weak":1},{"t":"عظم مفسدة الزنى","pg":376,"lv":"adl","key":"ومفسدة الزنا مناقضة لصلاح العالم","p":["وبدأ رسول الله ﷺ بالأكثر وقوعا، ثم بالذي يليه. فالزنى أكثر وقوعا من قتل النفس، وقتل النفس أكثر وقوعا من الردة. وأيضا فإنه انتقال من الأكبر إلى ما هو أكبر منه.","وفي هذه الكبيرة خراب الدنيا والدين"],"items":[{"h":"حديث الثلاث","x":"وفي الصحيحين عنه ﷺ: «لا يحل دم امرئ مسلم إلا بإحدى ثلاث: الثيب الزاني، والنفس بالنفس، والتارك لدينه المفارق للجماعة».","pg":376,"hd":"رواه البخاري 6878 ومسلم 1676"},{"h":"أثره في القلب","x":"ومن خاصيته أيضا: أنه يشتت القلب، ويمرضه إن لم يمته. ويجلب الهم والحزن والخوف، ويباعد صاحبه من الملك، ويقرب منه الشيطان.","pg":378},{"h":"أثره في العيش","x":"ومن خاصيته: أنه يوجب الفقر، ويقصر العمر، ويكسو صاحبه سواد الوجه وثوب المقت بين الناس.","pg":378},{"h":"غيرة الله","x":"وفي الصحيحين أيضا عنه ﷺ: «إن الله يغار، وإن المؤمن يغار، وغيرة الله أن يأتي العبد ما حرم عليه».","pg":379,"hd":"رواه البخاري 5223 ومسلم 2761"},{"h":"لا أحد أغير من الله","x":"وفي الصحيحين عنه ﷺ: «لا أحد أغير من الله، من أجل ذلك حرم الفواحش ما ظهر منها وما بطن».","pg":379,"hd":"متفق عليه، تقدم تخريجه عند المحقق ص 164"},{"h":"خطبة الكسوف","x":"وفي ذكر هذه الكبيرة بخصوصها عقيب صلاة الكسوف سر بديع لمن تأمله.","pg":379,"hd":"حديث خطبة الكسوف متفق عليه، تقدم تخريجه ص 164"},{"h":"من أشراط الساعة","x":"وظهور الزنى من أمارات خراب العالم، وهو من أشراط الساعة","pg":379,"hd":"حديث أنس في أشراط الساعة رواه البخاري 80 و81 ومسلم 2671"},{"h":"سنة الله عند ظهوره","x":"وقد جرت سنة الله سبحانه في خلقه أنه عند ظهور الزنى يغضب الله سبحانه، ويشتد غضبه، فلا بد أن يؤثر غضبه في الأرض عقوبة.","pg":380}],"note":"خصائص حد الزنى الثلاث وسبب الرأفة بالزاني (ص 380 إلى 382) أحكام حدية لم تنقل نصا، ويكفي الراشد فيها خلاصة: أن الشرع شدد في هذه العقوبة، ونهى أن تمنع الرأفة من إقامة أمر الله، وجعلها بمشهد من المؤمنين."},{"t":"التوبة تمحو كل ذنب","pg":384,"lv":"adl","key":"وقد ضمن الله سبحانه لمن تاب من الشرك وقتل النفس والزنى أنه يبدل سيئاته حسنات. وهذا حكم عام لكل تائب من كل ذنب.","p":[],"items":[{"h":"آية الزمر","x":"وقد قال تعالى: ﴿قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَىٰ أَنفُسِهِمْ لَا تَقْنَطُوا مِن رَّحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ﴾ [الزمر: 53]، فلا يخرج من هذا العموم ذنب واحد. ولكن هذا في حق التائبين خاصة.","pg":385}],"note":"ورد هذا التقرير في سياق مسألة حساسة (ص 383 إلى 385) فنقلت منه الجملة العامة في التوبة فقط."},{"t":"سوء الخاتمة وحسنها","pg":386,"lv":"yth","key":"وإذا نظرت إلى كثير من المحتضرين وجدتهم يحال بينهم وبين حسن الخاتمة، عقوبة لهم على أعمالهم السيئة.","p":["وهذا من أعظم الفقه: أن يخاف الرجل أن تخذله ذنوبه عند الموت، فتحول بينه وبين الخاتمة بالحسنى."],"items":[{"h":"أسباب سوء الخاتمة","x":"قال الحافظ أبو محمد عبدالحق بن عبدالرحمن الإشبيلي رحمه الله: «واعلم أن لسوء الخاتمة، أعاذنا الله منها، أسبابا، ولها طرق وأبواب، أعظمها: الإكباب على الدنيا، والإعراض عن الأخرى، والإقدام والجرأة على معاصي الله عز وجل».","pg":386},{"h":"لمن لا تكون","x":"«واعلم أن سوء الخاتمة، أعاذنا الله منها، لا تكون لمن استقام ظاهره، وصلح باطنه، ما سمع بهذا ولا علم به، ولله الحمد. وإنما تكون لمن له فساد في العقيدة، أو إصرار على الكبائر، أو إقدام على العظائم».","pg":391},{"h":"بكاء سفيان","x":"ولقد بكى سفيان الثوري ليلة إلى الصباح، فلما أصبح قيل له: كل هذا خوفا من الذنوب؟ فأخذ تبنة من الأرض، وقال: الذنوب أهون من هذا، وإنما أبكي من خوف الخاتمة.","pg":390},{"h":"أبو الدرداء عند الاحتضار","x":"وقد ذكر الإمام أحمد عن أبي الدرداء أنه لما احتضر جعل يغمى عليه، ثم يفيق ويقرأ: ﴿وَنُقَلِّبُ أَفْئِدَتَهُمْ وَأَبْصَارَهُمْ كَمَا لَمْ يُؤْمِنُوا بِهِ أَوَّلَ مَرَّةٍ وَنَذَرُهُمْ فِي طُغْيَانِهِمْ يَعْمَهُونَ﴾ [الأنعام: 110]. فمن هذا خاف السلف من الذنوب أن تكون حجابا بينهم وبين الخاتمة بالحسنى.","pg":390,"hd":"أثر قال المحقق: ثابت صحيح"}]},{"t":"فصل: مفسدة اللواط وعقوبته وما ألحق به من المسائل","pg":392,"lv":"adl","key":"","summary":"يقرر ابن القيم في ص 392 إلى 413 أن هذه الفاحشة من أعظم المفاسد، ويعرض خلاف الفقهاء في عقوبتها وأدلتهم والجواب عنها، ويستدل بما قص الله من خبر قوم لوط، ويلحق بها مسائل فقهية أخرى. وقد اكتفينا بهذه الخلاصة دون نقل نصوص هذه الفصول.","p":[],"items":[]},{"t":"فصل: فإن قيل: وهل مع ذلك كله من دواء لهذا الداء العضال؟","pg":413,"lv":"yth","key":"والكلام في دواء هذا الداء من طريقين: أحدهما: حسم مادته قبل حصولها. والثاني: قلعها بعد نزولها. وكلاهما يسير على من يسره الله عليه، ومتعذر على من لم يعنه، فإن أزمة الأمور بيديه.","p":["قيل: نعم، الجواب من رأس «وما أنزل الله سبحانه من داء إلا أنزل له دواء. علمه من علمه، وجهله من جهله»."],"items":[],"hd":"قال المحقق: تقدم في أول الكتاب، وأصله في البخاري 5678"},{"t":"فأما الطريق المانع من حصول هذا الداء، فأمران: أحدهما غض البصر","pg":415,"lv":"adl","key":"وفي غض البصر عدة منافع، وهو بعض أجزاء هذا الدواء النافع.","p":["والله سبحانه يجزي العبد على عمله بما هو من جنس عمله، ومن ترك لله شيئا عوضه الله خيرا منه، فإذا غض بصره عن محارم الله عوضه الله بأن يطلق نور بصيرته عوضا عن حبسه بصره لله"],"items":[{"h":"الأولى: امتثال الأمر","x":"أحدها: أنه امتثال لأمر الله الذي هو غاية سعادة العبد في معاشه ومعاده، فليس للعبد في دنياه وآخرته أنفع من امتثال أوامر ربه تبارك وتعالى.","pg":415},{"h":"الثانية: حماية القلب","x":"الثانية: أنه يمتنع من وصول أثر السهم المسموم الذي لعل فيه هلاكه إلى قلبه.","pg":415},{"h":"الثالثة: الأنس بالله","x":"الثالثة: أنه يورث القلب أنسا بالله وجمعية على الله، فإن إطلاق البصر يفرق القلب، ويشتته، ويبعده من الله. وليس على العبد شيء أضر من إطلاق البصر، فإنه يوقع الوحشة بين العبد وبين ربه.","pg":416},{"h":"الرابعة: قوة القلب وفرحه","x":"الرابعة: أنه يقوي القلب ويفرحه، كما أن إطلاق البصر يضعفه ويحزنه.","pg":416},{"h":"الخامسة: نور القلب","x":"الخامسة: أنه يكسب القلب نورا، كما أن إطلاقه يكسبه ظلمة. ولهذا ذكر سبحانه آية النور عقيب الأمر بغض البصر","pg":416},{"h":"السادسة: الفراسة الصادقة","x":"السادسة: أنه يورثه فراسة صادقة يميز بها بين المحق والمبطل، والصادق والكاذب.","pg":417},{"h":"السابعة: الثبات والشجاعة","x":"السابعة: أنه يورث القلب ثباتا وشجاعة وقوة، فيجمع الله له بين سلطان البصيرة والحجة وسلطان القدرة والقوة، كما في الأثر: الذي يخالف هواه يفرق الشيطان من ظله.","pg":419},{"h":"الثامنة: سد مدخل الشيطان","x":"الثامنة: أنه يسد على الشيطان مدخله إلى القلب، فإنه يدخل مع النظرة، وينفذ معها إلى القلب أسرع من نفوذ الهواء في المكان الخالي","pg":420},{"h":"التاسعة: فراغ القلب للمصالح","x":"التاسعة: أنه يفرغ القلب للفكرة في مصالحه والاشتغال بها، وإطلاق البصر يشتته عن ذلك، ويحول بينه وبينه","pg":421},{"h":"العاشرة: العين والقلب","x":"العاشرة: أن بين العين والقلب منفذا وطريقا يوجب انفعال أحدهما عن الآخر، وأن يصلح بصلاحه ويفسد بفساده.","pg":421},{"h":"العز قرين الطاعة","x":"وقد جعل الله سبحانه العز قرين طاعته، والذل قرين معصيته","pg":419},{"h":"قول الحسن","x":"كما قال الحسن: إنهم وإن طقطقت بهم البغال، وهملجت بهم البراذين، إن ذل المعصية في رقابهم، أبى الله إلا أن يذل من عصاه.","pg":419},{"h":"دعاء القنوت","x":"وفي دعاء القنوت: «إنه لا يذل من واليت، ولا يعز من عاديت». ومن أطاع الله فقد والاه فيما أطاعه فيه، وله من العز بحسب طاعته. ومن عصاه فقد عاداه فيما عصاه فيه، وله من الذل بحسب معصيته.","pg":420,"hd":"رواه أبو داود 1425 والترمذي 464، وقال المحقق: الحديث صحيح"},{"h":"سكر القلب","x":"فالتعلق بالصور يوجب فساد العقل، وعمه البصيرة، وسكر القلب","pg":418},{"h":"خاتمة الفوائد","x":"فهذه إشارة إلى بعض فوائد غض البصر تطلعك على ما وراءها.","pg":422}],"hd":"عبارة «فإن النظرة سهم مسموم من سهام إبليس» في ص 415 لفظ حديث ضعفه المحقق في ص 348، فلا تعرض للناشئ والشاب على أنها حديث.","weak":1},{"t":"فصل: الثاني: اشتغال القلب بما يصده عن ذلك","pg":422,"lv":"kid","key":"الثاني: اشتغال القلب بما يصده عن ذلك، ويحول بينه وبين الوقوع فيه. وهو إما خوف مقلق، أو حب مزعج.","p":["وشرح هذا أن النفس لا تترك محبوبا إلا لمحبوب أعلى منه، أو خشية مكروه حصوله أضر عليها من فوات هذا المحبوب.","إذا عرفت هذه المقدمة، فلا يمكن أن يجتمع في القلب حب المحبوب الأعلى وعشق الصور أبدا، بل هما ضدان لا يتلاقيان، بل لا بد أن يخرج أحدهما صاحبه."],"items":[{"h":"البصيرة الصحيحة","x":"أحدهما: بصيرة صحيحة يفرق بها بين درجات المحبوب والمكروه، فيؤثر أعلى المحبوبين على أدناهما، ويحتمل أدنى المكروهين ليخلص من أعلاهما. وهذا خاصة العقل","pg":422},{"h":"قوة العزم والصبر","x":"الثاني: قوة عزم وصبر يتمكن بها من هذا الفعل والترك. فكثيرا ما يعرف الرجل قدر التفاوت، ولكن يأبى له ضعف نفسه وهمته وعزيمته على إيثار الأنفع","pg":423},{"h":"الإمامة في الدين","x":"وقد منع الله سبحانه إمامة الدين إلا من أهل الصبر واليقين، فقال تعالى: ﴿وَجَعَلْنَا مِنْهُمْ أَئِمَّةً يَهْدُونَ بِأَمْرِنَا لَمَّا صَبَرُوا وَكَانُوا بِآيَاتِنَا يُوقِنُونَ﴾ [السجدة: 24].","pg":423},{"h":"ثلاثة أصناف","x":"وهذا هو الذي ينتفع بعلمه، وينتفع به الناس. وضده لا ينتفع بعلمه، ولا ينتفع به غيره. ومن الناس من ينتفع بعلمه في نفسه، ولا ينتفع به غيره. فالأول يمشي في نوره ويمشي الناس في نوره، والثاني قد طفئ نوره فهو يمشي في الظلمات ومن تبعه في ظلمته. والثالث يمشي في نوره وحده.","pg":423},{"h":"محبة الصور تفوت الأنفع","x":"فمحبة الصور تفوت محبة ما هو أنفع للعبد منها","pg":424}]},{"t":"ونختم الجواب بفصل يتعلق بعشق الصور","pg":482,"lv":"yth","key":"وإن كانت أضعاف ما يذكره ذاكر، فإنه يفسد القلب بالذات. وإذا فسد فسدت الإرادات والأقوال والأعمال، وفسد نفس التوحيد","p":["ونختم الجواب بفصل يتعلق بعشق الصور، وما فيه من المفاسد العاجلة والآجلة، وإن كانت أضعاف ما يذكره ذاكر، فإنه يفسد القلب بالذات.","فأخبر عن عشق امرأة العزيز ليوسف وما راودته وكادته به، وأخبر عن الحال التي صار إليها يوسف بصبره وعفته وتقواه، مع أن الذي ابتلي به أمر لا يصبر عليه إلا من صبره الله عليه."],"items":[{"h":"الطائفتان","x":"حكى الله هذا المرض عن طائفتين: امرأة العزيز في عشقها ليوسف، وقوم لوط.","pg":482}],"hd":""},{"t":"ابتلاء يوسف عليه السلام: دواعي الفعل مجتمعة","pg":482,"lv":"adl","key":"فإن موافقة الفعل بحسب قوة الداعي وزوال المانع، وكان الداعي هاهنا في غاية القوة","p":["ومع هذه الدواعي كلها، فآثر مرضاة الله وخوفه، وحمله حبه لله على أن اختار السجن على الزنى، فقال: ﴿رب السجن أحب إلي مما يدعونني إليه﴾ [يوسف 33]، وعلم أنه لا يطيق صرف ذلك عن نفسه، وأن ربه تعالى إن لم يعصمه ويصرفه عنه صبا إليهن بطبعه، وكان من الجاهلين. وهذا من كمال معرفته بربه وبنفسه.","وفي هذه القصة من العبر والفوائد والحكم ما يزيد على ألف فائدة، لعلنا إن وفق الله أن نفردها في مصنف مستقل."],"items":[{"h":"الأول","x":"ما ركبه الله في طبع الرجل من الميل إلى المرأة، وهذا لا يذم إذا صادف حلالا بل يحمد.","pg":483},{"h":"الثاني","x":"أن يوسف عليه السلام كان شابا، وشهوة الشباب وحدته أقوى.","pg":484},{"h":"الثالث","x":"أنه كان عزبا ليس له زوجة تكسر شدة الشهوة.","pg":484},{"h":"الرابع","x":"أنه كان في بلاد غربة بعيدا عن أهله ومعارفه، والغريب يتأتى له ما لا يتأتى له في وطنه.","pg":484},{"h":"الخامس","x":"أن المرأة كانت ذات منصب وجمال، وكل واحد منهما داع إليها.","pg":484},{"h":"السادس","x":"أنها غير ممتنعة ولا آبية.","pg":484},{"h":"السابع","x":"أنها طلبت وراودت وبذلت الجهد، فكانت هي الراغبة الذليلة، وهو العزيز المرغوب إليه.","pg":485},{"h":"الثامن","x":"أنه في دارها وتحت سلطانها، يخشى أذاها إن لم يطاوعها، فاجتمع داعي الرغبة والرهبة.","pg":485},{"h":"التاسع","x":"أنه لا يخشى أن ينكشف أمره، فهي الطالبة، وقد غلقت الأبواب، وغيبت الرقباء.","pg":485},{"h":"العاشر","x":"أنه كان في الظاهر مملوكا لها في الدار يدخل ويخرج ولا ينكر عليه، فكان الأنس سابقا على الطلب.","pg":486},{"h":"الحادي عشر","x":"أنها استعانت عليه بالنسوة، فاستعان هو بالله عليهن فقال: ﴿وإلا تصرف عني كيدهن أصب إليهن وأكن من الجاهلين﴾ [يوسف 33].","pg":486},{"h":"الثاني عشر","x":"أنها توعدته بالسجن والصغار، وهذا نوع إكراه، فاجتمع داعي الشهوة وداعي السلامة من السجن.","pg":486},{"h":"الثالث عشر","x":"أن الزوج لم يظهر منه من الغيرة ما يفرق به بينهما، بل قال ليوسف: ﴿أعرض عن هذا﴾ وللمرأة: ﴿واستغفري لذنبك إنك كنت من الخاطئين﴾ [يوسف 29].","pg":487}],"hd":"حديث «حبب إلي من دنياكم النساء والطيب، أصبر عن الطعام والشراب ولا أصبر عنهن» (ص 483 و484): قال المحقق: الحديث لا يصح، وعلته يوسف بن عطية فإنه متروك الحديث.","weak":1},{"t":"والطائفة الثانية الذين حكى عنهم العشق هم اللوطية","pg":487,"lv":"adl","key":"فحكاه سبحانه عن طائفتين عشق كل منهما ما حرم عليه من الصور، ولم يبال بما في عشقه من الضرر","p":["وهذا داء أعيا الأطباء دواؤه، وعز عليهم شفاؤه. وهو، لعمر الله، الداء العضال، والسم القتال، الذي ما علق بقلب إلا وعز على الورى استنقاذه من إساره، ولا اشتعلت ناره في مهجة إلا وصعب على الخلق تخليصها من ناره."],"items":[{"h":"الشاهد","x":"ذكر قوله تعالى في قوم لوط من سورة الحجر، وختمها: ﴿لعمرك إنهم لفي سكرتهم يعمهون﴾ [الحجر 72]، ثم قال: فهذه عشقت.","pg":488}],"hd":""},{"t":"وهو أقسام: العشق الشركي الكفري","pg":488,"lv":"adl","key":"فإنه تارة يكون كفرا، كمن اتخذ معشوقه ندا يحبه كما يحب الله، فكيف إذا كانت محبته أعظم من محبة الله في قلبه؟","p":["وعلامة هذا العشق الشركي الكفري أن يقدم العاشق رضا معشوقه على رضا ربه، وإذا تعارض عنده حق معشوقه وحظه وحق ربه وطاعته قدم حق معشوقه على حق ربه، وآثر رضاه على رضاه، وبذل لمعشوقه أنفس ما يقدر عليه، وبذل لربه، إن بذل، أردأ ما عنده.","فقد رضي هذا من عبودية الخالق جل جلاله بعبودية مخلوق مثله، فإن العبودية هي كمال الحب والخضوع، وهذا قد استفرغ قوة حبه وخضوعه وذله لمعشوقه، فقد أعطاه حقيقة العبودية.","ولا نسبة بين مفسدة هذا الأمر العظيم ومفسدة الفاحشة، فإن تلك ذنب كبير، لفاعله حكم أمثاله؛ ومفسدة هذا العشق مفسدة الشرك."],"items":[{"h":"حكمه","x":"فهذا عشق لا يغفر لصاحبه، فإنه من أعظم الشرك، والله لا يغفر أن يشرك به؛ وإنما يغفر بالتوبة الماحية.","pg":488},{"h":"الميزان","x":"فتأمل حال أكثر عشاق الصور، هل تجدها مطابقة لذلك؟ ثم ضع حالهم في كفة، وتوحيدهم وإيمانهم في كفة؛ ثم زن وزنا يرضي الله ورسوله، ويطابق العدل.","pg":489},{"h":"قول بعض العارفين","x":"لأن أبتلى بالفاحشة مع تلك الصورة أحب إلي من أن أبتلى فيها بعشق يتعبد لها قلبي ويشغله عن الله.","pg":490}],"hd":""},{"t":"فصل: ودواء هذا الداء القتال","pg":490,"lv":"yth","key":"وليس له دواء أنفع من الإخلاص لله. وهو الدواء الذي ذكره الله في كتابه","p":["ودواء هذا الداء القتال: أن يعرف ما ابتلي به من الداء المضاد للتوحيد أولا، ثم يأتي من العبادات الظاهرة والباطنة بما يشغل قلبه عن دوام الفكرة فيه، ويكثر اللجأ والتضرع إلى الله سبحانه في صرف ذلك عنه وأن يراجع بقلبه إليه.","حيث قال: ﴿كذلك لنصرف عنه السوء والفحشاء إنه من عبادنا المخلصين﴾ [يوسف 24]. فأخبر سبحانه أنه صرف عنه السوء من العشق والفحشاء من الفعل بإخلاصه. فإن القلب إذا خلص وأخلص عمله لله لم يتمكن منه عشق الصور، فإنه إنما يتمكن من قلب فارغ."],"items":[{"h":"المعرفة","x":"أن يعرف أن ما ابتلي به داء مضاد للتوحيد.","pg":490},{"h":"الشغل بالعبادة","x":"أن يأتي من العبادات الظاهرة والباطنة بما يشغل قلبه عن دوام الفكرة فيه.","pg":491},{"h":"اللجأ","x":"أن يكثر اللجأ والتضرع إلى الله في صرف ذلك عنه.","pg":491},{"h":"الإخلاص","x":"وليس له دواء أنفع من الإخلاص لله.","pg":491}],"hd":""},{"t":"وليعلم العاقل أن العقل والشرع يوجبان تحصيل المصالح","pg":491,"lv":"yth","key":"ومن المعلوم أنه ليس في عشق الصور مصلحة دينية ولا دنيوية، بل مفسدته الدينية والدنيوية أضعاف أضعاف ما يقدر فيه من المصلحة","p":["وليعلم العاقل أن العقل والشرع يوجبان تحصيل المصالح وتكميلها وإعدام المفاسد وتقليلها. فإذا عرض للعاقل أمر يرى فيه مصلحة ومفسدة وجب عليه أمران: أمر علمي، وأمر عملي. فالعلمي طلب معرفة الراجح من طرفي المصلحة والمفسدة، فإذا تبين له الرجحان وجب عليه إيثار الأصلح له."],"items":[{"h":"الأمر العلمي","x":"طلب معرفة الراجح من طرفي المصلحة والمفسدة.","pg":492},{"h":"الأمر العملي","x":"إذا تبين له الرجحان وجب عليه إيثار الأصلح له.","pg":492}],"hd":""},{"t":"مفاسد عشق الصور الدينية والدنيوية","pg":492,"lv":"adl","key":"فإن من أحب شيئا غير الله عذب به ولا بد","p":["فليس شيء أضيع لمصالح الدين والدنيا من عشق الصور. أما مصالح الدين فإنها منوطة بلم شعث القلب وإقباله على الله، وعشق الصور أعظم شيء تشعيثا وتشتيتا له.","والعشق مبادئه سهلة حلوة، وأوسطه هم وشغل قلب وسقم، وآخره عطب وقتل، إن لم يتداركه عناية من الله."],"items":[{"h":"الأول","x":"الاشتغال بحب المخلوق وذكره عن حب الرب تعالى وذكره. فلا يجتمع في القلب هذا وهذا إلا ويقهر أحدهما صاحبه.","pg":492},{"h":"الثاني","x":"عذاب قلبه بمعشوقه، والعشق، وإن استعذبه العاشق، فهو من أعظم عذاب القلب.","pg":492},{"h":"الثالث","x":"أن العاشق قلبه أسير في قبضة معشوقه، يسومه الهوان، ولكن لسكرة العشق لا يشعر بمصابه.","pg":493},{"h":"الرابع","x":"أنه يشتغل به عن مصالح دينه ودنياه، ومصالح الدنيا تابعة لمصالح الدين.","pg":494},{"h":"الخامس","x":"أن آفات الدنيا والآخرة أسرع إلى عشاق الصور من النار في يابس الحطب، لأن القلب كلما قرب من العشق بعد من الله.","pg":494},{"h":"السادس","x":"أنه إذا تمكن من القلب واستحكم وقوي سلطانه أفسد الذهن، وأحدث الوسواس.","pg":495},{"h":"السابع","x":"أنه ربما أفسد الحواس أو بعضها إما فسادا معنويا أو صوريا، فيرى القبيح حسنا، ويمرض البدن وينهكه.","pg":495},{"h":"الثامن","x":"أن العشق هو الإفراط في المحبة حتى لا يغيب المعشوق عن خاطره، فتتعطل القوى، ويحدث من الآفات على البدن والروح ما يعز دواؤه.","pg":497}],"hd":"«حبك للشيء يعمي ويصم» (ص 495): رواه أحمد 21694 و27548 وأبو داود 5130، واختلف في رفعه ووقفه على أبي الدرداء؛ قال المحقق: وسند الموقوف صحيح، ورجح الوقف السخاوي والسيوطي. وأثر ابن عباس في الشاب الذي نحل من العشق بعرفة (ص 497): قال المحقق: سنده ضعيف.","weak":1},{"t":"فصل: والعاشق له ثلاث مقامات","pg":499,"lv":"adl","key":"والعاشق له ثلاث مقامات: مقام ابتداء، ومقام توسط، ومقام انتهاء","p":["فأما مقام ابتدائه، فالواجب عليه فيه مدافعته بكل ما يقدر عليه، إذا كان الوصول إلى معشوقه متعذرا قدرا أو شرعا.","فإن عجز عن ذلك، وأبى قلبه إلا السفر إلى محبوبه، وهذا مقام التوسط والانتهاء، فعليه كتمان ذلك، وأن لا يفشيه إلى الخلق، ولا يشبب بمحبوبه ويهتكه بين الناس، فيجمع بين الشرك والظلم."],"items":[{"h":"مقام الابتداء","x":"المدافعة بكل ما يقدر عليه.","pg":499},{"h":"مقام التوسط والانتهاء","x":"الكتمان وعدم الإفشاء والهتك، لأن الهتك يعرض المعشوق وأهله لوقوع الناس فيهم.","pg":499},{"h":"شاهد الإفك","x":"وبذلك وقع أهل الإفك في الطيبة المطيبة حبيبة رسول الله صلى الله عليه وسلم، المبرأة من فوق سبع سماوات، بشبهة مجيء صفوان بن المعطل بها وحده خلف العسكر.","pg":500}],"hd":"قصة الإفك: أخرجها البخاري 2661 ومسلم 2770."},{"t":"فقد تضمن العشق أنواع الظلم كلها","pg":501,"lv":"adl","key":"ولا يسقط حق الغير بالتوبة من الفاحشة. فإن التوبة وإن أسقطت حق الله فحق العبد باق، له المطالبة به يوم القيامة","p":["والمقصود أن التعاون في هذا الباب تعاون على الإثم والعدوان.","فكل هذه الآفات وأضعافها وأضعاف أضعافها تنشأ من عشق الصور. وربما حمل على الكفر الصريح."],"items":[{"h":"الواسطة","x":"فإن استعان عليه بمن يستميله إليه، إما برغبة أو رهبة، تعدى الظلم وانتشر، وصار ذلك الواسطة ديوثا ظالما.","pg":501},{"h":"التخبيب","x":"وكم خببت امرأة على بعلها، وجارية وعبد على سيدهما! وقد لعن رسول الله صلى الله عليه وسلم من فعل ذلك، وتبرأ منه.","pg":501},{"h":"الخطبة على الخطبة","x":"نهى النبي صلى الله عليه وسلم أن يخطب الرجل على خطبة أخيه، فكيف بمن يسعى في التفريق بين الرجل وأهله؟","pg":502},{"h":"السحر","x":"فإن استعان العاشق على وصال معشوقه بشياطين الجن، إما بسحر أو استخدام أو نحو ذلك، ضم إلى الشرك والظلم كفر السحر.","pg":503},{"h":"ثمرته","x":"فكم للعشق من قتيل من الجانبين! وكم قد أزال من نعمة، وأفقر من غنى، وأسقط من مرتبة، وشتت من شمل!","pg":506}],"hd":"«لعن رسول الله صلى الله عليه وسلم الراشي والمرتشي والرائش» (ص 501): ضعفه الحاكم والمنذري والهيثمي لأن مداره على ليث وهو ضعيف، والثابت من حديث عبد الله بن عمرو: «لعن رسول الله صلى الله عليه وسلم الراشي والمرتشي» صححه الترمذي وابن الجارود وابن حبان والحاكم. حديث التخبيب «من خبب عبدا على أهله فليس منا» رواه أحمد 22980 وابن حبان 4363 والحاكم وصححه ابن حبان والحاكم. النهي عن الخطبة على الخطبة: البخاري 2140 و2727 ومسلم 1408. «خذ من حسناته ما شئت» و«فما ظنكم»: مسلم 1897. «لا يدخل الجنة قاطع رحم»: البخاري 5984 ومسلم 2556. «من لا يأمن جاره بوائقه»: مسلم 46.","weak":1},{"t":"فإن أول أسباب العشق الاستحسان","pg":506,"lv":"yth","key":"فلولا تكراره النظر إلى وجه معشوقه وطمعه في وصاله لم يتمكن عشقه من قلبه","p":["فعلى العاقل أن لا يحكم على نفسه عشق الصور، لئلا يؤديه ذلك إلى هذه المفاسد أو أكثرها أو بعضها. فمن فعل ذلك فهو المفرط بنفسه المغرر بها، فإذا هلكت فهو الذي أهلكها.","وكذلك إذا خاف من فوات محبوب هو أحب إليه وأنفع له من ذلك المعشوق، وقدم محبته على محبة المعشوق؛ اندفع عنه العشق."],"items":[{"h":"الاستحسان","x":"فإن أول أسباب العشق الاستحسان، سواء تولد عن نظر أو سماع.","pg":506},{"h":"الإياس","x":"فإن لم يقارنه طمع في الوصال، وقارنه الإياس من ذلك؛ لم يحدث له العشق.","pg":507},{"h":"صرف الفكر","x":"فإن اقترن به الطمع، فصرفه عن فكره ولم يشتغل قلبه به؛ لم يحدث له ذلك.","pg":507},{"h":"الخوف الديني","x":"فإن أطال الفكر وقارنه خوف ديني كدخول النار، وغضب الجبار، واحتقاب الأوزار، وغلب هذا الخوف، لم يحدث له العشق.","pg":507},{"h":"الخوف الدنيوي","x":"فإن فاته هذا الخوف فقارنه خوف دنيوي، كخوف تلاف نفسه وماله وذهاب جاهه، وغلب هذا الخوف لداعي العشق دفعه.","pg":507},{"h":"المحبوب الأعلى","x":"إذا خاف فوات محبوب هو أحب إليه وأنفع له من ذلك المعشوق اندفع عنه العشق.","pg":507},{"h":"التمكن","x":"فإن انتفى ذلك كله، أو غلبت محبة المعشوق لذلك؛ انجذب إليه القلب بكليته، ومالت إليه النفس كل الميل.","pg":508}],"hd":""},{"t":"فإن قيل: قد ذكرتم آفات العشق، فهلا ذكرتم منافعه","pg":508,"lv":"adl","key":"فإن قيل: قد ذكرتم آفات العشق ومضاره ومفاسده، فهلا ذكرتم منافعه وفوائده","p":["فإن قيل: قد ذكرتم آفات العشق ومضاره ومفاسده، فهلا ذكرتم منافعه وفوائده التي من جملتها: رقة الطبع، وترويح النفس، وخفتها، وزوال ثقلها، ورياضتها، وحملها على مكارم الأخلاق من الشجاعة والكرم والمروءة ورقة الحاشية ولطف الجانب."],"items":[{"h":"مضمون الاعتراض","x":"ساق ابن القيم على لسان المعترض أقوالا وأشعارا وأخبارا منسوبة إلى عشاق، يستدل بها المعترض على فوائد العشق، ثم رد عليه، فهي حكاية لحجة الخصم لا تقرير لها (ص 508 إلى 532).","pg":508}],"hd":"في أخبار المعترض أحاديث وآثار حكم المحقق بضعفها أو بطلانها، منها: «من عشق وكتم وعف وصبر غفر الله له وأدخله الجنة»، و«من عشق وعف وكتم فمات فهو شهيد» (منكر، ورد ابن القيم رفعه في آخر الكتاب)، وقصة داود عليه السلام (حديث باطل لا يثبت)، وقصة «سبحان مقلب القلوب» في زينب (الواقدي متروك)، وانظر قائمة الضعيف.","weak":1},{"t":"فالجواب: أنفع المحبة على الإطلاق محبة الله","pg":532,"lv":"adl","key":"اعلم أن أنفع المحبة على الإطلاق وأوجبها وأعلاها وأجلها محبة من جبلت القلوب على محبته، وفطرت الخليقة على تألهه","p":["فالجواب، وبالله التوفيق، أن الكلام في هذا الباب لا بد فيه من التمييز بين الواقع والجائز، والنافع والضار. ولا يسجل عليه بالذم والإنكار ولا بالمدح والقبول من حيث الجملة. وإنما يتبين حكمه وينكشف أمره بذكر متعلقه، وإلا فالعشق من حيث هو لا يحمد ولا يذم.","وبهذا التوحيد في الحب أرسل الله سبحانه جميع رسله، وأنزل جميع كتبه، وأطبقت عليه دعوة الرسل من أولهم إلى آخرهم، ولأجله خلق السماوات والأرض والجنة والنار، فجعل الجنة لأهله، والنار للمشركين به فيه.","فلو أن مخلوقا فعل بمخلوق أدنى شيء من ذلك لم يملك قلبه عن محبته، فكيف لا يحب العبد بكل قلبه وجوارحه من يحسن إليه على الدوام بعدد الأنفاس، مع إساءته؟"],"items":[{"h":"دليل الفطرة والنعمة","x":"فإن القلوب مفطورة مجبولة على محبة من أنعم عليها وأحسن إليها، فكيف بمن كل الإحسان منه: ﴿وما بكم من نعمة فمن الله ثم إذا مسكم الضر فإليه تجأرون﴾ [النحل 53].","pg":533},{"h":"داعيا المحبة","x":"والمحبة لها داعيان: الجمال والإجلال، والرب تعالى له الكمال المطلق من ذلك.","pg":533},{"h":"الولاية","x":"والولاية أصلها الحب، فلا موالاة إلا بحب؛ كما أن العداوة أصلها البغض.","pg":534},{"h":"كل ما منه يدعو إلى محبته","x":"فعطاؤه ومنعه، ومعافاته وابتلاؤه، وقبضه وبسطه، وعدله وفضله، كل ذلك داع للقلوب إلى تألهه ومحبته.","pg":535},{"h":"يريدك لك","x":"فكل من تحبه من الخلق ويحبك إنما يريدك لنفسه وغرضه منك، والله سبحانه وتعالى يريدك لك.","pg":536},{"h":"أعظم الربح","x":"والرب تعالى إنما يعاملك لتربح أنت عليه أعظم الربح وأعلاه. فالدرهم بعشرة أمثاله إلى سبعمائة ضعف إلى أضعاف كثيرة، والسيئة بواحدة، وهي أسرع شيء محوا.","pg":537},{"h":"يحب الملحين","x":"لا يتبرم بإلحاح الملحين، بل يحب الملحين في الدعاء. ويحب أن يسأل، ويغضب إذا لم يسأل.","pg":537},{"h":"أرحم وأفرح","x":"أرحم بعبده من الوالدة بولدها، وأشد فرحا بتوبة التائب من الفاقد لراحلته التي عليها طعامه وشرابه في الأرض المهلكة.","pg":538}],"hd":"«لا يؤمن عبد حتى يكون هو أحب إليه من ولده ووالده والناس أجمعين»: البخاري 15 ومسلم 44 (أحال المحقق إلى ص 464). قول عمر «لا حتى أكون أحب إليك من نفسك»: البخاري 6632. «من يسألني فأعطيه؟ من يستغفرني فأغفر له؟»: البخاري 1145 ومسلم 758 (أحال المحقق إلى ص 233). «أرحم بعبده من الوالدة بولدها»: البخاري 5999 ومسلم 2754. فرح الله بتوبة التائب: البخاري 6308 ومسلم 2744. «حجابه النور...»: مسلم 179. أما «أحق من ذكر، وأحق من شكر...» (ص 538) فقال المحقق: لفظ حديث رواه الطبراني، وقال الهيثمي: فيه فضالة بن جبير مجمع على ضعفه.","weak":1}],"lv":{"kid":{"show":false,"title":"","intro":"","points":[],"quiz":[],"act":null},"yth":{"show":true,"title":"عيني بوابة قلبي: العفة تبدأ من النظرة","intro":"بعد أن شرح ابن القيم أبواب المعاصي الأربعة قال: هذا كله مقدمة لحفظ العفة. ثم بين أن علاج التعلق المحرم يبدأ قبل أن يحصل، بأمرين: أن تحفظ عينك، وأن تملأ قلبك بما هو أعلى وأحب. وذكر لغض البصر عشر فوائد تجعلك ترى أنه ربح لا خسارة.","points":["حرم الله الفواحش ما ظهر منها وما بطن، وجعل الطريق إلى العفة حفظ النظر والخطرة واللسان والقدم","غض البصر ربح: نور القلب، وفرحه، وقوته، وأنسه بالله، وفراسة صادقة","الشيطان يدخل مع النظرة ويزين الصورة في القلب، فإذا حفظت عينك أغلقت عليه بابه","القلب لا يترك محبوبا إلا لمحبوب أعلى منه، فاملأ قلبك بحب الله والهمة العالية","الذنوب قد تحول بين العبد وحسن الخاتمة، ولذلك كان السلف يخافون على خواتيمهم","قوة الدواعي لا تبرر المعصية، فقد اجتمعت على يوسف ثلاثة عشر داعيا فاختار السجن على معصية الله.","يوسف لم يعتمد على قوته، بل علم أنه إن لم يصرف الله عنه الكيد مال إليه، فدعا ربه.","أنفع دواء للقلب الإخلاص لله، فالتعلق المحرم يتمكن من القلب الفارغ.","التعلق يبدأ بتكرار النظر والطمع وإطالة الفكر، فاقطعه من أوله قبل أن يتمكن.","من أحب شيئا غير الله عذب به، وباب التوبة الماحية مفتوح لمن رجع إلى ربه."],"quote":{"x":"ومن ترك لله شيئا عوضه الله خيرا منه","pg":417},"quiz":[{"q":"بماذا وصف ابن القيم كلامه السابق عن الأبواب الأربعة؟","o":["مقدمة بين يدي تحريم الفواحش","خاتمة لباب الدعاء وآدابه","تمهيد لباب الصبر على البلاء","استطراد عن أحكام البيوع"],"why":"وهذا كله ذكرناه مقدمة بين يدي تحريم الفواحش ووجوب حفظ الفرج.","pg":376},{"q":"ما الأمران المانعان من حصول التعلق المحرم في القلب؟","o":["غض البصر واشتغال القلب بما يصده","العزلة التامة عن الناس وترك الدراسة","كثرة النوم وقلة الخروج من البيت","السفر الدائم وتغيير الأصحاب"],"why":"فأما الطريق المانع من حصول هذا الداء، فأمران: أحدهما: غض البصر","pg":415},{"q":"ما الذي يورثه غض البصر ليميز به صاحبه بين الصادق والكاذب؟","o":["فراسة صادقة","شهرة واسعة","مالا كثيرا","قوة في البدن"],"why":"السادسة: أنه يورثه فراسة صادقة يميز بها بين المحق والمبطل، والصادق والكاذب.","pg":417},{"q":"لماذا بكى سفيان الثوري ليلة إلى الصباح؟","o":["من خوف الخاتمة","من شدة المرض","من فقد ماله","من ظلم الناس"],"why":"فأخذ تبنة من الأرض، وقال: الذنوب أهون من هذا، وإنما أبكي من خوف الخاتمة.","pg":390},{"q":"متى تترك النفس شيئا تحبه؟","o":["لمحبوب أعلى منه أو خوف مكروه أضر","إذا مل منه الإنسان وطال عهده به","إذا لامه الناس عليه وعابوه به كثيرا","إذا عجز عن الوصول إليه مرة"],"why":"وشرح هذا أن النفس لا تترك محبوبا إلا لمحبوب أعلى منه، أو خشية مكروه حصوله أضر عليها من فوات هذا المحبوب.","pg":422},{"q":"ما الدواء الذي قال ابن القيم إنه لا أنفع منه لهذا الداء؟","o":["الإخلاص لله سبحانه","كتمان الأمر عن الناس","السفر بعيدا عن البلد","الإكثار من الراحة"],"why":"وليس له دواء أنفع من الإخلاص لله. وهو الدواء الذي ذكره الله في كتابه","pg":491},{"q":"ما الذي حمل يوسف عليه السلام على اختيار السجن؟","o":["إيثاره مرضاة الله وحبه له","خوفه من غضب زوج المرأة","رغبته في الابتعاد عن إخوته","طمعه في منصب عند الملك"],"why":"ومع هذه الدواعي كلها، فآثر مرضاة الله وخوفه، وحمله حبه لله على أن اختار السجن","pg":487},{"q":"لما استعانت امرأة العزيز بالنسوة على يوسف، ماذا فعل؟","o":["استعان بالله عليهن ودعاه","اعتمد على قوة عزيمته وحده","طلب من العزيز أن يحميه منهن","شكا حاله إلى أهل المدينة"],"why":"فاستعان هو بالله عليهن، فقال: ﴿وإلا تصرف عني كيدهن أصب إليهن وأكن من الجاهلين﴾","pg":486},{"q":"ما أول أسباب العشق كما ذكر ابن القيم؟","o":["الاستحسان بنظر أو سماع","كثرة المال وسعة الغنى","الغربة عن الأهل والوطن","الشجاعة والكرم والمروءة"],"why":"فإن أول أسباب العشق الاستحسان، سواء تولد عن نظر أو سماع","pg":506},{"q":"كيف وصف ابن القيم بداية العشق ونهايته؟","o":["أوله حلو سهل وآخره عطب","أوله مر صعب وآخره راحة","أوله ونهايته سعادة دائمة","أوله هم وآخره لا ضرر فيه"],"why":"والعشق مبادئه سهلة حلوة، وأوسطه هم وشغل قلب وسقم، وآخره عطب وقتل، إن لم يتداركه عناية من الله","pg":498}],"scene":{"t":"في المجمع التجاري","x":"خرج يوسف مع أصحابه إلى المجمع، فصار أحدهم يتتبع المارة بنظره ويعلق عليهم، ويلح على يوسف أن يفعل مثله وإلا سخر منه.","opts":["يحفظ بصره ويذكر صاحبه بلطف بحق الطريق ثم يقترح تغيير المكان","يجاملهم بنظرة سريعة حتى لا يبدو مختلفا عنهم","يسكت وينشغل بهاتفه دون أن يقول شيئا"],"why":"فإن إطلاق البصر يفرق القلب، ويشتته، ويبعده من الله.","pg":416},"act":{"type":"plan","t":"خطتي للعفة وحفظ القلب","x":"يختار الشاب ثلاث خطوات على الأقل، ويكتبها في دفتره الخاص، ويتابعها أسبوعين، ويكتب في آخر كل أسبوع فائدة واحدة من فوائد غض البصر شعر بها.","items":["أصرف بصري من أول نظرة في الشارع والشاشة","أحذف التطبيقات والحسابات التي تفتح علي باب النظر","أشغل وقت الفراغ بعمل نافع أحبه: رياضة أو حفظ أو مشروع","أجعل لي وردا من القرآن والذكر يملأ قلبي بحب الله","أتذكر عند الضعف أن من ترك شيئا لله عوضه الله خيرا منه","أدعو الله أن يحسن خاتمتي وأن يحفظ قلبي","أختار رفقة تعينني على الخير وأبتعد عن مجالس السوء"]},"act2":{"type":"plan","t":"خطة يوسفية لحماية القلب","x":"اختر من الخطوات التالية ثلاث خطوات تلتزم بها هذا الأسبوع، واكتب أمام كل خطوة كيف ستطبقها في يومك. كل خطوة مأخوذة من علاج ابن القيم.","items":["أجدد نيتي وأجعل أعمالي خالصة لله، فالقلب الخالص لا يتمكن منه التعلق","أقطع تكرار النظر من أوله، فهو أول طريق التعلق","أشغل قلبي بعبادة ظاهرة وباطنة: صلاة في وقتها، وورد قرآن، وذكر","أكثر من الدعاء كما دعا يوسف: يا رب اصرف عني ما لا يرضيك","أوازن قبل أن أتعلق: ما المصلحة وما المفسدة في ديني ودنياي؟","أتذكر محبوبا أعظم أخاف فواته: رضا الله والجنة","أتوب فورا إن زلت قدمي، ولا أستسلم لليأس"]}},"adl":{"show":true,"title":"حفظ الفرج وعلاج العشق: الطريق المانع من حصوله","intro":"ينتقل ابن القيم من الأبواب الأربعة إلى مقصودها: تحريم الفواحش ووجوب حفظ الفرج. فيبين عظم مفسدة الزنى على الفرد والأسرة والمجتمع، ويحذر من أثر الذنوب في الحيلولة دون حسن الخاتمة، ثم يتكلم عن فاحشة قوم لوط وأحكامها بإسهاب فقهي. ثم يجيب عن سؤال الكتاب الأول: هل لداء العشق دواء؟ فيجعل الدواء من طريقين، ويشرح هنا الطريق المانع: غض البصر بفوائده العشر، واشتغال القلب بخوف مقلق أو حب مزعج.","points":["مفسدة الزنى مناقضة لصلاح العالم: تفسد الأنساب والبيوت، وتشتت القلب، وفيها خراب الدنيا والدين","من أجل غيرة الله حرم الفواحش ما ظهر منها وما بطن، وظهورها من أمارات خراب العالم","الإصرار على الكبائر من أسباب سوء الخاتمة، ومن استقام ظاهره وصلح باطنه لا يخذل عند الموت","علاج العشق من طريقين: حسم المادة قبل حصولها، وقلعها بعد نزولها","الطريق المانع غض البصر واشتغال القلب، ويحتاج صاحبه إلى بصيرة صحيحة وقوة عزم وصبر","قوة الداعي وزوال المانع هما سبب الوقوع، ويوسف عليه السلام اجتمعت عليه الدواعي كلها فعصمه إخلاصه.","العشق الذي يقدم فيه رضا المعشوق على رضا الرب شرك في المحبة، ومفسدته أعظم من مفسدة الفاحشة نفسها.","العلاج: معرفة أنه داء مضاد للتوحيد، ثم الشغل بالعبادات، ثم اللجأ إلى الله، ورأس ذلك الإخلاص.","للعاشق ثلاثة مقامات: في الابتداء المدافعة، وفي التوسط والانتهاء الكتمان وعدم الهتك، لأن الهتك ظلم للمعشوق وأهله.","العشق في ذاته لا يحمد ولا يذم، وإنما يتبين حكمه بمتعلقه، وأنفع المحبة محبة الله التي لأجلها خلقت السماوات والأرض."],"quote":{"x":"فلا يمكن أن يجتمع في القلب حب المحبوب الأعلى وعشق الصور أبدا، بل هما ضدان لا يتلاقيان","pg":424},"quiz":[{"q":"ما وجه ترتيب الثلاث في حديث «لا يحل دم امرئ مسلم» عند ابن القيم؟","o":["البدء بالأكثر وقوعا ثم الذي يليه","البدء بالأعظم إثما عند الله ثم الأخف منه","البدء بالأقدم تشريعا ثم المتأخر","ترتيب اتفاقي لا يقصد به معنى خاص"],"why":"وبدأ رسول الله ﷺ بالأكثر وقوعا، ثم بالذي يليه. فالزنى أكثر وقوعا من قتل النفس، وقتل النفس أكثر وقوعا من الردة.","pg":377},{"q":"ما الذي جرت به سنة الله عند ظهور الزنى؟","o":["يشتد غضبه فيؤثر في الأرض عقوبة","يمهل الناس دائما دون أن تنزل بهم عقوبة","تقع العقوبة على الفاعل وحده دون غيره","تزداد الأرزاق مدة ثم تنقطع فجأة"],"why":"وقد جرت سنة الله سبحانه في خلقه أنه عند ظهور الزنى يغضب الله سبحانه، ويشتد غضبه، فلا بد أن يؤثر غضبه في الأرض عقوبة.","pg":380},{"q":"لمن لا يكون سوء الخاتمة فيما نقله ابن القيم عن عبدالحق؟","o":["لمن استقام ظاهره وصلح باطنه","لمن كثر ماله وعلا جاهه بين الناس","لمن قل علمه وكثرت عبادته ونوافله","لمن طال عمره وكثر ولده وأهله"],"why":"واعلم أن سوء الخاتمة، أعاذنا الله منها، لا تكون لمن استقام ظاهره، وصلح باطنه","pg":391},{"q":"ما مضمون الفائدة العاشرة من فوائد غض البصر؟","o":["أن بين العين والقلب منفذا يصلح بصلاحه ويفسد بفساده","أن غض البصر يحفظ صحة العين من التعب والإجهاد الطويل","أن غض البصر يكسب صاحبه مكانة عالية بين الناس","أن غض البصر يقلل انشغال المرء بالأخبار والناس"],"why":"العاشرة: أن بين العين والقلب منفذا وطريقا يوجب انفعال أحدهما عن الآخر، وأن يصلح بصلاحه ويفسد بفساده.","pg":421},{"q":"ما الأمران اللذان يحتاجهما من أراد أن يترك محبوبا أدنى لمحبوب أعلى؟","o":["بصيرة صحيحة وقوة عزم وصبر","سعة في المال وفراغ في الوقت","عزلة عن الناس وترك النكاح","شهرة بين الناس وجاه عريض"],"why":"أحدهما: بصيرة صحيحة يفرق بها بين درجات المحبوب والمكروه ... الثاني: قوة عزم وصبر يتمكن بها من هذا الفعل والترك.","pg":422},{"q":"لماذا جعل ابن القيم مفسدة العشق الذي يتعبد له القلب أعظم من مفسدة الفاحشة؟","o":["لأن مفسدته مفسدة الشرك في المحبة","لأن الفاحشة ذنب لا يترتب عليه إثم","لأن العشق يمرض البدن أكثر من غيره","لأن العاشق يظلم معشوقه في ماله"],"why":"ولا نسبة بين مفسدة هذا الأمر العظيم ومفسدة الفاحشة، فإن تلك ذنب كبير، لفاعله حكم أمثاله؛ ومفسدة هذا العشق مفسدة الشرك","pg":490},{"q":"ما علامة العشق الشركي الكفري عند ابن القيم؟","o":["أن يقدم رضا معشوقه على رضا ربه","أن يكثر من ذكر معشوقه بين الناس","أن ينحل جسمه من شدة التعلق","أن يعجز عن كتمان ما في قلبه"],"why":"وعلامة هذا العشق الشركي الكفري أن يقدم العاشق رضا معشوقه على رضا ربه","pg":488},{"q":"ما الواجب على العاشق في مقام الابتداء إذا تعذر عليه الوصول قدرا أو شرعا؟","o":["مدافعته بكل ما يقدر عليه","كتمانه مع الاسترسال في الفكر","إظهاره ليجد من يعينه عليه","البحث عن واسطة تقربه منه"],"why":"فأما مقام ابتدائه، فالواجب عليه فيه مدافعته بكل ما يقدر عليه، إذا كان الوصول إلى معشوقه متعذرا قدرا أو شرعا","pg":499},{"q":"إذا عرض للعاقل أمر فيه مصلحة ومفسدة، فما الأمر العلمي الواجب عليه؟","o":["طلب معرفة الراجح من الطرفين","إيثار الأصلح بعد ظهور الرجحان","ترك الأمر كله دون نظر فيه","الأخذ برأي أكثر الناس فيه"],"why":"فالعلمي طلب معرفة الراجح من طرفي المصلحة والمفسدة، فإذا تبين له الرجحان وجب عليه إيثار الأصلح له","pg":492},{"q":"ما جواب ابن القيم المجمل عمن ذكر فوائد العشق ومنافعه؟","o":["أن حكمه يتبين بذكر متعلقه","أنه مذموم في كل أحواله","أنه محمود لرقة الطبع فيه","أنه مباح لأهل المروءة والكرم"],"why":"وإنما يتبين حكمه وينكشف أمره بذكر متعلقه، وإلا فالعشق من حيث هو لا يحمد ولا يذم","pg":532}],"scene":{"t":"أب وابنه والهاتف","x":"لاحظ أب أن ابنه ذا الخمسة عشر عاما يسهر على هاتفه، وبدأ يتعلق بمحتوى لا يحل، ففكر أن يصادر الهاتف ويكتفي بذلك.","opts":["يغلق باب النظر بحكمة ويملأ قلب ابنه بمحبوب أعلى وهمة عالية ورفقة صالحة","يصادر الهاتف ويكتفي بالتوبيخ الشديد","يتركه لأنه سيكبر ويترك ذلك وحده"],"why":"وشرح هذا أن النفس لا تترك محبوبا إلا لمحبوب أعلى منه، أو خشية مكروه حصوله أضر عليها من فوات هذا المحبوب.","pg":422},"act":{"type":"class","t":"لقاء تربوي للآباء والمعلمين: الطريق المانع","x":"لقاء مدته 45 دقيقة يدرب المربين على تطبيق الطريق المانع مع الأبناء والطلاب بأسلوب حكيم يجمع بين إغلاق الباب وملء القلب.","items":[{"h":"الافتتاح 5 دقائق","x":"يعرض الميسر سؤال الكتاب: هل لهذا الداء دواء؟ وجواب ابن القيم: الدواء من طريقين، حسم المادة قبل حصولها، وقلعها بعد نزولها."},{"h":"فوائد غض البصر 15 دقيقة","x":"توزع الفوائد العشر على المجموعات، وتصوغ كل مجموعة الفائدة بلغة يفهمها الابن، مع وسيلة عملية لتعليمها في البيت أو الصف."},{"h":"اشتغال القلب 15 دقيقة","x":"نقاش: ما المحبوب الأعلى الذي نغرسه في قلوب أبنائنا؟ وما الخوف النافع الذي نربيهم عليه؟ ويربط بشرطي البصيرة الصحيحة وقوة العزم والصبر."},{"h":"حالات 7 دقائق","x":"يناقش المشاركون حالة ابن تعلق بمحتوى محرم: ما الخطأ في الاكتفاء بالمنع؟ وكيف نجمع بين الحزم والرحمة؟"},{"h":"الختام 3 دقائق","x":"يكتب كل مشارك خطوة واحدة يطبقها هذا الأسبوع في بيته أو صفه."}]},"act2":{"type":"class","t":"درس صفي: يوسف عليه السلام وثلاثة عشر داعيا","x":"نشاط للمعلم مع طلاب المرحلة الثانوية مدته 40 دقيقة، يعرض فيه دواعي الفعل التي اجتمعت على يوسف عليه السلام بصياغة عفيفة، ثم يستخرج الطلاب منه دروس المقاومة.","items":["5 دقائق: يقرأ المعلم قوله تعالى ﴿رب السجن أحب إلي مما يدعونني إليه﴾ ويسأل: لماذا يختار إنسان السجن؟","10 دقائق: يوزع بطاقات فيها دواعي الفعل كما ذكرها ابن القيم (الشباب، الغربة، غلق الأبواب، التهديد بالسجن...) ويرتبها الطلاب من الأقوى إلى الأضعف","10 دقائق: يناقش الطلاب قاعدة ابن القيم: موافقة الفعل بحسب قوة الداعي وزوال المانع، ويذكرون موانع اليوم","10 دقائق: يستخرج الطلاب أدوية يوسف: الاستعانة بالله، ومعرفة النفس، والإخلاص ﴿إنه من عبادنا المخلصين﴾","5 دقائق: يكتب كل طالب في دفتره الخاص مانعا واحدا يقويه في نفسه هذا الأسبوع"]}},"alt":{"kid":{"title":"أحفظ عيني وقلبي","intro":"عينك نافذة على قلبك، فما تنظر إليه يدخل إلى قلبك. وقد أمرنا الله أن نحفظ أعيننا عما لا يحل، وجعل في ذلك خيرا كثيرا لنا: نورا في القلب، وفرحا، وقوة، وقربا منه سبحانه. ومن أجمل ما يحمي القلب أن نملأه بحب الله وبالأشياء النافعة، فلا يبقى فيه مكان لما يضره.","points":["حفظ العين طاعة لله، وطاعة الله أنفع شيء لي في الدنيا والآخرة","حين أصرف بصري عما لا يحل يمتلئ قلبي نورا وفرحا وقوة","إذا تركت شيئا لأجل الله أعطاني الله خيرا منه","الشيطان يحاول أن يدخل إلى القلب من باب العين، فأغلقه عليه","قلبي لا يترك شيئا يحبه إلا لشيء أحب إليه، فأملؤه بحب الله والعمل النافع"],"quote":{"x":"أنه يكسب القلب نورا، كما أن إطلاقه يكسبه ظلمة","pg":416},"quiz":[{"q":"ماذا يكسب القلب حين أحفظ عيني عما لا يحل؟","o":["نورا","ظلمة","تعبا","حزنا"],"why":"الخامسة: أنه يكسب القلب نورا، كما أن إطلاقه يكسبه ظلمة.","pg":416},{"q":"من ترك شيئا لأجل الله فماذا يعطيه الله؟","o":["خيرا منه","مثله فقط","نصفه فقط","أقل منه"],"why":"ومن ترك لله شيئا عوضه الله خيرا منه","pg":417},{"q":"مع أي شيء يدخل الشيطان إلى القلب كما ذكر ابن القيم؟","o":["مع النظرة","مع الطعام","مع النوم","مع اللعب"],"why":"الثامنة: أنه يسد على الشيطان مدخله إلى القلب، فإنه يدخل مع النظرة","pg":420},{"q":"ما أنفع شيء للعبد في دنياه وآخرته؟","o":["امتثال أوامر ربه","كثرة اللعب والمرح","جمع الألعاب الكثيرة","النوم الطويل المريح"],"why":"فليس للعبد في دنياه وآخرته أنفع من امتثال أوامر ربه تبارك وتعالى.","pg":415}],"scene":{"t":"أمام الشاشة","x":"كان خالد يشاهد برنامجا مع أخيه الصغير، فظهر فجأة مشهد لا يليق أن ينظر إليه.","opts":["يصرف بصره ويغير القناة بهدوء ويقترح على أخيه نشاطا آخر","يكمل المشاهدة لأنه مشهد قصير","يغمض عينيه وحده ويترك أخاه ينظر"],"why":"الرابعة: أنه يقوي القلب ويفرحه، كما أن إطلاق البصر يضعفه ويحزنه.","pg":416},"act":{"type":"match","t":"صل العمل بثمرته","x":"يصل الطالب كل عمل في العمود الأول بثمرته في العمود الثاني، ثم يختار ثمرة واحدة يحب أن يحصل عليها هذا الأسبوع ويكتب كيف سيصل إليها.","items":[{"a":"حفظ العين عما لا يحل","b":"نور في القلب"},{"a":"إطلاق العين فيما لا يحل","b":"ظلمة في القلب"},{"a":"ترك شيء لأجل الله","b":"عوض خير منه"},{"a":"طاعة الله","b":"عز وقوة"},{"a":"ملء القلب بحب الله والنافع","b":"لا يبقى مكان لما يضر"}]}}}},"highlights":[{"x":"ومن ترك لله شيئا عوضه الله خيرا منه","pg":417,"lv":"kid"},{"x":"أنه يكسب القلب نورا، كما أن إطلاقه يكسبه ظلمة","pg":416,"lv":"kid"},{"x":"وقد جعل الله سبحانه العز قرين طاعته، والذل قرين معصيته","pg":419,"lv":"kid"},{"x":"فليس للعبد في دنياه وآخرته أنفع من امتثال أوامر ربه تبارك وتعالى","pg":415,"lv":"kid"},{"x":"وهذا من أعظم الفقه: أن يخاف الرجل أن تخذله ذنوبه عند الموت","pg":390,"lv":"yth"},{"x":"أبى الله إلا أن يذل من عصاه","pg":419,"lv":"yth"},{"x":"فلا يمكن أن يجتمع في القلب حب المحبوب الأعلى وعشق الصور أبدا","pg":424,"lv":"adl"},{"x":"ومفسدة الزنا مناقضة لصلاح العالم","pg":377,"lv":"adl"},{"x":"وهذا من كمال معرفته بربه وبنفسه","pg":487,"lv":"yth"},{"x":"فإن القلب إذا خلص وأخلص عمله لله لم يتمكن منه عشق الصور","pg":491,"lv":"yth"},{"x":"فإن من أحب شيئا غير الله عذب به ولا بد","pg":492,"lv":"yth"},{"x":"فعيش العاشق عيش الأسير الموثق، وعيش الخلي عيش المسيب المطلق","pg":493,"lv":"yth"},{"x":"والعشق مبادئه سهلة حلوة، وأوسطه هم وشغل قلب وسقم، وآخره عطب وقتل، إن لم يتداركه عناية من الله","pg":498,"lv":"yth"},{"x":"فخيره إليه نازل، وشره إليه صاعد، يتحبب إليه بنعمه وهو غني عنه، والعبد يتبغض إليه بالمعاصي وهو فقير إليه!","pg":536,"lv":"yth"},{"x":"والله سبحانه وتعالى يريدك لك","pg":536,"lv":"yth"},{"x":"ولا نسبة بين مفسدة هذا الأمر العظيم ومفسدة الفاحشة","pg":490,"lv":"adl"}],"concepts":[{"term":"طريقا الدواء","def":"أحدهما: حسم مادته قبل حصولها. والثاني: قلعها بعد نزولها.","pg":415},{"term":"الفراسة الصادقة","def":"فراسة صادقة يميز بها بين المحق والمبطل، والصادق والكاذب","pg":417},{"term":"سكر القلب","def":"فالتعلق بالصور يوجب فساد العقل، وعمه البصيرة، وسكر القلب","pg":418},{"term":"اشتغال القلب","def":"اشتغال القلب بما يصده عن ذلك، ويحول بينه وبين الوقوع فيه. وهو إما خوف مقلق، أو حب مزعج.","pg":422},{"term":"خاصة العقل","def":"بصيرة صحيحة يفرق بها بين درجات المحبوب والمكروه، فيؤثر أعلى المحبوبين على أدناهما، ويحتمل أدنى المكروهين ليخلص من أعلاهما","pg":422},{"term":"إمامة الدين","def":"وقد منع الله سبحانه إمامة الدين إلا من أهل الصبر واليقين","pg":423},{"term":"العشق","def":"هو الإفراط في المحبة بحيث يستولي المعشوق على قلب العاشق حتى لا يخلو من تخيله وذكره والفكر فيه، بحيث لا يغيب عن خاطره وذهنه","pg":497},{"term":"العبودية","def":"فإن العبودية هي كمال الحب والخضوع","pg":490},{"term":"الإله","def":"هو الذي تألهه القلوب بالمحبة والإجلال والتعظيم والذل والخضوع، وتعبده","pg":532},{"term":"الرائش","def":"وهو الواسطة بين الراشي والمرتشي في إيصال الرشوة","pg":501},{"term":"داعيا المحبة","def":"والمحبة لها داعيان: الجمال والإجلال","pg":533},{"term":"الولاية","def":"والولاية أصلها الحب، فلا موالاة إلا بحب","pg":534}],"stories":[{"t":"سفيان يبكي من خوف الخاتمة","x":"بكى سفيان الثوري ليلة إلى الصباح، فلما قيل له: كل هذا خوفا من الذنوب؟ أخذ تبنة من الأرض وقال: الذنوب أهون من هذا، وإنما أبكي من خوف الخاتمة.","pg":390,"lv":"yth"},{"t":"أبو الدرداء عند الاحتضار","x":"لما احتضر أبو الدرداء جعل يغمى عليه ثم يفيق فيقرأ: ﴿وَنُقَلِّبُ أَفْئِدَتَهُمْ وَأَبْصَارَهُمْ كَمَا لَمْ يُؤْمِنُوا بِهِ أَوَّلَ مَرَّةٍ﴾، فمن هذا خاف السلف من الذنوب أن تحجبهم عن حسن الخاتمة.","pg":390,"lv":"yth","hd":"أثر قال المحقق: ثابت صحيح"},{"t":"محتضرون غلبت عليهم أحوالهم","x":"نقل ابن القيم عن عبدالحق الإشبيلي أخبار محتضرين لقنوا الشهادة فلم يقولوها، وغلب على ألسنتهم ما شغلهم في حياتهم: رجل يردد مدح سلطانه، وآخر يوصي بإصلاح داره وبستانه، وثالث من أهل الحساب يقول: عشرة بأحد عشر.","pg":386,"lv":"yth","hd":"حكايات من كتاب العاقبة لعبدالحق، رويت بلا إسناد"},{"t":"مؤذن فتنته نظرة","x":"يروى أن رجلا بمصر كان يلزم المسجد للأذان والصلاة، وعليه بهاء الطاعة، فرقي المنارة يوما فنظر إلى ما لا يحل، فافتتن، وترك الأذان، ثم ترك دينه طمعا فيما تعلق به، ثم مات قبل أن يناله، ففاته الأمران.","pg":391,"lv":"adl","hd":"حكاية نقلها المؤلف عن العاقبة بصيغة يروى"},{"t":"شاه الكرماني وفراسته","x":"كان شاه الكرماني يقول: من عمر ظاهره باتباع السنة، وباطنه بدوام المراقبة، وغض بصره عن المحارم، وكف نفسه عن الشهوات، واغتذى بالحلال، لم تخطئ فراسته. وكان لا تخطئ له فراسة.","pg":417,"lv":"yth"},{"t":"غيرة سعد بن عبادة","x":"قال سعد بن عبادة: لو رأيت رجلا مع امرأتي لضربته بالسيف غير مصفح، فقال النبي ﷺ: «أتعجبون من غيرة سعد؟ والله لأنا أغير منه، والله أغير مني».","pg":378,"lv":"adl","hd":"متفق عليه، تقدم تخريجه عند المحقق ص 163"},{"t":"الحبر الذي لان مع ابنه","x":"رأى بعض أحبار بني إسرائيل ابنا له يغامز امرأة، فقال له: مهلا يا بني، فعوقب بما أصابه، وقيل له: هكذا غضبت لي؟ لا يكون في جنسك حبر أبدا. وفيه درس للآباء في الغضب لله وعدم التهاون.","pg":380,"lv":"adl","hd":"خبر إسرائيلي تقدم تخريجه عند المحقق ص 124"},{"t":"أهل العشق عند الموت","x":"أورد ابن القيم عن عبدالحق حكايتين لرجلين غلب عليهما التعلق المحرم، فكان آخر كلام أحدهما من الدنيا بيتا في محبوبته، ومات الآخر وهو يقدم رضا معشوقه على رحمة الله، عياذا بالله.","pg":387,"lv":"adl","hd":"حكايتان من العاقبة، والثانية في جذوة المقتبس"},{"t":"يوسف عليه السلام يختار السجن","x":"اجتمعت على يوسف عليه السلام دواعي المعصية كلها: شبابه وغربته وكونه في دار المرأة وتحت سلطانها، وغلق الأبواب، والتهديد بالسجن، فآثر مرضاة الله وخوفه، واستعان به، واختار السجن، فصرف الله عنه السوء والفحشاء بإخلاصه.","pg":482,"lv":"kid","hd":""},{"t":"الطيبة المطيبة وأهل الإفك","x":"استشهد ابن القيم بحادثة الإفك على أن أكثر الناس يصدق في هذا الباب بأدنى شبهة، فقد وقع أهل الإفك في أم المؤمنين عائشة رضي الله عنها بشبهة مجيء صفوان بن المعطل بها خلف العسكر، حتى تولى الله براءتها.","pg":500,"lv":"adl","hd":"البخاري 2661 ومسلم 2770"},{"t":"مؤذن فتن بالعشق","x":"ذكر ابن القيم عن كتاب العاقبة لعبد الحق أن بعض المؤذنين رأى امرأة نصرانية ففتن بها حتى ترك دينه، ثم سقط فمات، شاهدا على أن العشق ربما حمل على الكفر الصريح، وتلا: ﴿يثبت الله الذين آمنوا بالقول الثابت في الحياة الدنيا وفي الآخرة﴾ [إبراهيم 27].","pg":505,"lv":"adl","hd":""},{"t":"ابن عباس والشاب بعرفة","x":"رفع إلى ابن عباس بعرفة شاب نحل حتى عاد عظما بلا لحم، فقيل: به العشق، فجعل ابن عباس يستعيذ بالله من العشق عامة يومه.","pg":497,"lv":"adl","hd":"قال المحقق: سنده ضعيف.","weak":1}],"ready":true},{"k":"s11","t":"المحبة أصل كل دين","pgs":[424,482],"q":"لماذا لا يصلح القلب ولا يسعد إلا إذا أفرد الله بالمحبة؟","essence":"محبة الله وحده أصل السعادة والدين","kw":["المحبة","العبودية","التوحيد"],"daa":"تشتت القلب بمحبة غير الله وإشراك المخلوقين في محبته حتى يصير الإنسان عبدا لما يحب.","dawa":"إفراد الله بالمحبة، والتقرب إليه بالفرائض ثم بالنوافل، وإيثار المحبوب الأعلى الدائم على العاجل الزائل.","sections":[{"t":"لا يجتمع في القلب حب المحبوب الأعلى وعشق الصور","pg":424,"lv":"yth","key":"فلا يمكن أن يجتمع في القلب حب المحبوب الأعلى وعشق الصور أبدا، بل هما ضدان لا يتلاقيان، بل لابد أن يخرج أحدهما صاحبه.","p":["فمن كانت قوة حبه كلها للمحبوب الأعلى الذي محبة ما سواه باطلة وعذاب على صاحبها، صرفه ذلك عن محبة ما سواه. وإن أحبه لم يحبه إلا لأجله ولكونه وسيلة له إلى محبته، أو قاطعا له عما يضاد محبته وينقصها.","والمحبة الصادقة تقتضي توحيد المحبوب، وأن لا يشرك بينه وبين غيره في محبته.","بل من أعرض عن محبة الله وذكره والشوق إلى لقائه ابتلاه بمحبة غيره، فيعذبه بها في الدنيا وفي البرزخ وفي الآخرة."],"items":[{"h":"غيرة المحبوب","x":"فكيف بالحبيب الأعلى الذي لا تنبغي المحبة إلا له وحده، وكل محبة لغيره فهي عذاب على صاحبها ووبال؛ ولهذا لا يغفر الله سبحانه أن يشرك به في هذه المحبة، ويغفر ما دون ذلك لمن يشاء.","pg":424},{"h":"الاختيار بين المحبتين","x":"فليختر إحدى المحبتين، فإنهما لا تجتمعان في القلب ولا ترتفعان منه.","pg":425},{"h":"عبودية المحبوب","x":"فالإنسان عبد محبوبه كائنا ما كان","pg":425},{"h":"إله الهوى","x":"فمن لم يكن إلهه مالكه ومولاه، كان إلهه هواه. قال تعالى: ﴿أَفَرَأَيْتَ مَنِ اتَّخَذَ إِلَٰهَهُ هَوَاهُ وَأَضَلَّهُ اللَّهُ عَلَىٰ عِلْمٍ﴾ [الجاثية: 23]","pg":425}]},{"t":"خاصية التعبد ومراتب الحب","pg":426,"lv":"yth","key":"وخاصية التعبد: الحب مع الخضوع والذل للمحبوب، فمن أحب شيئا وخضع له فقد تعبد قلبه له.","p":["بل التعبد آخر مراتب الحب، ويقال له التتيم أيضا. فإن أول مراتبه: العلاقة، وسميت علاقة لتعلق القلب بالمحبوب.","ثم العشق، وهو إفراط المحبة. ولهذا لا يوصف به الرب تعالى، ولا يطلق في حقه."],"items":[{"h":"العلاقة","x":"وسميت علاقة لتعلق القلب بالمحبوب.","pg":426},{"h":"الصبابة","x":"ثم بعدها الصبابة، وسميت بذلك لانصباب القلب إلى المحبوب.","pg":426},{"h":"الغرام","x":"ثم الغرام، وهو لزوم الحب للقلب لزوما لا ينفك عنه.","pg":427},{"h":"العشق","x":"ثم العشق، وهو إفراط المحبة. ولهذا لا يوصف به الرب تعالى، ولا يطلق في حقه.","pg":427},{"h":"الشوق","x":"ثم الشوق، وهو سفر القلب إلى المحبوب أحث السفر. وقد جاء إطلاقه في حق الرب تعالى","pg":427},{"h":"التتيم","x":"ثم التتيم، وهو آخر مراتب الحب، وهو تعبد المحب لمحبوبه.","pg":438}]},{"t":"الشوق إلى لقاء الله وعيش المحبين","pg":427,"lv":"kid","key":"وأطيب العيش وألذه على الإطلاق عيش المحبين المشتاقين المستأنسين، فحياتهم هي الحياة الطيبة في الحقيقة، ولا حياة للعبد أطيب ولا أنعم ولا أهنأ منها.","p":["وهذا هو المعنى الذي عبر عنه النبي ﷺ بقوله: «من أحب لقاء الله أحب الله لقاءه».","وقال بعض أهل البصائر في قوله تعالى: ﴿مَن كَانَ يَرْجُو لِقَاءَ اللَّهِ فَإِنَّ أَجَلَ اللَّهِ لَآتٍ﴾ [العنكبوت: 5]: لما علم الله سبحانه شدة شوق أوليائه إلى لقائه، وأن قلوبهم لا تهدأ دون لقائه، ضرب لهم أجلا وموعدا للقاء تسكن نفوسهم به."],"items":[{"h":"دعاء عمار رضي الله عنه","x":"وأسألك لذة النظر إلى وجهك الكريم، وأسألك الشوق إلى لقائك، في غير ضراء مضرة ولا فتنة مضلة. اللهم زينا بزينة الإيمان، واجعلنا هداة مهتدين","pg":428},{"h":"الحياة الطيبة","x":"وهي الحياة الطيبة المذكورة في قوله تعالى: ﴿مَنْ عَمِلَ صَالِحًا مِّن ذَكَرٍ أَوْ أُنثَىٰ وَهُوَ مُؤْمِنٌ فَلَنُحْيِيَنَّهُ حَيَاةً طَيِّبَةً﴾ [النحل: 97]. ليس المراد منها الحياة المشتركة بين المؤمنين والكفار، والأبرار والفجار، من طيب المأكل والملبس والمشرب والمنكح","pg":429},{"h":"اجتماع الهم","x":"وأي حياة أطيب من حياة من اجتمعت همومه كلها، وصارت هما واحدا في مرضاة الله، ولم شعث قلبه بالإقبال على الله","pg":430}],"hd":"حديث عمار في الدعاء: أخرجه أحمد 18325 والنسائي 1305 وابن حبان 1971، وصححه ابن حبان والحاكم. «من أحب لقاء الله أحب الله لقاءه»: أخرجه البخاري 6507 ومسلم 2683. أما «طال شوق الأبرار إلى لقائي» فأثر إسرائيلي كما قال المؤلف في روضة المحبين."},{"t":"تفسير حديث «ما تقرب إلي عبدي»","pg":430,"lv":"kid","key":"حصر أسباب محبته في أمرين: أداء فرائضه، والتقرب إليه بالنوافل.","p":["«ما تقرب إلي عبدي بمثل أداء ما افترضت عليه. ولا يزال عبدي يتقرب إلي بالنوافل حتى أحبه. فإذا أحببته كنت سمعه الذي يسمع به، وبصره الذي يبصر به، ويده التي يبطش بها، ورجله التي يمشي بها.»","وأخبر سبحانه أن أداء فرائضه أحب ما تقرب به إليه المتقربون، ثم بعدها النوافل؛ وأن المحب لا يزال يكثر من النوافل حتى يصير محبوبا لله.","فإذا كان سمع العبد بالله وبصره بالله كان محفوظا في آلات إدراكه، وكان محفوظا في حبه وبغضه، فحفظ في بطشه ومشيه."],"items":[{"h":"المحبة الثانية","x":"فإذا صار محبوبا لله أوجبت محبة الله له محبة أخرى منه لله، فوق المحبة الأولى، فشغلت هذه المحبة قلبه عن الفكرة والاهتمام بغير محبوبه","pg":432},{"h":"مسألة حالية","x":"وهي مصاحبة لا نظير لها، ولا تدرك بمجرد الإخبار عنها والعلم بها، فالمسألة حالية لا علمية محضة.","pg":432},{"h":"لماذا السمع والبصر واليد والرجل","x":"فإن هذه الآلات آلات الإدراك، وآلات الفعل، والسمع والبصر يوردان على القلب الإرادة والكراهة، ويجلبان إليه الحب والبغض، فيستعمل اليد والرجل.","pg":434},{"h":"المعية الخاصة","x":"فمتى كان العبد بالله هانت عليه المشاق، وانقلبت المخاوف في حقه أمانا. فبالله يهون كل صعب، ويسهل كل عسير، ويقرب كل بعيد.","pg":436},{"h":"لا هم مع الله","x":"وبالله تزول الهموم والغموم والأحزان. فلا هم مع الله، ولا غم، ولا حزن، إلا حيث يفوته معنى هذه الباء. فيصير قلبه حينئذ كالحوت إذا فارق الماء، يثب ويتقلب حتى يعود إليه.","pg":437},{"h":"حكمة التدبير","x":"فإنه ما أماته إلا ليحييه، ولا أمرضه إلا ليصحه، ولا أفقره إلا ليغنيه، ولا منعه إلا ليعطيه، ولم يخرجه من الجنة في صلب أبيه إلا ليعيده إليها على أحسن أحواله","pg":437},{"h":"الحبيب على الحقيقة","x":"فهذا هو الحبيب على الحقيقة لا سواه، بل لو كان في كل منبت شعرة من العبد محبة تامة لله لكان بعض ما يستحقه على عبده","pg":438}],"hd":"أخرجه البخاري 6502 من حديث أبي هريرة، ما عدا قوله «فبي يسمع، وبي يبصر، وبي يبطش، وبي يمشي»، فهذه الزيادة قال فيها الألباني فيما نقله المحقق: لم أر هذه الزيادة عند البخاري ولا عند غيره ممن ذكرنا من المخرجين. «أنا مع عبدي ما ذكرني وتحركت بي شفتاه»: علقه البخاري في التوحيد، ووصله ابن حبان وغيره، وقال المحقق: سند صحيح. «ما ظنك باثنين الله ثالثهما»: البخاري 3653 ومسلم 2381."},{"t":"التتيم والعبودية أشرف المقامات","pg":438,"lv":"kid","key":"ولهذا كانت أشرف أحوال العبد ومقاماته هي العبودية، فلا منزل له أشرف منها.","p":["وحقيقة التعبد: الذل والخضوع للمحبوب. ومنه قولهم: طريق معبد أي مذلل قد ذللته الأقدام. فالعبد هو الذي ذلله الحب والخضوع لمحبوبه.","وقد ذكر الله سبحانه أكرم الخلق عليه وأحبهم إليه وهو رسوله محمد ﷺ بالعبودية في أشرف مقاماته، وهي: مقام الدعوة إليه، ومقام التحدي بالنبوة، ومقام الإسراء.","فنال مقام الشفاعة بكمال عبوديته وكمال مغفرة الله له."],"items":[{"h":"مقام الدعوة","x":"﴿وَأَنَّهُ لَمَّا قَامَ عَبْدُ اللَّهِ يَدْعُوهُ﴾ [الجن: 19]","pg":438},{"h":"مقام التحدي","x":"﴿وَإِن كُنتُمْ فِي رَيْبٍ مِّمَّا نَزَّلْنَا عَلَىٰ عَبْدِنَا﴾ [البقرة: 23]","pg":438},{"h":"مقام الإسراء","x":"﴿سُبْحَانَ الَّذِي أَسْرَىٰ بِعَبْدِهِ لَيْلًا﴾ [الإسراء: 1]","pg":438},{"h":"مقام الشفاعة","x":"«اذهبوا إلى محمد، عبد غفر الله له ما تقدم من ذنبه وما تأخر»","pg":439}],"hd":"حديث الشفاعة: أخرجه البخاري 7410 ومسلم 193 من حديث أنس."},{"t":"أصل الشرك الإشراك في المحبة","pg":439,"lv":"yth","key":"وأصل الشرك بالله الإشراك به في المحبة","p":["والله سبحانه خلق الخلق لعبادته وحده لا شريك له، التي هي أكمل أنواع المحبة، مع أكمل أنواع الخضوع والذل. وهذا هو حقيقة الإسلام وملة إبراهيم التي من رغب عنها فقد سفه نفسه.","ولهذا كان أعظم الذنوب عند الله الشرك، والله لا يغفر أن يشرك به.","فأخبر سبحانه أن من الناس من يشرك به، فيتخذ من دونه ندا يحبه كحب الله؛ وأخبر أن الذين آمنوا أشد حبا لله من أصحاب الأنداد لأندادهم."],"items":[{"h":"العدل بالله","x":"والعدل برب العالمين والتسوية بينه وبين الأنداد هو في هذه المحبة","pg":440},{"h":"الولي والشفيع","x":"فإذا والى العبد ربه وحده أقام له الشفعاء، وعقد الموالاة بينه وبين عباده المؤمنين، فصاروا أولياءه في الله، بخلاف من اتخذ مخلوقا وليا من دون الله.","pg":441},{"h":"فرقان التوحيد","x":"فهذا لون وذاك لون، كما أن الشفاعة الشركية الباطلة لون، والشفاعة الحق الثابتة التي إنما تنال بالتوحيد لون. وهذا موضع فرقان بين أهل التوحيد وأهل الإشراك.","pg":441},{"h":"محبة الرسول ﷺ","x":"فإن محبة الرسول بل تقديمه في الحب على الأنفس والآباء والأبناء لا يتم الإيمان إلا بها، إذ محبته من محبة الله. وكذلك كل حب في الله ولله","pg":441},{"h":"حلاوة الإيمان","x":"«ثلاث من كن فيه وجد حلاوة الإيمان: أن يكون الله ورسوله أحب إليه مما سواهما، وأن يحب المرء لا يحبه إلا لله، وأن يكره أن يرجع في الكفر بعد إذ أنقذه الله منه، كما يكره أن يلقى في النار»","pg":441}],"hd":"«ثلاث من كن فيه»: البخاري 16 و6041 ومسلم 43. «من أحب لله وأبغض لله وأعطى لله ومنع لله فقد استكمل الإيمان»: أخرجه أبو داود 4681 وغيره، وذكر المحقق اختلافا في رفعه ووقفه وضعفا في بعض طرقه. «ما تحاب رجلان في الله إلا كان أفضلهما أشدهما حبا لصاحبه»: صححه ابن حبان والحاكم، وقال المحقق: رفعه خطأ، والصواب أنه من قول مطرف بن عبدالله بن الشخير."},{"t":"أنواع المحبة","pg":443,"lv":"yth","key":"وهاهنا أربعة أنواع من المحبة يجب التفريق بينها، وإنما ضل من ضل بعدم التمييز بينها","p":["فإن هذه المحبة من لوازم محبة الله وموجباتها وكلما كانت أقوى كان أصلها كذلك."],"items":[{"h":"محبة الله","x":"أحدها: محبة الله. ولا تكفي وحدها في النجاة من عذابه والفوز بثوابه، فإن المشركين وعباد الصليب واليهود وغيرهم يحبون الله.","pg":443},{"h":"محبة ما يحبه الله","x":"الثاني: محبة ما يحبه الله. وهذه هي التي تدخله في الإسلام، وتخرجه من الكفر؛ وأحب الناس إلى الله أقومهم بهذه المحبة وأشدهم فيها.","pg":443},{"h":"الحب لله وفيه","x":"الثالث: الحب لله وفيه. وهي من لوازم محبة ما يحب، ولا تستقيم محبة ما يحب إلا بالحب فيه وله.","pg":444},{"h":"المحبة مع الله","x":"الرابع: المحبة مع الله. وهي المحبة الشركية، وكل من أحب شيئا مع الله، لا لله ولا من أجله ولا فيه، فقد اتخذه ندا من دون الله، وهذه محبة المشركين.","pg":444},{"h":"المحبة الطبعية","x":"وبقي قسم خامس: ليس مما نحن فيه، وهو المحبة الطبعية، وهي ميل الإنسان إلى ما يلائم طبعه، كمحبة العطشان للماء، والجائع للطعام، ومحبة النوم والزوجة والولد. فتلك لا تذم إلا إذا ألهت عن ذكر الله وشغلت عن محبته.","pg":444}]},{"t":"الخلة","pg":444,"lv":"adl","key":"ثم الخلة، وهي تتضمن كمال المحبة ونهايتها، بحيث لا يبقى في قلب المحب سعة لغير محبوبه، وهي منصب لا يقبل المشاركة بوجه ما.","p":["وهذا المنصب خلص لخليلين صلوات الله وسلامه عليهما: إبراهيم ومحمد، كما قال ﷺ: «إن الله اتخذني خليلا، كما اتخذ إبراهيم خليلا».","ولم يكن المقصود ذبح الولد، ولكن المقصود ذبحه من قلبه، ليخلص القلب للرب. فلما بادر الخليل إلى الامتثال، وقدم محبة الله على محبة ولده؛ حصل المقصود، فرفع الذبح، وفدي بذبح عظيم.","فإن المحبة عامة، والخلة خاصة، والخلة نهاية المحبة."],"items":[{"h":"خلة لا تقبل الشركة","x":"«لو كنت متخذا من أهل الأرض خليلا لاتخذت أبا بكر خليلا، ولكن صاحبكم خليل الله»","pg":445},{"h":"ما أمر الله بشيء ثم أبطله رأسا","x":"فإن الرب تعالى ما أمر بشيء ثم أبطله رأسا، بل لابد أن يبقى بعضه أو بدله، كما أبقى شرعية الفداء، وكما أبقى استحباب الصدقة بين يدي المناجاة، وكما أبقى الخمس صلوات بعد رفع الخمسين وأبقى ثوابها","pg":445},{"h":"غلط من فضل المحبة على الخلة","x":"وأما ما يظنه بعض الغالطين أن المحبة أكمل من الخلة، وأن إبراهيم خليل الله، ومحمد حبيب الله، فمن جهله.","pg":446},{"h":"عموم المحبة","x":"وأيضا فإن الله سبحانه يحب التوابين، ويحب المتطهرين، ويحب الصابرين، ويحب المحسنين، ويحب المتقين، ويحب المقسطين. وخلته خاصة بالخليلين.","pg":446}],"hd":"«إن الله اتخذني خليلا»: مسلم 532. «لو كنت متخذا خليلا»: مسلم 2383. «إني أبرأ إلى كل خليل من خلته»: مسلم 2383. «لا يبدل القول لدي، هي خمس، وهي خمسون في الأجر»: البخاري 349 ومسلم 163. وعبارة «والشاب التائب حبيب الله» في 446 ذكر المحقق أنها رويت بلفظ «إن الله يحب الشاب التائب» بسند ضعيف.","weak":1},{"t":"العاقل يؤثر أعلى المحبوبين","pg":447,"lv":"yth","key":"وتقدم أن خاصية العقل إيثار أعلى المحبوبين على أدناهما، وأيسر المكروهين على أقواهما.","p":["وقد تقدم أن العبد لا يترك ما يحبه ويهواه إلا لما يحبه ويهواه، لكن يترك أضعفهما محبة لأقواهما محبة","ولا يتم له هذا إلا بأمرين: قوة الإدراك، وشجاعة القلب.","فإذا صح إدراكه، وقويت نفسه، وتشجع القلب على إيثار المحبوب الأعلى والمكروه الأدنى؛ فقد وفق لأسباب السعادة."],"items":[{"h":"سلطان الشهوة وسلطان الإيمان","x":"فمن الناس من يكون سلطان شهوته أقوى من سلطان عقله وإيمانه، فيقهر الغالب الضعيف. ومنهم من يكون سلطان إيمانه وعقله أقوى من سلطان شهوته.","pg":448},{"h":"مثل المريض","x":"وإذا كان كثير من المرضى يحميه الطبيب عما يضره، فتأبى عليه نفسه وشهوته إلا تناوله، ويقدم شهوته على عقله، وتسميه الأطباء عديم المروءة؛ فهكذا أكثر مرضى القلوب يؤثرون ما يزيد مرضهم لقوة شهوتهم له.","pg":448},{"h":"أصل الشر وأصل الخير","x":"فأصل الشر من ضعف الإدراك، وضعف النفس ودناءتها. وأصل الخير من كمال الإدراك، وقوة النفس وشرفها وشجاعتها.","pg":448}]},{"t":"الحب والإرادة أصل كل فعل","pg":448,"lv":"adl","key":"فالحب والإرادة أصل كل فعل ومبدؤه، والبغض والكراهة أصل كل ترك ومبدؤه. وهاتان القوتان في القلب أصل سعادة العبد وشقاوته.","p":["ووجود الفعل الاختياري لا يكون إلا بوجود سببه من الحب والإرادة. وأما عدم الفعل فتارة يكون لعدم مقتضيه وسببه، وتارة يكون لوجود البغض والكراهة المانع منه. وهذا متعلق الأمر والنهي، وهو الذي يسمى الكف، وهو متعلق الثواب والعقاب.","والتحقيق أنه قسمان: فالترك المضاف إلى عدم السبب المقتضي عدمي، والمضاف إلى السبب المانع من الفعل وجودي."],"items":[{"h":"علة الفعل والترك","x":"وكل واحد من الفعل والترك الاختياريين إنما يؤثره الحي لما فيه من حصول المنفعة التي يلتذ بحصولها، أو زوال الألم الذي يحصل له الشفاء بزواله.","pg":449},{"h":"الغلط القبيح","x":"ولكن يغلط فيه أكثر الناس غلطا قبيحا، فيقصد حصول اللذة بما يعقب عليه أعظم الألم، فيؤلم نفسه من حيث يظن أنه يحصل لذتها، ويشفي قلبه بما يعقب عليه غاية المرض.","pg":449}]},{"t":"أعقل الناس من آثر اللذة الدائمة","pg":450,"lv":"yth","key":"وخاصة العقل: النظر في العواقب، فأعقل الناس من آثر لذته وراحته الآجلة الدائمة على العاجلة المنقضية الزائلة","p":["وهذا شأن من قصر نظره على العاجل، ولم يلاحظ العواقب.","وأسفه الخلق من باع نعيم الأبد وطيب الحياة الدائمة واللذة العظمى التي لا تنغيص فيها ولا نقص بوجه ما، بلذة منغصة مشوبة بالآلام والمخاوف، وهي سريعة الزوال وشيكة الانقضاء."],"items":[{"h":"مطلوب العقلاء","x":"قال بعض العلماء: فكرت فيما يسعى فيه العقلاء، فرأيت سعيهم كله في مطلوب واحد، وإن اختلفت طرقهم في تحصيله؛ رأيتهم جميعهم إنما يسعون في دفع الهم والغم عن نفوسهم.","pg":450},{"h":"الطريق الموصلة","x":"ولم أر في جميع هذه الطرق طريقا موصلة إلا الإقبال على الله ومعاملته وحده، وإيثار مرضاته على كل شيء.","pg":450},{"h":"الحظ العالي","x":"فإن سالك هذا الطريق إن فاته حظه من الدنيا فقد ظفر بالحظ العالي الذي لا فوت معه، وإن حصل للعبد حصل له كل شيء، وإن فاته فاته كل شيء. وإن ظفر بحظه من الدنيا ناله على أهنأ الوجوه.","pg":451}]},{"t":"المحبوب قسمان","pg":451,"lv":"yth","key":"والمحبوب قسمان: محبوب لنفسه، ومحبوب لغيره. والمحبوب لغيره لابد أن ينتهي إلى المحبوب لنفسه، دفعا للتسلسل المحال.","p":["وكل ما سوى المحبوب الحق فهو محبوب لغيره، وليس شيء يحب لنفسه إلا الله وحده، وكل ما سواه مما يحب فإنما محبته تبع لمحبة الرب تعالى، كمحبة ملائكته وأنبيائه وأوليائه","وهذا موضع يجب الاعتناء به، فإنه محل فرقان بين المحبة النافعة لغيره، والتي لا تنفع، بل قد تضر.","والمحبوب لغيره قسمان أيضا: أحدهما: ما يلتذ المحب بإدراكه وحصوله. والثاني: ما يتألم به، ولكن يحتمله لإفضائه إلى محبوبه، كشرب الدواء الكريه."],"items":[{"h":"مكروه يوصل إلى مكروه","x":"فالأمور أربعة: مكروه يوصل إلى مكروه.","pg":453},{"h":"مكروه يوصل إلى محبوب","x":"ومكروه يوصل إلى محبوب.","pg":453},{"h":"محبوب يوصل إلى محبوب","x":"ومحبوب يوصل إلى محبوب.","pg":453},{"h":"محبوب يوصل إلى مكروه","x":"ومحبوب يوصل إلى مكروه.","pg":453},{"h":"معترك الابتلاء","x":"بقي القسمان الآخران يتجاذبهما الداعيان، وهما معترك الابتلاء والامتحان. فالنفس تؤثر أقربهما جوارا منها، وهو العاجل. والعقل والإيمان يؤثران أنفعهما وأبقاهما. والقلب بين الداعيين، وهو إلى هذا مرة، وإلى هذا مرة.","pg":454},{"h":"نداء العقل والإيمان","x":"فداعي العقل والإيمان ينادي كل وقت: حي على الفلاح، عند الصباح يحمد القوم السرى، وفي الممات يحمد العبد التقى.","pg":454}]},{"t":"ميزان الموالاة والمعاداة","pg":452,"lv":"yth","key":"فالولاية عبارة عن موافقة الولي الحميد في محابه ومساخطه، ليست بكثرة صوم ولا صلاة ولا تمزق ولا رياضة.","p":["فهذا ميزان عادل يوزن به موافقة الرب ومخالفته، وموالاته ومعاداته. فإذا رأينا شخصا يحب ما يكرهه الرب تعالى، ويكره ما يحبه، علمنا أن فيه من معاداته بحسب ذلك.","فتمسك بهذا الأصل غاية التمسك في نفسك وفي غيرك."],"items":[{"h":"أصل الميزان","x":"فاعلم أنه لا يحب لذاته إلا من كماله من لوازم ذاته، وإلهيته وربوبيته وغناه من لوازم ذاته. وما سواه فإنما يبغض ويكره لمنافاته محابه ومضادته لها","pg":451}]},{"t":"حب الله ورسوله أصل الأعمال الدينية، ولا ولاء إلا ببراء","pg":455,"lv":"adl","key":"وإذا كان الحب أصل كل عمل من حق وباطل، فأصل الأعمال الدينية حب الله ورسوله، كما أن أصل الأقوال الدينية تصديق الله ورسوله.","p":["وكل إرادة تمنع كمال الحب لله ورسوله وتزاحم هذه المحبة، أو شبهة تمنع كمال التصديق؛ فهي معارضة لأصل الإيمان أو مضعفة له. فإن قويت حتى عارضت أصل الحب والتصديق كانت كفرا وشركا أكبر، وإن لم تعارضه قدحت في كماله، وأثرت فيه ضعفا وفتورا في العزيمة والطلب. وهي تحجب الواصل، وتقطع الطالب، وتنكس الراغب.","فلا تصح الموالاة إلا بالمعاداة"],"items":[{"h":"خلة إبراهيم والبراءة","x":"فلم تصح لخليل الله هذه الموالاة والخلة إلا بتحقيق هذه المعاداة فإنه لا ولاء إلا ببراء، ولا ولاء لله إلا بالبراءة من كل معبود سواه.","pg":455},{"h":"الكلمة الباقية","x":"أي جعل هذه الموالاة لله والبراءة من كل معبود سواه كلمة باقية في عقبه، يتوارثها الأنبياء وأتباعهم بعضهم عن بعض. وهي كلمة لا إله إلا الله","pg":456}]},{"t":"روح كلمة لا إله إلا الله","pg":456,"lv":"adl","key":"وروح هذه الكلمة وسرها: إفراد الرب جل ثناؤه، وتقدست أسماؤه، وتبارك اسمه، وتعالى جده، ولا إله غيره، بالمحبة والإجلال والتعظيم والخوف والرجاء، وتوابع ذلك من التوكل والإنابة والرغبة والرهبة.","p":["وهي الكلمة التي قامت بها الأرض والسماوات، وفطر الله عليها جميع المخلوقات. وهي كلمة الإسلام، ومفتاح دار السلام.","ويجتمع ذلك كله في حرف واحد، وهو أن لا يعبد إلا إياه بجميع أنواع العبادة؛ فهذا هو تحقيق شهادة أن لا إله إلا الله.","فحياة الروح بحياة هذه الكلمة فيها، كما أن حياة البدن بوجود الروح فيه."],"items":[{"h":"مراتب الشهادة في القلوب","x":"فإن من الناس من تكون شهادته ميتة، ومنهم من تكون نائمة إذا نبهت انتبهت، ومنهم من تكون مضطجعة، ومنهم من تكون إلى القيام أقرب.","pg":458},{"h":"جنة الدنيا","x":"فمن كانت هذه الجنة مأواه هاهنا، كانت جنة الخلد مأواه يوم المعاد. ومن حرم هذه الجنة، فهو لتلك أشد حرمانا.","pg":459},{"h":"الأبرار والفجار","x":"والأبرار في النعيم، وإن اشتد بهم العيش، وضاقت عليهم الدنيا. والفجار في جحيم، وإن اتسعت عليهم الدنيا.","pg":459},{"h":"شرح الصدر","x":"فأي نعيم أطيب من شرح الصدر؟ وأي عذاب أمر من ضيق الصدر؟","pg":459},{"h":"الجنة العاجلة","x":"فالمؤمن المخلص لله من أطيب الناس عيشا، وأنعمهم بالا، وأشرحهم صدرا، وأسرهم قلبا. وهذه جنة عاجلة قبل الجنة الآجلة.","pg":459},{"h":"غذاء القلب","x":"فأخبر ﷺ أن ما يحصل له من الغذاء عند ربه يقوم مقام الطعام والشراب الحسي","pg":460}],"hd":"«ومن كان آخر كلامه لا إله إلا الله دخل الجنة»: أخرجه أبو داود 3116 وأحمد والحاكم وقال: صحيح الإسناد، وذكر المحقق أن فيه صالح بن أبي عريب قال فيه ابن حجر: مقبول، وأورد له شاهدا عند مسلم 26 «من مات وهو يعلم أنه لا إله إلا الله دخل الجنة». «إني لأعلم كلمة لا يقولها عبد عند الموت إلا وجدت روحه لها روحا»: ابن ماجه 3795 وابن حبان 205، وقال المحقق: سنده صحيح. «إذا مررتم برياض الجنة فارتعوا»: ضعيف، تقدم تخريجه 281 وفيه محمد بن ثابت البناني ضعيف وطرقه كلها لا تصح. «ما بين بيتي ومنبري روضة من رياض الجنة»: البخاري 1195 و1196 ومسلم 1390 و1391. «إني لست كهيئتكم، إني أظل عند ربي يطعمني ويسقيني»: البخاري 1964 ومسلم 1105.","weak":1},{"t":"لا شيء أنفع للعبد من الإقبال على الله","pg":461,"lv":"kid","key":"ولا شيء على الإطلاق أنفع للعبد من إقباله على الله، واشتغاله بذكره، وتنعمه بحبه، وإيثاره لمرضاته؛ بل لا حياة له ولا نعيم ولا سرور ولا بهجة إلا بذلك.","p":["وكلما كان وجود الشيء أنفع للعبد وهو إليه أحوج، كان تألمه بفقده أشد. وكلما كان عدمه أنفع له كان تألمه بوجوده أشد.","فعدمه آلم شيء له، وأشده عذابا عليه. وإنما يغيب الروح عن شهود هذا الألم والعذاب اشتغالها بغيره، واستغراقها في ذلك الغير"],"items":[{"h":"مثل السكران","x":"وهذا بمنزلة السكران، المستغرق في سكره، الذي احترقت داره وأمواله وأهله وأولاده، وهو لاستغراقه في السكر لا يشعر بألم ذلك الفوت وحسرته، حتى إذا صحا وكشف عنه غطاء السكر، وانتبه من رقدة الخمر، فهو أعلم بحاله حينئذ.","pg":461},{"h":"ما لا عوض عنه","x":"فإن المصاب في الدنيا يرجو جبر مصيبته بالعوض، ويعلم أنه قد أصيب بشيء زائل لا بقاء له؛ فكيف بمن مصيبته بما لا عوض عنه، ولا بدل منه","pg":462},{"h":"اعرض على نفسك","x":"فاعرض الآن على نفسك أعظم محبوب لك في الدنيا بحيث لا تطيب لك الحياة إلا معه، فأصبحت وقد أخذ منك، وحيل بينك وبينه، أحوج ما كنت إليه، كيف يكون حالك؟ هذا، ومنه كل عوض، فكيف بمن لا عوض عنه؟","pg":462},{"h":"بيت شعر","x":"من كل شيء إذا ضيعته عوض ... وما من الله إن ضيعته عوض","pg":462}],"hd":"الأثر الإلهي «ابن آدم خلقتك لعبادتي فلا تلعب...» أثر إسرائيلي كما نص عليه شيخ الإسلام في الفتاوى 8/52، فيما نقله المحقق."},{"t":"أصل السعادة محبة الله","pg":463,"lv":"kid","key":"وأعظم أنواعها المحمودة: محبة الله وحده، ومحبة ما أحب. وهذه المحبة هي أصل السعادة ورأسها، التي لا ينجو أحد من العذاب إلا بها.","p":["وأعظم أنواع المحبة المذمومة: المحبة مع الله، التي يسوي المحب فيها بين محبته لله ومحبته للند الذي اتخذه من دونه.","وأصل دعوة جميع الرسل من أولهم إلى آخرهم إنما هو عبادة الله وحده لا شريك له، المتضمنة لكمال حبه، وكمال الخضوع والذل له، والإجلال والتعظيم، ولوازم ذلك من الطاعة والتقوى.","فإن الواجب له من ذلك أن يكون أحب إلى العبد من ولده ووالده، بل من سمعه وبصره ونفسه التي بين جنبيه؛ فيكون إلهه الحق ومعبوده أحب إليه من ذلك كله."],"items":[{"h":"مدار القرآن","x":"ومدار القرآن على الأمر بتلك المحبة ولوازمها، والنهي عن المحبة الأخرى ولوازمها","pg":464},{"h":"محبة النبي ﷺ","x":"«والذي نفسي بيده، لا يؤمن أحدكم حتى أكون أحب إليه من ولده ووالده والناس أجمعين»","pg":464},{"h":"قصة عمر","x":"يا رسول الله، والله لأنت أحب إلي من كل شيء إلا من نفسي. فقال: «لا يا عمر، حتى أكون أحب إليك من نفسك». فقال: والذي بعثك بالحق لأنت أحب إلي من نفسي. قال: «الآن يا عمر».","pg":465},{"h":"التأله","x":"وليس شيء يحب لذاته من كل وجه إلا الله وحده، ولا تصلح الألوهية إلا له، والتأله هو المحبة، والطاعة، والخضوع.","pg":465}],"hd":"«لا يؤمن أحدكم حتى أكون أحب إليه»: البخاري 15 ومسلم 44 من حديث أنس. حديث عمر: البخاري 6632 من حديث عبدالله بن هشام."},{"t":"كل حركة في العالم أصلها المحبة","pg":466,"lv":"adl","key":"وكل حركة في العالم العلوي والسفلي فأصلها المحبة، فهي علتها الفاعلية والغائية.","p":["وذلك لأن الحركات ثلاثة أنواع: حركة اختيارية إرادية، وحركة طبيعية، وحركة قسرية. والحركة الاختيارية الإرادية هي أصل الحركتين الأخريين، وهي تابعة للإرادة والمحبة، فصارت الحركات الثلاث تابعة للمحبة والإرادة.","إذا عرف ذلك فكل حي له إرادة ومحبة وعمل بحسبه، وكل متحرك فأصل حركته المحبة والإرادة. ولا صلاح للموجودات إلا بأن تكون حركاتها ومحبتها لفاطرها وبارئها وحده، كما لا وجود لها إلا بإبداعه وحده."],"items":[{"h":"الملائكة الموكلة","x":"فإن الله وكل بالرحم ملائكة، وبالقطر ملائكة، وبالنبات ملائكة، وبالرياح، وبالأفلاك، وبالشمس والقمر والنجوم.","pg":467},{"h":"لولا الحب","x":"فلولا الحب ما دارت الأفلاك، ولا تحركت الكواكب النيرات، ولا هبت الرياح المسخرات، ولا مرت السحب الحاملات","pg":469},{"h":"دليل الوحدانية","x":"فصلاح السماوات والأرض واستقامتهما وانتظام أمر المخلوقات على أتم نظام من أظهر الأدلة على أنه لا إله إلا الله وحده لا شريك له","pg":471},{"h":"فساد التعدد","x":"وأصل فساد العالم إنما هو من اختلاف الملوك والخلفاء. ولهذا لم يطمع أعداء الإسلام فيه في زمن من الأزمنة إلا في زمن تعدد ملوك المسلمين واختلافهم وانفراد كل منهم ببلاد، وطلب بعضهم العلو على بعض.","pg":471},{"h":"قول شيخ الإسلام في آية الإسراء","x":"قال شيخنا: والصحيح أن المعنى: لابتغوا إليه سبيلا بالتقرب إليه وطاعته، فكيف تعبدونهم من دونه، وهم لو كانوا آلهة كما تقولون لكانوا عبيدا له؟","pg":472}]},{"t":"آثار المحبة وتوابعها","pg":473,"lv":"yth","key":"والمحبة المحمودة هي المحبة النافعة التي تجلب لصاحبها ما ينفعه في دنياه وآخرته، وهذه المحبة هي عنوان سعادته، والضارة هي التي تجلب لصاحبها ما يضره في دنياه وآخرته، وهي عنوان شقاوته.","p":["والمحبة لها آثار وتوابع ولوازم وأحكام، سواء كانت محمودة أو مذمومة، نافعة أو ضارة، من الذوق، والوجد، والحلاوة، والشوق، والأنس، والاتصال بالمحبوب والقرب منه، والانفصال عنه والبعد منه، والصد والهجران، والفرح والسرور، والبكاء والحزن، وغير ذلك من أحكامها ولوازمها.","فالمحبة النافعة المحمودة التي هي عنوان سعادة العبد، توابعها كلها نافعة له، حكمها حكم متبوعها. فإن بكى نفعه، وإن حزن نفعه، وإن فرح نفعه، وإن انقبض نفعه، وإن انبسط نفعه."],"items":[{"h":"منشأ المحبة الفاسدة","x":"فلا تقع المحبة الفاسدة إلا من جهل واعتقاد فاسد، أو هوى غالب، أو ما تركب من ذلك، وأعان بعضه بعضا","pg":474},{"h":"جيشان","x":"فيتساعد جيش الشبهة والشهوة على جيش العقل والإيمان، والغلبة لأقواهما.","pg":474},{"h":"المحبة الضارة","x":"والمحبة الضارة المذمومة، توابعها وآثارها كلها ضارة لصاحبها، مبعدة له من ربه، كيفما تقلب في آثارها ونزل في منازلها فهو في خسارة وبعد.","pg":475},{"h":"ما تولد عن الطاعة والمعصية","x":"فكل ما تولد عن الطاعة فهو زيادة لصاحبه وقربة، وكل ما تولد عن المعصية فهو خسران لصاحبه وبعد.","pg":475}]},{"t":"المحبة أصل كل دين","pg":476,"lv":"adl","key":"وكما أن المحبة والإرادة أصل كل فعل كما تقدم، فهي أصل كل دين سواء كان حقا أو باطلا.","p":["فإن الدين هو من الأعمال الباطنة والظاهرة، والمحبة والإرادة أصل ذلك كله. والدين هو الطاعة والعادة والخلق. فهو الطاعة اللازمة الدائمة التي صارت خلقا وعادة.","والدين الباطن لابد فيه من الحب والخضوع كالعبادة سواء، بخلاف الدين الظاهر فإنه لا يستلزم الحب، وإن كان فيه انقياد وذل في الظاهر."],"items":[{"h":"تفسير الخلق بالدين","x":"ولهذا فسر الخلق بالدين في قوله تعالى: ﴿وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٍ﴾ [القلم: 4]. قال ابن عباس: لعلى دين عظيم.","pg":476},{"h":"خلق النبي ﷺ","x":"وسئلت عائشة عن خلق رسول الله ﷺ، فقالت: كان خلقه القرآن.","pg":476},{"h":"معنيا الدين","x":"والدين فيه معنى الإذلال والقهر، وفيه معنى الذل والخضوع والطاعة. فلذلك يكون من الأعلى إلى الأسفل","pg":476},{"h":"يوم الدين","x":"وسمى الله سبحانه يوم القيامة يوم الدين لأنه اليوم الذي يدين فيه الناس بأعمالهم، إن خيرا فخير، وإن شرا فشر.","pg":477}],"hd":"أثر ابن عباس: أخرجه الطبري وقال المحقق: سنده حسن. قول عائشة: مسلم 746."},{"t":"الدين دينان","pg":479,"lv":"adl","key":"والدين دينان: دين شرعي أمري، ودين حسابي جزائي. وكلاهما لله وحده، فالدين كله لله أمرا أو جزاء. والمحبة أصل كل واحد من الدينين.","p":["فإن ما شرعه سبحانه وأمر به يحبه ويرضاه، وما نهى عنه فإنه يكرهه ويبغضه لمنافاته لما يحبه ويرضاه، فهو يحب ضده. فعاد دينه الأمري كله إلى محبته ورضاه. ودين العبد لله به إنما يقبل إذا كان عن محبة ورضى","وكذلك دينه الجزائي، فإنه يتضمن مجازاة المحسن بإحسانه والمسيء بإساءته، وكل من الأمرين محبوب للرب، فإنهما عدله وفضله، وكلاهما من صفات كماله. وهو سبحانه يحب أسماءه وصفاته، ويحب من يحبها."],"items":[{"h":"ذوق طعم الإيمان","x":"«ذاق طعم الإيمان من رضي بالله ربا، وبالإسلام دينا، وبمحمد رسولا». فهذا الدين قائم بالمحبة، وبسببها شرع، ولأجلها شرع، وعليها أسس.","pg":479},{"h":"فضل وعدل","x":"إن أعطى وأكرم وهدى ووفق، فبفضله ورحمته. وإن منع وأهان وأضل وخذل وأشقى، فبعدله وحكمته. وهو على صراط مستقيم في هذا وهذا.","pg":481},{"h":"دعاء الهم والحزن","x":"«اللهم إني عبدك، ابن عبدك، ابن أمتك؛ ناصيتي بيدك، ماض في حكمك، عدل في قضاؤك»","pg":481},{"h":"الحكمان","x":"وهذا يتناول حكم الرب الكوني والأمري وقضاءه الذي يكون باختيار العبد وغير اختياره، فكلا الحكمين ماض في عبده، وكلا القضائين عدل فيه.","pg":482}],"hd":"«ذاق طعم الإيمان»: مسلم 34 من حديث العباس. حديث «ما أصاب عبدا قط هم ولا حزن»: تقدم تخريجه 22 و23، صححه ابن حبان والحاكم والمؤلف وحسنه ابن حجر، وذكر المحقق في إسناده كلاما (عدم سماع عبدالرحمن من أبيه إلا القليل، وجهالة أبي سلمة إن لم يكن موسى بن عبدالله)."}],"lv":{"kid":{"show":true,"title":"أحب الله أكثر من كل شيء","intro":"يسعد القلب إذا أحب الله سبحانه أكثر من كل شيء، وأقبل عليه بالصلاة والذكر والطاعة. وفي هذه المحطة نتعلم كيف نصير من أحباب الله، ولماذا يذهب الحزن عمن كان قلبه مع الله.","points":["الله سبحانه أحق من نحبه، ونحب كل شيء طيب لأن الله يحبه.","نحب النبي محمدا ﷺ أكثر من أنفسنا وأهلنا والناس جميعا.","نتقرب إلى الله أولا بالفرائض كالصلاة، ثم نزيد بالنوافل حتى يحبنا الله.","من كان مع الله سهل عليه كل صعب وذهب عنه الهم والحزن.","حب الطعام واللعب والنوم لا بأس به ما لم يشغلنا عن ذكر الله وطاعته."],"quote":{"x":"فبالله يهون كل صعب، ويسهل كل عسير، ويقرب كل بعيد.","pg":436},"quiz":[{"q":"ما أحب عمل نتقرب به إلى الله؟","o":["أداء الفرائض التي فرضها الله","الإكثار من النوافل وترك الفرائض","كثرة الكلام عن حب الله فقط","قضاء الوقت كله في اللعب المباح"],"why":"وأخبر سبحانه أن أداء فرائضه أحب ما تقرب به إليه المتقربون، ثم بعدها النوافل","pg":431},{"q":"ماذا ينال من يكثر من النوافل بعد الفرائض؟","o":["يصير محبوبا عند الله","يستغني عن الفرائض","يصبح أغنى الناس مالا","يترك الدعاء والذكر"],"why":"وأن المحب لا يزال يكثر من النوافل حتى يصير محبوبا لله.","pg":432},{"q":"من أطيب الناس عيشا كما في الكتاب؟","o":["المؤمن المخلص لله","صاحب المال الكثير","صاحب القصر الواسع","من يلعب طوال يومه"],"why":"فالمؤمن المخلص لله من أطيب الناس عيشا، وأنعمهم بالا، وأشرحهم صدرا، وأسرهم قلبا.","pg":459},{"q":"كيف يجب أن تكون محبتنا للنبي ﷺ؟","o":["أكثر من محبتنا لأنفسنا","مثل محبتنا لأصدقائنا","أقل من محبتنا لألعابنا","بقدر محبتنا لجيراننا"],"why":"لا يا عمر، حتى أكون أحب إليك من نفسك","pg":465}],"scene":{"t":"الأذان والمرحلة الأخيرة","x":"كان سالم يلعب لعبة يحبها على الجهاز، ووصل إلى المرحلة الأخيرة، فسمع أذان المغرب. ماذا يفعل؟","opts":["يوقف اللعب ويقوم إلى الصلاة فورا، لأن الفريضة أحب إلى الله","يكمل المرحلة أولا ثم يصلي متأخرا","يقول سأصلي بعد قليل ويستمر في اللعب"],"why":"وأخبر سبحانه أن أداء فرائضه أحب ما تقرب به إليه المتقربون، ثم بعدها النوافل","pg":431},"act":{"type":"sort","t":"محبة تقربني ومحبة تلهيني","x":"اقرأ كل بطاقة، ثم ضعها في السلة المناسبة: (أ) تقربني من الله، (ب) تلهيني عن ذكر الله. تذكر أن حب الطعام واللعب لا يذم إلا إذا شغلنا عن ذكر الله.","items":[{"x":"أصلي الفرض في وقته","ok":"أ"},{"x":"أقرأ صفحة من القرآن كل يوم","ok":"أ"},{"x":"أذكر الله قبل النوم","ok":"أ"},{"x":"ألعب بعد أداء الصلاة وواجباتي","ok":"أ"},{"x":"أصلي ركعتين نافلة بعد المغرب","ok":"أ"},{"x":"ألعب حتى يفوتني وقت الصلاة","ok":"ب"},{"x":"أنشغل بالجهاز عن نداء أمي","ok":"ب"},{"x":"أنام عن صلاة الفجر لأني سهرت على اللعب","ok":"ب"}]}},"yth":{"show":true,"title":"قلب واحد لمحبوب واحد","intro":"القلب لا يتسع لمحبتين متضادتين: إما أن يملكه حب الله فيسعد، وإما أن يتعلق بالصور والهوى فيصير عبدا لما يحب. في هذه المحطة تتعلم كيف تختار المحبوب الأعلى، وكيف يقدم العاقل اللذة الدائمة على اللذة العاجلة.","points":["حب الله وعشق الصور ضدان، لا بد أن يخرج أحدهما الآخر من القلب.","الإنسان عبد لما يحب، فاختر ما يستحق أن يملك قلبك.","طريق محبة الله الفرائض أولا، ثم الإكثار من النوافل.","العاقل ينظر في العواقب، فيقدم اللذة الدائمة على لذة تعقبها حسرة.","الولاية لله موافقته فيما يحب ويكره، لا مجرد مظاهر العبادة."],"quote":{"x":"فالإنسان عبد محبوبه كائنا ما كان","pg":425},"quiz":[{"q":"لماذا لا يجتمع في القلب حب الله وعشق الصور؟","o":["لأنهما ضدان يخرج أحدهما الآخر","لأن القلب لا يتسع لأي محبة أصلا","لأن عشق الصور يقوي محبة الله","لأن المحبة لا تكون إلا للمخلوق"],"why":"فلا يمكن أن يجتمع في القلب حب المحبوب الأعلى وعشق الصور أبدا، بل هما ضدان لا يتلاقيان، بل لابد أن يخرج أحدهما صاحبه.","pg":424},{"q":"ما خاصية العقل كما يقررها ابن القيم؟","o":["إيثار أعلى المحبوبين على أدناهما","تقديم العاجل على الآجل في كل الأحوال","ترك المحبوبات كلها دون تمييز","اتباع أول ما تميل إليه النفس"],"why":"وتقدم أن خاصية العقل إيثار أعلى المحبوبين على أدناهما، وأيسر المكروهين على أقواهما.","pg":447},{"q":"بأي أمرين يتم للعبد إيثار المحبوب الأعلى؟","o":["قوة الإدراك وشجاعة القلب","كثرة المال وسعة الوقت","قوة البدن وكثرة الأصدقاء","حدة الذكاء وطول العمر"],"why":"ولا يتم له هذا إلا بأمرين: قوة الإدراك، وشجاعة القلب.","pg":447},{"q":"بم عرف ابن القيم الولاية لله؟","o":["موافقة الله في محابه ومساخطه","كثرة الصوم والصلاة وحدها","التمزق والرياضة وترك الدنيا","الانتساب إلى أهل الصلاح والعلم"],"why":"فالولاية عبارة عن موافقة الولي الحميد في محابه ومساخطه، ليست بكثرة صوم ولا صلاة ولا تمزق ولا رياضة.","pg":452},{"q":"أي الأمور الأربعة هما معترك الابتلاء والامتحان؟","o":["مكروه يوصل إلى محبوب وعكسه","محبوب يوصل إلى محبوب مثله","مكروه يوصل إلى مكروه مثله","المحبوب لنفسه دون سواه"],"why":"بقي القسمان الآخران يتجاذبهما الداعيان، وهما معترك الابتلاء والامتحان.","pg":454}],"scene":{"t":"لذة دقائق وحسرة يوم","x":"يسهر شاب كل ليلة على مقاطع تجره إلى نظرات لا تحل، فيجد لذة عاجلة ثم ضيقا في صدره، وتفوته صلاة الفجر. ما الموقف الأعقل؟","opts":["يغلق الجهاز ليلا ويملأ قلبه بالفرائض والنوافل، مقدما اللذة الدائمة","يقلل السهر قليلا ويستمر حتى يمل من تلقاء نفسه","يؤجل التغيير إلى ما بعد الامتحانات"],"why":"فأعقل الناس من آثر لذته وراحته الآجلة الدائمة على العاجلة المنقضية الزائلة","pg":450},"act":{"type":"match","t":"الأمور الأربعة","x":"صل كل موقف من حياتك بقسمه من الأمور الأربعة التي ذكرها ابن القيم، ثم اكتب في دفترك: أي القسمين المتجاذبين أكثر حضورا في يومك؟ وكيف ينتصر فيه داعي العقل والإيمان؟","items":[{"a":"السهر على اللهو ليلة الامتحان","b":"محبوب يوصل إلى مكروه"},{"a":"مذاكرة شاقة تنتهي بالنجاح","b":"مكروه يوصل إلى محبوب"},{"a":"صلاة الجماعة مع رفقة صالحة تحبها","b":"محبوب يوصل إلى محبوب"},{"a":"رفقة سوء تكرهها وتجرك إلى المعصية","b":"مكروه يوصل إلى مكروه"},{"a":"شرب الدواء الكريه طلبا للشفاء","b":"مكروه يوصل إلى محبوب"}]}},"adl":{"show":true,"title":"المحبة أصل كل دين","intro":"يقرر ابن القيم في هذه الفصول أن المحبة والإرادة أصل كل فعل وكل دين، حقا كان أو باطلا، وأن أصل الشرك الإشراك في المحبة، وأن روح لا إله إلا الله إفراد الرب بالمحبة والتعظيم. ويرسم مراتب الحب وأنواع المحبة، ويضع ميزانا تعرف به الموالاة، ثم يختم بأن الدين الأمري والجزائي قائمان على المحبة.","points":["المحبة الصادقة تقتضي توحيد المحبوب، وأصل الشرك الإشراك في المحبة.","مراتب الحب تنتهي إلى التتيم وهو التعبد، والخلة كمال المحبة ونهايتها.","خمسة أقسام للمحبة يجب التمييز بينها، والمحبة الطبعية لا تذم إلا إذا ألهت عن الله.","الحب والإرادة أصل كل فعل، والبغض والكراهة أصل كل ترك، فإصلاح المحبة إصلاح للعمل كله.","الدين دينان أمري وجزائي، والمحبة أصل كل واحد منهما."],"quote":{"x":"فالحب والإرادة أصل كل فعل ومبدؤه، والبغض والكراهة أصل كل ترك ومبدؤه.","pg":448},"quiz":[{"q":"لماذا قرر ابن القيم أن محبة الله وحدها لا تكفي في النجاة؟","o":["لأن المشركين وأهل الكتاب يحبون الله","لأن المحبة عمل قلبي لا يثاب عليه أحد","لأن محبة الله مرتبة دون الخوف والرجاء","لأن محبة الله لا تتحقق لأحد من الخلق"],"why":"أحدها: محبة الله. ولا تكفي وحدها في النجاة من عذابه والفوز بثوابه، فإن المشركين وعباد الصليب واليهود وغيرهم يحبون الله.","pg":443},{"q":"ما الفرق بين المحبة لله والمحبة مع الله؟","o":["الأولى من لوازم العبودية والثانية شرك","الأولى طبعية مباحة والثانية شرعية مستحبة","كلتاهما محمودة إذا قويت في القلب","الأولى للأنبياء والثانية لعامة الناس"],"why":"الرابع: المحبة مع الله. وهي المحبة الشركية، وكل من أحب شيئا مع الله، لا لله ولا من أجله ولا فيه، فقد اتخذه ندا من دون الله","pg":444},{"q":"لماذا رد ابن القيم قول من جعل المحبة أكمل من الخلة؟","o":["لأن المحبة عامة والخلة نهايتها","لأن الخلة لم تثبت إلا لإبراهيم وحده","لأن المحبة لا تطلق في حق الله أصلا","لأن الخلة والمحبة لفظان لمعنى واحد"],"why":"فإن المحبة عامة، والخلة خاصة، والخلة نهاية المحبة.","pg":446},{"q":"ما المقصود من أمر الخليل بذبح ولده كما يقرره ابن القيم؟","o":["تخليص القلب للرب لا ذبح الولد نفسه","عقوبة الخليل على سؤاله الولد","بيان أن الفداء لا يشرع لأحد بعد ذلك","اختبار قوة الخليل البدنية وحدها"],"why":"ولم يكن المقصود ذبح الولد، ولكن المقصود ذبحه من قلبه، ليخلص القلب للرب.","pg":445},{"q":"كيف يكون الدين الجزائي قائما على المحبة؟","o":["لأن الثواب والعقاب عدل وفضل يحبهما الرب","لأن الجزاء كله فضل محض لا عدل فيه","لأن العبد يختار جزاءه بقدر محبته","لأنه منفصل عن الأمر والنهي تماما"],"why":"وكذلك دينه الجزائي، فإنه يتضمن مجازاة المحسن بإحسانه والمسيء بإساءته، وكل من الأمرين محبوب للرب، فإنهما عدله وفضله، وكلاهما من صفات كماله.","pg":479}],"scene":{"t":"صلاة تحت المراقبة","x":"لاحظ معلم أن طلابه يؤدون صلاة الظهر في المدرسة بانتظام، لكنه سمع أحدهم يقول: نصلي لأن المعلم يراقبنا. كيف يتصرف المعلم؟","opts":["يربطهم بمحبة الله ويبين أن الدين الباطن لا يقوم إلا على الحب والخضوع، مع استمرار المتابعة","يشدد المراقبة والعقوبة على المتأخرين فقط","يكتفي بالانقياد الظاهر ما دامت الصلاة تؤدى"],"why":"والدين الباطن لابد فيه من الحب والخضوع كالعبادة سواء، بخلاف الدين الظاهر فإنه لا يستلزم الحب، وإن كان فيه انقياد وذل في الظاهر.","pg":477},"act":{"type":"class","t":"ميزان المحبة في الصف","x":"نشاط صفي مدته 40 دقيقة لطلاب المرحلة الثانوية أو لمجلس الآباء، يقوم على أنواع المحبة وميزان الموالاة كما في الكتاب.","items":["5 دقائق: يكتب المعلم على السبورة: «فالإنسان عبد محبوبه كائنا ما كان» ويسأل: ما الذي يملك قلبك أكثر في يومك؟","10 دقائق: يعرض أقسام المحبة الخمسة (محبة الله، محبة ما يحبه الله، الحب لله وفيه، المحبة مع الله، المحبة الطبعية) على بطاقات، ويوزع أمثلة من حياة الطلاب ليصنفوها.","10 دقائق: تعمل المجموعات على الأمور الأربعة (مكروه يوصل إلى مكروه، مكروه يوصل إلى محبوب، محبوب يوصل إلى محبوب، محبوب يوصل إلى مكروه) وتستخرج مثالين لكل قسم.","10 دقائق: نقاش حول الميزان العادل: «فالولاية عبارة عن موافقة الولي الحميد في محابه ومساخطه، ليست بكثرة صوم ولا صلاة ولا تمزق ولا رياضة.» ويكتب كل طالب محبوبا واحدا يريد أن يجعله تابعا لمحبة الله.","5 دقائق: ختام بدعاء عمار رضي الله عنه «وأسألك الشوق إلى لقائك» وتكليف منزلي بتأمل يكتبه الطالب في دفتره الخاص."]}},"alt":{}},"highlights":[{"x":"فالإنسان عبد محبوبه كائنا ما كان","pg":425,"lv":"yth"},{"x":"فبالله يهون كل صعب، ويسهل كل عسير، ويقرب كل بعيد.","pg":436,"lv":"kid"},{"x":"فلا هم مع الله، ولا غم، ولا حزن","pg":437,"lv":"kid"},{"x":"فإنه ما أماته إلا ليحييه، ولا أمرضه إلا ليصحه، ولا أفقره إلا ليغنيه، ولا منعه إلا ليعطيه","pg":437,"lv":"yth"},{"x":"فالحب والإرادة أصل كل فعل ومبدؤه، والبغض والكراهة أصل كل ترك ومبدؤه.","pg":448,"lv":"adl"},{"x":"فأعقل الناس من آثر لذته وراحته الآجلة الدائمة على العاجلة المنقضية الزائلة","pg":450,"lv":"yth"},{"x":"فالولاية عبارة عن موافقة الولي الحميد في محابه ومساخطه، ليست بكثرة صوم ولا صلاة ولا تمزق ولا رياضة.","pg":452,"lv":"adl"},{"x":"وطيب الحياة جنة الدنيا.","pg":459,"lv":"kid"}],"concepts":[{"term":"خاصية التعبد","def":"الحب مع الخضوع والذل للمحبوب، فمن أحب شيئا وخضع له فقد تعبد قلبه له.","pg":426},{"term":"العلاقة","def":"وسميت علاقة لتعلق القلب بالمحبوب.","pg":426},{"term":"الصبابة","def":"وسميت بذلك لانصباب القلب إلى المحبوب.","pg":426},{"term":"الغرام","def":"وهو لزوم الحب للقلب لزوما لا ينفك عنه.","pg":427},{"term":"العشق","def":"وهو إفراط المحبة. ولهذا لا يوصف به الرب تعالى، ولا يطلق في حقه.","pg":427},{"term":"الشوق","def":"وهو سفر القلب إلى المحبوب أحث السفر.","pg":427},{"term":"التتيم","def":"وهو آخر مراتب الحب، وهو تعبد المحب لمحبوبه.","pg":438},{"term":"حقيقة التعبد","def":"الذل والخضوع للمحبوب.","pg":438},{"term":"الخلة","def":"وهي تتضمن كمال المحبة ونهايتها، بحيث لا يبقى في قلب المحب سعة لغير محبوبه، وهي منصب لا يقبل المشاركة بوجه ما.","pg":444},{"term":"المحبة الطبعية","def":"وهي ميل الإنسان إلى ما يلائم طبعه، كمحبة العطشان للماء، والجائع للطعام","pg":444},{"term":"الولاية","def":"فالولاية عبارة عن موافقة الولي الحميد في محابه ومساخطه","pg":452},{"term":"روح لا إله إلا الله","def":"إفراد الرب جل ثناؤه بالمحبة والإجلال والتعظيم والخوف والرجاء، وتوابع ذلك من التوكل والإنابة والرغبة والرهبة.","pg":457},{"term":"التأله","def":"والتأله هو المحبة، والطاعة، والخضوع.","pg":465},{"term":"الدين","def":"فهو الطاعة اللازمة الدائمة التي صارت خلقا وعادة.","pg":476},{"term":"الدينان","def":"دين شرعي أمري، ودين حسابي جزائي. وكلاهما لله وحده","pg":479}],"stories":[{"t":"عمر ومحبة النبي ﷺ","x":"قال عمر رضي الله عنه: يا رسول الله، والله لأنت أحب إلي من كل شيء إلا من نفسي، فقال: «لا يا عمر، حتى أكون أحب إليك من نفسك»، فقال: والذي بعثك بالحق لأنت أحب إلي من نفسي، قال: «الآن يا عمر».","pg":464,"lv":"kid","hd":"البخاري 6632"},{"t":"الخليل يقدم محبة الله على محبة ولده","x":"لما سأل إبراهيم عليه السلام الولد فأعطيه وتعلق حبه بقلبه، أمره الله بذبحه، ولم يكن المقصود ذبح الولد بل تخليص القلب للرب، فلما بادر إلى الامتثال وقدم محبة الله رفع الذبح وفدي بذبح عظيم.","pg":445,"lv":"yth","hd":""},{"t":"صلاة عمار الموجزة","x":"صلى عمار بن ياسر رضي الله عنه صلاة فأوجز فيها، فقيل له في ذلك، فقال: أما إني دعوت فيها بدعوات كان النبي ﷺ يدعو بهن، ومنها: «وأسألك لذة النظر إلى وجهك الكريم، وأسألك الشوق إلى لقائك».","pg":428,"lv":"yth","hd":"أحمد 18325 والنسائي 1305 وابن حبان 1971، صححه ابن حبان والحاكم"},{"t":"ما يسعى فيه العقلاء","x":"نقل ابن القيم عن بعض العلماء (ابن حزم كما قال المحقق) أنه تأمل مساعي العقلاء فوجدها كلها في دفع الهم والغم، بالأكل والشرب والتجارة والنكاح واللهو، فلم يجد طريقا موصلة إليه إلا الإقبال على الله ومعاملته وحده.","pg":450,"lv":"yth","hd":""},{"t":"مثل السكران الذي احترقت داره","x":"شبه ابن القيم الغافل عن ألم فوت الله بسكران احترقت داره وأمواله وأهله وهو لا يشعر، حتى إذا صحا وانكشف عنه الغطاء علم حاله، وكذلك الحال عند كشف الغطاء ومعاينة طلائع الآخرة.","pg":461,"lv":"yth","hd":""},{"t":"أجل اللقاء","x":"قال بعض أهل البصائر (أبو عثمان الحيري كما قال المحقق) في قوله تعالى: ﴿مَن كَانَ يَرْجُو لِقَاءَ اللَّهِ فَإِنَّ أَجَلَ اللَّهِ لَآتٍ﴾: لما علم الله شدة شوق أوليائه إلى لقائه ضرب لهم أجلا وموعدا للقاء تسكن نفوسهم به.","pg":429,"lv":"adl","hd":""},{"t":"الوصال في الصوم","x":"سأل الصحابة النبي ﷺ عن وصاله في الصوم فقال: «إني لست كهيئتكم، إني أظل عند ربي يطعمني ويسقيني»، فبين ابن القيم أن غذاء القلب عند ربه يقوم مقام الطعام والشراب الحسي.","pg":460,"lv":"adl","hd":"البخاري 1964 ومسلم 1105"}],"ready":true},{"k":"s12","t":"لذة القلب ونعيم الآخرة","pgs":[540,573],"q":"ما أعظم لذة في الدنيا والآخرة، ومتى تكون اللذة محمودة أو مذمومة؟","essence":"أطيب الدنيا معرفة الله وألذ الجنة رؤيته","kw":["اللذة","الرؤية","المحبة"],"daa":"التعلق باللذات الفانية القاطعة عن الله، والمحبة الباطلة التي تعقب أعظم الآلام.","dawa":"طلب اللذة الكبرى بمعرفة الله ومحبته ومحبة رسوله وكلامه، وجعل لذات الدنيا وسيلة إلى نعيم الآخرة، وتصريف المحبة الفطرية في الحلال.","sections":[{"t":"فصل: كمال اللذة تابع لكمال المحبوب وكمال المحبة","pg":540,"lv":"yth","key":"وهاهنا أمر عظيم يجب على اللبيب الاعتناء به، وهو أن كمال اللذة والفرح والسرور ونعيم القلب وابتهاج الروح تابع لأمرين","p":["أحدهما: كمال المحبوب في نفسه وجماله وأنه أولى بإيثار الحب من كل ما سواه. والأمر الثاني: كمال محبته، واستفراغ الوسع في حبه، وإيثار قربه والوصول إليه على كل شيء.","وتحمد إذا أعانت على لذة عظيمة دائمة مستقرة لا تنغيص فيها ولا نكد بوجه ما، وهي لذة الآخرة ونعيمها وطيب العيش فيها.","والله سبحانه خلق الخلق لينيلهم هذه اللذة الدائمة في دار الخلد، وأما الدنيا فمنقطعة، ولذاتها لا تصفو أبدا ولا تدوم."],"items":[{"h":"اللذة بحسب المحبة","x":"وكل عاقل يعلم أن اللذة بحصول المحبوب بحسب قوة محبته. فكلما كانت المحبة أقوى كانت لذة المحب أكمل.","pg":540},{"h":"متى تذم","x":"فهي تذم إذا أعقبت ألما أعظم منها، أو منعت لذة خيرا وأجل منها.","pg":541},{"h":"الدنيا متاع","x":"فأخبرهم أن الدنيا متاع يستمتع بها إلى غيرها، وأن الآخرة هي المستقر.","pg":542},{"h":"القاعدة","x":"فكل لذة أعانت على لذة الآخرة وأوصلت إليها لم يذم تناولها، بل يحمد بحسب إيصالها إلى لذة الآخرة.","pg":542}],"hd":""},{"t":"أعظم نعيم الآخرة النظر إلى وجه الرب جل جلاله","pg":542,"lv":"adl","key":"فأعظم نعيم الآخرة ولذاتها: النظر إلى وجه الرب جل جلاله، وسماع كلامه منه، والقرب منه","p":["كما ثبت في الصحيح في حديث الرؤية: «فوالله ما أعطاهم شيئا أحب إليهم من النظر إليه».","وفي النسائي ومسند الإمام أحمد من حديث عمار بن ياسر عن النبي صلى الله عليه وسلم في دعائه: «وأسألك لذة النظر إلى وجهك والشوق إلى لقائك»."],"items":[],"hd":"«فوالله ما أعطاهم شيئا أحب إليهم من النظر إليه»: مسلم 181 من حديث صهيب. دعاء عمار: النسائي 1305 وابن حبان 1971، صححه ابن حبان والحاكم (أحال المحقق إلى ص 428). أما «إنه إذا تجلى لهم ورأوه نسوا ما هم فيه من النعيم» فرواه ابن ماجه 184، وفيه الفضل بن عيسى الرقاشي متروك. و«كأن الناس يوم القيامة لم يسمعوا القرآن إذا سمعوه من الرحمن» قال المحقق: المرفوع لا يصح، فيه إسماعيل بن رافع ضعيف.","weak":1},{"t":"أعظم لذات الدنيا لذة معرفته سبحانه ولذة محبته","pg":543,"lv":"yth","key":"فأطيب ما في الدنيا معرفته ومحبته، وألذ ما في الجنة رؤيته ومشاهدته","p":["فأعظم الأسباب التي تحصل هذه اللذة هو أعظم لذات الدنيا على الإطلاق، وهو لذة معرفته سبحانه ولذة محبته، فإن ذلك هو جنة الدنيا ونعيمها العالي؛ ونسبة لذاتها الفانية إليه كتفلة في بحر.","بل لذات الدنيا القاطعة عن ذلك تنقلب آلاما وعذابا، ويبقى صاحبها في المعيشة الضنك، فليست الحياة الطيبة إلا بالله.","بل فساد القلب إذا خلا من محبة فاطره وبارئه وإلهه الحق أعظم من فساد البدن إذا خلا من الروح."],"items":[{"h":"أحوال المحبين","x":"وكان بعض المحبين تمر به أوقات، فيقول: إن كان أهل الجنة في مثل هذا، إنهم لفي عيش طيب!","pg":544},{"h":"فقد المحبة","x":"وإذا فقدها القلب كان ألمه أعظم من ألم العين إذا فقدت نورها، والأذن إذا فقدت سمعها.","pg":546},{"h":"الخلاصة","x":"والمقصود أن أعظم لذات الدنيا هو السبب الموصل إلى أعظم لذة في الآخرة.","pg":546}],"hd":""},{"t":"ولذات الدنيا ثلاثة أنواع","pg":546,"lv":"adl","key":"فما أعان على اللذة المطلوبة لذاتها فهو حق، وما لم يعن عليها فهو باطل","p":["فأعظمها وأكملها: ما أوصل إلى لذة الآخرة. ويثاب الإنسان على هذه اللذة أتم ثواب. ولهذا كان المؤمن يثاب على ما يقصد به وجه الله من أكله وشربه ولبسه ونكاحه.","وهذه اللذات في الحقيقة إنما هي استدراج من الله لهم، ليذيقهم بها أعظم الآلام، ويحرمهم بها أكمل اللذات؛ بمنزلة من قدم لغيره طعاما لذيذا مسموما يستدرجه به إلى هلاكه.","وهذا القسم هو الذي عناه النبي صلى الله عليه وسلم بقوله: «كل لهو يلهو به الرجل فهو باطل، إلا رميه بقوسه، وتأديبه فرسه، وملاعبته امرأته؛ فإنهن من الحق»."],"items":[{"h":"النوع الأول","x":"ما أوصل إلى لذة الآخرة، ويثاب عليه أتم ثواب.","pg":546},{"h":"النوع الثاني","x":"لذة تمنع لذة الآخرة، وتعقب آلاما أعظم منها، كلذة الذين اتخذوا من دون الله أوثانا، ولذة أصحاب الفواحش والظلم والبغي في الأرض والعلو بغير الحق.","pg":546},{"h":"تفسير بعض السلف","x":"قال بعض السلف في تفسير ﴿سنستدرجهم من حيث لا يعلمون﴾: كلما أحدثوا ذنبا أحدثنا لهم نعمة.","pg":547},{"h":"النوع الثالث","x":"لذة لا تعقب لذة في دار القرار ولا ألما، ولا تمنع أصل لذة دار القرار، وإن منعت كمالها. فهذه زمانها يسير، ولا بد أن تشغل عما هو خير وأنفع منها.","pg":548}],"hd":"«كل لهو يلهو به الرجل فهو باطل...»: رواه أبو داود 2513 والترمذي 1637 والنسائي 3580 وابن ماجه 2811 وأحمد والحاكم من حديث عقبة بن عامر؛ قال الترمذي: حسن (وفي نسخة: حسن صحيح)، وقال الحاكم: صحيح الإسناد.","weak":1},{"t":"فصل: فهذا الحب لا ينكر ولا يذم، وكذلك حب رسول الله","pg":548,"lv":"kid","key":"فهذا الحب لا ينكر ولا يذم، بل هو أحمد أنواع الحب. وكذلك حب رسول الله صلى الله عليه وسلم","p":["وإنما نعني المحبة الخاصة، وهي التي تشغل قلب المحب وفكره وذكره لمحبوبه، وإلا فكل مسلم في قلبه محبة لله ورسوله، لا يدخل في الإسلام إلا بها.","فهذه المحبة التي تلطف الروح، وتخفف أثقال التكاليف، وتسخي البخيل، وتشجع الجبان، وتصفي الذهن، وتروض النفس، وتطيب الحياة على الحقيقة، لا محبة الصور المحرمة.","وهذه المحبة التي تنور الوجه، وتشرح الصدر، وتحيي القلب."],"items":[{"h":"التفاوت","x":"والناس متفاوتون في درجات هذه المحبة تفاوتا لا يحصيه إلا الله، فبين محبة الخليلين ومحبة غيرهما ما بينهما.","pg":549}],"hd":""},{"t":"وكذلك محبة كلام الله","pg":549,"lv":"adl","key":"وكذلك محبة كلام الله، فإنه من علامة محبة الله","p":["وإذا أردت أن تعلم ما عندك وعند غيرك من محبة الله، فانظر إلى محبة القرآن من قلبك، والتذاذك بسماعه أعظم من التذاذ أصحاب الملاهي والغناء المطرب بسماعهم؛ فإنه من المعلوم أن من أحب محبوبا كان كلامه وحديثه أحب شيء إليه.","وقال النبي صلى الله عليه وسلم يوما لعبد الله بن مسعود: «اقرأ علي»، فقال: أقرأ عليك، وعليك أنزل؟ فقال: «إني أحب أن أسمعه من غيري». فاستفتح، وقرأ سورة النساء، حتى إذا بلغ قوله: ﴿فكيف إذا جئنا من كل أمة بشهيد وجئنا بك على هؤلاء شهيدا﴾ [النساء 41] قال: «حسبك». فرفع رأسه، فإذا عينا رسول الله صلى الله عليه وسلم تذرفان من البكاء."],"items":[{"h":"لا شبع","x":"وكيف يشبع المحب من كلام محبوبه، وهو غاية مطلوبه!","pg":550},{"h":"أثر الصحابة","x":"وكان الصحابة إذا اجتمعوا وفيهم أبو موسى يقولون: يا أبا موسى ذكرنا ربنا، فيقرأ وهم يستمعون.","pg":551},{"h":"العلامة الفارقة","x":"فإذا رأيت الرجل ذوقه ووجده وطربه في سماع الأبيات دون سماع الآيات، فهذا من أقوى الأدلة على فراغ قلبه من محبة الله وكلامه.","pg":552},{"h":"الخلاصة","x":"ففي محبة الله وكلامه ورسوله أضعاف أضعاف ما ذكر السائل من فوائد العشق ومنافعه، بل لا حب على الحقيقة أنفع منه.","pg":552}],"hd":"حديث ابن مسعود: البخاري 5055 ومسلم 800. أثر عثمان «لو طهرت قلوبنا لما شبعت من كلام الله»: قال المحقق: سنده ضعيف للانقطاع. أثر «يا أبا موسى ذكرنا ربنا»: سنده ضعيف للانقطاع، وذكر المحقق طرقا قال إنها تدل على أن للأثر أصلا.","weak":1},{"t":"فصل: وأما محبة النسوان","pg":552,"lv":"adl","key":"وأما محبة النسوان فلا لوم على المحب فيها، بل هي من كماله","p":["وقد امتن الله سبحانه بها على عباده فقال: ﴿ومن آياته أن خلق لكم من أنفسكم أزواجا لتسكنوا إليها وجعل بينكم مودة ورحمة إن في ذلك لآيات لقوم يتفكرون﴾ [الروم 21]. فجعل المرأة سكنا للرجل يسكن قلبه إليها، وجعل بينهما خالص الحب، وهو المودة المقترنة بالرحمة.","فنكاح المعشوقة هو دواء العشق الذي جعله الله دواءه شرعا وقدرا.","فمحبة النساء من كمال الإنسان. قال ابن عباس: خير هذه الأمة أكثرها نساء."],"items":[{"h":"حديث جابر","x":"إرشاد من أعجبته امرأة إلى أن يأتي أهله، ففيه التسلي عن المطلوب بجنسه، ومداواة الإعجاب بأنفع الأدوية.","pg":553},{"h":"زواج زينب بنت جحش","x":"تولى الله عز وجل نكاحها من رسوله بنفسه، وجاء الوحي بذلك: ﴿فلما قضى زيد منها وطرا زوجناكها﴾ [الأحزاب 37]، فكانت تفخر على نساء النبي صلى الله عليه وسلم.","pg":555},{"h":"حبب إليه النساء","x":"ولا ريب أن النبي صلى الله عليه وسلم كان قد حبب إليه النساء: «حبب إلي من دنياكم النساء والطيب، وجعلت قرة عيني في الصلاة». هذا لفظ الحديث، لا ما يرويه بعضهم: «حبب إلي من دنياكم ثلاث».","pg":556},{"h":"عائشة وخديجة","x":"وقد سئل رسول الله صلى الله عليه وسلم عن أحب الناس إليه، فقال: «عائشة». وقال عن خديجة: «إني رزقت حبها».","pg":558},{"h":"مغيث وبريرة","x":"شفع النبي صلى الله عليه وسلم لمغيث عند بريرة أن تراجعه فأبت، ولم ينكر عليه حبها، فإن هذا ما لا يملكه.","pg":559},{"h":"القسم بين النساء","x":"﴿ولن تستطيعوا أن تعدلوا بين النساء ولو حرصتم﴾ [النساء 129] يعني: في الحب والجماع.","pg":560},{"h":"الشفاعة في النكاح","x":"ولم يزل الخلفاء الراشدون والرحماء من الناس يشفعون في العشاق إلى معشوقهم الجائز وصلهن.","pg":561},{"h":"أخبار متفرقة","x":"ثم أورد ابن القيم أخبارا عن بعض الخلفاء والناس في الشفاعة للمتحابين وتزويجهم (ص 561 إلى 565)، وفي بعضها ضعف شديد.","pg":561}],"hd":"حديث جابر «إن المرأة تقبل في صورة شيطان...»: مسلم 1403. «لم ير للمتحابين مثل النكاح»: ابن ماجه 1847، ورجح العقيلي والخليلي إرساله، وبين المحقق أن من رفعه عن الثوري أخطأ. قصة زينب: مسلم 1428 والبخاري 7420 و7421. «حبب إلي من دنياكم النساء والطيب، وجعلت قرة عيني في الصلاة»: النسائي 3939 و3940 وأحمد 12315، صححه الحاكم والضياء والذهبي والمؤلف والعراقي وابن حجر، وزيادة «أصبر عن الطعام والشراب ولا أصبر عنهن» لا تصح. حديث «عائشة» أحب الناس إليه: البخاري 3662 ومسلم 2384. «إني رزقت حبها»: مسلم 2435. قول ابن عباس: البخاري 5069. قصة سليمان عليه السلام: البخاري 5242 ومسلم 1654. قصة بريرة: البخاري 5283. «اللهم هذا قسمي فيما أملك فلا تلمني فيما لا أملك»: أبو داود 2134 والترمذي 1140 والنسائي 3943، صححه ابن حبان والحاكم، وتكلم فيه البخاري وأبو زرعة والنسائي والترمذي والدارقطني ورأوا أنه مرسل. وقصة داود عليه السلام: قال المحقق إنها باطلة من أكاذيب اليهود.","weak":1},{"t":"فعشق النساء ثلاثة أقسام","pg":565,"lv":"adl","key":"عشق هو قربة وطاعة، وهو عشق الرجل امرأته وجاريته. وهذا العشق نافع فإنه أدعى إلى المقاصد التي شرع الله لها النكاح، وأكف للبصر والقلب عن التطلع إلى غير أهله","p":["ودواء هذا الداء الدوي: الاستعانة بمقلب القلوب، وصدق اللجأ إليه، والاشتغال بذكره، والتعوض بحبه وقربه، والتفكر في الألم الذي يعقبه هذا العشق، واللذة التي تفوته به؛ فيترتب عليه فوات أعظم محبوب، وحصول أعظم مكروه.","والقسم الثالث من العشق: عشق مباح لا يملك، كعشق من وصفت له امرأة جميلة، أو رآها فجأة من غير قصد، فأورثه ذلك عشقا لها، ولم يحدث له ذلك العشق معصية؛ فهذا لا يملك ولا يعاقب عليه. والأنفع له مدافعته، والاشتغال بما هو أنفع له. والواجب على هذا أن يكتم، ويعف، ويصبر على بلواه."],"items":[{"h":"القسم الأول","x":"عشق قربة وطاعة: عشق الرجل امرأته، ولهذا يحمد هذا العاشق عند الله وعند الناس.","pg":565},{"h":"القسم الثاني","x":"عشق مقت من الله وبعد من رحمته، وهو أضر شيء على العبد في دينه ودنياه، وهو عشق المردان، وهو الذي جلب على قوم لوط ما جلب.","pg":565},{"h":"القسم الثالث","x":"عشق مباح لا يملك، والواجب فيه أن يكتم ويعف ويصبر، فيثيبه الله على صبره وعفته وتركه طاعة هواه.","pg":566}],"hd":""},{"t":"فصل: والعشاق ثلاثة أقسام","pg":567,"lv":"adl","key":"وبين هذه الأنواع تفاوت في القوة والضعف","p":["منهم من يعشق الجمال المطلق. ومنهم من يعشق الجمال المقيد، سواء طمع بوصاله أو لم يطمع. ومنهم من لا يعشق إلا من يطمع في الوصول إليه."],"items":[{"h":"عاشق الجمال المطلق","x":"قلبه يهيم في كل واد، فهذا عشقه واسع، ولكنه غير ثابت كثير التنقل.","pg":567},{"h":"عاشق الجمال المقيد","x":"أثبت على معشوقه، وأدوم محبة له، ولكن يضعفها عدم الطمع في الوصال.","pg":568},{"h":"عاشق من يطمع في وصاله","x":"أعقل العشاق وأعرفهم، وحبه أقوى لأن الطمع يمده ويقويه.","pg":568}],"hd":""},{"t":"فصل: وأما حديث «من عشق فعف»","pg":568,"lv":"adl","key":"وأما حديث «من عشق فعف»، فهذا يرويه سويد بن سعيد، فقد أنكره حفاظ الإسلام عليه","p":["قلت: والصواب في الحديث أنه من كلام ابن عباس رضي الله عنهما موقوفا عليه، فغلط سويد في رفعه.","ومما يوضح ذلك أن النبي صلى الله عليه وسلم عد الشهداء في الصحيح، فذكر المقتول في الجهاد، والمبطون، والحرق، والنفساء يقتلها ولدها، والغرق، وصاحب ذات الجنب؛ ولم يعد منهم العاشق يقتله العشق.","وحسب قتيل العشق أن يصح له هذا الأثر عن ابن عباس، على أنه لا يدخل تحته حتى يصبر لله، ويعف لله، ويكتم لله. وهذا لا يكون إلا مع قدرته على معشوقه، وإيثار محبة الله وخوفه ورضاه."],"items":[{"h":"من أنكره","x":"أنكره ابن عدي والبيهقي وابن طاهر وأبو الفرج بن الجوزي وعده في الموضوعات، والحاكم على تساهله.","pg":568},{"h":"رجوع سويد","x":"عاتب ابن المرزبان سويدا في رفعه، فأسقط ذكر النبي صلى الله عليه وسلم، وكان بعد ذلك لا يرفعه.","pg":569},{"h":"المتن","x":"ولا يشبه هذا كلام النبوة.","pg":569},{"h":"طريق عائشة","x":"ونحن نشهد الله أن عائشة ما حدثت بهذا عن رسول الله صلى الله عليه وسلم قط، ولا حدث به عنها عروة، ولا حدث به عنه هشام قط.","pg":570},{"h":"الميزان","x":"وكلام حفاظ الإسلام في إنكار هذا الحديث هو الميزان، وإليهم يرجع في هذا الشأن.","pg":571},{"h":"الخاتمة","x":"وهذا من أحق من دخل تحت قوله: ﴿وأما من خاف مقام ربه ونهى النفس عن الهوى فإن الجنة هي المأوى﴾ [النازعات 40، 41] وتحت قوله: ﴿ولمن خاف مقام ربه جنتان﴾ [الرحمن 46].","pg":573}],"hd":"«من عشق فعف وكتم فمات فهو شهيد»: أنكره الحفاظ، وعده ابن الجوزي في الموضوعات، ورجح ابن القيم وقفه على ابن عباس، وقال في زاد المعاد: وفي صحته موقوفا على ابن عباس نظر. حديث الشهداء: رواه مالك في الموطأ 555 من حديث جابر بن عتيك، قال النووي: صحيح بلا خلاف، وإن لم يخرجه البخاري ومسلم.","weak":1}],"lv":{"kid":{"show":true,"title":"أحب الله ورسوله والقرآن، وأشتاق إلى الجنة","intro":"في الجنة نعيم كثير لا تراه عين في الدنيا، وأعظمه أن يرى المؤمنون ربهم سبحانه. والطريق إلى هذا النعيم يبدأ من الدنيا: أن نعرف الله ونحبه، ونحب رسوله صلى الله عليه وسلم، ونحب القرآن ونفرح بسماعه. وكلما زادت محبتنا لهذه الأشياء زادت سعادة قلوبنا.","points":["أعظم نعيم في الجنة أن يرى المؤمنون وجه ربهم سبحانه، وهذا أحب إليهم من كل شيء.","أطيب شيء في الدنيا أن تعرف الله وتحبه، فهذه سعادة القلب الحقيقية.","نحب رسول الله صلى الله عليه وسلم أكثر من آبائنا وأبنائنا والناس أجمعين.","محبة القرآن علامة على محبة الله، فمن أحب أحدا أحب كلامه.","كان النبي صلى الله عليه وسلم يحب أن يسمع القرآن من غيره، وبكى حين سمعه من ابن مسعود."],"quote":{"x":"فأطيب ما في الدنيا معرفته ومحبته، وألذ ما في الجنة رؤيته ومشاهدته","pg":543},"quiz":[{"q":"ما أعظم نعيم أهل الجنة؟","o":["النظر إلى وجه الله","القصور العالية الجميلة","الأنهار الجارية العذبة","الثمار الطيبة الكثيرة"],"why":"فأعظم نعيم الآخرة ولذاتها: النظر إلى وجه الرب جل جلاله","pg":542},{"q":"ماذا طلب النبي صلى الله عليه وسلم من ابن مسعود؟","o":["أن يقرأ عليه القرآن","أن يؤذن للناس للصلاة","أن يكتب له رسالة طويلة","أن يحفظ له حديثا جديدا"],"why":"وقال النبي صلى الله عليه وسلم يوما لعبد الله بن مسعود: «اقرأ علي»","pg":550},{"q":"ما العلامة التي تدل على محبة الله في قلبك؟","o":["أن أحب القرآن","أن أكثر اللعب","أن أنام كثيرا","أن أجمع الألعاب"],"why":"وكذلك محبة كلام الله، فإنه من علامة محبة الله","pg":549},{"q":"النبي صلى الله عليه وسلم يجب أن يكون أحب إلينا من:","o":["الوالد والولد والناس أجمعين","الأصدقاء والجيران وحدهم","الألعاب والهدايا والحلوى كلها","المعلمين في المدرسة فقط"],"why":"«لا يؤمن عبد حتى يكون هو أحب إليه من ولده ووالده والناس أجمعين»","pg":535}],"scene":{"t":"اللعبة والحلقة","x":"دعاك أصدقاؤك لإكمال لعبة ممتعة، وقد حان وقت حلقة تحفيظ القرآن في المسجد.","opts":["أذهب إلى الحلقة فرحا، وألعب بعدها في وقت مناسب","أكمل اللعب وأترك الحلقة هذا اليوم","أذهب إلى الحلقة وأنا متضايق ولا أنتبه للقرآن"],"why":"وكذلك محبة كلام الله، فإنه من علامة محبة الله","pg":549},"act":{"type":"match","t":"صل كل بطاقة بما يناسبها","x":"اسحب كل بطاقة من العمود الأول إلى ما يناسبها في العمود الثاني، ثم اقرأها بصوت مرتفع لأهلك.","items":[{"a":"أعظم نعيم في الجنة","b":"النظر إلى وجه الله"},{"a":"علامة محبة الله","b":"محبة القرآن"},{"a":"ابن مسعود","b":"قرأ القرآن على النبي"},{"a":"رسول الله صلى الله عليه وسلم","b":"أحب إلينا من الناس أجمعين"},{"a":"لذات الدنيا","b":"قليلة وتنقطع"},{"a":"لذات الجنة","b":"دائمة لا تنقطع"}]}},"yth":{"show":true,"title":"اللذة الكبرى: كيف تختار لذتك؟","intro":"كل إنسان يبحث عن اللذة والسعادة، وهذا ليس عيبا، لكن ابن القيم يعلمك ميزانا دقيقا: اللذة تحمد إذا أوصلت إلى لذة الآخرة الدائمة، وتذم إذا أعقبت ألما أعظم منها أو حرمتك ما هو خير منها. وأطيب ما في الدنيا معرفة الله ومحبته، وأطيب ما في الجنة رؤيته. ومن علامات محبة الله أن تحب كلامه، فانظر إلى مكان القرآن في قلبك.","points":["كمال اللذة يتبع أمرين: كمال المحبوب، وكمال محبتك له، فإذا أحببت أكمل محبوب نلت أكمل لذة.","لذات الدنيا ثلاثة أنواع: ما يوصل إلى الآخرة فهو أعظمها، وما يمنع منها فهو استدراج، ومباح يسير الزمن يشغل عما هو خير.","المؤمن يثاب حتى على أكله وشربه ولبسه إذا قصد بها وجه الله.","محبة رسول الله صلى الله عليه وسلم تلطف الروح وتخفف ثقل التكاليف وتشجع الجبان.","إذا أردت أن تعرف ما عندك من محبة الله فانظر إلى محبة القرآن في قلبك."],"quote":{"x":"فما أعان على اللذة المطلوبة لذاتها فهو حق، وما لم يعن عليها فهو باطل","pg":548},"quiz":[{"q":"كمال اللذة ونعيم القلب تابع لأمرين، ما هما؟","o":["كمال المحبوب وكمال المحبة له","كثرة المال وطول العمر معا","صحة البدن وكثرة الأصدقاء","قوة الشهوة وسهولة الوصول إليها"],"why":"أحدهما: كمال المحبوب في نفسه وجماله وأنه أولى بإيثار الحب من كل ما سواه. والأمر الثاني: كمال محبته","pg":540},{"q":"متى تذم اللذة كما قرر ابن القيم؟","o":["إذا أعقبت ألما أعظم منها","إذا كان زمانها يسيرا قليلا","إذا شعر بها الإنسان وحده","إذا كانت من الطعام والشراب"],"why":"فهي تذم إذا أعقبت ألما أعظم منها، أو منعت لذة خيرا وأجل منها","pg":541},{"q":"ما أعظم أنواع لذات الدنيا وأكملها؟","o":["ما أوصل إلى لذة الآخرة","ما كان أطول زمنا وأكثر","ما اجتمع عليه أكثر الناس","ما لم يكلف مالا ولا جهدا"],"why":"فأعظمها وأكملها: ما أوصل إلى لذة الآخرة. ويثاب الإنسان على هذه اللذة أتم ثواب","pg":546},{"q":"اللذة المباحة التي لا يستعان بها على الآخرة، ما أثرها؟","o":["تنقص كمال لذة الآخرة فقط","تمنع أصل لذة الآخرة كلها","يثاب عليها صاحبها أتم ثواب","هي استدراج يعقب أعظم الآلام"],"why":"لذة لا تعقب لذة في دار القرار ولا ألما، ولا تمنع أصل لذة دار القرار، وإن منعت كمالها","pg":548},{"q":"كيف تعرف ما عندك من محبة الله كما أرشد ابن القيم؟","o":["انظر إلى محبة القرآن في قلبك","انظر إلى كثرة أصدقائك حولك","انظر إلى ثناء الناس عليك ومدحهم","انظر إلى سعة رزقك ومالك"],"why":"وإذا أردت أن تعلم ما عندك وعند غيرك من محبة الله، فانظر إلى محبة القرآن من قلبك","pg":549}],"scene":{"t":"ساعات السماع","x":"شاب يقضي ساعات يوميا في سماع المقاطع والأغاني، ويشعر أن سماع القرآن ثقيل عليه، ويقول: قلبي سليم ولا علاقة لهذا بإيماني.","opts":["يجعل لنفسه وردا يوميا من سماع القرآن بتدبر، ويقلل ما يشغله عنه تدريجيا","يرى أن الأمر لا يدل على شيء في قلبه فيبقى على حاله","يترك القرآن حتى يشعر برغبة من تلقاء نفسه"],"why":"وإذا أردت أن تعلم ما عندك وعند غيرك من محبة الله، فانظر إلى محبة القرآن من قلبك","pg":549},"act":{"type":"sort","t":"حق أم باطل؟","x":"اقرأ كل بطاقة وضعها في صندوق «حق» إذا كانت اللذة تعين على لذة الآخرة، أو في صندوق «باطل» إذا كانت لا تعين عليها أو تمنع منها، كما قال ابن القيم: فما أعان على اللذة المطلوبة لذاتها فهو حق، وما لم يعن عليها فهو باطل.","a":"حق","b":"باطل","items":[{"x":"آكل وأنام بنية التقوي على الطاعة","ok":"أ"},{"x":"لذة التسلط على الضعفاء والعلو عليهم","ok":"ب"},{"x":"سماع القرآن والتلذذ بتلاوته","ok":"أ"},{"x":"ساعات طويلة في لهو لا ينفع","ok":"ب"},{"x":"التدرب على الرمي والرياضة النافعة","ok":"أ"},{"x":"التعلق بالصور المحرمة","ok":"ب"},{"x":"الفرح بمعرفة الله وذكره","ok":"أ"},{"x":"لذة تعقب ندما وألما أعظم منها","ok":"ب"}]}},"adl":{"show":true,"title":"اللذة والمحبة: من نعيم القلب إلى محبة النساء وحديث من عشق فعف","intro":"يبني ابن القيم هنا ميزان اللذة: كمالها تابع لكمال المحبوب وكمال المحبة، واللذة تحمد بقدر إيصالها إلى لذة الآخرة وأعلاها النظر إلى وجه الله. ثم يقسم لذات الدنيا ثلاثة أنواع، ويقرر أن محبة الله ورسوله وكلامه أنفع المحبة، ويجعل محبة القرآن مقياسا لمحبة الله. ثم يتناول محبة النساء بلغة الفقيه: هي من كمال الرجل، ونكاح المعشوقة دواء العشق، ويقسم عشق النساء والعشاق، ويختم بنقد حديث «من عشق فعف» وبيان أن الصواب وقفه، وأن الفضل لمن صبر لله وعف لله وكتم لله.","points":["اللذة مطلوبة في نفسها، والحكم عليها بعاقبتها: ما أعقب ألما أعظم أو منع لذة أجل فمذموم.","النوع الثاني من اللذات استدراج، كمن قدم لغيره طعاما لذيذا مسموما.","محبة النساء في الحلال من كمال الإنسان، وقد امتن الله بالمودة والرحمة بين الزوجين، والنكاح دواء العشق شرعا وقدرا.","عشق الرجل امرأته قربة وطاعة، والعشق المباح الذي لا يملك يجب فيه الكتمان والعفة والصبر.","حديث «من عشق فعف» لا يصح مرفوعا، والصواب أنه من كلام ابن عباس، فلا يبنى عليه وعد."],"quote":{"x":"والمقصود أن أعظم لذات الدنيا هو السبب الموصل إلى أعظم لذة في الآخرة","pg":546},"quiz":[{"q":"لماذا وصف ابن القيم لذات الظلم والفواحش بأنها استدراج؟","o":["ليذيقهم بها أعظم الآلام","لأنها لا تشغل عن الطاعة","لأنها تقوي البدن على العمل","لأن زمانها يسير لا يؤثر"],"why":"وهذه اللذات في الحقيقة إنما هي استدراج من الله لهم، ليذيقهم بها أعظم الآلام، ويحرمهم بها أكمل اللذات","pg":547},{"q":"ما الدواء الذي جعله الله للعشق بين المتحابين شرعا وقدرا؟","o":["نكاح المعشوقة","الهجر والبعد","الصوم الطويل","كثرة الأسفار"],"why":"فنكاح المعشوقة هو دواء العشق الذي جعله الله دواءه شرعا وقدرا","pg":554},{"q":"أي أقسام عشق النساء يحمد صاحبه عند الله وعند الناس؟","o":["عشق الرجل امرأته","عشق من رآها فجأة","عشق لا يملكه صاحبه","عشق الجمال المطلق"],"why":"عشق هو قربة وطاعة، وهو عشق الرجل امرأته وجاريته. ولهذا يحمد هذا العاشق عند الله وعند الناس","pg":565},{"q":"ما الذي رجحه ابن القيم في حديث «من عشق فعف»؟","o":["أن الصواب وقفه على ابن عباس","أنه حديث صحيح مرفوع ثابت","أنه حسن لغيره بمجموع طرقه","أنه ثابت من رواية عائشة مرفوعا"],"why":"قلت: والصواب في الحديث أنه من كلام ابن عباس رضي الله عنهما موقوفا عليه، فغلط سويد في رفعه","pg":569},{"q":"بم استدل ابن القيم على أن العاشق لا يعد من الشهداء نصا؟","o":["بأن النبي عد الشهداء ولم يذكره","بأن العشق لا يقتل صاحبه أبدا","بأن النبي لعن العاشق وتبرأ منه","بأن الصحابة لم يعرفوا العشق"],"why":"ومما يوضح ذلك أن النبي صلى الله عليه وسلم عد الشهداء في الصحيح... ولم يعد منهم العاشق يقتله العشق","pg":572}],"scene":{"t":"شاب يريد خطبة من تعلق بها","x":"أخبر شاب صالح أباه أن قلبه تعلق بفتاة ذات دين يعرف أهلها، وأنه يريد خطبتها، والأب يميل إلى الرفض لأسباب شكلية لا تتعلق بالدين ولا الخلق.","opts":["يتحرى عن دينها وخلقها، فإن رضيهما أعانه على النكاح الحلال","يرفض ويأمره بنسيانها دون نقاش","يسمح له بالتواصل معها قبل الخطبة ليختبر مشاعره"],"why":"فنكاح المعشوقة هو دواء العشق الذي جعله الله دواءه شرعا وقدرا","pg":554},"act":{"type":"class","t":"حلقة للمربين: ميزان اللذات الثلاث","x":"نشاط للمعلم أو الأب مع مجموعة من الشباب مدته 35 دقيقة، يبني فيه ميزان ابن القيم للذات ويطبقه على واقعهم.","items":["5 دقائق: يسأل المربي: ما أكثر شيء تستمتع به في يومك؟ ويكتب الإجابات دون تعليق","10 دقائق: يعرض أنواع اللذات الثلاثة من كلام ابن القيم (ص 546 إلى 548) مع مثال لكل نوع","10 دقائق: يوزع الإجابات المكتوبة على الأنواع الثلاثة مع الشباب، ويناقش ما يمكن نقله من المباح إلى الموصل للآخرة بالنية","5 دقائق: يقرأ قول ابن القيم: فإذا أردت أن تعلم ما عندك وعند غيرك من محبة الله، فانظر إلى محبة القرآن من قلبك","5 دقائق: يتفق كل شاب على ورد قرآني يومي قصير يسمعه بتدبر لمدة أسبوع"]}},"alt":{}},"highlights":[{"x":"فأطيب ما في الدنيا معرفته ومحبته، وألذ ما في الجنة رؤيته ومشاهدته","pg":543,"lv":"kid"},{"x":"وهذه المحبة التي تنور الوجه، وتشرح الصدر، وتحيي القلب","pg":549,"lv":"kid"},{"x":"فليست الحياة الطيبة إلا بالله","pg":544,"lv":"yth"},{"x":"وكيف يشبع المحب من كلام محبوبه، وهو غاية مطلوبه!","pg":550,"lv":"yth"},{"x":"فما أعان على اللذة المطلوبة لذاتها فهو حق، وما لم يعن عليها فهو باطل","pg":548,"lv":"yth"},{"x":"فنسأل الله العظيم رب العرش العظيم أن يجعلنا ممن آثر حبه على هواه، وابتغى بذلك قربه ورضاه","pg":573,"lv":"yth"},{"x":"فمحبة النساء من كمال الإنسان","pg":558,"lv":"adl"}],"concepts":[{"term":"اللذة المحمودة","def":"وتحمد إذا أعانت على لذة عظيمة دائمة مستقرة لا تنغيص فيها ولا نكد بوجه ما، وهي لذة الآخرة ونعيمها وطيب العيش فيها","pg":541},{"term":"الاستدراج","def":"وهذه اللذات في الحقيقة إنما هي استدراج من الله لهم، ليذيقهم بها أعظم الآلام، ويحرمهم بها أكمل اللذات","pg":547},{"term":"المحبة الخاصة","def":"وهي التي تشغل قلب المحب وفكره وذكره لمحبوبه","pg":549},{"term":"المودة","def":"وجعل بينهما خالص الحب، وهو المودة المقترنة بالرحمة","pg":552},{"term":"العشق المباح الذي لا يملك","def":"كعشق من وصفت له امرأة جميلة، أو رآها فجأة من غير قصد، فأورثه ذلك عشقا لها، ولم يحدث له ذلك العشق معصية","pg":566}],"stories":[{"t":"النبي صلى الله عليه وسلم يسمع القرآن من ابن مسعود","x":"طلب النبي صلى الله عليه وسلم من ابن مسعود أن يقرأ عليه، فتعجب ابن مسعود أن يقرأ على من أنزل عليه القرآن، فقال: إني أحب أن أسمعه من غيري. فقرأ سورة النساء حتى بلغ ﴿فكيف إذا جئنا من كل أمة بشهيد وجئنا بك على هؤلاء شهيدا﴾ فقال: حسبك، فإذا عيناه تذرفان.","pg":550,"lv":"kid","hd":"البخاري 5055 ومسلم 800"},{"t":"إن كان أهل الجنة في مثل هذا","x":"كان بعض المحبين تمر به أوقات من لذة المعرفة والمحبة فيقول: إن كان أهل الجنة في مثل هذا إنهم لفي عيش طيب، وكان غيره يقول: لو علم الملوك ما نحن فيه لجالدونا عليه بالسيوف.","pg":544,"lv":"yth","hd":""},{"t":"زينب بنت جحش زوجها الله من فوق سبع سماوات","x":"لما طلقها زيد وانقضت عدتها أرسله النبي صلى الله عليه وسلم يخطبها، فقالت: ما أنا بصانعة شيئا حتى أوامر ربي، وقامت إلى محرابها فصلت، فتولى الله نكاحها من رسوله، فكانت تفخر على أزواج النبي بذلك.","pg":555,"lv":"adl","hd":"مسلم 1428 والبخاري 7420 و7421"},{"t":"مغيث وبريرة","x":"رأى النبي صلى الله عليه وسلم مغيثا يمشي خلف بريرة بعد فراقها ودموعه تجري على خديه، فشفع له أن تراجعه، فقالت: أتأمرني؟ قال: إنما أشفع، فقالت: لا حاجة لي به، ولم ينكر عليه حبها.","pg":559,"lv":"adl","hd":"البخاري 5283"}],"ready":true}],"tools":{"pharmacy":[{"daa":"كل داء ينزل بالقلب أو البدن","dawa":"الشفاء الذي أنزله الله له","x":"ما أنزل الله داء إلا أنزل له شفاء","pg":4,"lv":"kid"},{"daa":"الجهل","dawa":"سؤال العلماء","x":"وقد جعل النبي ﷺ الجهل داء، وجعل دواءه سؤال العلماء","pg":5,"lv":"adl"},{"daa":"الجهل والشك والريب","dawa":"القرآن","x":"فهو شفاء للقلوب من داء الجهل والشك والريب","pg":6,"lv":"kid"},{"daa":"الأدواء والآلام","dawa":"التداوي بالفاتحة","x":"ولو أحسن العبد التداوي بالفاتحة لرأى لها تأثيرا عجيبا في الشفاء","pg":8,"lv":"kid"},{"daa":"تخلف أثر الرقية","dawa":"قبول المحل وقوة همة الفاعل","x":"وكذلك القلب إذا أخذ الرقى والتعاويذ بقبول تام، وكان للراقي نفس فعالة وهمة مؤثرة، أثر في إزالة الداء","pg":8,"lv":"yth"},{"daa":"المكروه النازل والمطلوب المفقود","dawa":"الدعاء","x":"وكذلك الدعاء، فإنه من أقوى الأسباب في دفع المكروه وحصول المطلوب","pg":9,"lv":"kid"},{"daa":"غفلة القلب عن الله","dawa":"إقبال القلب وجمعيته على الله وقت الدعاء","x":"فهذا دواء نافع مزيل للداء، ولكن غفلة القلب عن الله تبطل قوته","pg":10,"lv":"yth"},{"daa":"أكل الحرام","dawa":"الطيب من المطعم والمشرب والملبس","x":"وكذلك أكل الحرام يبطل قوته ويضعفها","pg":10,"lv":"yth"},{"daa":"البلاء النازل أو المتوقع","dawa":"الدعاء","x":"والدعاء من أنفع الأدوية، وهو عدو البلاء، يدافعه ويعالجه، ويمنع نزوله، ويرفعه، أو يخففه إذا نزل","pg":11,"lv":"kid"},{"daa":"ضعف الدعاء أمام البلاء","dawa":"الإلحاح في الدعاء","x":"ومن أنفع الأدوية: الإلحاح في الدعاء","pg":13,"lv":"kid"},{"daa":"الاستعجال واستبطاء الإجابة","dawa":"المداومة كمن يتعاهد غرسه ويسقيه","x":"وهو بمنزلة من بذر بذرا، أو غرس غراسا، فجعل يتعاهده ويسقيه، فلما استبطأ كماله وإدراكه، تركه وأهمله!","pg":15,"lv":"kid"},{"daa":"رد الدعاء","dawa":"جمع حضور القلب وأوقات الإجابة وآداب الدعاء","x":"فإن هذا الدعاء لا يكاد يرد أبدا","pg":17,"lv":"yth"},{"daa":"الكرب","dawa":"دعوة ذي النون ودعاء الكرب","x":"دعوة ذي النون إذ دعا، وهو في بطن الحوت: ﴿لا إله إلا أنت سبحانك إني كنت من الظالمين﴾ إنه لم يدع بها مسلم في شيء قط إلا استجاب الله له","pg":20,"lv":"kid"},{"daa":"الهم والحزن","dawa":"دعاء «اللهم إني عبدك ابن عبدك»","x":"إلا أذهب الله عز وجل همه وحزنه، وأبدله مكانه فرحا","pg":23,"lv":"kid"},{"daa":"الظن بأن السر في لفظ الدعاء أو في المكان","dawa":"العلم بأن السر في الاضطرار وصدق اللجأ","x":"ولم يعلم أن السر للاضطرار وصدق اللجأ إلى الله","pg":25,"lv":"yth"},{"daa":"ضعف أثر الدعاء","dawa":"صلاح الدعاء وقوة الداعي وانتفاء المانع","x":"والسلاح بضاربه لا بحده فقط","pg":26,"lv":"yth"},{"daa":"ترك الدعاء بحجة القدر","dawa":"العلم بأن المقدور قدر بأسبابه ومنها الدعاء","x":"فإذا قدر وقوع المدعو به بالدعاء لم يصح أن يقال: لا فائدة في الدعاء","pg":29,"lv":"yth"},{"daa":"جلب الشرور ونزول النقم","dawa":"طاعة الله والتقرب إليه والإحسان إلى خلقه","x":"فما استجلبت نعم الله واستدفعت نقمه بمثل طاعته والتقرب إليه، والإحسان إلى خلقه","pg":31,"lv":"yth"},{"daa":"الاتكال على القدر عجزا وتفريطا","dawa":"فقه رد القدر بالقدر","x":"بل الفقيه كل الفقيه الذي يرد القدر بالقدر، ويدفع القدر بالقدر، ويعارض القدر بالقدر","pg":34,"lv":"yth"},{"daa":"خوف العقوبة الأخروية","dawa":"التوبة والإيمان والأعمال الصالحة","x":"يدفع قدر العقوبة الأخروية بقدر التوبة والإيمان والأعمال الصالحة","pg":34,"lv":"yth"},{"daa":"الجهل بأسباب الخير والشر","dawa":"تدبر القرآن ثم السنة","x":"ومن أنفع ما في ذلك تدبر القرآن، فإنه كفيل بذلك على أكمل الوجوه","pg":35,"lv":"yth"},{"daa":"الجهل بتفاصيل أسباب الخير والشر","dawa":"تدبر القرآن ثم السنة والاعتبار بأخبار الأمم","x":"ومن أنفع ما في ذلك تدبّر القرآن، فإنه كفيل بذلك على أكمل الوجوه، وفيه أسباب الشرّ والخير جميعًا مفصّلةً مبيّنةً.","pg":35,"lv":"yth"},{"daa":"مغالطة النفس بالاتكال والتسويف واستغفار اللسان","dawa":"الحذر من مغالطة النفس على أسباب الهلاك","x":"والأمر الثاني: أن يحذر مغالطة نفسه له على هذه الأسباب. وهذا من أهم الأمور","pg":36,"lv":"yth"},{"daa":"الاعتماد على العفو مع الإصرار","dawa":"تذكر أن الله شديد العقاب وأن بأسه لا يرد عن المجرمين","x":"وكثير من الجهال اعتمدوا على رحمة الله وعفوه وكرمه، وضيّعوا أمره ونهيه، ونسوا أنه شديد العقاب، وأنه لا يردّ بأسه عن القوم المجرمين.","pg":51,"lv":"yth"},{"daa":"الفهم الفاسد لنصوص الرجاء","dawa":"العلم ووضع الرجاء في مواضعه","x":"فالعالم يضع الرجاء مواضعه، والجاهل المغتر يضعه في غير مواضعه.","pg":50,"lv":"adl"},{"daa":"حسن الظن مع الإساءة","dawa":"الإحسان والطاعة، فأحسن الناس ظنا أطوعهم","x":"وأحسنُ الناس ظنًّا بربّه أطوعُهم له.","pg":45,"lv":"kid"},{"daa":"اتباع الهوى مع دعوى حسن الظن","dawa":"العمل الذي يحمل عليه حسن الظن","x":"وكلّما حسُن ظنُّه حسُن عملُه، وإلا فحسنُ الظن مع اتباع الهوى عجز.","pg":48,"lv":"yth"},{"daa":"الاغترار بتتابع النعم مع المعصية","dawa":"الحذر من الاستدراج","x":"إذا رأيت الله يتابع نعمه عليك، وأنت مقيم على معاصيه، فاحذره؛ فإنما هو استدراج يستدرجك به.","pg":78,"lv":"yth"},{"daa":"إيثار الدنيا العاجلة على الآخرة","dawa":"الموازنة بين الدنيا الفانية والآخرة الباقية","x":"فكيف والدنيا كلّها من أولها إلى آخرها كنفس واحد من أنفاس الآخرة!","pg":80,"lv":"yth"},{"daa":"الشك في المعاد","dawa":"التفكر في آيات الله الدالة على وجوده وصدق رسله","x":"وإن كنتَ على شك، فراجعْ آيات الربّ تعالى الدالّة على وجوده وقدرته ومشيئته ووحدانيته، وصدق رسُله فيما أخبروا به عنه.","pg":81,"lv":"adl"},{"daa":"تخلف العمل مع التصديق","dawa":"تقوية البصيرة والصبر واليقين","x":"وجِماعُ هذه الأسباب يرجع إلى ضعف البصيرة والصبر.","pg":85,"lv":"yth"},{"daa":"الأماني","dawa":"رجاء يقارنه محبة وخوف وسعي","x":"وأما رجاءٌ لا يقارنه شيء من ذلك، فهو من باب الأماني! والرجاء شيء، والأماني شيء آخر.","pg":88,"lv":"kid"},{"daa":"الجمع بين التقصير والأمن","dawa":"الإحسان مع الخوف كحال الصحابة","x":"ومن تأمل أحوال الصحابة رضي الله عنهم وجدهم في غاية العمل مع غاية الخوف.","pg":91,"lv":"kid"},{"daa":"سموم الذنوب في القلب","dawa":"تركها والحذر منها","x":"وأن ضررها في القلوب كضرر السموم في الأبدان","pg":98,"lv":"kid"},{"daa":"النكتة السوداء والران","dawa":"التوبة والنزع والاستغفار","x":"فإن تاب، ونزع، واستغفر، صقل قلبه","pg":127,"lv":"kid"},{"daa":"استصغار الذنب","dawa":"استحضار عظمة من يعصى","x":"لا تنظر إلى صغر الخطيئة، ولكن انظر من عصيت","pg":126,"lv":"kid"},{"daa":"ضعف الحفظ وحرمان العلم","dawa":"ترك المعاصي","x":"شكوت إلى وكيع سوء حفظي ... فأرشدني إلى ترك المعاصي","pg":132,"lv":"kid"},{"daa":"حرمان الرزق والفقر","dawa":"تقوى الله","x":"فما استجلب رزق الله بمثل ترك المعاصي.","pg":133,"lv":"kid"},{"daa":"وحشة الذنوب","dawa":"ترك الذنوب والأنس بالله","x":"إذا كنت قد أوحشتك الذنوب ... فدعها إذا شئت واستأنس","pg":133,"lv":"kid"},{"daa":"تعسير الأمور","dawa":"التقوى","x":"وهذا كما أن من اتقى الله جعل له من أمره يسرا، فمن عطل التقوى جعل له من أمره عسرا.","pg":134,"lv":"kid"},{"daa":"ظلمة القلب","dawa":"الطاعة","x":"فإن الطاعة نور، والمعصية ظلمة","pg":135,"lv":"kid"},{"daa":"ضياع العمر","dawa":"الإقبال على الله بالحب والذكر","x":"ولا حياة له إلا بإقباله على ربه، والتنعم بحبه وذكره، وإيثار مرضاته.","pg":138,"lv":"yth"},{"daa":"عموم العقوبة في المجتمع","dawa":"الأخذ على يد الظالم وتغيير المنكر","x":"إن الناس إذا رأوا الظالم، فلم يأخذوا على يديه، أوشك أن يعمهم الله بعقاب من عنده","pg":121,"lv":"yth"},{"daa":"توالد المعاصي","dawa":"إلف الطاعة حتى تؤز الملائكة إليها","x":"ولا يزال العبد يعاني الطاعة، ويألفها، ويحبها، ويؤثرها حتى يرسل الله سبحانه برحمته عليه الملائكة تؤزه إليها أزا","pg":140,"lv":"kid"},{"daa":"المجاهرة بالذنب","dawa":"ستر العبد ما ستره الله عليه","x":"وإن من الإجهار أن يستر الله على العبد، ثم يصبح يفضح نفسه","pg":142,"lv":"yth"},{"daa":"ذل المعصية","dawa":"طلب العز بطاعة الله","x":"اللهم أعزني بطاعتك، ولا تذلني بمعصيتك.","pg":146,"lv":"kid"},{"daa":"ذهاب الغيرة","dawa":"إحياء الغيرة التي تدفع داء القلب","x":"ومثل الغيرة في القلب مثل القوة التي تدفع المرض وتقاومه","pg":168,"lv":"adl"},{"daa":"ذهاب الحياء","dawa":"الاستحياء من الله عند المعصية","x":"ومن استحيا من الله عند معصيته استحيا الله من عقوبته يوم يلقاه","pg":170,"lv":"kid"},{"daa":"نسيان العبد لنفسه","dawa":"التقوى والنظر فيما قدم لغد","x":"﴿يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَلْتَنظُرْ نَفْسٌ مَّا قَدَّمَتْ لِغَدٍ﴾","pg":172,"lv":"yth"},{"daa":"إرادة المعصية","dawa":"الإحسان: أن يعبد الله كأنه يراه","x":"فإن الإحسان إذا باشر القلب منعه من المعاصي","pg":174,"lv":"yth"},{"daa":"الهم والحزن والعجز والكسل والجبن والبخل","dawa":"الاستعاذة النبوية منها وترك أسبابها من الذنوب","x":"حتى ينتهي ضعفه إلى الأشياء الثمانية التي استعاذ منها النبي ﷺ","pg":178,"lv":"yth"},{"daa":"زوال النعم","dawa":"تغيير المعصية بالطاعة والتوبة","x":"فإن غير المعصية بالطاعة غير الله عليه العقوبة بالعافية، والذل بالعز.","pg":180,"lv":"kid"},{"daa":"الرعب والخوف","dawa":"خوف الله ودخول حصن الطاعة","x":"فمن خاف الله آمنه من كل شيء، ومن لم يخف الله أخافه من كل شيء.","pg":182,"lv":"yth"},{"daa":"الوحشة","dawa":"القرب من الله بالطاعة","x":"وسر المسألة أن الطاعة توجب القرب من الرب، وكلما اشتد القرب قوي الأنس","pg":183,"lv":"yth"},{"daa":"أمراض القلوب","dawa":"ترك الذنوب ومخالفة الهوى","x":"بل الذنوب أمراض القلوب وأدواؤها، ولا دواء لها إلا تركها.","pg":184,"lv":"yth"},{"daa":"هوى النفس","dawa":"مخالفته","x":"فهواها مرضها، وشفاؤها مخالفته","pg":184,"lv":"yth"},{"daa":"صغر النفس","dawa":"طاعة الله","x":"فما صغر النفوس مثل معصية الله، وما كبرها وشرفها ورفعها مثل طاعة الله.","pg":189,"lv":"yth"},{"daa":"أسر الشيطان وافتراسه","dawa":"التقوى والقرب من الله","x":"وإنما يكون عليه حافظ من الله بالتقوى، فهي وقاية وجنة حصينة بينه وبين ذئبه","pg":191,"lv":"kid"},{"daa":"القطيعة وتولي الشيطان","dawa":"أن يتولاه الله","x":"فإن أعرض الله عنه تولاه الشيطان، وإن تولاه الله لم يقدر عليه الشيطان.","pg":197,"lv":"yth"},{"daa":"محق البركة","dawa":"الإيمان والتقوى","x":"﴿وَلَوْ أَنَّ أَهْلَ الْقُرَىٰ آمَنُوا وَاتَّقَوْا لَفَتَحْنَا عَلَيْهِم بَرَكَاتٍ مِّنَ السَّمَاءِ وَالْأَرْضِ﴾","pg":199,"lv":"kid"},{"daa":"محق البركة في الطعام والشراب والأحوال","dawa":"ذكر اسم الله","x":"ولهذا شرع ذكر اسم الله تعالى عند الأكل والشرب واللبس والركوب والجماع، لما في مقارنة اسم الله من البركة. وذكر اسمه يطرد الشيطان، فتحصل البركة، ولا معارض لها.","pg":202,"lv":"kid"},{"daa":"الإعراض عن الله وموت القلب","dawa":"معرفة الله ومحبته والأنس به","x":"ولا حياة لقلبه إلا بمعرفة فاطره، ومحبته، وعبادته وحده، والإنابة إليه، والطمأنينة بذكره، والأنس بقربه.","pg":201,"lv":"yth"},{"daa":"النزول بالمعصية عن الدرجة","dawa":"التوبة النصوح والإنابة الصادقة","x":"ومنهم من يكون نزوله إلى معصية: إما صغيرة أو كبيرة، فهذا يحتاج في عوده إلى درجته إلى توبة نصوح وإنابة صادقة.","pg":207,"lv":"kid"},{"daa":"النزول إلى الغفلة","dawa":"اليقظة","x":"ولكن من الناس من يكون نزوله إلى غفلة، فهذا متى استيقظ من غفلته عاد إلى درجته، أو إلى أرفع منها بحسب يقظته.","pg":206,"lv":"yth"},{"daa":"داء العجب والثقة بالنفس","dawa":"الانكسار والذل بين يدي الله بعد التوبة","x":"فهذا قد تكون الخطيئة في حقه رحمة، فإنها نفت عنه داء العجب، وخلصته من ثقته بنفسه وأعماله، ووضعت خد ضراعته وذله وانكساره على عتبة باب سيده ومولاه","pg":208,"lv":"adl"},{"daa":"الشك والريب والنفاق","dawa":"تجديد الإسلام من رأس","x":"فإن كان نزوله إلى أمر يقدح في أصل إيمانه مثل الشكوك والريب والنفاق، فذاك نزول لا يرجى لصاحبه صعود إلا بتجديد إسلامه من رأس.","pg":212,"lv":"adl"},{"daa":"اجتراء الشياطين والخلق على العبد","dawa":"الذكر والطاعة والصدقة والأمر بالمعروف","x":"فإن ذكر الله، وطاعته، والصدقة، وإرشاد الجاهل، والأمر بالمعروف والنهي عن المنكر وقاية ترد عن العبد، بمنزلة القوة التي ترد المرض وتقاومه","pg":213,"lv":"kid"},{"daa":"عمى القلب وظلمته","dawa":"الطاعة","x":"وهذا كما أن الطاعة تنور القلب، وتجلوه، وتصقله، وتقويه وتثبته، حتى يصير كالمرآة المجلوة في جلائها وصفائها ويمتلئ نورا","pg":222,"lv":"kid"},{"daa":"العشى عن ذكر الله وتسلط القرين","dawa":"الإقبال على كتاب الله فهما وتدبرا","x":"فأخبر سبحانه أن من عشا عن ذكره وهو كتابه الذي أنزله على رسوله فأعرض عنه، وعمي عنه، وعشت بصيرته عن فهمه وتدبره ومعرفة مراد الله منه قيض الله منه شيطانا عقوبة له بإعراضه عن كتابه.","pg":223,"lv":"yth"},{"daa":"تسلط العدو على القلب","dawa":"الصبر والمصابرة والمرابطة والتقوى","x":"وجماع هذه الثلاثة وعمودها الذي تقوم به هو تقوى الله، فلا ينفع الصبر ولا المصابرة ولا المرابطة إلا بالتقوى، ولا تقوم التقوى إلا على ساق الصبر.","pg":229,"lv":"yth"},{"daa":"الغفلة واتباع الهوى","dawa":"ذكر الله ومخالفة الهوى","x":"وأبلغ أسلحتكم فيهم وأنكاها: الغفلة، واتباع الهوى. وأعظم أسلحتهم فيكم وأمنع حصونهم: ذكر الله، ومخالفة الهوى.","pg":242,"lv":"kid"},{"daa":"نار الغضب والشهوة","dawa":"الماء والصلاة والذكر والتكبير","x":"واعلموا أن الغضب جمرة في قلب ابن آدم، والشهوة نار تثور من قلبه، وإنما تطفأ النار بالماء والصلاة والذكر والتكبير","pg":241,"lv":"yth"},{"daa":"كيد العدو بالشهوة والغضب","dawa":"الصبر والصلاة","x":"وقد أوصاهم الله أن يستعينوا عليكم بالصبر والصلاة، فحولوا بينهم وبين ذلك، وأنسوهم إياه","pg":242,"lv":"yth"},{"daa":"نسيان العبد نفسه وعيوبها وأمراضها","dawa":"ذكر الله وعدم نسيانه","x":"فلما نسوا ربهم سبحانه نسيهم وأنساهم أنفسهم","pg":244,"lv":"yth"},{"daa":"بيع الآخرة بالدنيا","dawa":"تجارة الأكياس: بيع الفاني بالباقي","x":"وأما الرابحون، فإنهم باعوا فانيا بباق، وخسيسا بنفيس، وحقيرا بعظيم","pg":246,"lv":"yth"},{"daa":"زوال النعم","dawa":"الطاعة","x":"فإن نعم الله ما حفظ موجودها بمثل طاعته، ولا استجلب مفقودها بمثل طاعته، فإن ما عنده لا ينال إلا بطاعته.","pg":248,"lv":"kid"},{"daa":"بعد الملك وقرب الشيطان","dawa":"الحياء من الحافظين الكرام وإكرامهم بالطاعة","x":"أي: استحيوا من هؤلاء الحافظين الكرام، وأكرموهم، وأجلوهم أن يروا منكم ما تستحيون أن يراكم عليه من هو مثلكم.","pg":256,"lv":"kid"},{"daa":"أمراض القلب المهلكة","dawa":"غذاء الإيمان واستفراغ التوبة وحمية التقوى","x":"فمن حفظ القوة بامتثال الأوامر، واستعمل الحمية باجتناب النواهي، واستفرغ التخليط بالتوبة النصوح لم يدع للخير مطلبا، ولا من الشر مهربا.","pg":258,"lv":"yth"},{"daa":"قلب لا تزعه العقوبات القدرية ولا يجد لها أثرا","dawa":"استحضار العقوبات الشرعية التي شرعها الله على الجرائم","x":"«فإن لم ترعك هذه العقوبات، ولم تجد لها تأثيرا في قلبك، فأحضره العقوبات الشرعية التي شرعها الله ورسوله على الجرائم»","pg":258,"lv":"adl"},{"daa":"التخليط بين الطاعة والمعصية","dawa":"حفظ القوة بالأوامر، والحمية باجتناب النواهي، والاستفراغ بالتوبة النصوح","x":"«فمن حفظ القوة بامتثال الأوامر، واستعمل الحمية باجتناب النواهي، واستفرغ التخليط بالتوبة النصوح = لم يدع للخير مطلبا، ولا من الشر مهربا»","pg":258,"lv":"kid"},{"daa":"الذنب الذي يعمل في القلب على التدريج ولا يرى صاحبه أثره","dawa":"التدارك بالأدوية والاستفراغ والحمية","x":"«فإن تدارك العبد بالأدوية والاستفراغ والحمية، وإلا فهو صائر إلى الهلاك. هذا إذا كان ذنبا واحدا لم يتداركه بما يزيل أثره، فكيف بالذنب على الذنب كل يوم وكل ساعة؟»","pg":272,"lv":"yth"},{"daa":"شرور النفس وسيئات الأعمال","dawa":"الاستعاذة النبوية في خطبة الحاجة","x":"«فتضمنت هذه الاستعاذة أصل الشر، وفروعه، وغايته، ومقتضاه»","pg":269,"lv":"yth"},{"daa":"عقوبات السيئات في الدنيا والآخرة","dawa":"سؤال الله وقايتها بالتوفيق والمغفرة، والتوسل بسعة علمه ورحمته","x":"«وقاية السيئات نوعان: أحدهما: وقاية فعلها بالتوفيق فلا تصدر منه. والثاني: وقاية جزائها بالمغفرة فلا يعاقب عليها»","pg":270,"lv":"yth"},{"daa":"المعيشة الضنك بالإعراض عن الذكر","dawa":"الإيمان والعمل الصالح، وبهما الحياة الطيبة","x":"«والله تعالى إنما جعل الحياة الطيبة لمن آمن به وعمل صالحا»","pg":280,"lv":"kid"},{"daa":"الشرك والبدعة والشهوة والغفلة والهوى، وهي حجب عن الله","dawa":"سؤال الله الهداية إلى الصراط المستقيم","x":"«ولذلك اشتدت حاجة العبد بل ضرورته إلى أن يسأل الله أن يهديه الصراط المستقيم. فليس العبد أحوج منه إلى هذه الدعوة، وليس شيء أنفع له منها»","pg":283,"lv":"kid"},{"daa":"الصغائر","dawa":"الأعمال المكفرة كالصلوات الخمس، وقوتها على قدر الإخلاص فيها","x":"«أن تقصر عن تكفير الصغائر، لضعفها وضعف الإخلاص فيها والقيام بحقوقها؛ بمنزلة الدواء الضعيف الذي ينقص عن مقاومة الداء كمية وكيفية»","pg":289,"lv":"yth"},{"daa":"إساءة الظن بالله","dawa":"الظن به ما هو أهله من العلم والقدرة والغنى والقيام بالقسط","x":"«فلو ظننتم به ما هو أهله من أنه بكل شيء عليم، وعلى كل شيء قدير، وأنه غني عن كل ما سواه، وكل ما سواه فقير إليه»","pg":319,"lv":"kid"},{"daa":"الرياء والشرك في العبادة","dawa":"العمل الخالص المقيد بالسنة","x":"«فالعمل الصالح هو الخالي من الرياء، المقيد بالسنة»","pg":303,"lv":"kid"},{"daa":"الشرك في الإرادات والنيات","dawa":"الإخلاص لله في الأقوال والأفعال والإرادات والنية","x":"«والإخلاص أن يخلص لله في أقواله وأفعاله وإراداته ونيته. وهذه هي الحنيفية ملة إبراهيم»","pg":313,"lv":"yth"},{"daa":"الشرك في اللفظ كقول: ما شاء الله وشئت","dawa":"إفراد الله بالمشيئة في اللفظ","x":"«قل: ما شاء الله وحده»","pg":310,"lv":"kid","hd":"أحمد وغيره، مداره على الأجلح وهو مختلف فيه، وله شواهد."},{"daa":"التعطيل والقول على الله بلا علم","dawa":"إثبات صفات الكمال التي وصف الله بها نفسه ووصفه بها رسوله","x":"«فداء التعطيل هو الداء العضال الذي لا دواء له»","pg":330,"lv":"adl"},{"daa":"إدخال الوسائط بين الله وخلقه","dawa":"توحيده بالعبادة لأنه القادر الغني العليم الرحيم بذاته","x":"«فأما القادر على كل شيء، الغني بذاته عن كل شيء، العالم بكل شيء، الرحمن الرحيم الذي وسعت رحمته كل شيء فإدخال الوسائط بينه وبين خلقه تنقص بحق ربوبيته، وإلهيته، وتوحيده»","pg":320,"lv":"adl"},{"daa":"قتل النفس عمدا","dawa":"التوبة النصوح مع تسليم النفس للولي","x":"«فإذا سلم القاتل نفسه طوعا واختيارا إلى الولي ندما على ما فعل، وخوفا من الله، وتوبة نصوحا = سقط حق الله بالتوبة، وحق الولي بالاستيفاء أو الصلح أو العفو»","pg":334,"lv":"adl"},{"daa":"غصب المال","dawa":"رد أعيان المال القائمة إلى الوارث","x":"«فإذا كان المال عقارا أو أرضا أو أعيانا قائمة باقية بعد الموت، فهي ملك للوارث، يجب على الغاصب دفعها إليه كل وقت»","pg":336,"lv":"adl"},{"daa":"الزنى وأسبابه","dawa":"غض البصر وحفظ الفرج واستحضار اطلاع الله","x":"«وأمر تعالى نبيه ﷺ أن يأمر المؤمنين بغض أبصارهم وحفظ فروجهم، وأن يعلمهم أنه مشاهد لأعمالهم، مطلع عليها»","pg":347,"lv":"yth"},{"daa":"إطلاق النظر","dawa":"غض البصر من أوله","x":"وفي هذا قيل: الصبر على غض البصر أيسر من الصبر على ألم ما بعده.","pg":350,"lv":"kid"},{"daa":"حسرات النظر","dawa":"حبس اللحظات","x":"وقد قيل: حبس اللحظات أيسر من دوام الحسرات.","pg":353,"lv":"yth"},{"daa":"استدعاء الخواطر الرديئة","dawa":"تركها تمر وعدم محادثتها","x":"فالخاطر كالمار على الطريق، فإن لم تستدعه وتركته مر وانصرف عنك، وإن استدعيته سحرك بحديثه وخدعه وغروره.","pg":360,"lv":"kid"},{"daa":"الأماني الكاذبة","dawa":"مباشرة الحقائق بالعمل وعلو الهمة","x":"وأخس الناس همة وأوضعهم نفسا من رضي من الحقائق بالأماني الكاذبة، واستجلبها لنفسه، وتحلى بها","pg":354,"lv":"yth"},{"daa":"تشتت الهم وتضييع الوقت","dawa":"الفكرة في واجب الوقت وجمع الهم عليه","x":"الخامس: الفكرة في واجب الوقت ووظيفته، وجمع الهم كله عليه.","pg":358,"lv":"yth"},{"daa":"عيوب النفس الخفية","dawa":"الفكرة في عيوب النفس والعمل","x":"الرابع: الفكرة في عيوب النفس وآفاتها وفي عيوب العمل. وهذه الفكرة عظيمة النفع، وهي باب لكل خير","pg":357,"lv":"adl"},{"daa":"فراغ القلب من الخير","dawa":"ملؤه بالفكر في مراضي الرب","x":"إنما الكمال في امتلاء القلب والسر من الخواطر والإرادات والفكر في تحصيل مراضي الرب تعالى","pg":362,"lv":"adl"},{"daa":"فضول الكلام","dawa":"وزن الكلمة قبل النطق بها","x":"فإذا أراد أن يتكلم بالكلمة نظر: هل فيها ربح وفائدة أم لا؟ فإن لم يكن فيها ربح أمسك عنها","pg":363,"lv":"kid"},{"daa":"السكوت عن الحق مداهنة","dawa":"منهج أهل الوسط في الكلام والسكوت","x":"وأهل الوسط، وهم أهل الصراط المستقيم، كفوا ألسنتهم عن الباطل، وأطلقوها فيما يعود عليهم نفعه في الآخرة.","pg":375,"lv":"adl"},{"daa":"الخطى الضائعة","dawa":"نية القربة في المباح","x":"ويمكنه أن يستخرج من كل مباح يخطو إليه قربة ينويها لله، فتقع خطاه قربة.","pg":375,"lv":"kid"},{"daa":"تفرق القلب ووحشته","dawa":"غض البصر","x":"الثالثة: أنه يورث القلب أنسا بالله وجمعية على الله، فإن إطلاق البصر يفرق القلب، ويشتته، ويبعده من الله.","pg":416,"lv":"kid"},{"daa":"ضعف القلب وحزنه","dawa":"غض البصر","x":"الرابعة: أنه يقوي القلب ويفرحه، كما أن إطلاق البصر يضعفه ويحزنه.","pg":416,"lv":"kid"},{"daa":"ظلمة القلب","dawa":"غض البصر","x":"الخامسة: أنه يكسب القلب نورا، كما أن إطلاقه يكسبه ظلمة.","pg":416,"lv":"kid"},{"daa":"ذل المعصية","dawa":"الطاعة","x":"وقد جعل الله سبحانه العز قرين طاعته، والذل قرين معصيته","pg":419,"lv":"kid"},{"daa":"ضعف البصيرة والتمييز","dawa":"غض البصر عن المحارم","x":"السادسة: أنه يورثه فراسة صادقة يميز بها بين المحق والمبطل، والصادق والكاذب.","pg":417,"lv":"yth"},{"daa":"تسلط الشيطان على القلب","dawa":"سد مدخله بغض البصر","x":"الثامنة: أنه يسد على الشيطان مدخله إلى القلب، فإنه يدخل مع النظرة","pg":420,"lv":"yth"},{"daa":"تشتت الفكر عن المصالح","dawa":"غض البصر","x":"التاسعة: أنه يفرغ القلب للفكرة في مصالحه والاشتغال بها، وإطلاق البصر يشتته عن ذلك","pg":421,"lv":"yth"},{"daa":"اتباع الهوى","dawa":"مخالفة الهوى","x":"كما في الأثر: الذي يخالف هواه يفرق الشيطان من ظله.","pg":419,"lv":"yth"},{"daa":"خوف سوء الخاتمة","dawa":"استقامة الظاهر وصلاح الباطن وترك الإصرار على الكبائر","x":"واعلم أن سوء الخاتمة، أعاذنا الله منها، لا تكون لمن استقام ظاهره، وصلح باطنه","pg":391,"lv":"yth"},{"daa":"داء العشق","dawa":"حسم مادته قبل حصولها، أو قلعها بعد نزولها","x":"والكلام في دواء هذا الداء من طريقين: أحدهما: حسم مادته قبل حصولها. والثاني: قلعها بعد نزولها.","pg":415,"lv":"adl"},{"daa":"تعلق القلب بالصور","dawa":"اشتغاله بخوف مقلق أو حب مزعج","x":"الثاني: اشتغال القلب بما يصده عن ذلك، ويحول بينه وبين الوقوع فيه. وهو إما خوف مقلق، أو حب مزعج.","pg":422,"lv":"adl"},{"daa":"عشق الصور","dawa":"محبة المحبوب الأعلى","x":"فلا يمكن أن يجتمع في القلب حب المحبوب الأعلى وعشق الصور أبدا، بل هما ضدان لا يتلاقيان","pg":424,"lv":"adl"},{"daa":"ضعف الهمة عن إيثار الأنفع","dawa":"قوة العزم والصبر","x":"الثاني: قوة عزم وصبر يتمكن بها من هذا الفعل والترك.","pg":423,"lv":"adl"},{"daa":"الذنب الكبير","dawa":"التوبة النصوح","x":"وقد ضمن الله سبحانه لمن تاب من الشرك وقتل النفس والزنى أنه يبدل سيئاته حسنات. وهذا حكم عام لكل تائب من كل ذنب.","pg":385,"lv":"adl"},{"daa":"تشتت القلب بين محبوبين","dawa":"توحيد المحبوب وصرف قوة الحب إلى الله","x":"والمحبة الصادقة تقتضي توحيد المحبوب، وأن لا يشرك بينه وبين غيره في محبته.","pg":424,"lv":"yth"},{"daa":"التعلق بمحبة غير الله وعذابها","dawa":"الإقبال على محبة الله وذكره والشوق إلى لقائه","x":"بل من أعرض عن محبة الله وذكره والشوق إلى لقائه ابتلاه بمحبة غيره، فيعذبه بها في الدنيا وفي البرزخ وفي الآخرة.","pg":425,"lv":"yth"},{"daa":"المشاق والمخاوف","dawa":"أن يكون العبد بالله في معيته الخاصة","x":"فمتى كان العبد بالله هانت عليه المشاق، وانقلبت المخاوف في حقه أمانا. فبالله يهون كل صعب، ويسهل كل عسير، ويقرب كل بعيد.","pg":436,"lv":"kid"},{"daa":"الهموم والغموم والأحزان","dawa":"الأنس بالله وصحبة ذكره","x":"وبالله تزول الهموم والغموم والأحزان. فلا هم مع الله، ولا غم، ولا حزن","pg":437,"lv":"kid"},{"daa":"تفرق الهموم وشعث القلب","dawa":"جمع الهم على مرضاة الله","x":"وأي حياة أطيب من حياة من اجتمعت همومه كلها، وصارت هما واحدا في مرضاة الله، ولم شعث قلبه بالإقبال على الله","pg":430,"lv":"yth"},{"daa":"غلبة سلطان الشهوة على العقل","dawa":"قوة الإدراك وشجاعة القلب","x":"فإذا صح إدراكه، وقويت نفسه، وتشجع القلب على إيثار المحبوب الأعلى والمكروه الأدنى؛ فقد وفق لأسباب السعادة.","pg":448,"lv":"yth"},{"daa":"إيثار مريض القلب ما يزيد مرضه","dawa":"الاحتماء كما يحتمي المريض بأمر الطبيب","x":"فهكذا أكثر مرضى القلوب يؤثرون ما يزيد مرضهم لقوة شهوتهم له.","pg":448,"lv":"yth"},{"daa":"طلب اللذة بما يعقب الألم","dawa":"النظر في العواقب وإيثار الدائم على الزائل","x":"وخاصة العقل: النظر في العواقب، فأعقل الناس من آثر لذته وراحته الآجلة الدائمة على العاجلة المنقضية الزائلة","pg":450,"lv":"yth"},{"daa":"الهم والغم الذي يسعى كل الناس في دفعه","dawa":"الإقبال على الله ومعاملته وحده","x":"ولم أر في جميع هذه الطرق طريقا موصلة إلا الإقبال على الله ومعاملته وحده، وإيثار مرضاته على كل شيء.","pg":450,"lv":"yth"},{"daa":"حب الراحة والدعة والرفاهية","dawa":"احتمال المكروه الموصل إلى المحبوب كشرب الدواء الكريه","x":"والنفوس تحب الراحة والدعة والرفاهية، وذلك شر لها لإفضائه إلى فوات هذا المحبوب.","pg":453,"lv":"yth"},{"daa":"تحكم سلطان الشهوة في ظلام ليل المحبة","dawa":"الصبر وتذكر أن اللذة ساعة ثم تنقضي","x":"فإن اشتد ظلام ليل المحبة، وتحكم سلطان الشهوة والإرادة يقول: يا نفس اصبري، فما هي إلا ساعة ثم تنقضي ويذهب هذا كله ويزول","pg":454,"lv":"yth"},{"daa":"إرادة أو شبهة تزاحم محبة الله ورسوله","dawa":"كمال الحب لله ورسوله وكمال التصديق","x":"وكل إرادة تمنع كمال الحب لله ورسوله وتزاحم هذه المحبة، أو شبهة تمنع كمال التصديق؛ فهي معارضة لأصل الإيمان أو مضعفة له.","pg":455,"lv":"adl"},{"daa":"موت الشهادة في القلب أو نومها","dawa":"القيام بالشهادة ظاهرا وباطنا","x":"فيكون قائما بشهادته في ظاهره وباطنه، في قلبه وقالبه. فإن من الناس من تكون شهادته ميتة، ومنهم من تكون نائمة إذا نبهت انتبهت","pg":458,"lv":"yth"},{"daa":"ضيق الصدر","dawa":"شرح الصدر بالإسلام والإخلاص لله","x":"فأي نعيم أطيب من شرح الصدر؟ وأي عذاب أمر من ضيق الصدر؟","pg":459,"lv":"kid"},{"daa":"الغفلة عن ألم فوت الله","dawa":"الإقبال على الله واشتغاله بذكره وتنعمه بحبه","x":"ولا شيء على الإطلاق أنفع للعبد من إقباله على الله، واشتغاله بذكره، وتنعمه بحبه، وإيثاره لمرضاته","pg":461,"lv":"kid"},{"daa":"المحبة الطبعية إذا ألهت","dawa":"ألا تشغل عن ذكر الله ومحبته","x":"فتلك لا تذم إلا إذا ألهت عن ذكر الله وشغلت عن محبته.","pg":444,"lv":"kid"},{"daa":"المحبة الفاسدة","dawa":"العلم الصحيح ومخالفة الهوى الغالب","x":"فلا تقع المحبة الفاسدة إلا من جهل واعتقاد فاسد، أو هوى غالب، أو ما تركب من ذلك، وأعان بعضه بعضا","pg":474,"lv":"adl"},{"daa":"عشق الصور، الداء القتال المضاد للتوحيد","dawa":"معرفة أنه مضاد للتوحيد، ثم العبادات الشاغلة، ثم كثرة اللجأ والتضرع","x":"ودواء هذا الداء القتال: أن يعرف ما ابتلي به من الداء المضاد للتوحيد أولا، ثم يأتي من العبادات الظاهرة والباطنة بما يشغل قلبه عن دوام الفكرة فيه، ويكثر اللجأ والتضرع إلى الله سبحانه","pg":490,"lv":"yth"},{"daa":"تمكن عشق الصور من القلب","dawa":"الإخلاص لله","x":"وليس له دواء أنفع من الإخلاص لله. وهو الدواء الذي ذكره الله في كتابه","pg":491,"lv":"yth"},{"daa":"القلب الفارغ الذي يتمكن منه العشق","dawa":"إخلاص القلب والعمل لله","x":"فإن القلب إذا خلص وأخلص عمله لله لم يتمكن منه عشق الصور، فإنه إنما يتمكن من قلب فارغ","pg":491,"lv":"yth"},{"daa":"التردد بين مصلحة ومفسدة","dawa":"معرفة الراجح ثم إيثار الأصلح","x":"فالعلمي طلب معرفة الراجح من طرفي المصلحة والمفسدة، فإذا تبين له الرجحان وجب عليه إيثار الأصلح له","pg":492,"lv":"yth"},{"daa":"العشق في مقام الابتداء","dawa":"المدافعة بكل ما يقدر عليه","x":"فأما مقام ابتدائه، فالواجب عليه فيه مدافعته بكل ما يقدر عليه","pg":499,"lv":"adl"},{"daa":"العشق في مقام التوسط والانتهاء","dawa":"الكتمان وترك الهتك","x":"فعليه كتمان ذلك، وأن لا يفشيه إلى الخلق، ولا يشبب بمحبوبه ويهتكه بين الناس","pg":499,"lv":"adl"},{"daa":"تولد العشق من تكرار النظر والطمع","dawa":"قطع تكرار النظر والطمع","x":"فلولا تكراره النظر إلى وجه معشوقه وطمعه في وصاله لم يتمكن عشقه من قلبه","pg":506,"lv":"yth"},{"daa":"إطالة الفكر في محاسن المعشوق","dawa":"الخوف الديني من النار وغضب الجبار","x":"وقارنه خوف ما هو أكبر عنده من لذة وصاله: إما خوف ديني كدخول النار، وغضب الجبار، واحتقاب الأوزار؛ وغلب هذا الخوف على ذلك الطمع والفكر، لم يحدث له العشق","pg":507,"lv":"yth"},{"daa":"انجذاب القلب إلى محبوب أدنى","dawa":"تقديم محبوب أحب وأنفع","x":"وكذلك إذا خاف من فوات محبوب هو أحب إليه وأنفع له من ذلك المعشوق، وقدم محبته على محبة المعشوق؛ اندفع عنه العشق","pg":507,"lv":"yth"},{"daa":"تعلق القلب بغير الله","dawa":"تأمل إحسان الله الدائم مع إساءة العبد","x":"فكيف لا يحب العبد بكل قلبه وجوارحه من يحسن إليه على الدوام بعدد الأنفاس، مع إساءته؟","pg":536,"lv":"yth"},{"daa":"اللذات القاطعة عن الله","dawa":"معرفة الله ومحبته، فهي جنة الدنيا","x":"بل لذات الدنيا القاطعة عن ذلك تنقلب آلاما وعذابا، ويبقى صاحبها في المعيشة الضنك، فليست الحياة الطيبة إلا بالله","pg":543,"lv":"yth"},{"daa":"فراغ القلب من محبة الله وكلامه","dawa":"محبة القرآن والتلذذ بسماعه","x":"وإذا أردت أن تعلم ما عندك وعند غيرك من محبة الله، فانظر إلى محبة القرآن من قلبك","pg":549,"lv":"yth"},{"daa":"الإعجاب بامرأة أجنبية عند المتزوج","dawa":"أن يأتي أهله","x":"ومنها: الأمر بمداواة الإعجاب بالمرأة المورث لشهوتها بأنفع الأدوية، وهو قضاء وطره من أهله، وذلك ينقص شهوته لها","pg":553,"lv":"adl"},{"daa":"العشق بين متحابين يحل لهما النكاح","dawa":"النكاح","x":"فنكاح المعشوقة هو دواء العشق الذي جعله الله دواءه شرعا وقدرا","pg":554,"lv":"adl"},{"daa":"عشق المردان، الداء الدوي","dawa":"الاستعانة بمقلب القلوب وصدق اللجأ والذكر والتعوض بحبه والتفكر في العاقبة","x":"ودواء هذا الداء الدوي: الاستعانة بمقلب القلوب، وصدق اللجأ إليه، والاشتغال بذكره، والتعوض بحبه وقربه، والتفكر في الألم الذي يعقبه هذا العشق، واللذة التي تفوته به","pg":566,"lv":"adl"},{"daa":"العشق المباح الذي لا يملك","dawa":"المدافعة والاشتغال بالأنفع، والكتمان والعفة والصبر","x":"والأنفع له مدافعته، والاشتغال بما هو أنفع له. والواجب على هذا أن يكتم، ويعف، ويصبر على بلواه","pg":566,"lv":"adl"}],"dua":{"cond":[{"x":"حضور القلب وجمعيته بكليته على المطلوب","pg":16},{"x":"خشوعا في القلب، وانكسارا بين يدي الرب، وذلا له، وتضرعا ورقة","pg":16},{"x":"واستقبل الداعي القبلة","pg":16},{"x":"وكان على طهارة","pg":16},{"x":"ورفع يديه إلى الله تعالى","pg":16},{"x":"وبدأ بحمد الله والثناء عليه","pg":16},{"x":"ثم ثنى بالصلاة على محمد عبده ورسوله ﷺ","pg":16},{"x":"ثم قدم بين يدي حاجته التوبة والاستغفار","pg":17},{"x":"ثم دخل على الله، وألح عليه في المسألة، وتملقه، ودعاه رغبة ورهبة","pg":17},{"x":"وتوسل إليه بأسمائه وصفاته وتوحيده","pg":17},{"x":"وقدم بين يدي دعائه صدقة","pg":17},{"x":"الإلحاح في الدعاء","pg":13},{"x":"الدعاء الصالح في نفسه، والداعي يجمع بين قلبه ولسانه، والمانع مفقود","pg":26},{"x":"الأدعية التي أخبر النبي ﷺ أنها مظنة الإجابة، أو أنها متضمنة للاسم الأعظم","pg":17}],"bar":[{"x":"بأن يكون دعاء لا يحبه الله لما فيه من العدوان","pg":9},{"x":"لضعف القلب وعدم إقباله على الله وجمعيته عليه وقت الدعاء","pg":9},{"x":"أكل الحرام","pg":9},{"x":"والظلم","pg":9},{"x":"ورين الذنوب على القلوب","pg":9},{"x":"واستيلاء الغفلة والسهو واللهو وغلبتها عليها","pg":9},{"x":"أن يستعجل العبد، ويستبطئ الإجابة، فيستحسر، ويدع الدعاء","pg":15},{"x":"ما لم يدع بإثم أو قطيعة رحم","pg":15},{"x":"أو الداعي لم يجمع بين قلبه ولسانه في الدعاء، أو كان ثم مانع من الإجابة","pg":26},{"x":"فظنت طائفة صحة هذا السؤال، فتركت الدعاء، وقالت: لا فائدة فيه!","pg":26}],"times":[{"x":"الثلث الأخير من الليل","pg":16},{"x":"وعند الأذان","pg":16},{"x":"وبين الأذان والإقامة","pg":16},{"x":"وأدبار الصلوات المكتوبات","pg":16},{"x":"وعند صعود الإمام يوم الجمعة على المنبر حتى تقضى الصلاة","pg":16},{"x":"وآخر ساعة بعد العصر من ذلك اليوم","pg":16},{"x":"ضرورة صاحبه، وإقباله على الله","pg":25},{"x":"أو حسنة تقدمت منه جعل الله سبحانه إجابة دعوته شكرا لحسنته","pg":25},{"x":"السر للاضطرار وصدق اللجأ إلى الله. فإذا حصل ذلك في بيت من بيوت الله كان أفضل وأحب إلى الله","pg":26}],"maqamat":[{"x":"أحدها: أن يكون أقوى من البلاء، فيدفعه.","pg":12},{"x":"الثاني: أن يكون أضعف من البلاء، فيقوى عليه البلاء، فيصاب به العبد، ولكن قد يخففه، وإن كان ضعيفا.","pg":12},{"x":"الثالث: أن يتقاوما، ويمنع كل واحد منهما صاحبه.","pg":12}]},"rajaa":[{"x":"ولا ريب أنّ حسن الظن إنما يكون مع الإحسان، فإنّ المحسن حسن الظن بربه أنه يجازيه على إحسانه، ولا يخلف وعده، ويقبل توبته.","pg":44},{"x":"ولا يجامع وحشةَ الإساءة إحسانُ الظنّ أبدًا، فإنّ المسيء مستوحش بقدر إساءته. وأحسنُ الناس ظنًّا بربّه أطوعُهم له.","pg":45},{"x":"فإذا ظنّ أنه يُدخله الجنة كان هذا غرورًا وخداعًا من نفسه، وتسويلًا من الشيطان، لا إحسانَ ظنٍّ بربّه.","pg":46},{"x":"ومن تأمل هذا الموضع حقّ التأمل علم أنّ حسنَ الظن بالله هو حسنُ العمل نفسه.","pg":48},{"x":"فالذي حمله على العمل حسنُ الظن، وكلّما حسُن ظنُّه حسُن عملُه، وإلا فحسنُ الظن مع اتباع الهوى عجز.","pg":48},{"x":"وبالجملة، فحسن الظن إنّما يكون مع انعقاد أسباب النجاة. وأما مع انعقاد أسباب الهلاك، فلا يتأتّى إحسان الظن.","pg":49},{"x":"بل حسن الظن ينفع من تاب، وندم، وأقلع، وبدّل السيئة بالحسنة، واستقبل بقية عمره بالخير والطاعة، ثم حسّن الظنّ. فهذا حسن الظن، والأول غرور!","pg":49},{"x":"ولا تستطِلْ هذا الفصل، فإنّ الحاجة إليه شديدة لكل أحد، ففرّقٌ بين حسن الظن بالله وبين الغِرّة به.","pg":50},{"x":"فالعالم يضع الرجاء مواضعه، والجاهل المغتر يضعه في غير مواضعه.","pg":50},{"x":"ومن اعتمد على العفو مع الإصرار فهو كالمعاند.","pg":51},{"x":"فقد تبين الفرق بين حسن الظن والغرور، وأنّ حسن الظن إن حمل على العمل، وحثّ عليه، وساق إليه، فهو صحيح. وإن دعا إلى البطالة والانهماك في المعاصي، فهو غرور.","pg":86},{"x":"وحسن الظن هو الرجاء. فمن كان رجاؤه حاديًا له على الطاعة، زاجرًا له عن المعصية، فهو رجاء صحيح. ومن كانت بطالته رجاءً، ورجاؤه بطالةً وتفريطًا، فهو المغرور.","pg":86},{"x":"فتأمّلْ كيف جعل رجاءَهم إتيانَهم بهذه الطاعات!","pg":87},{"x":"وسرّ المسألة أنّ الرجاء وحسن الظن إنما يكون مع الإتيان بالأسباب التي اقتضتها حكمة الله في شرعه، وقدَره، وثوابه وكرامته؛ فيأتي العبد بها، ثم يحسن ظنّه بربه، ويرجوه أن لا يكِلَه إليها، وأن يجعلها موصلةً إلى ما ينفعه، ويصرف ما يعارضها، ويبطل أثرها.","pg":87},{"x":"ومما ينبغي أن يعلم أنّ من رجا شيئًا استلزم رجاؤه أمورًا: أحدها: محبة ما يرجوه.","pg":87},{"x":"الثاني: خوفه من فواته.","pg":87},{"x":"الثالث: سعيه في تحصيله بحسب الإمكان.","pg":88},{"x":"وأما رجاءٌ لا يقارنه شيء من ذلك، فهو من باب الأماني! والرجاء شيء، والأماني شيء آخر.","pg":88},{"x":"فكلُّ راجٍ خائفٌ، والسائر على الطريق إذا خاف أسرعَ السيرَ مخافةَ الفوات.","pg":88},{"x":"وهو سبحانه كما جعل الرجاء لأهل الأعمال الصالحة، فكذلك جعل الخوف لأهل الأعمال. فعُلم أنّ الرجاء والخوف النافع هو ما اقترن به العمل.","pg":89},{"x":"والله سبحانه وصف أهل السعادة بالإحسان مع الخوف، ووصف الأشقياء بالإساءة مع الأمن.","pg":91}],"effects":[{"t":"الذنوب تضر ولابد","x":"فمما ينبغي أن يعلم أن الذنوب تضر ولابد، وأن ضررها في القلوب كضرر السموم في الأبدان","pg":98,"lv":"kid","cat":"qlb"},{"t":"كل شر في الدنيا والآخرة سببه الذنوب","x":"وهل في الدنيا والآخرة شر وداء إلا وسببه الذنوب والمعاصي؟","pg":98,"lv":"yth","cat":"akh"},{"t":"هلاك الأمم بإضاعة أمر الله","x":"ما أهون الخلق على الله عز وجل إذا أضاعوا أمره!","pg":101,"lv":"yth","cat":"rab"},{"t":"عموم العقوبة بترك تغيير المنكر","x":"إن الناس إذا رأوا الظالم، فلم يأخذوا على يديه، أوشك أن يعمهم الله بعقاب من عنده","pg":121,"lv":"yth","cat":"akh"},{"t":"الران على القلب","x":"إن المؤمن إذا أذنب نكتت في قلبه نكتة سوداء، فإن تاب، ونزع، واستغفر، صقل قلبه","pg":127,"lv":"kid","cat":"qlb"},{"t":"تأخر أثر الذنب لا يعني السلامة","x":"ولم يعلم المغتر أن الذنب ينقض، ولو بعد حين؛ كما ينقض السم","pg":130,"lv":"yth","cat":"qlb"},{"t":"المذلة العاجلة","x":"إن الرجل ليصيب الذنب في السر، فيصبح وعليه مذلته.","pg":131,"lv":"yth","cat":"qlb"},{"t":"حرمان العلم","x":"فمنها: حرمان العلم، فإن العلم نور يقذفه الله في القلب، والمعصية تطفئ ذلك النور.","pg":132,"lv":"kid","cat":"qlb"},{"t":"حرمان الرزق","x":"وكما أن تقوى الله مجلبة للرزق، فترك التقوى مجلبة للفقر.","pg":133,"lv":"kid","cat":"hay"},{"t":"الوحشة بين العاصي وربه","x":"ومنها: وحشة يجدها العاصي في قلبه بينه وبين الله، لا يوازنها ولا يقارنها لذة أصلا.","pg":133,"lv":"kid","cat":"qlb"},{"t":"الوحشة بينه وبين الناس","x":"ومنها: الوحشة التي تحصل له بينه وبين الناس، ولا سيما أهل الخير منهم","pg":134,"lv":"kid","cat":"qlb"},{"t":"تعسير الأمور","x":"ومنها: تعسير أموره عليه. فلا يتوجه لأمر إلا يجده مغلقا دونه، أو متعسرا عليه.","pg":134,"lv":"kid","cat":"hay"},{"t":"ظلمة القلب","x":"ومنها: ظلمة يجدها في قلبه حقيقة، يحس بها كما يحس بظلمة الليل البهيم إذا ادلهم","pg":134,"lv":"kid","cat":"qlb"},{"t":"وهن القلب والبدن","x":"ومنها: أن المعاصي توهن القلب والبدن.","pg":136,"lv":"yth","cat":"qlb"},{"t":"حرمان الطاعة","x":"فلو لم يكن للذنب عقوبة إلا أنه يصد عن طاعة تكون بدله، ويقطع طريق طاعة أخرى","pg":136,"lv":"kid","cat":"rab"},{"t":"قصر العمر ومحق بركته","x":"ومنها: أن المعاصي تقصر العمر، وتمحق بركته، ولابد؛ فإن البر كما يزيد في العمر، فالفجور يقصر العمر.","pg":137,"lv":"yth","cat":"hay"},{"t":"المعاصي تزرع أمثالها","x":"ومنها: أن المعاصي تزرع أمثالها، ويولد بعضها بعضا حتى يعز على العبد مفارقتها والخروج منها","pg":139,"lv":"kid","cat":"qlb"},{"t":"تضعف القلب عن إرادته","x":"أنها تضعف القلب عن إرادته، فتقوى إرادة المعصية، وتضعف إرادة التوبة شيئا فشيئا","pg":141,"lv":"yth","cat":"qlb"},{"t":"ينسلخ من القلب استقباحها","x":"ومنها: أنه ينسلخ من القلب استقباحها، فتصير له عادة","pg":141,"lv":"yth","cat":"qlb"},{"t":"كل معصية ميراث عن أمة","x":"ومنها: أن كل معصية من المعاصي فهي ميراث عن أمة من الأمم التي أهلكها الله عز وجل.","pg":142,"lv":"yth","cat":"rab"},{"t":"هوان العبد على ربه","x":"ومنها: أن المعصية سبب لهوان العبد على ربه، وسقوطه من عينه.","pg":144,"lv":"yth","cat":"qlb"},{"t":"الذنب يهون ويصغر في القلب","x":"فإن الذنب كلما صغر في عين العبد عظم عند الله.","pg":144,"lv":"kid","cat":"qlb"},{"t":"شؤم الذنوب على الناس والدواب","x":"ومنها: أن غيره من الناس والدواب يعود عليه شؤم ذنوبه، فيحترق هو وغيره بشؤم الذنوب والظلم.","pg":145,"lv":"yth","cat":"hay"},{"t":"المعصية تورث الذل","x":"ومنها: أن المعصية تورث الذل، ولابد؛ فإن العز كل العز في طاعة الله تعالى.","pg":146,"lv":"kid","cat":"hay"},{"t":"المعاصي تفسد العقل","x":"فإن للعقل نورا، والمعصية تطفئ نور العقل، ولابد","pg":147,"lv":"yth","cat":"qlb"},{"t":"الطبع على القلب","x":"ومنها: أن الذنوب إذا تكاثرت طبع على قلب صاحبها، فكان من الغافلين","pg":148,"lv":"yth","cat":"qlb"},{"t":"الدخول تحت اللعنة","x":"ومنها: أن الذنوب تدخل العبد تحت لعنة رسول الله ﷺ.","pg":149,"lv":"adl","cat":"rab"},{"t":"حرمان دعوة الرسول والملائكة","x":"ومنها: حرمان دعوة رسول الله ﷺ ودعوة الملائكة.","pg":152,"lv":"yth","cat":"rab"},{"t":"عقوبات البرزخ في حديث سمرة","x":"ومن عقوبات المعاصي: ما رواه البخاري في صحيحه من حديث سمرة بن جندب","pg":153,"lv":"yth","cat":"qlb"},{"t":"الفساد في الأرض","x":"أنها تحدث في الأرض أنواعا من الفساد في المياه، والهواء، والزروع، والثمار، والمساكن.","pg":157,"lv":"yth","cat":"hay"},{"t":"تطفئ نار الغيرة","x":"أنها تطفئ من القلب نار الغيرة التي هي لحياته وصلاحه كالحرارة الغريزية لحياة جميع البدن.","pg":163,"lv":"yth","cat":"qlb"},{"t":"ذهاب الحياء","x":"ومن عقوباتها: ذهاب الحياء الذي هو مادة الحياة للقلب، وهو أصل كل خير، وذهابه ذهاب الخير أجمعه.","pg":168,"lv":"kid","cat":"rab"},{"t":"ضعف تعظيم الرب","x":"أنها تضعف في القلب تعظيم الرب جل جلاله، وتضعف وقاره في قلب العبد، ولابد، شاء أم أبى.","pg":170,"lv":"yth","cat":"qlb"},{"t":"نسيان الله لعبده","x":"أنها تستدعي نسيان الله لعبده، وتركه، وتخليته بينه وبين نفسه وشيطانه. وهنالك الهلاك الذي لا يرجى معه نجاة.","pg":172,"lv":"yth","cat":"rab"},{"t":"الخروج من دائرة الإحسان","x":"أنها تخرج العبد من دائرة الإحسان، وتمنعه ثواب المحسنين.","pg":174,"lv":"yth","cat":"qlb"},{"t":"الخروج من دائرة الإيمان","x":"فإن عصاه بالمعاصي التي تخرجه من دائرة الإيمان... فاته رفقة المؤمنين وحسن دفاع الله عنهم","pg":175,"lv":"yth","cat":"rab"},{"t":"ضعف سير القلب إلى الله","x":"أنها تضعف سير القلب إلى الله والدار الآخرة، أو تعوقه، أو توقفه وتقطعه عن السير","pg":178,"lv":"yth","cat":"qlb"},{"t":"جلب الهم والحزن والعجز والكسل","x":"والمقصود أن الذنوب من أقوى الأسباب الجالبة لهذه الثمانية","pg":179,"lv":"yth","cat":"qlb"},{"t":"زوال النعم وحلول النقم","x":"فما زالت عن العبد نعمة إلا بذنب، ولا حلت به نقمة إلا بذنب","pg":179,"lv":"kid","cat":"hay"},{"t":"الرعب والخوف","x":"ما يلقيه الله سبحانه من الرعب والخوف في قلب العاصي، فلا تراه إلا خائفا مرعوبا.","pg":182,"lv":"yth","cat":"rab"},{"t":"الوحشة العظيمة","x":"أنها توقع الوحشة العظيمة في القلب، فيجد المذنب نفسه مستوحشا","pg":182,"lv":"yth","cat":"qlb"},{"t":"مرض القلب","x":"أنها تصرف القلب عن صحته واستقامته إلى مرضه وانحرافه، فلا يزال مريضا معلولا","pg":184,"lv":"yth","cat":"qlb"},{"t":"عمى البصيرة","x":"أنها تعمي بصيرة القلب، وتطمس نوره، وتسد طرق العلم، وتحجب مواد الهداية.","pg":187,"lv":"yth","cat":"qlb"},{"t":"تصغير النفس","x":"أنها تصغر النفس، وتقمعها، وتدسيها، وتحقرها، حتى تصير أصغر شيء وأحقره","pg":189,"lv":"yth","cat":"qlb"},{"t":"أسر الشيطان","x":"أن العاصي دائما في أسر شيطانه، وسجن شهواته، وقيود هواه؛ فهو أسير مسجون مقيد.","pg":190,"lv":"kid","cat":"rab"},{"t":"سقوط الجاه والكرامة","x":"سقوط الجاه والمنزلة والكرامة عند الله وعند خلقه.","pg":192,"lv":"yth","cat":"hay"},{"t":"سلب أسماء المدح","x":"أنها تسلب صاحبها أسماء المدح والشرف، وتكسوه أسماء الذم والصغار.","pg":193,"lv":"yth","cat":"qlb"},{"t":"نقصان العقل","x":"أنها تؤثر بالخاصية في نقصان العقل.","pg":194,"lv":"yth","cat":"qlb"},{"t":"القطيعة بين العبد وربه","x":"أنها توجب القطيعة بين العبد وبين ربه تبارك وتعالى، وإذا وقعت القطيعة انقطعت عنه أسباب الخير، واتصلت به أسباب الشر.","pg":196,"lv":"yth","cat":"qlb"},{"t":"محق البركة","x":"أنها تمحق بركة العمر، وبركة الرزق، وبركة العلم، وبركة العمل، وبركة الطاعة. وبالجملة، تمحق بركة الدين والدنيا.","pg":199,"lv":"kid","cat":"hay"},{"t":"تمحق البركة","x":"ومن عقوباتها: أنها تمحق بركة العمر، وبركة الرزق، وبركة العلم، وبركة العمل، وبركة الطاعة. وبالجملة، تمحق بركة الدين والدنيا.","pg":199,"lv":"kid","cat":"hay"},{"t":"تجعل صاحبها من السفلة","x":"ومن عقوباتها: أنها تجعل صاحبها من السفلة بعد أن كان مهيأ لأن يكون من العلية.","pg":205,"lv":"kid","cat":"qlb"},{"t":"تجرئ عليه المخلوقات","x":"ومن عقوباتها: أنها تجرئ على العبد من لم يكن يجترئ عليه من أصناف المخلوقات.","pg":212,"lv":"kid","cat":"qlb"},{"t":"تخونه أحوج ما يكون إلى نفسه","x":"ومن عقوباتها: أنها تخون العبد أحوج ما يكون إلى نفسه.","pg":213,"lv":"yth","cat":"qlb"},{"t":"تعمي القلب","x":"ومن عقوباتها: أنها تعمي القلب، فإن لم تعمه أضعفت بصيرته، ولابد.","pg":220,"lv":"kid","cat":"qlb"},{"t":"مدد من الإنسان لعدوه","x":"ومن عقوباتها: أنها مدد من الإنسان يمد به عدوه عليه، وجيش يقويه به على حربه.","pg":225,"lv":"kid","cat":"qlb"},{"t":"تنسي العبد نفسه","x":"ومن عقوباتها: أنها تنسي العبد نفسه، فإذا نسي نفسه أهملها وأفسدها وأهلكها.","pg":243,"lv":"yth","cat":"qlb"},{"t":"تزيل النعم","x":"ومن عقوباتها: أنها تزيل النعم الحاضرة، وتقطع النعم الواصلة، فتزيل الحاصل، وتمنع الواصل.","pg":248,"lv":"kid","cat":"hay"},{"t":"تباعد الملك وتدني الشيطان","x":"ومن عقوباتها: أنها تباعد عن العبد وليه، وأنفع الخلق له، وأنصحهم له، ومن سعادته في قربه منه، وهو الملك الموكل به. وتدني منه عدوه، وأغش الخلق له وأعظمهم ضررا له، وهو الشيطان.","pg":249,"lv":"kid","cat":"rab"},{"t":"تستجلب مواد الهلاك","x":"ومن عقوباتها: أنها تستجلب مواد هلاك العبد في دنياه وآخرته.","pg":257,"lv":"kid","cat":"qlb"}],"thughur":[{"k":"العين","danger":"ودونكم ثغر العين، فإن منه تنالون بغيتكم، فإني ما أفسدت بني آدم بشيء مثل النظر، فإني أبذر به في القلب بذر الشهوة، ثم أسقيه بماء الأمنية","guard":["أن يكون النظر اعتبارا لا تفرجا: «فامنعوا ثغر العين أن يكون نظره اعتبارا، بل اجعلوا نظره تفرجا واستحسانا وتلهيا» (ص 230)","حراسة نظرة العبرة من أن يفسدها نظر الغفلة: «فإن استرق نظرة عبرة فأفسدوها عليه بنظر الغفلة والاستحسان والشهوة» (ص 230)","رد شبهة التهوين: «وهونوا عليه أمره، وقولوا له: ما مقدار نظرة تدعوك إلى تسبيح الخالق» (ص 231)","لزوم الثغر وعدم إخلائه: «فالمرابطة لزوم هذه الثغور. ولا يخلي مكانها، فيصادف العدو الثغر خاليا، فيدخل منه» (ص 229)","مخالفة الهوى وذكر الله: «وأعظم أسلحتهم فيكم وأمنع حصونهم: ذكر الله، ومخالفة الهوى» (ص 242)","الحياء من الحافظين: «استحيوا من هؤلاء الحافظين الكرام، وأكرموهم، وأجلوهم أن يروا منكم ما تستحيون أن يراكم عليه من هو مثلكم» (ص 256)"],"pg":230},{"k":"الأذن","danger":"ثم امنعوا ثغر الأذن أن يدخل منه ما يفسد عليكم الأمر، فاجتهدوا أن لا تدخلوا منه إلا الباطل، فإنه خفيف على النفس تستحليه وتستملحه","guard":["إدخال كلام الله ورسوله والنصحاء، وهو ما يحذره العدو: «وإياكم أن يدخل من هذا الثغر شيء من كلام الله أو كلام رسوله أو كلام النصحاء!» (ص 232)","الفهم والتدبر والتفكر والعظة بما يسمع: «فحولوا بينه وبين فهمه وتدبره، والتفكر فيه، والعظة به» (ص 232)","النظر إلى حقيقة الكلام لا إلى قالبه وزخرفه: «فيدخلون الباطل عليه في كل قالب يقبله ويخف عليه، ويخرجون له الحق في كل قالب يكرهه ويثقل عليه» (ص 233)","ألا يغتر بالقول المزخرف: «فسماه زخرفا وهو باطل، لأن صاحبه يزخرفه ويزينه ما استطاع، ويلقيه إلى سمع المغرور، فيغتر به» (ص 234)","ألا يعطي الكلمة الباطلة إصغاء: «وألقوا الكلمة، فإن رأيتم منه إصغاء إليها فزجوه بأخواتها» (ص 232)"],"pg":231},{"k":"اللسان","danger":"ثم يقول: قوموا على ثغر اللسان، فإنه الثغر الأعظم، وهو قبالة الملك؛ فأجروا عليه من الكلام ما يضره ولا ينفعه","guard":["قاعدة الرباط: «فالرباط الرباط على هذا الثغر أن يتكلم بحق، أو يمسك عن باطل» (ص 235)","إجراء النافع على اللسان: «من ذكر الله تعالى، واستغفاره، وتلاوة كتابه، ونصيحة عباده، أو التكلم بالعلم النافع» (ص 234)","الحذر من الطرفين معا: «المتكلم بالباطل شيطان ناطق، والساكت عن الحق شيطان أخرس» (ص 235)","ألا يكون السامع عونا على الباطل باستحسانه: «ويكون الآخر على لسان السامع، فينطق باستحسانها وتعظيمها والتعجب منها» (ص 235)","تقريب الملك بالطاعة: «وإذا اشتد قرب الملك من العبد تكلم على لسانه، وألقى على لسانه القول السديد» (ص 252)","تذكر خطر الكلمة: «واعلموا يا بني أن ثغر اللسان هو الذي أهلك منه بني آدم، وأكبهم منه على مناخرهم في النار» (ص 235)"],"pg":234}],"sins4":[{"k":"ملكية","x":"«فالذنوب الملكية: أن يتعاطى ما لا يصلح له من صفات الربوبية كالعظمة، والكبرياء، والجبروت، والقهر، والعلو، واستعباد الخلق، ونحو ذلك»","pg":287,"note":"«ويدخل في هذا: الشرك بالرب تعالى»، «وهذا القسم أعظم أنواع الذنوب. ويدخل فيه القول على الله بلا علم في خلقه وأمره» ص 288"},{"k":"شيطانية","x":"«وأما الشيطانية، فالتشبه بالشيطان في الحسد، والبغي، والغش والغل، والخداع، والمكر، والأمر بمعاصي الله وتحسينها، والنهي عن طاعته وتهجينها، والابتداع في دينه، والدعوة إلى البدع والضلال»","pg":288,"note":"«وهذا النوع يلي النوع الأول في المفسدة، وإن كانت مفسدته دونه»"},{"k":"سبعية","x":"«وأما السبعية، فذنوب العدوان، والغضب، وسفك الدماء، والتوثب على الضعفاء والعاجزين. ويتولد منها أنواع أذى النوع الإنساني، والجرأة على الظلم والعدوان»","pg":288,"note":""},{"k":"بهيمية","x":"«وأما الذنوب البهيمية، فمثل الشره والحرص على قضاء شهوة البطن والفرج. ومنها يتولد الزنى، والسرقة، وأكل أموال اليتامى، والبخل والشح، والجبن، والهلع، والجزع، وغير ذلك»","pg":288,"note":"«وهذا القسم أكثر ذنوب الخلق لعجزهم عن الذنوب السبعية والملكية. ومنه يدخلون إلى سائر الأقسام» ص 288 و289"}],"gates":[{"k":"اللحظات","danger":"فأما اللحظات فهي رائد الشهوة ورسولها، وحفظها أصل حفظ الفرج. فمن أطلق بصره أورده موارد الهلكات.","guard":["غض البصر من أول النظرة قبل أن تولد خطرة ثم فكرة ثم شهوة ثم إرادة ثم عزيمة","الصبر على غض البصر في أوله، فإن الصبر عليه أيسر من الصبر على ألم ما بعده","إعطاء الطريق حقه لمن جلس فيه: غض البصر، وكف الأذى، ورد السلام","استحضار أن إطلاق النظر يورث الحسرات، فيرى ما ليس قادرا عليه ولا صابرا عنه","ألا يظن أن تكرار النظر يداوي الأولى، فالنظرة تجرح القلب فيتبعها جرحا على جرح","تذكر أن حبس اللحظات أيسر من دوام الحسرات"],"pg":348},{"k":"الخطرات","danger":"وأما الخطرات فشأنها أصعب، فإنها مبدأ الخير والشر، ومنها تتولد الإرادات والهمم والعزائم. فمن راعى خطراته ملك زمام نفسه، وقهر هواه. ومن غلبته خطراته فهواه ونفسه له أغلب، ومن استهان بالخطرات قادته قسرا إلى الهلكات.","guard":["مراعاة الخطرات من أولها، فمن راعاها ملك زمام نفسه وقهر هواه","ألا يستدعي الخاطر ولا يحادثه، فالخاطر كالمار على الطريق، إن تركه مر وانصرف","ألا يرضى من الحقائق بالأماني الكاذبة، فإنها رؤوس أموال المفلسين وتتولد من العجز والكسل","أن يحصر خطراته وهمومه في أربعة أصول: جلب منافع دنياه، ودفع مضارها، وجلب مصالح آخرته، ودفع مضارها","أن يقدم عند التزاحم الأهم الذي يخشى فوته، ويحكم القاعدة الكبرى: إيثار أعلى المصلحتين ودفع أكبر المفسدتين","أن يشغل فكره بما كان لله والدار الآخرة: آياته المنزلة، وآياته المشهودة، وآلاؤه، وعيوب النفس والعمل، وواجب الوقت","أن يحفظ وقته، فوقت الإنسان هو عمره في الحقيقة","أن يفرغ القلب من الخواطر الردية لتستقر فيه النافعة، لا أن يخليه من كل خاطر فيصادفه الشيطان خاليا","أن يملأ القلب بالخواطر والإرادات في تحصيل مراضي الرب، فالكمال في امتلائه لا في فراغه","أن يصبر في الحرب بين النفس الأمارة والمطمئنة، فالنصر مع الصبر والعاقبة للتقوى"],"pg":353},{"k":"اللفظات","danger":"وأيسر حركات الجوارح حركة اللسان، وهي أضرها على العبد.","guard":["ألا يخرج لفظة ضائعة، ولا يتكلم إلا فيما يرجو فيه الربح والزيادة في دينه","أن يزن الكلمة قبل النطق: هل فيها ربح؟ فإن لم يكن أمسك، وإن كان نظر هل تفوته بها كلمة أربح منها","أن يقول خيرا أو يصمت","أن يتذكر أن الكلمة يقولها لا يلقي لها بالا قد ترفعه درجات أو تهوي به في جهنم، وأن كلمة واحدة أحبطت عمل عابد","أن يحاسب نفسه على ألفاظه كما كان السلف يحاسب أحدهم نفسه في قوله: يوم حار، ويوم بارد","أن يتذكر أن الكلام أسيره، فإذا خرج من فيه صار أسيره، وأن الله عند لسان كل قائل","أن يحذر الوقيعة في أعراض الأحياء والأموات ولو كان متورعا عن الفواحش","أن يكون من أهل الوسط: يكف لسانه عن الباطل، ولا يسكت عن الحق مداهنة، ويطلقه فيما ينفعه في الآخرة","أن يكثر من ذكر الله وما اتصل به، فإن اللسان يهدم به السيئات كما يهدم بالباطل الحسنات"],"pg":374},{"k":"الخطوات","danger":"فإن لم يكن في خطاه مزيد ثواب، فالقعود عنها خير له.","guard":["ألا ينقل قدمه إلا فيما يرجو ثوابه","أن يقعد عن الخطى التي لا مزيد ثواب فيها","أن يستخرج من كل مباح يخطو إليه قربة ينويها لله، فتقع خطاه قربة","أن يقرن حفظ الخطوة بحفظ اللفظة، فالعثرة عثرتان: عثرة الرجل وعثرة اللسان، وعباد الرحمن يمشون على الأرض هونا وإذا خاطبهم الجاهلون قالوا سلاما"],"pg":375}],"love":[{"g":"مرتبة","n":0,"k":"خاصية التعبد","x":"وخاصية التعبد: الحب مع الخضوع والذل للمحبوب، فمن أحب شيئا وخضع له فقد تعبد قلبه له. بل التعبد آخر مراتب الحب، ويقال له التتيم أيضا.","pg":426},{"g":"مرتبة","n":1,"k":"العلاقة","x":"فإن أول مراتبه: العلاقة، وسميت علاقة لتعلق القلب بالمحبوب.","pg":426},{"g":"مرتبة","n":2,"k":"الصبابة","x":"ثم بعدها الصبابة، وسميت بذلك لانصباب القلب إلى المحبوب.","pg":426},{"g":"مرتبة","n":3,"k":"الغرام","x":"ثم الغرام، وهو لزوم الحب للقلب لزوما لا ينفك عنه. ومنه سمي الغريم غريما لملازمته صاحبه.","pg":427},{"g":"مرتبة","n":4,"k":"العشق","x":"ثم العشق، وهو إفراط المحبة. ولهذا لا يوصف به الرب تعالى، ولا يطلق في حقه.","pg":427},{"g":"مرتبة","n":5,"k":"الشوق","x":"ثم الشوق، وهو سفر القلب إلى المحبوب أحث السفر. وقد جاء إطلاقه في حق الرب تعالى","pg":427},{"g":"مرتبة","n":6,"k":"التتيم","x":"ثم التتيم، وهو آخر مراتب الحب، وهو تعبد المحب لمحبوبه. يقال: تيمه الحب إذا عبده. ومنه تيم الله، أي عبد الله.","pg":438},{"g":"مرتبة","n":7,"k":"الخلة","x":"ثم الخلة، وهي تتضمن كمال المحبة ونهايتها، بحيث لا يبقى في قلب المحب سعة لغير محبوبه، وهي منصب لا يقبل المشاركة بوجه ما.","pg":444},{"g":"نوع","n":1,"k":"محبة الله","x":"أحدها: محبة الله. ولا تكفي وحدها في النجاة من عذابه والفوز بثوابه، فإن المشركين وعباد الصليب واليهود وغيرهم يحبون الله.","pg":443},{"g":"نوع","n":2,"k":"محبة ما يحبه الله","x":"الثاني: محبة ما يحبه الله. وهذه هي التي تدخله في الإسلام، وتخرجه من الكفر؛ وأحب الناس إلى الله أقومهم بهذه المحبة وأشدهم فيها.","pg":443},{"g":"نوع","n":3,"k":"الحب لله وفيه","x":"الثالث: الحب لله وفيه. وهي من لوازم محبة ما يحب، ولا تستقيم محبة ما يحب إلا بالحب فيه وله.","pg":444},{"g":"نوع","n":4,"k":"المحبة مع الله","x":"الرابع: المحبة مع الله. وهي المحبة الشركية، وكل من أحب شيئا مع الله، لا لله ولا من أجله ولا فيه، فقد اتخذه ندا من دون الله، وهذه محبة المشركين.","pg":444},{"g":"نوع","n":5,"k":"المحبة الطبعية","x":"وبقي قسم خامس: ليس مما نحن فيه، وهو المحبة الطبعية، وهي ميل الإنسان إلى ما يلائم طبعه، كمحبة العطشان للماء، والجائع للطعام، ومحبة النوم والزوجة والولد. فتلك لا تذم إلا إذا ألهت عن ذكر الله وشغلت عن محبته.","pg":444},{"g":"قسمة","n":1,"k":"المحبوب لنفسه والمحبوب لغيره","x":"والمحبوب قسمان: محبوب لنفسه، ومحبوب لغيره. والمحبوب لغيره لابد أن ينتهي إلى المحبوب لنفسه، دفعا للتسلسل المحال.","pg":451},{"g":"قسمة","n":2,"k":"قسما المحبوب لغيره","x":"والمحبوب لغيره قسمان أيضا: أحدهما: ما يلتذ المحب بإدراكه وحصوله. والثاني: ما يتألم به، ولكن يحتمله لإفضائه إلى محبوبه، كشرب الدواء الكريه.","pg":452},{"g":"قسمة","n":3,"k":"المحبة المحمودة والمذمومة","x":"وأعظم أنواع المحبة المذمومة: المحبة مع الله، التي يسوي المحب فيها بين محبته لله ومحبته للند الذي اتخذه من دونه. وأعظم أنواعها المحمودة: محبة الله وحده، ومحبة ما أحب.","pg":463},{"g":"قسمة","n":4,"k":"المحبة النافعة والضارة","x":"والمحبة المحمودة هي المحبة النافعة التي تجلب لصاحبها ما ينفعه في دنياه وآخرته، وهذه المحبة هي عنوان سعادته، والضارة هي التي تجلب لصاحبها ما يضره في دنياه وآخرته، وهي عنوان شقاوته.","pg":473},{"k":"أنفع المحبة","x":"اعلم أن أنفع المحبة على الإطلاق وأوجبها وأعلاها وأجلها محبة من جبلت القلوب على محبته، وفطرت الخليقة على تألهه","pg":532},{"k":"العبادة","x":"والعبادة لا تصح إلا له وحده، والعبادة هي كمال الحب مع كمال الخضوع والذل","pg":532},{"k":"داعيا المحبة","x":"والمحبة لها داعيان: الجمال والإجلال، والرب تعالى له الكمال المطلق من ذلك","pg":533},{"k":"الولاية","x":"والولاية أصلها الحب، فلا موالاة إلا بحب؛ كما أن العداوة أصلها البغض","pg":534},{"k":"التوحيد في الحب","x":"وبهذا التوحيد في الحب أرسل الله سبحانه جميع رسله، وأنزل جميع كتبه","pg":534},{"k":"محبة الله تبعا ومحبة لذاته","x":"والله تعالى يحب لذاته من جميع الوجوه، وما سواه فإنما يحب تبعا لمحبته","pg":532},{"k":"العشق الشركي","x":"فإنه تارة يكون كفرا، كمن اتخذ معشوقه ندا يحبه كما يحب الله","pg":488},{"k":"العشق","x":"أن العشق، كما تقدم، هو الإفراط في المحبة بحيث يستولي المعشوق على قلب العاشق حتى لا يخلو من تخيله وذكره والفكر فيه","pg":497},{"k":"محبة رسول الله صلى الله عليه وسلم","x":"فهذا الحب لا ينكر ولا يذم، بل هو أحمد أنواع الحب. وكذلك حب رسول الله صلى الله عليه وسلم","pg":548},{"k":"المحبة الخاصة","x":"وإنما نعني المحبة الخاصة، وهي التي تشغل قلب المحب وفكره وذكره لمحبوبه","pg":549},{"k":"محبة كلام الله","x":"وكذلك محبة كلام الله، فإنه من علامة محبة الله","pg":549},{"k":"المحبة الباطلة","x":"وكل حب سوى ذلك باطل، إن لم يعن عليه ويسوق المحب إليه","pg":552},{"k":"محبة النساء","x":"وأما محبة النسوان فلا لوم على المحب فيها، بل هي من كماله","pg":552},{"k":"المودة","x":"وجعل بينهما خالص الحب، وهو المودة المقترنة بالرحمة","pg":552},{"k":"عشق قربة وطاعة","x":"عشق هو قربة وطاعة، وهو عشق الرجل امرأته وجاريته","pg":565},{"k":"عشق مقت","x":"وعشق هو مقت من الله، وبعد من رحمته، وهو أضر شيء على العبد في دينه ودنياه","pg":565},{"k":"عشق مباح لا يملك","x":"عشق مباح لا يملك، كعشق من وصفت له امرأة جميلة، أو رآها فجأة من غير قصد","pg":566},{"k":"أقسام العشاق","x":"منهم من يعشق الجمال المطلق. ومنهم من يعشق الجمال المقيد، سواء طمع بوصاله أو لم يطمع. ومنهم من لا يعشق إلا من يطمع في الوصول إليه","pg":567}],"pleasures":[{"k":"لذة توصل إلى لذة الآخرة","x":"فأعظمها وأكملها: ما أوصل إلى لذة الآخرة. ويثاب الإنسان على هذه اللذة أتم ثواب","ex":"ما يقصد به وجه الله من أكله وشربه ولبسه ونكاحه، ولذة إيمانه ومعرفته بالله ومحبته وشوقه إلى لقائه","pg":546},{"k":"لذة تمنع لذة الآخرة","x":"لذة تمنع لذة الآخرة، وتعقب آلاما أعظم منها","ex":"لذة الذين اتخذوا من دون الله أوثانا مودة بينهم، ولذة أصحاب الفواحش والظلم والبغي والعلو بغير الحق، وهي استدراج","pg":546},{"k":"لذة مباحة لا يستعان بها على الآخرة","x":"لذة لا تعقب لذة في دار القرار ولا ألما، ولا تمنع أصل لذة دار القرار، وإن منعت كمالها","ex":"اللهو الذي عناه النبي صلى الله عليه وسلم بقوله: كل لهو يلهو به الرجل فهو باطل، إلا رميه بقوسه، وتأديبه فرسه، وملاعبته امرأته","pg":548}]},"weak":[{"x":"زيادة «علمه من علمه، وجهله من جهله» في حديث أسامة بن شريك","pg":4,"hd":"من طريق مصعب بن سلام وفيه ضعف، ورواية الجماعة بدون هذه الزيادة؛ وأصل الحديث صحيح"},{"x":"حديث جابر في صاحب الشجة: «قتلوه، قتلهم الله! ألا سألوا إذ لم يعلموا! فإنما شفاء العي السؤال...»","pg":6,"hd":"أخرجه أبو داود 336، تفرد به الزبير بن خريق، قال الدارقطني: ليس بالقوي، وصححه ابن السكن (مختلف فيه)"},{"x":"«ادعوا الله وأنتم موقنون بالإجابة، واعلموا أن الله لا يقبل دعاء من قلب غافل لاه»","pg":9,"hd":"أخرجه الحاكم 1817 والترمذي 3479، تفرد به صالح المري وهو متروك، وضعفه الترمذي؛ وله شاهد عند أحمد 6655 فيه ابن لهيعة، وحسنه المنذري والهيثمي"},{"x":"أثر بني إسرائيل: «تخرجون إلى الصعيد بأبدان نجسة، وترفعون إلي أكفا قد سفكتم بها الدماء...»","pg":11,"hd":"لم يقف عليه المحقق في المطبوع من زهد أحمد، وأخرجه أبو داود في الزهد 13، وفي سنده ضعف"},{"x":"قول أبي ذر: «يكفي من الدعاء مع البر ما يكفي الطعام من الملح»","pg":11,"hd":"أخرجه أحمد في الزهد 788 وابن المبارك، وبكر بن عبدالله المزني عن أبي ذر مرسل"},{"x":"«الدعاء سلاح المؤمن، وعماد الدين، ونور السموات والأرض»","pg":11,"hd":"أخرجه الحاكم 1812 وصححه، وفيه محمد بن الحسن الهمداني متروك الحديث، كذبه ابن معين وأبو داود؛ انظر السلسلة الضعيفة 179"},{"x":"«لا يغني حذر من قدر، والدعاء ينفع مما نزل ومما لم ينزل. وإن البلاء لينزل، فيلقاه الدعاء، فيعتلجان إلى يوم القيامة»","pg":12,"hd":"أخرجه الحاكم 1813 وصححه، وتعقبه الذهبي: زكريا مجمع على ضعفه"},{"x":"«الدعاء ينفع مما نزل ومما لم ينزل، فعليكم عباد الله بالدعاء»","pg":12,"hd":"أخرجه الحاكم 1815 والترمذي 3548 وقال: غريب، فيه عبدالرحمن بن أبي بكر القرشي ضعيف، وقال الذهبي: واه"},{"x":"«لا يرد القدر إلا الدعاء، ولا يزيد في العمر إلا البر، وإن الرجل ليحرم الرزق بالذنب يصيبه»","pg":13,"hd":"أخرجه الحاكم 1814 وصححه، وابن ماجه 4022 وأحمد 22386 وابن حبان 872، وفي سنده عبدالله بن أبي الجعد لم يوثقه غير ابن حبان؛ وحديث سلمان عند الترمذي 2139 تفرد به أبو مودود وهو ضعيف"},{"x":"«من لم يسأل الله يغضب عليه»","pg":13,"hd":"أخرجه ابن ماجه 3827 والترمذي 3373 وأحمد والحاكم وصححه، تفرد به أبو صالح الخوزي، ضعفه ابن معين، وقال ابن حجر: لين الحديث (أعاده المؤلف في ص 30)"},{"x":"«لا تعجزوا في الدعاء، فإنه لا يهلك مع الدعاء أحد»","pg":14,"hd":"أخرجه الحاكم 1818 وابن حبان، تفرد به عمر بن محمد عن ثابت، منكر الحديث متروك"},{"x":"«إن الله يحب الملحين في الدعاء»","pg":14,"hd":"أخرجه العقيلي والطبراني وابن عدي، فيه يوسف بن السفر متروك كذاب، والصحيح أنه من قول الأوزاعي"},{"x":"«لا يزال العبد بخير ما لم يستعجل»","pg":16,"hd":"أخرجه أحمد 3/193، فيه أبو هلال الراسبي في حفظه مقال، وروي من وجهين عن أنس ولا يثبت"},{"x":"«اسم الله الأعظم في هاتين الآيتين...»","pg":18,"hd":"أخرجه الترمذي 3476 وصححه، وتكلم فيه البغوي، وعبيدالله بن أبي زياد وشهر في حفظهما ضعف"},{"x":"«ألظوا بيا ذا الجلال والإكرام» من حديث أبي هريرة وأنس","pg":19,"hd":"لا يثبت عن غير ربيعة بن عامر؛ أما من حديث ربيعة فصحيح الإسناد"},{"x":"كان النبي ﷺ إذا أهمه الأمر رفع رأسه إلى السماء فقال: «سبحان الله العظيم»، وإذا اجتهد في الدعاء قال: «يا حي يا قيوم»","pg":19,"hd":"أخرجه الترمذي 3436 وقال: غريب، فيه إبراهيم بن الفضل المخزومي منكر الحديث متروك"},{"x":"«يا حي يا قيوم، برحمتك أستغيث»","pg":20,"hd":"أخرجه الترمذي 3524 وقال: غريب، تفرد به يزيد الرقاشي وأقل أحواله أنه ضعيف؛ وله طريق عند الطبراني ظاهر سنده لا بأس به"},{"x":"«اسم الله الأعظم في ثلاث سور من القرآن: البقرة وآل عمران وطه»","pg":20,"hd":"أخرجه الحاكم 1861 وابن ماجه 3856، وفي رواية القاسم عن أبي أمامة كلام"},{"x":"«ألا أخبركم بشيء، إذا نزل برجل منكم كرب أو بلاء من بلايا الدنيا فدعا به يفرج الله عنه؟ دعاء ذي النون»","pg":21,"hd":"أخرجه الحاكم 1864 والنسائي في عمل اليوم والليلة، فيه محمد بن مهاجر، قال ابن حجر: لين"},{"x":"«هل أدلكم على اسم الله الأعظم؟ دعاء يونس... فأيما مسلم دعا بها في مرضه أربعين مرة، فمات في مرضه ذلك، أعطي أجر شهيد»","pg":21,"hd":"أخرجه الحاكم 1865، فيه عمرو بن بكر السكسكي، قال الذهبي: أحاديثه شبه موضوعة، وقال ابن حجر: متروك"},{"x":"قول ابن مسعود: «ما كرب نبي من الأنبياء إلا استغاث بالتسبيح»","pg":23,"hd":"لم يقف عليه المحقق"},{"x":"قصة أبي معلق الأنصاري واللص ودعائه «يا ودود يا ذا العرش المجيد»","pg":23,"hd":"رواه ابن أبي الدنيا في مجابي الدعوة 23، ولا يثبت سنده"},{"x":"قول عمر: «لستم تنصرون بكثرة، وإنما تنصرون من السماء»","pg":29,"hd":"لم يقف عليه المحقق"},{"x":"الكيّس من دان نفسه، وعمل لما بعد الموت. والعاجز من أتبع نفسه هواها، وتمنّى على الله","pg":48,"hd":"رواه الترمذي 2459 وحسّنه، وصححه الحاكم، فتعقبه الذهبي: لا والله، أبو بكر واهٍ (يعني ابن أبي مريم)."},{"x":"حديث أبي رافع: «أفّ لك، أفّ لك!... فدُرّع الآن مثلها من نار»","pg":52,"hd":"رواه أحمد 27192 والنسائي، في إسناده منبوذ لم يقف المحقق على توثيقه، والفضل بن عبيدالله لا يعرف له سماع من جده. وله شواهد أحدها سنده حسن مع اختلاف، قال المحقق: ولعل هذا يدل على أن للحديث أصلًا."},{"x":"مالي لم أر ميكائيل ضاحكًا قط؟ قال: ما ضحك منذ خلقت النار","pg":55,"hd":"رواه أحمد 13343، قال المحقق: هذا سند لا يصح، وحميد بن عبيد فيه جهالة."},{"x":"لفظ أحمد في حديث البراء: «ثم يقيَّض له أعمى أصمّ أبكم، في يده مرزبّة...»","pg":60,"hd":"رواه أحمد 18614 من طريق يونس بن خباب، قال المحقق: يونس ضعيف الحديث وتفرد بها، وأصحاب الأعمش لم يذكروا اللفظة."},{"x":"أي إخواني، لمثل هذا اليوم فأعدّوا","pg":61,"hd":"رواه أحمد 18601 وابن ماجه 4195، وتكلم المحقق في رجاله: محمد بن مالك قال فيه ابن حجر: صدوق يخطئ كثيرًا، وقال ابن حبان: لم يسمع من البراء شيئًا. ولم يصرح المحقق بحكم."},{"x":"إنما مثلي ومثلكم مثل قوم خافوا عدوًا يأتيهم... أيها الناس أتيتم","pg":62,"hd":"رواه أحمد 22948، فيه بشير بن المهاجر: قال أحمد منكر الحديث، وقال ابن عدي: فيه بعض الضعف."},{"x":"إني أرى ما لا ترون، وأسمع ما لا تسمعون... لوددت أني شجرة تعضد","pg":63,"hd":"رواه أحمد 21516 والترمذي 2312، قال المحقق: هذا سند ضعيف، مورق لم يسمع من أبي ذر، وإبراهيم بن مهاجر فيه ضعف. وقوله: لوددت أني شجرة تعضد، من قول أبي ذر."},{"x":"يُضغط المؤمن فيه ضغطة تزول منها حمائله، ويملأ على الكافر نارًا","pg":64,"hd":"رواه أحمد 23457، قال ابن الجوزي: هذا حديث لا يصح، ومحمد بن جابر ضعيف، وأبو البختري لم يدرك حذيفة."},{"x":"لقد تضايق على هذا العبد الصالح قبره، حتى فرّج الله عنه","pg":64,"hd":"رواه أحمد 14873، قال المحقق: معاذ بن رفاعة فيه ضعف يسير، وخولف ابن إسحاق في إسناده."},{"x":"كيف أنعم، وصاحب القرن قد التقم القرن، وحنى جبهته يسمع متى يؤمر فينفخ؟","pg":65,"hd":"رواه أحمد 3008 وغيره، والحديث معروف عن عطية العوفي، قال المحقق: عطية العوفي ضعيف الحديث."},{"x":"من اشترى ثوبًا بعشرة دراهم فيها درهم حرام، لم يقبل الله له صلاة ما دام عليه","pg":67,"hd":"رواه أحمد 5732، فيه هاشم الأوقص ضعيف جدًا، وضعف الحديث أحمد وابن حبان والبيهقي والذهبي."},{"x":"من ترك الصلاة سكرًا مرة واحدة، فكأنما كانت له الدنيا وما عليها فسلبها","pg":68,"hd":"رواه أحمد 6659 والحاكم وقال: صحيح الإسناد، فتعقبه الذهبي: سمعه ابن وهب عنه، وهو غريب جدًا."},{"x":"من مات مدمنًا للخمر سقاه الله من نهر الغوطة","pg":69,"hd":"رواه أحمد 19569 وابن حبان 5346 والحاكم وصححه، وفيه أبو حريز ضعفه ابن معين والنسائي، وقال أحمد: حديثه منكر."},{"x":"تعرض الناس يوم القيامة ثلاث عرضات","pg":70,"hd":"رواه أحمد 19715 وابن ماجه 4277، قال الترمذي: لا يصح من قبل أن الحسن لم يسمع من أبي هريرة، والحسن لم يسمع من أبي موسى، وقال الدارقطني: الموقوف هو الصحيح."},{"x":"وصية معاذ: «لا تشرك بالله شيئًا وإن قتلت وحرقت... فإن المعصية تحلّ سخط الله»","pg":74,"hd":"رواه أحمد 22075، قال المنذري: إسناد أحمد صحيح لو سلم من الانقطاع، فإن عبدالرحمن بن جبير بن نفير لم يسمع من معاذ."},{"x":"إن الله يعطي الدنيا من يحب ومن لا يحب، ولا يعطي الإيمان إلا من يحب","pg":78,"hd":"لم يقف عليه المحقق في الترمذي، ورواه أحمد 3672 والحاكم، قال المحقق: الصباح بن محمد ضعيف الحديث، ورجح العقيلي والدارقطني والذهبي الموقوف على ابن مسعود."},{"x":"من خاف أدلج، ومن أدلج بلغ المنزل. ألا إن سلعة الله غالية، ألا إن سلعة الله الجنة","pg":88,"hd":"رواه الترمذي 2450 وقال: حسن غريب، وصححه الحاكم، قال المحقق: يزيد بن سنان ضعيف الحفظ يخطئ كثيرًا، وجملة «من خاف أدلج» من طريق أبي بن كعب لا يثبت إسنادها."},{"x":"لا يا بنت الصديق، ولكنهم الذين يصومون ويصلّون ويتصدّقون، ويخافون أن لا يُقبل منهم","pg":90,"hd":"رواه الترمذي 3175 وابن ماجه 4198، قال المحقق: هذا الإسناد ضعيف للإرسال، ولا يثبت سنده عن عائشة. وطريق أبي هريرة عند الطبراني تفرد بها الحكم بن بشير، والمحفوظ عن عبدالرحمن بن سعيد مرسلًا."},{"x":"لا تزال هذه الأمة تحت يد الله وفي كنفه، ما لم يمالئ قراؤها أمراءها، وما لم يزك صلحاؤها فجارها، وما لم يهن خيارها شرارها...","pg":103,"hd":"من مراسيل الحسن، أخرجه ابن المبارك وابن أبي الدنيا والداني، وسنده ضعيف إلى الحسن"},{"x":"يخرج في آخر الزمان قوم يختلون الدنيا بالدين، ويلبسون للناس مسوك الضأن من اللين، ألسنتهم أحلى من السكر، وقلوبهم قلوب الذئاب...","pg":105,"hd":"الترمذي 2404 وغيره، فيه يحيى بن عبيدالله بن موهب، قال ابن حجر: متروك، وأفحش الحاكم فرماه بالوضع"},{"x":"يأتي على الناس زمان لا يبقى من الإسلام إلا اسمه، ولا من القرآن إلا رسمه...","pg":106,"hd":"عن علي، واختلف في رفعه ووقفه، قال أبو حاتم في رواية الراوي له: منكر الحديث، والموقوف منقطع، وطريق البيهقي الآخر قال فيه: موقوف إسناده إلى شريك مجهول"},{"x":"إذا أظهر الناس العلم، وضيعوا العمل، وتحابوا بالألسن، وتباغضوا بالقلوب، وتقاطعوا بالأرحام، لعنهم الله عز وجل عند ذلك، فأصمهم، وأعمى أبصارهم","pg":107,"hd":"من مراسيل الحسن، وهو مرسل ضعيف الإسناد"},{"x":"يا معشر المهاجرين، خمس خصال وأعوذ بالله أن تدركوهن...","pg":107,"hd":"ابن ماجه 4019، وفي إسناده خالد بن يزيد بن عبدالرحمن ضعيف جدا؛ ورواه الحاكم من طريق آخر وصححه، وفي سماع عطاء من ابن عمر خلاف، ولم يجزم المحقق بثبوته"},{"x":"إن من كان قبلكم كان إذا عمل العامل فيهم بالخطيئة جاءه الناهي تعذيرا، فإذا كان الغد جالسه وواكله وشاربه...","pg":108,"hd":"أبو داود والترمذي وابن ماجه وغيرهم، وفي سنده انقطاع، أبو عبيدة لم يسمع من أبيه ابن مسعود"},{"x":"إذا استباحوا الزنا، وشربوا الخمر، وضربوا بالمعازف، غار الله عز وجل في سمائه، فقال للأرض: تزلزلي بهم...","pg":111,"hd":"حديث أنس عن عائشة، صححه الحاكم وتعقبه الذهبي بقوله: بل أحسبه موضوعا على أنس، وفيه نعيم بن حماد ومجاهيل"},{"x":"اسكني فإنه لم يأن لك بعد... إن ربكم يستعتبكم فأعتبوه","pg":111,"hd":"حديث مرسل، قال ابن حجر: هذا مرسل ضعيف، وقال ابن عبدالبر: لم يأت عن النبي ﷺ من وجه صحيح أن الزلزلة كانت في عصره"},{"x":"إذا كان يوم القيامة فليس فيها ذراع ولا شبر إلا وهو ينطق","pg":112,"hd":"من مناقب عمر لابن أبي الدنيا، وسنده ضعيف جدا، فيه سعد بن طريف الإسكاف متروك الحديث"},{"x":"إن الله عز وجل إذا أراد بالعباد نقمة أمات الأطفال، وأعقم أرحام النساء، فتنزل النقمة، وليس فيهم مرحوم","pg":116,"hd":"حديث عمار وحذيفة، قال المحقق: فالحديث لا يثبت سنده"},{"x":"إذا أراد الله بقوم خيرا جعل أمرهم إلى حلمائهم، وفيئهم عند سمحائهم. وإذا أراد بقوم شرا جعل أمرهم إلى سفهائهم، وفيئهم عند بخلائهم","pg":116,"hd":"من مراسيل الحسن، أخرجه ابن أبي الدنيا في العقوبات وفي الحلم، ولم يصرح المحقق بحكمه، والمرسل من قسم الضعيف"},{"x":"والذي نفسي بيده، لا تقوم الساعة حتى يبعث الله أمراء كذبة، ووزراء فجرة، وأعوانا خونة...","pg":117,"hd":"حديث ابن عمر، فيه كوثر بن حكيم، قال أحمد: أحاديثه بواطيل ليس بشيء، وقال النسائي: متروك الحديث"},{"x":"ما طفف قوم كيلا، ولا بخسوا ميزانا، إلا منعهم الله عز وجل القطر...","pg":118,"hd":"قال المحقق: هذا حديث منكر، ورواية ابن أبي الدنيا سندها ضعيف جدا؛ والثابت موقوف على ابن عباس: ما نقض قوم العهد قط إلا سلط الله عليهم عدوهم... وسنده صحيح"},{"x":"أيها الناس، إن الله عز وجل يقول لكم: مروا بالمعروف وانهوا عن المنكر، قبل أن تدعوني فلا أجيبكم، وتستنصروني فلا أنصركم، وتسألوني فلا أعطيكم","pg":120,"hd":"حديث عائشة، تفرد به عاصم بن عمر وهو مجهول، وضعفه العراقي والهيثمي"},{"x":"إذا أخفيت الخطيئة لم تضر إلا صاحبها، وإذا ظهرت فلم تغير ضرت العامة","pg":121,"hd":"مرفوعا من حديث أبي هريرة، آفته مروان بن سالم الغفاري متهم بالوضع؛ والصحيح أنه من قول بلال بن سعد، وثبت عن عمر بن عبدالعزيز"},{"x":"سيظهر شرار أمتي على خيارها حتى يستخفي المؤمن فيهم كما يستخفي المنافق فينا اليوم","pg":122,"hd":"عن حسان بن عطية، والحديث معضل"},{"x":"يأتي زمان يذوب فيه قلب المؤمن، كما يذوب الملح في الماء. قيل: مم ذاك يا رسول الله؟ قال: مما يرى من المنكر لا يستطيع تغييره","pg":122,"hd":"حديث معضل ضعيف الإسناد، وفيه أشرس فيه جهالة"},{"x":"أما بعد يا معشر قريش، فإنكم أهل لهذا الأمر، ما لم تعصوا الله...","pg":128,"hd":"المسند وأبو يعلى، قال ابن حجر: رجاله ثقات، إلا أنه من رواية عبيدالله بن عبدالله بن عتبة عن عم أبيه ولم يدركه، فهو منقطع"},{"x":"الشيطان ذئب الإنسان","pg":190,"hd":"أحمد والطبراني وغيرهما عن معاذ، وفيه انقطاع، العلاء بن زياد لم يدرك معاذا، وطريق شهر منقطع أيضا وفيه متروك، ولا يصح؛ ولأصل معناه شواهد صحيحة"},{"x":"إن روح القدس نفث في روعي أنه لن تموت نفس حتى تستكمل رزقها، فاتقوا الله وأجملوا في الطلب، فإنه لا ينال ما عند الله إلا بطاعته","pg":199,"hd":"من حديث ابن مسعود: ضعيف الإسناد للإبهام في قوله (عمن أخبره). وورد معناه من حديث جابر عند ابن ماجه 2144 وابن حبان والحاكم."},{"x":"إن الله جعل الروح والفرح في الرضا واليقين، وجعل الهم والحزن في الشك والسخط","pg":199,"hd":"موقوف على ابن مسعود رجاله ثقات لكن فيه انقطاع، وروي مرفوعا ولا يصح."},{"x":"الدنيا ملعونة، ملعون ما فيها، إلا ذكر الله عز وجل وما والاه، وعالم أو متعلم","pg":204,"hd":"الترمذي 2322 وقال: حسن غريب. وذكر المحقق اضطراب عبدالرحمن بن ثابت بن ثوبان فيه، وعدّه العقيلي من منكراته. أدرج هنا احتياطا لأنه متكلم فيه."},{"x":"الدنيا ملعونة، ملعون ما فيها، إلا ما كان لله","pg":204,"hd":"الصواب أنه مرسل عن محمد بن المنكدر، كما رجحه أبو حاتم والدارقطني وابن الجوزي."},{"x":"إن الغضب جمرة في قلب ابن آدم. أما رأيتم من احمرار عينيه وانتفاخ أوداجه؟ فمن أحس بذلك فليتوضأ","pg":241,"hd":"الترمذي 2191 وغيره من طريق علي بن زيد بن جدعان، قال المحقق: ابن جدعان إلى الضعف أقرب، وخاصة إذا تفرد بهذا السياق الطويل."},{"x":"إنما تطفأ النار بالماء","pg":241,"hd":"أبو داود 4784 وأحمد، قال المحقق: هذا الإسناد ضعيف، محمد بن عطية مجهول، والحديث عده ابن حبان من منكرات أبي وائل القاص."},{"x":"أحاديث إطفاء الحريق بالتكبير (أشار إليها المؤلف بقوله: والتكبير)","pg":241,"hd":"من طرق عن عمرو بن شعيب عن أبيه عن جده وغيره، كلها واهية، ولا يثبت منها شيء."},{"x":"إذا كذب العبد تباعد منه الملك ميلا من نتن ريحه","pg":250,"hd":"الترمذي 1972 وغيره، قال المحقق: الحديث منكر لا يثبت لتفرد عبدالرحيم بن هارون به."},{"x":"كان الملك ينافح عنك، فلما رددت عليه جاء الشيطان، فلم أكن لأجلس","pg":253,"hd":"أبو داود 4896 مرسلا و4897 موصولا، قال البخاري: والأول أصح يعني المرسل، وصوبه الدارقطني، وفيه بشير بن المحرر فيه جهالة."},{"x":"وإذا نام على وضوء بات في شعاره ملك","pg":254,"hd":"ابن حبان 1051 وغيره، وفيه اضطراب، والطريق الثاني لا يصح، وضعفه العقيلي، وجوّد المنذري وابن حجر إسناد حديث ابن عباس."},{"x":"إن معكم من لا يفارقكم، فاستحيوا منهم وأكرموهم","pg":255,"hd":"لم يقف عليه المحقق موقوفا على الصحابة، والمرفوع عند الترمذي 2800 غريب، ضعفه الترمذي والبيهقي وعبدالحق الإشبيلي، وفي سنده الحسن بن أبي جعفر وليث بن أبي سليم."},{"x":"«إذا مررتم برياض الجنة فارتعوا. قالوا: وما رياض الجنة؟ قال: حلق الذكر»","pg":281,"hd":"أخرجه الترمذي 3510 وأحمد وغيرهما من طريق محمد بن ثابت البناني، قال المحقق: محمد بن ثابت ضعيف، والحديث من منكراته، وروي من طريق آخر عن أنس وهو ضعيف جدا، وجاء عن ابن عمر وجابر وابن عباس وكلها لا تصح."},{"x":"أثر حذيفة: «القلوب أربعة: فقلب أجرد فيه سراج يزهر...»","pg":273,"hd":"موقوف، لم يقف عليه المحقق عند أحمد، وفي سنده انقطاع (أبو البختري لم يدرك حذيفة)، ورفعه ليث بن أبي سليم وهو مخلط."},{"x":"تفسير المعيشة الضنك بعذاب القبر مرفوعا","pg":278,"hd":"روي مرفوعا من حديث أبي هريرة عند ابن حبان ومن حديث أبي سعيد عند الحاكم، وروي موقوفا، قال المحقق: والموقوف أصح."},{"x":"«الشرك في هذه الأمة أخفى من دبيب النمل... قل: اللهم إني أعوذ بك أن أشرك بك وأنا أعلم، وأستغفرك لما لا أعلم»","pg":302,"hd":"قال المحقق: ليس في صحيح ابن حبان المطبوع، وورد عن أبي بكر وعائشة وابن عباس وكلها لا تثبت، وأصحها حديث أبي موسى عند أحمد، وفيه أبو علي الكاهلي لم يذكر الهيثمي فيه إلا توثيق ابن حبان. لم يجزم المحقق بثبوته فلم يبن عليه شيء."},{"x":"دعاء عمر: «اللهم اجعل عملي كله صالحا، واجعله لوجهك خالصا، ولا تجعل لأحد فيه شيئا»","pg":303,"hd":"أخرجه أحمد في الزهد من طريق الحسن، والحسن لم يسمع من عمر، فهو منقطع."},{"x":"«لعن الله زوارات القبور والمتخذين عليها المساجد والسرج»","pg":307,"hd":"من طريق أبي صالح باذام مولى أم هانئ، ضعفه أكثر العلماء، ولشطره الأول شواهد تقويه."},{"x":"«اشتد غضب الله على قوم اتخذوا قبور أنبيائهم مساجد»","pg":307,"hd":"موصولا فيه عمر بن صهبان وقد أجمعوا على ضعفه، والأصح أنه مرسل عن عطاء بن يسار كما في الموطأ."},{"x":"«اللهم إني أتوب إليك، ولا أتوب إلى محمد. فقال: عرف الحق لأهله»","pg":312,"hd":"فيه محمد بن مصعب القرقساني، قال الذهبي: ضعيف، والحسن لم يسمع من الأسود بن سريع."},{"x":"قول إبليس: «أهلكت بني آدم بالذنوب، وأهلكوني بالاستغفار وبلا إله إلا الله، فلما رأيت ذلك بثثت فيهم الأهواء...»","pg":331,"hd":"سنده واه، فيه عبد الغفور متروك وكان يضع الحديث، وعثمان بن مطير ضعيف أيضا، وبه ضعفه الهيثمي."},{"x":"«لزوال الدنيا أهون على الله من قتل مؤمن بغير حق»","pg":344,"hd":"مرفوعا: من حديث بريدة وفيه بشير بن المهاجر فيه ضعف، ومن حديث البراء وفيه روح بن جناح فيه ضعف، ومن حديث عبدالله بن عمرو وقال البخاري: الصحيح عن عبدالله بن عمرو موقوف، والموقوف سنده لا بأس به."},{"x":"«لا تتبع النظرة النظرة، فإنما لك الأولى، وليست لك الآخرة»","pg":348,"hd":"من طريق شريك القاضي عن أبي ربيعة الإيادي، قال المحقق: فالحديث ضعيف الإسناد، وجاء من طريق آخر ولا يثبت."},{"x":"لا تتبع النظرة النظرة، فإنما لك الأولى، وليست لك الآخرة","pg":348,"hd":"أبو داود 2149 والترمذي 2777: قال المحقق: الحديث ضعيف الإسناد، شريك ساء حفظه، وأبو ربيعة الإيادي منكر الحديث"},{"x":"النظرة سهم مسموم من سهام إبليس، فمن غض بصره عن محاسن امرأة لله أورث الله قلبه حلاوة إلى يوم يلقاه","pg":348,"hd":"لم يقف عليه المحقق في المسند، أخرجه الحاكم والقضاعي، ومداره على عبدالرحمن بن إسحاق وهو ضعيف، وتعقب الذهبي تصحيح الحاكم. وأعاد المؤلف لفظه في ص 415"},{"x":"غضوا أبصاركم، واحفظوا فروجكم","pg":349,"hd":"من حديث «اضمنوا لي ستا» عند أحمد 22757، أعله المنذري والذهبي والهيثمي بالانقطاع، وروي عن أنس ولا يثبت"},{"x":"لا يستقيم إيمان عبد حتى يستقيم قلبه، ولا يستقيم قلبه حتى يستقيم لسانه","pg":364,"hd":"أحمد 13048: حديث منكر، تفرد به علي بن مسعدة وهو ضعيف، وضعفه الهيثمي والعراقي، وثبت موقوفا عن ابن مسعود"},{"x":"ثكلتك أمك يا معاذ! وهل يكب الناس في النار على وجوههم، أو على مناخرهم، إلا حصائد ألسنتهم؟","pg":365,"hd":"الترمذي 2616 وقال: حسن صحيح، وتعقبه ابن رجب بأنه لم يثبت سماع أبي وائل من معاذ، وطرقه عن معاذ كلها ضعيفة، مع قول العقيلي: في الباب أحاديث ثابتة. فهو معلول عند المحقق، فلم نبن عليه سؤالا"},{"x":"أو لا تدري فلعله تكلم فيما لا يعنيه، أو بخل بما لا ينقصه","pg":370,"hd":"الترمذي 2316: لا يثبت، يحيى بن يعلى الأسلمي ضعيف، وضعفه الهيثمي، والرواية الأخرى في الغلام الشهيد يوم أحد لا تصح"},{"x":"من حسن إسلام المرء تركه ما لا يعنيه","pg":371,"hd":"الترمذي 2317، وقال المؤلف: بإسناد صحيح، لكن رجح الإرسال أحمد وابن معين والبخاري والعقيلي والدارقطني وغيرهم"},{"x":"كلام ابن آدم عليه لا له، إلا أمر بمعروف، أو نهي عن منكر، أو ذكر الله","pg":371,"hd":"الترمذي 2412: ضعفه الترمذي بقوله غريب، وفيه أم صالح مجهولة"},{"x":"إذا أصبح العبد فإن الأعضاء كلها تكفر اللسان، تقول: اتق الله فينا، فإنما نحن بك","pg":372,"hd":"الترمذي 2407: اضطرب فيه حماد بن زيد رفعا ووقفا، وقال الترمذي: الموقوف أصح"},{"x":"لا يدخل الجنة ولد زنية","pg":383,"hd":"أحمد والنسائي في الكبرى: لا يصح، قال البخاري: لا يعرف لجابان سماع من عبدالله بن عمرو، وجابان مجهول"},{"x":"التائب من الذنب كمن لا ذنب له","pg":384,"hd":"ورد مرفوعا عن ابن مسعود وابن عباس وغيرهما ولا يثبت منها شيء، وهو ثابت من قول الشعبي. والمؤلف ساقه تقريرا لا رواية"},{"x":"من وجدتموه يعمل عمل قوم لوط فاقتلوا الفاعل والمفعول به","pg":397,"hd":"أبو داود 4462 والترمذي 1456: صححه الحاكم، ونقل المحقق استنكار ابن معين والنسائي وابن عدي لرواية عمرو بن أبي عمرو عن عكرمة، وقال الشافعي: إن صح قلت به. مختلف فيه"},{"x":"لعن الله من عمل عمل قوم لوط","pg":398,"hd":"أحمد والنسائي في الكبرى: قال النسائي: عمرو بن أبي عمرو ليس بالقوي"},{"x":"من وقع على ذات محرم فاقتلوه","pg":408,"hd":"ابن ماجه 2564: قال الترمذي: لا نعرفه إلا من هذا الوجه، وإبراهيم بن إسماعيل يضعف، وقال أبو حاتم: حديث منكر"},{"x":"من تخطى حرم المؤمنين فخطوا وسطه بالسيف","pg":408,"hd":"لا يثبت لضعف رفدة وخطئه، والصحيح أنه من فتوى عبدالله بن مطرف"},{"x":"من أتى بهيمة فاقتلوه واقتلوها معه","pg":411,"hd":"أبو داود 4464: حديث منكر تكلم فيه أحمد والبخاري وأبو داود والترمذي، وقال الطحاوي: الحديث ضعيف"},{"x":"إذا أتت المرأة المرأة فهما زانيتان","pg":412,"hd":"منكر بهذا الإسناد، فيه محمد بن عبدالرحمن القشيري متروك، والطريق الآخر لا يصح"},{"x":"فبي يسمع، وبي يبصر، وبي يبطش، وبي يمشي","pg":430,"hd":"زيادة في حديث «ما تقرب إلي عبدي» ليست في البخاري 6502، نقل المحقق عن الألباني: لم أر هذه الزيادة عند البخاري ولا عند غيره ممن ذكرنا من المخرجين، وذكرها الحافظ نقلا عن الطوفي ولم يعزها لأحد"},{"x":"طال شوق الأبرار إلى لقائي، وأنا إلى لقائهم أشد شوقا","pg":428,"hd":"أثر إسرائيلي كما قال المؤلف في روضة المحبين، وأخرجه صاحب الفردوس عن أبي الدرداء"},{"x":"ما تحاب رجلان في الله إلا كان أفضلهما أشدهما حبا لصاحبه","pg":442,"hd":"صححه ابن حبان والحاكم، وقال المحقق: رفعه خطأ، والصواب أنه من قول مطرف بن عبدالله بن الشخير، وقال الدارقطني: رواه حماد بن سلمة عن ثابت مرسلا وهو الصواب"},{"x":"والشاب التائب حبيب الله","pg":446,"hd":"رواه ابن أبي الدنيا وأبو الشيخ من حديث أنس بسند ضعيف بلفظ «إن الله يحب الشاب التائب»، قاله العراقي فيما نقله المحقق"},{"x":"إذا مررتم برياض الجنة فارتعوا. قالوا: وما رياض الجنة؟ قال: حلق الذكر","pg":459,"hd":"تقدم تخريجه في 281: في سنده محمد بن ثابت البناني وهو ضعيف والحديث من منكراته، وطرقه الأخرى كلها لا تصح"},{"x":"ابن آدم خلقتك لعبادتي فلا تلعب، وتكفلت برزقك فلا تتعب، ابن آدم اطلبني تجدني، فإن وجدتني وجدت كل شيء، وإن فتك فاتك كل شيء. وأنا أحب إليك من كل شيء","pg":462,"hd":"أثر إسرائيلي كما نص على ذلك شيخ الإسلام في الفتاوى 8/52"},{"x":"حبب إلي من دنياكم النساء والطيب، أصبر عن الطعام والشراب ولا أصبر عنهن","pg":484,"hd":"قال المحقق: الحديث لا يصح، وعلته يوسف بن عطية فإنه متروك. وأصل الحديث بلفظ «حبب إلي من دنياكم النساء والطيب، وجعلت قرة عيني في الصلاة» صححه جماعة (ص 556)، والزيادة تكررت ص 557."},{"x":"حبك للشيء يعمي ويصم","pg":495,"hd":"رواه أحمد وأبو داود 5130 مرفوعا وموقوفا على أبي الدرداء؛ قال المحقق: سند الموقوف صحيح، ورجح الوقف السخاوي والسيوطي، فالرفع مرجوح."},{"x":"أثر ابن عباس في الشاب الذي نحل من العشق بعرفة فجعل يستعيذ بالله من العشق عامة يومه","pg":497,"hd":"قال المحقق: سنده ضعيف."},{"x":"لعن رسول الله صلى الله عليه وسلم الراشي والمرتشي والرائش","pg":501,"hd":"مداره على ليث وهو ضعيف، وضعفه الحاكم والمنذري والهيثمي؛ والثابت لفظ «لعن الراشي والمرتشي» من حديث عبد الله بن عمرو."},{"x":"خبر أبي بكر الصديق مع الجارية التي قالت: وهويته من قبل قطع تمائمي","pg":512,"hd":"قال المحقق: لا يثبت، وبين النهدي وأبي بكر مفاوز (من أخبار المعترض)."},{"x":"خبر عمر بن عبد العزيز وجارية فاطمة بنت عبد الملك","pg":514,"hd":"أخرجه ابن عساكر بسنده عن الهيثم بن عدي، والهيثم كذاب متروك الحديث (من أخبار المعترض)."},{"x":"من عشق وكتم وعف وصبر غفر الله له وأدخله الجنة","pg":515,"hd":"منكر، من رواية سويد بن سعيد، وقد تكلم عليه ابن القيم في آخر الكتاب (ص 568 إلى 573)."},{"x":"من عشق وعف وكتم فمات فهو شهيد","pg":527,"hd":"أنكره ابن عدي والبيهقي وابن طاهر والحاكم، وعده ابن الجوزي في الموضوعات، والصواب عند ابن القيم وقفه على ابن عباس، وقال في زاد المعاد: وفي صحته موقوفا على ابن عباس نظر."},{"x":"قصة نظر النبي صلى الله عليه وسلم إلى زينب بنت جحش وقوله: سبحان مقلب القلوب","pg":528,"hd":"من طريق الواقدي وهو متروك، وطريق الشعبي مرسل وفيه سليم ضعيف؛ ورد ابن القيم في زاد المعاد على من زعم أنه صلى الله عليه وسلم ابتلي بعشقها."},{"x":"قصة داود عليه السلام لما كان تحته تسع وتسعون امرأة فأحب امرأة فتزوجها فكمل المائة","pg":529,"hd":"قال المحقق: حديث باطل لا يثبت، والقصة باطلة من أكاذيب اليهود (ص 554 و557)."},{"x":"قول الزهري: أول حب كان في الإسلام حب النبي صلى الله عليه وسلم عائشة","pg":529,"hd":"المرفوع من طريق أنس باطل موضوع، والوليد متروك، ورواية محمد بن الزبير منكرة."},{"x":"حديث أم سلمة في أن النبي صلى الله عليه وسلم كان إذا رأى عائشة لا يتمالك عنها","pg":530,"hd":"قال ابن عبد البر: ليس بالقوي، وهو منكر على أصل ما روي عن أم سلمة، تفرد به موسى بن علي."},{"x":"خبر زيارة إبراهيم عليه السلام هاجر كل يوم من الشام على البراق","pg":530,"hd":"فيه الواقدي متروك الحديث."},{"x":"خبر عبد الله بن عمر والجارية الرومية","pg":531,"hd":"لا يصح لجهالة الشيخ وللانقطاع بين مالك وابن عمر."},{"x":"أحق من ذكر، وأحق من شكر، وأحق من عبد، وأحق من حمد... وأكفى من توكل عليه","pg":538,"hd":"لفظ حديث رواه الطبراني عن أبي أمامة، قال الهيثمي: فيه فضالة بن جبير مجمع على ضعفه."},{"x":"إنه إذا تجلى لهم ورأوه نسوا ما هم فيه من النعيم","pg":542,"hd":"رواه ابن ماجه 184 والعقيلي في الضعفاء، فيه الفضل بن عيسى الرقاشي متروك الحديث."},{"x":"كأن الناس يوم القيامة لم يسمعوا القرآن إذا سمعوه من الرحمن، فكأنهم لم يسمعوه قبل ذلك","pg":543,"hd":"قال المحقق: المرفوع لا يصح، فيه إسماعيل بن رافع ضعيف، وروي من قول محمد بن كعب القرظي."},{"x":"قول عثمان رضي الله عنه: لو طهرت قلوبنا لما شبعت من كلام الله","pg":550,"hd":"أثر، قال المحقق: سنده ضعيف للانقطاع."},{"x":"قول الصحابة: يا أبا موسى ذكرنا ربنا","pg":551,"hd":"أثر، سنده ضعيف للانقطاع، وقال المحقق: له طرق تدل على أن له أصلا."},{"x":"لم ير للمتحابين مثل النكاح","pg":554,"hd":"رواه ابن ماجه 1847 مرفوعا، ورواه جماعة مرسلا، قال العقيلي: المرسل أولى، وبين المحقق أن من رفعه عن الثوري أخطأ."},{"x":"تفسير ابن عباس قوله تعالى ﴿أم يحسدون الناس على ما آتاهم الله من فضله﴾ بحسد اليهود النبي على النكاح","pg":557,"hd":"أخرجه ابن أبي حاتم والطبري من طريق العوفي، وسنده ضعيف جدا."},{"x":"خبر عبد الله بن عمر يوم جلولاء","pg":559,"hd":"في سنده ضعف، علي بن زيد في حفظه ضعف."},{"x":"اللهم هذا قسمي فيما أملك، فلا تلمني فيما لا أملك","pg":560,"hd":"صححه ابن حبان والحاكم، وتكلم فيه البخاري وأبو زرعة والنسائي والترمذي والدارقطني ورأوا أنه مرسل، قال الترمذي: المرسل أصح."},{"x":"خبر علي رضي الله عنه مع الغلام الذي وجد في دار قوم","pg":561,"hd":"من طريق أبي مخنف لوط بن يحيى، قال المحقق: إسناده تالف."}]};
